export const SEEDS: Record<string, Record<string, string>> = {
  "dev": {
    "package.json": "{\n  \"name\": \"dev-extension-app\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"engines\": {\n    \"node\": \">=24\"\n  },\n  \"dependencies\": {\n    \"@rancher/shell\": \"^3.0.11\"\n  },\n  \"resolutions\": {\n    \"@types/node\": \"~25.3.0\",\n    \"@types/lodash\": \"4.17.5\"\n  },\n  \"scripts\": {\n    \"dev\": \"NODE_ENV=dev ./node_modules/.bin/vue-cli-service serve\",\n    \"build\": \"./node_modules/.bin/vue-cli-service build\",\n    \"clean\": \"./node_modules/@rancher/shell/scripts/clean\"\n  }\n}\n",
    "babel.config.js": "module.exports = require('@rancher/shell/babel.config.js');\n",
    "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2018\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"Node\",\n    \"lib\": [\n      \"ESNext\",\n      \"ESNext.AsyncIterable\",\n      \"DOM\"\n    ],\n    \"esModuleInterop\": true,\n    \"allowJs\": true,\n    \"sourceMap\": false,\n    \"strict\": true,\n    \"noEmit\": true,\n    \"baseUrl\": \".\",\n    \"paths\": {\n      \"~/*\": [\n        \"./*\"\n      ],\n      \"@/*\": [\n        \"./*\"\n      ],\n      \"@shell/*\": [\n        \"./node_modules/@rancher/shell/*\"\n      ]\n    },\n    \"typeRoots\": [\n      \"./node_modules\",\n      \"./node_modules/@rancher/shell/types\"\n    ],\n    \"types\": [\n      \"@types/node\",\n      \"cypress\",\n      \"rancher\",\n      \"shell\"\n    ]\n  },\n  \"exclude\": [\n    \"node_modules\"\n  ]\n}",
    "boot.sh": "#!/bin/sh\n# Entrypoint for the dev server pod.\n#\n# A real file rather than a string built in TypeScript: it is baked into the seed ConfigMap\n# verbatim by scripts/gen-dev-extension-seed.mjs, so what is in the repo is exactly what\n# runs. The only thing substituted is __, read out of\n# pkg/barn/dev-extension.ts, so the flattening this loop undoes cannot drift from\n# the flattening that produced the ConfigMap keys.\nset -e\n\nSEP=__\nAPP_HOME=/app/.home\n\n# ---------------------------------------------------------------------------\n# Root section. The container starts as root and nothing after this does.\n#\n# A terminal tab runs claude in this tree, claude refuses\n# --dangerously-skip-permissions as root, and the files it edits are the ones\n# webpack is watching - so the tree has to belong to an ordinary user, and the\n# dev server has to be that same user or the two would fight over who owns what\n# they each write.\n# ---------------------------------------------------------------------------\nif [ \"$(id -u)\" = 0 ]; then\n  mkdir -p /app \"$APP_HOME\"\n  # Cheap, so unconditional: a directory this created as root a moment ago is\n  # one the node user cannot write, and .home in particular is where claude\n  # keeps state it has to be able to update.\n  chown node:node /app \"$APP_HOME\"\n\n  # Once, not every boot: after the first install this is tens of thousands of\n  # files, and the hostPath keeps them between restarts.\n  if [ ! -f /app/.owned ]; then\n    echo \"[boot] handing /app to the node user\"\n    chown -R node:node /app\n    touch /app/.owned\n    chown node:node /app/.owned\n  fi\n\n  # tmux and the claude CLI, in the background: the dev server does not depend\n  # on either, and installing them here would put minutes in front of it. A\n  # terminal tab that opens before this finishes waits for it in shell.sh.\n  /bin/sh /seed/terminal-tools.sh >/app/.terminal-tools.log 2>&1 &\n\n  exec setpriv --reuid=1000 --regid=1000 --init-groups /bin/sh /seed/boot.sh\nfi\n\nexport HOME=\"$APP_HOME\"\nexport YARN_CACHE_FOLDER=/app/.yarn-cache\n\ncd /app\n\n# Seed the tree from the ConfigMap.\n#\n# Only files that are not already there are written. Once the pod has booted, its copy of\n# the tree is the live source - you edit it in here, and a terminal tab points claude at it -\n# and a restart must not throw those edits away. Writing just the missing ones still lets a\n# file added to the seed reach a pod that already exists.\n#\n# vue.config.js is the exception, refreshed on every boot: it is pod plumbing (it is what\n# addresses this server through the apiserver proxy), not something anyone edits in here.\nfor f in /seed/*; do\n  name=$(basename \"$f\")\n\n  # /seed holds two kinds of file: this app tree, whose paths are flattened with $SEP, and\n  # the pod's own scripts, which are run straight out of /seed so that a terminal tab always\n  # starts the version the extension last wrote, with no pod restart in between. Only the\n  # tree belongs in /app - plus the skeleton files that sit at the root of it.\n  case \"$name\" in\n    *\"$SEP\"*|package.json|babel.config.js|tsconfig.json|vue.config.js) ;;\n    *) continue ;;\n  esac\n\n  dest=\"/app/$(echo \"$name\" | sed \"s|$SEP|/|g\")\"\n\n  if [ ! -f \"$dest\" ] || [ \"$dest\" = \"/app/vue.config.js\" ]; then\n    mkdir -p \"$(dirname \"$dest\")\"\n    cp \"$f\" \"$dest\"\n  fi\ndone\n\n# The install is guarded by a marker rather than by node_modules existing. /app is a\n# hostPath, so a pod killed part-way through an install leaves a directory that is present\n# and unusable, and \"does node_modules exist\" would then skip the install forever and fail\n# in the compile instead. The marker is only written by an install that exited 0.\nif [ ! -f /app/.install-done ]; then\n  echo \"[boot] installing dependencies (first start only, this takes a few minutes)\"\n  rm -rf /app/node_modules\n  yarn install --network-timeout 600000\n  touch /app/.install-done\nelse\n  echo \"[boot] dependencies already installed\"\nfi\n\necho \"[boot] starting the dev server\"\nexec ./node_modules/.bin/vue-cli-service serve\n",
    "claude-credentials.mjs": "// One claude login, shared by every pod, through a Kubernetes Secret.\n//\n//   node /seed/claude-credentials.mjs pull    before claude starts\n//   node /seed/claude-credentials.mjs push    after it has run\n//\n// The reason both halves exist is the same reason the harness mirrors its credential file\n// between the global session and the project containers: OAuth tokens refresh, and whoever\n// refreshed last has the only working one. Pull without push means every pod that did not do\n// the refresh is stranded on a token that has expired; push without pull means a pod that has\n// never been logged in stays that way.\n//\n// Newest wins, on `expiresAt`, which is the only ordering these two copies have in common: file\n// mtimes are per pod and a pod that merely read the file would otherwise look newer than the\n// pod that refreshed it.\n//\n// Only the `claudeAiOauth` block moves. Everything else in the local file belongs to the pod\n// it is in, and the Secret is not a backup of it.\n//\n// It never fails loudly. A pod with no kubectl, no rights, or no Secret yet is a pod that is\n// not sharing a login, which is a thing to say on the way past rather than a reason to stop a\n// terminal from opening.\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { execFileSync } from 'node:child_process';\n\nconst MODE = process.argv[2] || 'pull';\nconst NAMESPACE = 'dev-system';\nconst SECRET = 'claude-credentials';\nconst KEY = 'credentials.json';\nconst LOCAL = path.join(process.env.HOME || os.homedir(), '.claude', '.credentials.json');\n\nfunction say(message) {\n  console.log(`[credentials] ${ message }`); // eslint-disable-line no-console\n}\n\nfunction kubectl(args) {\n  return execFileSync('kubectl', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });\n}\n\nfunction readLocal() {\n  try {\n    return JSON.parse(fs.readFileSync(LOCAL, 'utf8'));\n  } catch {\n    return {};\n  }\n}\n\nfunction readRemote() {\n  try {\n    const encoded = kubectl(['-n', NAMESPACE, 'get', 'secret', SECRET, '-o', `jsonpath={.data.${ KEY.replace('.', '\\\\.') }}`]).trim();\n\n    return encoded ? JSON.parse(Buffer.from(encoded, 'base64').toString('utf8')) : {};\n  } catch {\n    return null;\n  }\n}\n\n/** When the access token in a copy runs out, or 0 for a copy that has none. */\nfunction expiresAt(blob) {\n  return Number(blob?.claudeAiOauth?.expiresAt) || 0;\n}\n\n/**\n * Replace the file in one step.\n *\n * A terminal starting while this writes would otherwise be able to read half a token, and the\n * mode is set on the temporary file rather than after the rename so the file is never briefly\n * readable by anything else on the node.\n */\nfunction writeLocal(blob) {\n  fs.mkdirSync(path.dirname(LOCAL), { recursive: true });\n\n  const tmp = path.join(path.dirname(LOCAL), `.credentials.${ process.pid }`);\n\n  fs.writeFileSync(tmp, `${ JSON.stringify(blob, null, 2) }\\n`, { mode: 0o600 });\n  fs.renameSync(tmp, LOCAL);\n}\n\nconst local = readLocal();\nconst remote = readRemote();\n\nif (remote === null) {\n  say('the shared secret is not readable from this pod, so this terminal keeps its own login');\n  process.exit(0);\n}\n\nif (MODE === 'push') {\n  if (expiresAt(local) <= expiresAt(remote)) {\n    process.exit(0);\n  }\n\n  const merged = { ...remote, claudeAiOauth: local.claudeAiOauth };\n  const encoded = Buffer.from(JSON.stringify(merged)).toString('base64');\n\n  try {\n    kubectl([\n      '-n', NAMESPACE, 'patch', 'secret', SECRET, '--type=merge',\n      '-p', JSON.stringify({ data: { [KEY]: encoded } }),\n    ]);\n    say('pushed a newer token to the shared secret');\n  } catch {\n    say('could not write the shared secret, so the refreshed token stays in this pod only');\n  }\n\n  process.exit(0);\n}\n\nif (expiresAt(remote) <= expiresAt(local)) {\n  process.exit(0);\n}\n\nwriteLocal({ ...local, claudeAiOauth: remote.claudeAiOauth });\nsay('pulled the shared login');\n",
    "claude-defaults.mjs": "// The settings a fresh claude stops and asks for, answered in advance.\n//\n// A pod is a fresh machine every time, so without this the first thing the\n// editor's terminal shows is a theme picker, then a \"do you trust this folder\"\n// dialog, then a \"Yes, I accept\" for bypass permissions - three questions whose\n// answers are the same every time and none of which the person opening the\n// editor is being asked anything real by. What they should land in is a prompt,\n// or a login.\n//\n// Only the flags are set here. The login itself is pulled from a Kubernetes\n// Secret before the pane starts (see claude-credentials.mjs); what this file\n// adds for it is the Stop hook that pushes a refreshed token back, so the pod\n// that happens to refresh does not leave every other pod on a stale one.\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { execFileSync } from 'node:child_process';\n\nconst HOME = process.env.HOME || '/app/.home';\nconst CONFIG = path.join(HOME, '.claude.json');\nconst SETTINGS = path.join(HOME, '.claude', 'settings.json');\n\n// The directories a pane may start claude in, which is not the same list in\n// every pod: the dev server's tabs land in its own tree, and a workspace's land\n// in the checkout it cloned. shell.sh passes the pane's own directory; the\n// default is the dev server pod's source and the app around it, which is what\n// boot.sh's background run has no directory to pass.\nconst TRUSTED = (process.env.TRUST_DIRS || '/app/pkg/dev-extension:/app').split(':').filter(Boolean);\n\nfunction read(file) {\n  try {\n    return JSON.parse(fs.readFileSync(file, 'utf8'));\n  } catch {\n    // Missing, or half-written by a claude that was killed. Either way the\n    // defaults below are a better starting point than failing here.\n    return {};\n  }\n}\n\n// Written back only when something actually changed. claude rewrites this file\n// as it runs, and this can be called while a session is attached, so the common\n// case (everything already set) must not touch it at all.\nfunction update(file, mutate) {\n  const before = read(file);\n  const after = JSON.parse(JSON.stringify(before));\n\n  mutate(after);\n\n  if (JSON.stringify(after) === JSON.stringify(before)) {\n    return false;\n  }\n\n  fs.mkdirSync(path.dirname(file), { recursive: true });\n  fs.writeFileSync(file, `${ JSON.stringify(after, null, 2) }\\n`, { mode: 0o600 });\n\n  return true;\n}\n\nfunction claudeVersion() {\n  try {\n    return execFileSync('claude', ['--version'], { encoding: 'utf8' }).trim().split(' ')[0];\n  } catch {\n    return undefined;\n  }\n}\n\nconst changed = [\n  update(CONFIG, (config) => {\n    // Skips the whole first-run flow, the theme picker included.\n    config.hasCompletedOnboarding = true;\n\n    // claude re-runs onboarding when its version is newer than this, so it is\n    // stamped with whatever is installed rather than hardcoded.\n    const version = claudeVersion();\n\n    if (version) {\n      config.lastOnboardingVersion = version;\n    }\n\n    config.projects = config.projects || {};\n\n    for (const dir of TRUSTED) {\n      config.projects[dir] = {\n        ...config.projects[dir],\n        // The pod's tree came from this extension's own seed, so asking whether\n        // it is trusted is asking the wrong side.\n        hasTrustDialogAccepted:       true,\n        hasCompletedProjectOnboarding: true,\n      };\n    }\n  }),\n\n  // The \"Yes, I accept\" dialog for --dangerously-skip-permissions, which the\n  // pane's claude is always started with, and the hook that shares a refreshed\n  // token with the other pods.\n  update(SETTINGS, (settings) => {\n    settings.skipDangerousModePermissionPrompt = true;\n\n    // Stop, not a session end: it runs every time claude finishes a response,\n    // which is the only moment this can be sure a refresh has already landed in\n    // the file. The script itself does nothing when the local copy is not newer,\n    // so running it that often costs a comparison.\n    //\n    // Merged rather than assigned, so a hook someone added by hand survives, and\n    // matched on the command so this cannot accumulate copies of itself.\n    const hooks = settings.hooks || (settings.hooks = {});\n    const stop = hooks.Stop || (hooks.Stop = []);\n    const command = 'node /seed/claude-credentials.mjs push';\n\n    const already = stop.some((entry) => (entry.hooks || []).some((hook) => hook.command === command));\n\n    if (!already) {\n      stop.push({ hooks: [{ type: 'command', command }] });\n    }\n  }),\n].some(Boolean);\n\nconsole.log(changed ? '[claude] defaults written' : '[claude] defaults already set');\n",
    "claude-session.sh": "#!/bin/bash\n# What runs in the tmux pane: claude, in a loop.\n#\n# The loop is the point. If claude exits - a crash, a /quit, an update - the\n# pane would die with it and take the tmux session down, so the next tab would\n# come up blank instead of where you left off. Restarting keeps the session, and\n# `--continue` means the restart resumes the conversation rather than opening a\n# new one. A run that ends in under three seconds is treated as an error and\n# backed off, so a claude that cannot start does not spin.\n#\n# bash rather than sh: `read` with no variable name is a bashism, and this is\n# the pane's interactive shell anyway.\n# The pane's own home, set by shell.sh in the tmux environment. The default is\n# only for a pane started some other way.\nexport HOME=${HOME:-/app/.home}\n\n# Ctrl-C at the prompt below leaves you in a shell rather than closing the pane.\n# While claude is running it is claude that gets the signal, not this script, so\n# this only fires where it is offered.\ntrap 'echo; exec /bin/bash' INT\n\nif ! command -v claude >/dev/null 2>&1; then\n  echo \"[claude is not installed in this pod - see /app/.terminal-tools.log]\"\n  echo \"[dropping to a shell]\"\n  exec /bin/bash\nfi\n\n# A prompt somebody queued for this conversation, used once and then gone.\n#\n# Read before the loop rather than inside it: it is what this conversation is\n# for, and a restart of claude within the same pane should carry on rather than\n# ask the same thing again. Deleted before claude runs, not after, so a claude\n# that crashes on the prompt does not ask it again on every restart.\nQUEUE=${1:-}\nPROMPT=\"\"\n\nif [ -n \"$QUEUE\" ] && [ -f \"$QUEUE\" ]; then\n  PROMPT=$(cat \"$QUEUE\")\n  rm -f \"$QUEUE\"\nfi\n\nif [ -n \"$PROMPT\" ]; then\n  claude --dangerously-skip-permissions \"$PROMPT\" || true\nfi\n\nwhile true; do\n  start=$(date +%s)\n\n  # --continue fails when the directory has no conversation yet, which is the\n  # only reason for the fallback.\n  claude --dangerously-skip-permissions --continue 2>/dev/null ||\n    claude --dangerously-skip-permissions\n\n  end=$(date +%s)\n\n  if [ $((end - start)) -lt 3 ]; then\n    echo \"\"\n    echo \"[claude exited immediately, which usually means an error. Waiting 5s.]\"\n    sleep 5\n  fi\n\n  echo \"\"\n  echo \"[claude exited - press Enter to restart, Ctrl-C for a shell]\"\n  read -r || exec /bin/bash\ndone\n",
    "session-claude.md": "# Where you are\n\nYou are claude, running in a terminal inside a Rancher extension's own dev server pod. The\nthing you are building is a **Rancher dashboard extension**, and the Rancher you are building\nit against is the one two clicks away in the next pane.\n\nThis file is copied into a session's directory the first time that session starts (see\n`/seed/shell.sh`). It is yours to edit. It describes the shape of this place, not its contents,\nbecause the contents change and a file that describes them goes stale.\n\n## The pod you are in\n\n`vue-cli-service serve` is running over `/app`, a whole Rancher dashboard with the extension\ncompiled into it. `/app/pkg/$EXTENSION_NAME-extension` (or `/app/pkg/dev-extension` if this pod\nwas made before extensions had names) is that extension's source, and it is the live one:\nsaving a file there is recompiled and pushed into the browser over the hot-reload socket within\nseconds. There is no build step and no server to restart, and **restarting the dev server is the\none thing that interrupts whoever is watching it**.\n\n`/app/node_modules/@rancher/shell` is watched too, so the login page, the nav and the rest of\nthe dashboard are editable the same way. That is deliberate and it is also a trap: an edit in\nthere changes this dashboard and nothing else, and it is not in any repo.\n\n- `node`, `npm`, `yarn`, `git`, `curl`, `tmux` and `kubectl` are here.\n- Your session is a tmux session. Closing the browser leaves it running; reopening reattaches.\n- Each terminal session has its own directory, which is what keeps its conversation its own.\n\n## What you can reach\n\nYour ServiceAccount is `barn-extension`, and it is bound to **cluster-admin**. `kubectl` is\nconfigured from it, so from this pane you can read and change every resource in the cluster this\nRancher manages. That is not an accident and it is the point: an extension is mostly a UI over\nRancher's own resources, and it cannot be written, and certainly cannot be tried, from a pane\nthat gets 403 to every question.\n\nRancher's own objects are CRDs in that same apiserver, so `kubectl` is how you look at them:\n\n```bash\nkubectl get settings.management.cattle.io                 # what Rancher is configured to do\nkubectl get users.management.cattle.io                    # who can log in\nkubectl get projects.management.cattle.io -A              # Rancher's grouping of namespaces\nkubectl get clusters.management.cattle.io                 # the clusters it manages\nkubectl get clusterrepos.catalog.cattle.io                # where its Apps come from\nkubectl get uiplugins.catalog.cattle.io -A                # extensions installed into its UI\nkubectl api-resources | grep cattle.io                    # the rest, and there is a lot of it\n```\n\nTreat that access the way you would treat a root shell on somebody's cluster: it is a live\nRancher that a person is looking at. Reading is free. Before you change or delete something that\nwas not yours to begin with, say what you are about to do.\n\n## What you are building\n\nA Rancher extension is a package under `pkg/`, and the dashboard loads it by convention rather\nthan by configuration. The parts, and where to look:\n\n| Thing | File | What it does |\n| --- | --- | --- |\n| Entry point | `index.ts` | `importTypes`, `addProduct`, `addRoutes`, `register` |\n| Product | `product.ts` | Nav entries, resource types, which store they live in |\n| Routes | `routing/index.ts` | Pages, and which parent template they render under |\n| Pages | `pages/*.vue` | The pages themselves |\n| Models | `models/<type>.js` | Behaviour on a resource: actions, computed fields, links |\n| Detail/Edit | `detail/`, `edit/` | Resolved by resource type name, not by import |\n| Strings | `l10n/en-us.yaml` | `nav.group.*`, `typeLabel.*`, and anything `t()` looks up |\n\nTwo conventions cause most of the confusion:\n\n- **Files are found by name.** A spoofed type `my.thing` looks for `models/my.thing.js`,\n  `detail/my.thing.vue`, `edit/my.thing.vue`. Renaming the type without renaming the files is a\n  page that renders blank with no error.\n- **The parent route decides the chrome.** `addRoute('default', ...)` gets the cluster side nav\n  and renders nothing until a cluster is ready; `'plain'` gets the header and the top-level\n  menu; `'blank'` gets nothing at all. A page that renders alone on a white background is\n  almost always registered under the wrong parent.\n\nThe shell's own components are the fastest documentation there is, because they are right here:\n\n```bash\nls /app/node_modules/@rancher/shell/components          # SortableTable, AppModal, Tabbed, ...\nls /app/node_modules/@rancher/shell/components/form     # LabeledInput, LabeledSelect, ...\nls /app/node_modules/@rancher/shell/pkg                 # what a packaged extension looks like\n```\n\nRead one before writing a wrapper for it. `SortableTable`, `LabeledSelect`, `AsyncButton`,\n`Banner`, `AppModal` and `Card` cover most of what a page needs, and they carry Rancher's own\nbehaviour (sorting, paging, the busy state on a button) that a hand-rolled version will not.\n\nThe published docs are at <https://extensions.rancher.io/extensions/next/home>. They are thin on\neverything above, which is why this file lists it.\n\n## The rules of this tree\n\n- **Nothing here syncs back.** The repo copy lives in the barn repo at\n  `pkg/barn/dev-extension/`, which is what a fresh pod is seeded from. A change meant to outlive\n  this pod has to be copied back there. If you are asked to make something permanent and you\n  cannot reach the repo, say so rather than assuming the edit will survive.\n- **Do not restart the dev server.** Somebody is watching the pane it serves.\n- **`yarn install` is minutes.** Adding a dependency is a real cost here and it survives only as\n  long as this pod's `/app` does.\n",
    "shell.sh": "#!/bin/sh\n# Entrypoint for a terminal tab. The extension's terminal component runs this\n# over the Kubernetes exec subresource, with the tab's session id as $1 and,\n# optionally, the directory the pane should start in as $2 and the home\n# directory claude should keep its state in as $3.\n#\n# Everything the tab runs comes out of /seed rather than the tree, so a tab\n# always starts the scripts the extension last wrote, without a pod restart.\n#\n# The session is a tmux session, which is the whole persistence story: `-A`\n# attaches to it if it is already there and creates it otherwise, so closing the\n# browser leaves claude running and reopening the editor lands back in the same\n# conversation.\nset -e\n\nSESSION=${1:-main}\n\n# Where the pane starts, and what claude is therefore pointed at. The default is\n# DevExtension's own source, the tree this pod's dev server is compiling and\n# serving, which is what the editor's pane wants.\n#\n# It is an argument because claude keys its conversation history by working\n# directory, so one directory means one conversation, and two panes sharing a\n# directory means the second one resumes the first one's conversation rather than\n# having its own. The harness gives each terminal tab a directory for exactly\n# this reason. Callers that want several independent sessions (the Dev product's\n# global terminals) pass one per session; callers that want the source tree pass\n# nothing.\nWORKDIR=${2:-/app/pkg/dev-extension}\n\n# Where claude's login and settings live, which has to be on whatever storage\n# outlives the pod or every restart is another /login. It is an argument because\n# this script runs in two kinds of pod: the dev server's, whose durable\n# directory is /app, and a workspace's, whose is /workspace.\nHOME_DIR=${3:-/app/.home}\n\n# Made here as well as by whatever booted the pod, because everything below\n# writes into it and a missing one is a login that cannot be saved. Cheap, and\n# a no-op on the second tab.\nif [ ! -d \"$HOME_DIR\" ]; then\n  mkdir -p \"$HOME_DIR\"\n\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$HOME_DIR\"\n  fi\nfi\n\n# A prompt this conversation was opened with, if something queued one. It is a file rather\n# than an argument because whoever queues it is not the thing that starts the pane: a page\n# writes it into the pod and the pane picks it up whenever it next starts. Beside the home\n# directory, so it is on the same storage and outlives a pod restart the way a login does.\nQUEUE_DIR=\"$(dirname \"$HOME_DIR\")/.queue\"\nMC_QUEUE=\"$QUEUE_DIR/$SESSION\"\n\nexport MC_QUEUE\n\nHOME_DIR=\"$HOME_DIR\" TRUST_DIRS=\"$WORKDIR\" /bin/sh /seed/terminal-tools.sh\n\n# A session directory has to exist before tmux is told to start in it, and it has\n# to belong to the node user, since everything in the pane is that user and\n# claude writes here. Only for a directory this creates: the default is the\n# source tree, which boot.sh already handed over.\nif [ ! -d \"$WORKDIR\" ]; then\n  mkdir -p \"$WORKDIR\"\n\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$WORKDIR\"\n  fi\nfi\n\n# What claude reads before it is asked anything. A session in a directory of its\n# own would otherwise start knowing nothing about the cluster it is in and\n# re-derive it, badly, every time. Copied rather than linked so a session can\n# edit its own, and only when there is none, so an edited one is never\n# overwritten. The source tree has its own CLAUDE.md, so this is a no-op there.\nif [ ! -f \"$WORKDIR/CLAUDE.md\" ] && [ -f /seed/session-claude.md ]; then\n  cp /seed/session-claude.md \"$WORKDIR/CLAUDE.md\"\n\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$WORKDIR/CLAUDE.md\"\n  fi\nfi\n\n# The shared login, before anything that would use it. Run as the node user and\n# with the pane's HOME, because it writes into that user's ~/.claude and a\n# root-owned credentials file is one claude cannot then refresh.\nif [ \"$(id -u)\" = 0 ]; then\n  setpriv --reuid=1000 --regid=1000 --init-groups \\\n    env \"HOME=$HOME_DIR\" node /seed/claude-credentials.mjs pull || true\nelse\n  env \"HOME=$HOME_DIR\" node /seed/claude-credentials.mjs pull || true\nfi\n\n# tmux does not pass this script's environment into a session it is attaching to, only into one\n# it creates, so the queue file is given on the command line of the pane's own script instead.\nset -- tmux -f /seed/tmux.conf new-session -A -s \"mc-$SESSION\" -c \"$WORKDIR\" \\\n  \"/bin/bash /seed/claude-session.sh '$MC_QUEUE'\"\n\n# The exec subresource runs as the container's user, which is root, whatever the\n# dev server dropped itself to. Everything in the pane has to be the node user\n# instead: claude refuses --dangerously-skip-permissions as root, and the files\n# it edits are the ones webpack is watching, which boot.sh made node's.\nif [ \"$(id -u)\" = 0 ]; then\n  exec setpriv --reuid=1000 --regid=1000 --init-groups \\\n    env \"HOME=$HOME_DIR\" TERM=xterm-256color \"$@\"\nfi\n\nexec env \"HOME=$HOME_DIR\" TERM=xterm-256color \"$@\"\n",
    "terminal-tools.sh": "#!/bin/sh\n# What a terminal tab needs, on top of what the dev server needs: tmux, so a\n# session outlives the browser tab that opened it, and the claude CLI, which is\n# what actually runs in the pane.\n#\n# Both land in the container filesystem, which a restart throws away, so this\n# runs on every boot. It is called twice, deliberately:\n#\n#   - from boot.sh, in the background, because the dev server does not depend on\n#     any of it and must not wait for it;\n#   - from shell.sh, in the foreground, so a tab opened before the background\n#     run finished waits here, where the waiting is visible, rather than landing\n#     in a pane with no claude in it.\n#\n# Hence the lock: the two can overlap on a pod that has just started.\nset -e\n\nLOCK=/tmp/terminal-tools.lock\n\n# Is there anything to do at all?\n#\n# Asked before the lock is touched, and that ordering is the point. Everything the lock\n# protects is an install, so a tab opening in a pod that finished installing hours ago has\n# nothing to serialise with anybody - and a pod is in that state for all but the first few\n# minutes of its life. Taking a lock to discover there is no work is how one wedged tab used to\n# block every tab after it.\nhave_tools() {\n  command -v tmux >/dev/null 2>&1 &&\n    command -v claude >/dev/null 2>&1 &&\n    command -v kubectl >/dev/null 2>&1\n}\n\n# What wedges a tab, and why the waiting had to be bounded.\n#\n# A tab is a Kubernetes exec on a pty. Close the browser tab and nothing drains that pty any\n# more, so the next write into it blocks - and stays blocked, because the reader is never\n# coming back. A shell stuck there is alive by every test available: it has a pid, kill -0\n# succeeds, and if it was holding the lock when it stopped, it holds it for the life of the pod.\n# Observed: six of them in one pod, the oldest four hours old, each stopped mid-echo of the\n# message below.\n#\n# So three things, none of which is sufficient alone. The check above means a settled pod never\n# takes the lock. The message is printed once rather than every three seconds, because it was\n# the repetition that filled the pty. And the wait gives up: if the tools turn out to be there,\n# whoever holds the lock is not installing anything this tab needs.\nif ! have_tools; then\n  waited=0\n  said=\"\"\n  took=\"\"\n\n  while true; do\n    # Taking it is the loop's exit, and `took` is how the release below knows this shell owns\n    # what it is about to delete. The other way out of here is giving up, which must not.\n    if mkdir \"$LOCK\" 2>/dev/null; then\n      took=yes\n      break\n    fi\n\n    holder=$(cat \"$LOCK/pid\" 2>/dev/null || true)\n\n    # A holder that has exited outright. Older locks carry no pid at all, which is the same\n    # conclusion by a different route once nobody has claimed it for a while.\n    if [ -n \"$holder\" ] && ! kill -0 \"$holder\" 2>/dev/null; then\n      echo \"[tools] the install holding this lock is gone; clearing it\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    if [ -z \"$holder\" ] && [ \"$waited\" -ge 10 ]; then\n      echo \"[tools] this lock has no owner; clearing it\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    # Two minutes is longer than an install of tmux and the claude CLI on a warm image and\n    # shorter than anybody will sit and watch. Past it, believe the filesystem over the lock.\n    if [ \"$waited\" -ge 40 ]; then\n      if have_tools; then\n        echo \"[tools] the lock is held but everything is installed; carrying on\"\n        break\n      fi\n\n      echo \"[tools] the lock has been held for two minutes; taking it over\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    if [ -z \"$said\" ]; then\n      echo \"[tools] another install is running, waiting for it\"\n      said=yes\n    fi\n\n    waited=$((waited + 1))\n    sleep 3\n  done\n\n  # Only what this shell actually took. Giving up on a lock somebody else holds and then\n  # deleting it on the way out would be worse than the wait it was avoiding.\n  if [ -n \"$took\" ]; then\n    echo $$ > \"$LOCK/pid\" 2>/dev/null || true\n\n    # HUP as well as the rest: an exec that is hung up should release this on the way out\n    # rather than leave it for a pod restart to clear.\n    trap 'rm -rf \"$LOCK\" 2>/dev/null || true' EXIT INT TERM HUP\n  fi\nfi\n\nif ! command -v tmux >/dev/null 2>&1; then\n  echo \"[tools] installing tmux\"\n  apt-get update -qq\n  apt-get install -y -qq tmux </dev/null\nfi\n\nif ! command -v claude >/dev/null 2>&1; then\n  echo \"[tools] installing the claude cli (this takes a moment)\"\n  npm install -g --silent @anthropic-ai/claude-code\nfi\n\n# kubectl, so the pod's own ServiceAccount is usable from a terminal. It needs\n# no configuration: in-cluster credentials are mounted and client-go finds them,\n# which is the whole reason the terminals can manage the cluster at all.\n#\n# Pinned to the cluster's version rather than \"stable\", so what a terminal gets\n# does not change under it on a day when upstream moves.\nif ! command -v kubectl >/dev/null 2>&1; then\n  echo \"[tools] installing kubectl\"\n  curl -sSLo /usr/local/bin/kubectl \"https://dl.k8s.io/release/v1.36.1/bin/linux/amd64/kubectl\"\n  chmod 0755 /usr/local/bin/kubectl\nfi\n\n# Answer claude's first-run questions before it can ask them, so a tab opens on\n# a prompt or a login rather than on a theme picker. Idempotent, and a no-op\n# once the flags are set, so it is safe to run on every boot and every tab.\n#\n# As the node user: this writes into the home claude runs with, and a root-owned\n# .claude.json is one claude cannot then update.\n# HOME_DIR is passed by shell.sh, since which directory outlives the pod depends\n# on which kind of pod this is: /app for the dev server, /workspace for a\n# workspace. The default is for the background run from boot.sh, which is the\n# dev server's.\nAPP_HOME=${HOME_DIR:-/app/.home}\n\n# TRUST_DIRS is the pane's own directory, passed by shell.sh, so the folder the\n# tab is about to open in is one claude already trusts rather than one it stops\n# and asks about.\nif [ \"$(id -u)\" = 0 ]; then\n  setpriv --reuid=1000 --regid=1000 --init-groups \\\n    env \"HOME=$APP_HOME\" \"TRUST_DIRS=${TRUST_DIRS:-}\" node /seed/claude-defaults.mjs\nelse\n  env \"HOME=$APP_HOME\" \"TRUST_DIRS=${TRUST_DIRS:-}\" node /seed/claude-defaults.mjs\nfi\n\necho \"[tools] ready\"\n",
    "tmux.conf": "# tmux config for a terminal tab. Read straight out of /seed (tmux -f), so it is\n# always the version the extension last wrote and there is no copy in the tree.\n#\n# Mouse on so the scroll wheel scrolls tmux's 50k-line scrollback (it enters\n# copy-mode automatically and exits at the bottom). A plain mouse drag selects\n# via tmux copy-mode; when the drag ends, set-clipboard emits the selection as\n# an OSC 52 sequence, which the terminal component hands to the browser\n# clipboard - so drag-select auto-copies. (Shift+drag still does a native\n# xterm.js selection.) The terminal-features line tells tmux the outer terminal\n# understands OSC 52.\nset -g mouse on\nset -g history-limit 50000\n\n# Pass focus in and out of the pane through to what is running in it. claude\n# asks for this by name on startup when it is off, and asking is the thing this\n# pod is trying not to do.\nset -g focus-events on\nset -s set-clipboard on\nset -as terminal-features ',xterm-256color:clipboard'\n\n# No status bar. The harness keeps tmux's, where it lists the windows of a\n# session you can switch between; this pane has one session and one window, so\n# it would be a row of screen spent on a constant - and a green one, which is\n# the only thing in the pane that cannot follow Rancher's theme.\nset -g status off\n",
    "vue.config.js": "// Dev server config for the pod. Seeded to /app/vue.config.js, so `__dirname` is the app.\n//\n// The browser reaches this server through the Kubernetes apiserver's service proxy, on\n// Rancher's own origin:\n//\n//   https://<rancher>/k8s/clusters/local/api/v1/namespaces/<ns>/services/http:<svc>:8005/proxy/\n//\n// That inverts the shell's dev server defaults in three ways. Every URL this build hands to\n// the browser has to carry the proxy prefix, every request that arrives has had it stripped\n// again by the proxy, and the TLS the browser sees is Rancher's, not this server's.\n//\n// DEV_PROXY_PATH is the only thing passed in. It is built by the extension out of the same\n// namespace/service/port constants it creates the Deployment and Service with, so this build\n// never learns - and never needs - the hostname Rancher is served on.\nconst proxyPath = process.env.DEV_PROXY_PATH;\n\nif (!proxyPath) {\n  throw new Error('DEV_PROXY_PATH must be set - it is the service-proxy path this dev server is reached at');\n}\n\n// The vue-router base: the prefix on every in-app link, which has to be the path the page\n// was loaded at. The shell reads it out of the environment when its exported function runs;\n// setting it above the require means that cannot matter. RESOURCE_BASE, the other half of\n// that pair, is deliberately left unset - asset URLs are handled below instead.\nprocess.env.ROUTER_BASE = `${ proxyPath }/`;\n\nconst config = require('@rancher/shell/vue.config'); // eslint-disable-line @typescript-eslint/no-var-requires\n\nconst base = config(__dirname, { excludes: [] });\n\n// Asset URLs, and why they are not simply the proxy path.\n//\n// The apiserver's service proxy rewrites absolute URLs in HTML responses, prepending its own\n// proxy path - it is what lets a naive web UI work behind it at all. So an asset URL that\n// already carried the proxy path comes back to the browser carrying it twice.\n//\n// Both halves of this use that rewriting rather than fight it:\n//\n//  - index.html asks for `/js/index.js`, and the proxy hands the browser\n//    `<proxy>/js/index.js`. Absolute, so it does not depend on which route the page was\n//    loaded at, the way a relative URL would.\n//  - webpack's runtime publicPath is `auto`, which it works out from its own script URL when\n//    it loads. So chunks, fonts and images fetched later land on the same base, and nothing\n//    has to be told what that base is.\nbase.publicPath = 'auto';\n\nconst previousChainWebpack = base.chainWebpack;\n\nbase.chainWebpack = (webpackConfig) => {\n  if (typeof previousChainWebpack === 'function') {\n    previousChainWebpack(webpackConfig);\n  }\n\n  // html-webpack-plugin has a publicPath of its own, which is what makes the two halves\n  // above able to disagree. `html-index` is the plugin's name because the shell's config\n  // declares an `index` page.\n  webpackConfig.plugin('html-index').tap((args) => {\n    args[0].publicPath = '/';\n\n    return args;\n  });\n};\n\nbase.devServer = {\n  ...base.devServer,\n\n  // Rancher's proxy terminates TLS, and it will not talk to the shell's self-signed dev\n  // certificate on the way through. Plain http here, https to the browser.\n  server: { type: 'http' },\n\n  // Requests arrive with whatever Host the proxy chain last set, never this server's own.\n  allowedHosts: 'all',\n\n  // No gzip. The proxy rewrites URLs in HTML responses as they pass through (see below),\n  // and it cannot do that to a compressed body: the request comes back as\n  // `stream error: ...; INTERNAL`, which the browser reports as an incomplete response and\n  // a blank page. webpack-dev-server compresses by default, so this has to be said.\n  compress: false,\n\n  // The proxy strips its prefix before a request lands here, so everything this server\n  // serves is served from the root: webpack's output, and the files in public/.\n  devMiddleware: { publicPath: '/' },\n  static:        { publicPath: '/' },\n\n  // Serve index.html for any path that is not a file, so a deep link into the dashboard\n  // (rather than its root) loads the app instead of 404ing. vue-cli installs a version of\n  // this derived from publicPath, which is `auto` here and therefore no use; setting it at\n  // all replaces theirs outright. disableDotRule matters more than usual in Rancher, where\n  // routes routinely carry a resource name with dots in it.\n  historyApiFallback: {\n    index:             '/index.html',\n    disableDotRule:    true,\n    htmlAcceptHeaders: ['text/html', 'application/xhtml+xml']\n  },\n\n  // Hot reload rides the same proxy: the apiserver passes the upgrade through, so webpack's\n  // own client works unmodified. The sentinels are webpack-dev-server's \"infer it from\n  // window.location\" values (protocol 'auto', hostname '0.0.0.0', port 0) - only the path is\n  // ours. The socket needs a Rancher session because the proxy does, which is the one place\n  // this shows: hot reload works on every page you are logged in for, not on the login page.\n  hot:             true,\n  webSocketServer: { type: 'ws', options: { path: '/ws' } },\n  client:          {\n    webSocketURL: {\n      protocol: 'auto',\n      hostname: '0.0.0.0',\n      port:     0,\n      pathname: `${ proxyPath }/ws`\n    },\n    // The full-screen compile-error overlay is the dev build's, so it would cover this\n    // dashboard entirely for whoever happens to be looking when an edit fails to compile.\n    overlay: false\n  }\n};\n\n// The API the shell's dev server proxies to is deliberately left at its default. The browser\n// is same-origin with Rancher here, so every /v1, /k8s and /rancherversion request it makes\n// goes straight to Rancher and never through this server - the proxy config exists for a dev\n// server on its own origin, which this one is not.\n\n// The shell ships /node_modules/ in watchOptions.ignored, which makes its own pages (login,\n// nav, anything outside pkg/) impossible to edit live. Watching @rancher/shell and ignoring\n// the rest is what makes the whole dashboard editable in the pod, not just the extension.\nconst previousConfigureWebpack = base.configureWebpack;\n\nbase.configureWebpack = (config) => {\n  const result = typeof previousConfigureWebpack === 'function'\n    ? previousConfigureWebpack(config)\n    : previousConfigureWebpack;\n\n  config.watchOptions = {\n    ...(config.watchOptions || {}),\n    ignored: /node_modules\\/(?!@rancher\\/shell)/\n  };\n\n  // Watching is not enough on its own. Webpack 5 treats node_modules as a \"managed path\" and\n  // assumes its contents never change, so it caches them and skips the watcher entirely.\n  // Clearing that is what actually makes an edit under @rancher/shell rebuild.\n  config.snapshot = {\n    ...(config.snapshot || {}),\n    managedPaths:   [],\n    immutablePaths: []\n  };\n\n  return result;\n};\n\nmodule.exports = base;\n",
    "pkg/dev-extension/CLAUDE.md": "# DevExtension, from inside the pod\n\nYou are running in the pod that serves this extension, in the tree it serves. `/app` is a\nwhole Rancher dashboard build with this package (`/app/pkg/dev-extension`) compiled into it,\nand `vue-cli-service serve` is watching it. Every file you save here is recompiled and\npushed into the browser over the hot-reload socket, usually within a few seconds. That\nincludes `/app/node_modules/@rancher/shell`, which is watched too, so the login page, the\nnav and the rest of the dashboard are editable the same way.\n\nSo: edit files and look at the result. There is no build step to run and no server to\nrestart, and restarting the dev server is the one thing that will interrupt the person\nwatching it.\n\n- `pkg/dev-extension/` is this extension: `product.ts` (nav entries), `routing/index.ts`,\n  `pages/`, `models/` (overrides of the shell's models, which win over the shell's own).\n- It registers two products. `devextension` is the live-reload demo. `dev` is the Claude\n  Harness rebuilt on Kubernetes: a workspace is a namespace with a Deployment and a Service,\n  started and stopped by scaling, with a terminal on the pod's exec subresource. Its\n  Kubernetes calls are in `api.ts`, the container each workspace runs is in `templates.ts`,\n  and the terminal is `components/DevTerminal.vue`, which will point at any pod given a\n  namespace, labels, a container and an argv.\n- The `dev` product's nav is Workspaces, Terminal, My Work, Templates, Settings. A workspace\n  opens as tabs (Overview, Conversations, Browser, Ports) at\n  `/dev/c/_/workspaces/<name>#<tab>`; the tab is the hash rather than a path segment, and\n  `pages/WorkspaceDetail.vue` says at the top why that is not cosmetic. Terminal is the same\n  DevTerminal pointed at this pod, running `/seed/shell.sh <session> /app/.sessions/<session>`,\n  so it is a tmux session that survives the browser and a conversation of its own. My Work and\n  Settings are deliberately empty pages describing what they are waiting on, which is a GitHub\n  token in a Secret and shared claude credentials.\n- Editing anything in `pod/` needs three steps, and the third is the one that gets forgotten:\n  edit it in the repo, regenerate the seed, then `scripts/apply-dev-extension-seed.mjs` to put\n  it in the ConfigMap this pod mounts at `/seed`. Without the third it only reaches a fresh pod;\n  patched by hand instead, the extension writes its own copy back over it on the next load.\n- The harness calls a workspace a project. This does not, because Rancher's own nav already\n  uses that word for a group of namespaces in a cluster. The `dev-` namespace prefix is\n  unchanged by that: it names the product, not the concept.\n- The dashboard is reached through the Kubernetes service proxy, not on its own port. Never\n  hardcode a hostname; every URL the build hands out is derived from the proxy path in\n  `/app/vue.config.js`.\n- `yarn` is available. Adding a dependency means an install in here, which is slow and\n  survives only as long as this pod's `/app` does.\n\n## What you can reach from here\n\nThis pod runs as the `barn-extension` ServiceAccount, bound to **cluster-admin**, and `kubectl`\nis installed. So every resource in the cluster this Rancher manages is readable and writable\nfrom a terminal in here, including Rancher's own, which are CRDs in the same apiserver:\n\n```bash\nkubectl get settings.management.cattle.io      # what Rancher is configured to do\nkubectl get projects.management.cattle.io -A   # its grouping of namespaces\nkubectl get clusterrepos.catalog.cattle.io     # where its Apps come from\nkubectl get uiplugins.catalog.cattle.io -A     # extensions installed into its UI\nkubectl api-resources | grep cattle.io         # the rest, and there is a lot of it\n```\n\nThat is deliberate: an extension is mostly a UI over those resources and cannot be tried from a\npane that gets 403 to every question about them. It is also a live Rancher somebody is looking\nat, so read freely and say what you are about to change before you change it.\n\nThe dashboard's own components are the best documentation available and they are already here:\n`/app/node_modules/@rancher/shell/components` and `.../components/form`. `SortableTable`,\n`LabeledSelect`, `AsyncButton`, `Banner`, `AppModal` and `Card` cover most of what a page needs.\nThe published docs are at <https://extensions.rancher.io/extensions/next/home>.\n\n## The browser you can look at it in\n\nEditing here is only half a loop. The other half is a Chromium in this namespace with its\nDevTools protocol open, so you can open the page you just changed and see what it did rather\nthan describing what it should have done. One browser serves every extension in here, and\nsomebody may be watching it, so leave it somewhere sensible and expect tabs you did not open.\n\n**Where to point it.** `https://$NODE_IP$DEV_PROXY_PATH/` - both are set on this pod.\n`DEV_PROXY_PATH` is the service-proxy path this dev server is reached at, and it is\nroot-relative, which means nothing to something driving a browser from outside a page: it has\nto be made absolute. `NODE_IP` is what it is absolute against, and it is Rancher's address\nbecause this cluster is k3s inside the Rancher container - the node and Rancher are one\naddress. Never write a hostname in yourself; those two are the whole URL.\n\n**Where the browser is, and the one trap in it.** `$BARN_BROWSER_SERVICE` names the Service\n(`barn-browser`) and `$BARN_BROWSER_CDP_PORT` its port. You have to resolve that name to an\naddress yourself:\n\n```bash\nCDP=\"http://$(kubectl -n barn get svc \"$BARN_BROWSER_SERVICE\" -o jsonpath='{.spec.clusterIP}'):$BARN_BROWSER_CDP_PORT\"\n```\n\nChromium validates the `Host` header on the debugging port and answers anything that is not an\nIP or `localhost` with a 403, so `http://barn-browser:9222` fails and the ClusterIP works. This\nis also why there is no environment variable holding a ready-made CDP URL: one would look like\nan endpoint and behave like a bug. A pod older than the browser has neither variable; the\nService is `barn-browser` on 9222 either way.\n\n### Getting past the login page\n\nA fresh profile has no Rancher session, so the first navigation lands on Rancher's login page\nrather than your dashboard. Rancher's session is a cookie whose value is an API token, so mint\none from the endpoint the rest of this product uses:\n\n```bash\ncurl -sk -X POST \"https://$NODE_IP/v3-public/localProviders/local?action=login\" \\\n  -H 'Content-Type: application/json' \\\n  -d '{\"username\":\"admin\",\"password\":\"<the admin password>\"}' | jq -r .token\n```\n\nThat token is the whole value of the `R_SESS` cookie. Set it over CDP (`Network.setCookie`,\ndomain `$NODE_IP`) before navigating, and the dashboard loads logged in.\n\nThe password is the one thing this pod is not given. If you have not been told it, ask - do not\nguess, and do not go fishing for it in Secrets you happen to be able to read. The alternative\nthat needs no password is to log in once by hand in the browser's own web UI: the session lives\nin the profile and lasts until that pod restarts, which is usually longer than the work.\n\n### Driving it\n\nNode 24 is what runs here and it has `fetch` and `WebSocket` built in, so this needs no install\n- which matters, because `yarn add` in this pod is slow and survives only as long as `/app`.\n\n```js\nconst cdp = process.env.CDP;                       // resolved as above\nconst url = `https://${ process.env.NODE_IP }${ process.env.DEV_PROXY_PATH }/`;\n\n// A tab of your own rather than the one somebody is looking at.\nconst tab = await (await fetch(`${ cdp }/json/new?${ encodeURIComponent(url) }`, { method: 'PUT' })).json();\n\n// The websocket URL comes back with 127.0.0.1 in it, because that is the address Chromium\n// thinks it is on: it binds CDP to loopback and a forwarder in the pod republishes it. Point\n// it back at the address you reached it on or the connection is refused.\nconst ws = new WebSocket(tab.webSocketDebuggerUrl.replace('ws://127.0.0.1:9222', cdp.replace('http://', 'ws://')));\nlet id = 0;\n\nawait new Promise((ok) => { ws.onopen = ok; });\nconst send = (method, params = {}) => ws.send(JSON.stringify({ id: ++id, method, params }));\n\n// Console output and page errors are most of what you are looking for: a change that failed to\n// compile shows up here long before it shows up in a picture.\nws.onmessage = (e) => console.log(e.data.slice(0, 400));\nsend('Runtime.enable');\nsend('Log.enable');\n```\n\n`Page.captureScreenshot` returns base64 PNG when you want a picture rather than a log. It works\nwith nobody watching because a keepalive service in that pod holds the display open; without it\nthe display collapses to 1x1 and the call hangs rather than failing, which is worth knowing if\nscreenshots ever start timing out.\n\nTwo things about this dev server in particular:\n\n- **A save is not instant.** The compile is a few seconds and the result is pushed to the page\n  over the hot-reload socket. Navigating immediately after a save shows you the old page or a\n  half-compiled one, so wait for the recompile rather than racing it.\n- **Hot reload needs the session too.** That socket rides the same proxy, so it works on every\n  page you are logged in for and not on the login page. A page that never updates is usually a\n  page that is not logged in.\n\n## This tree is not the repo\n\nNothing here is checked out from git and nothing syncs back. The repo copy lives in\n`pkg/barn/dev-extension/` in the barn repo, and it is what a fresh pod is\nseeded from, so a change that should outlive this pod has to be copied back there (and the\nseed regenerated with `node scripts/gen-dev-extension-seed.mjs`).\n\nIf you are asked to make a change permanent and you cannot reach the repo, say so rather\nthan assuming the edit will survive.\n",
    "pkg/dev-extension/api.ts": "/**\n * The Dev product's half of the Claude Harness, expressed in Kubernetes.\n *\n * A workspace is a namespace `dev-<name>` holding a Deployment and a Service, all three\n * labelled with the workspace's name so the list can find them again. Starting and stopping is\n * scaling the Deployment between one replica and none, which is the Kubernetes shape of the\n * harness's `docker start` / `docker stop`; deleting is deleting the namespace, so nothing can\n * be left behind by a resource this file forgot it created.\n *\n * The harness calls this a project. It is a workspace here because Rancher already has\n * projects, and they are a different thing living one nav entry away (see config/constants).\n * The `dev-` namespace prefix is unaffected: that names the product, not the concept.\n *\n * Everything goes through the browser's own Rancher session: same-origin `fetch` against\n * Steve on `/k8s/clusters/<cluster>/v1`, with the CSRF header the API wants on writes. There\n * is no controller and no credential anywhere in here.\n */\nimport {\n  templateById, TEMPLATES, DevTemplate, DevSidecar, GLOBAL_SECRETS, WORKSPACE_WORKDIR, WORKSPACE_HOME,\n  WORKSPACE_QUEUE\n} from './templates';\nimport { MANAGER_RULES } from './rancher-sidecar';\nimport {\n  DevShare, shareName, nginxConf, htpasswd, sharePodSpec\n} from './share';\nimport { WORKSPACE_VUE_CONFIG, WORKSPACE_CONFIG_MOUNT } from './workspace-config';\nimport { INSIGHTS_SERVER } from './insights-server';\nimport { WORKSPACE_API_SERVER } from './workspace-api';\nimport { DevPrompt, DEFAULT_PROMPTS } from './prompts';\nimport { BROWSER_EXTENSION_FILES } from './browser-extension';\n// Which pod this dashboard is being served from. Worked out from the URL rather than written\n// down, because barn runs one of these per named extension - see config/constants.\nimport { DEV_POD_NAMESPACE as POD_NAMESPACE, DEV_POD_SERVICE as POD_SERVICE } from './config/constants';\n\n// The `local` cluster, like the pod this dev server runs in. The product shows no cluster\n// switcher, so there is nothing that could make this a choice.\n/**\n * The cluster every call below is about.\n *\n * A workspace can be hosted on any cluster this Rancher manages, not only the one Rancher runs\n * in, so this is a variable rather than a constant. It is read at call time by the eighty-odd\n * template strings that build a URL, which is why setting it is enough and none of them takes a\n * cluster of its own.\n *\n * One at a time, deliberately. A page is about one workspace, and a workspace is in one cluster,\n * so opening one sets this before it asks anything else and every request that follows agrees.\n * The one thing that is genuinely about several clusters is listing workspaces, and that takes\n * its cluster explicitly (see listWorkspaces) rather than moving this under its own feet.\n */\nconst DEFAULT_CLUSTER = 'local';\n\nlet currentCluster = DEFAULT_CLUSTER;\nlet BASE = clusterBase(DEFAULT_CLUSTER);\n\nexport function clusterBase(cluster: string): string {\n  return `/k8s/clusters/${ cluster }`;\n}\n\n/** Point every call that follows at a cluster. Called when a workspace is opened. */\nexport function setCluster(cluster: string): void {\n  currentCluster = cluster || DEFAULT_CLUSTER;\n  BASE = clusterBase(currentCluster);\n}\n\nexport function activeCluster(): string {\n  return currentCluster;\n}\n\n/** The label a workspace's namespace carries, so its cluster survives a page reload. */\nexport const LABEL_CLUSTER = 'dev.rancher.io/cluster';\n\n/** One cluster this Rancher manages, with enough of its capacity to choose between them. */\nexport interface DevCluster {\n  id: string;\n  name: string;\n  state: string;\n  /** Bytes not asked for by anything, or 0 where the cluster does not say. */\n  memoryFree: number;\n  diskFree: number;\n}\n\n/**\n * Kubernetes quantities as a number of bytes.\n *\n * They arrive as `65166836Ki`, `518Mi` or a bare `466047163641`, and the difference between the\n * three is a suffix rather than a scale anyone would guess. Binary units, which is what the\n * suffix means: Ki is 1024, not 1000.\n */\nfunction bytes(quantity: string): number {\n  const match = /^(\\d+(?:\\.\\d+)?)([KMGTP]i?)?$/.exec(String(quantity || '').trim());\n\n  if (!match) {\n    return 0;\n  }\n\n  const scale: Record<string, number> = {\n    Ki: 1024, Mi: 1024 ** 2, Gi: 1024 ** 3, Ti: 1024 ** 4, Pi: 1024 ** 5,\n    K: 1e3, M: 1e6, G: 1e9, T: 1e12, P: 1e15,\n  };\n\n  return Number(match[1]) * (scale[match[2] || ''] || 1);\n}\n\n/**\n * The clusters a workspace could be hosted on, with what is left on each.\n *\n * Memory comes from Rancher's own view of a cluster, which knows both what its nodes can offer\n * and what the pods already on it have asked for. Disk does not: Rancher does not carry\n * ephemeral storage at the cluster level, so the nodes are asked, and what is reported is what\n * they can allocate rather than what is unclaimed - almost nothing requests ephemeral storage,\n * so the two are the same number in practice and the difference is worth knowing about.\n *\n * A cluster that cannot be reached is still offered, with no numbers beside it. It is a cluster\n * somebody may still want, and refusing to list it would be this page deciding that for them.\n */\nexport async function listClusters(): Promise<DevCluster[]> {\n  const response = await devFetch('/v3/clusters').catch(() => null);\n  const clusters = (response?.data || []).filter((cluster: Json) => cluster.state === 'active');\n\n  return Promise.all(clusters.map(async(cluster: Json) => {\n    const memoryFree = Math.max(0, bytes(cluster.allocatable?.memory) - bytes(cluster.requested?.memory));\n    const [nodes, pods] = await Promise.all([\n      devFetch(`${ clusterBase(cluster.id) }/v1/nodes`).catch(() => null),\n      devFetch(`${ clusterBase(cluster.id) }/v1/pods`).catch(() => null),\n    ]);\n\n    const allocatable = (nodes?.data || [])\n      .reduce((total: number, node: Json) => total + bytes(node.status?.allocatable?.['ephemeral-storage']), 0);\n\n    // What the pods on it have asked for, summed here because Rancher's own `requested` carries\n    // cpu, memory and pods and not this. Almost nothing requests ephemeral storage, so this is\n    // usually nothing at all - but a cluster where something does would otherwise be offered as\n    // having room it has already given away.\n    const requested = (pods?.data || [])\n      .flatMap((pod: Json) => pod.spec?.containers || [])\n      .reduce((total: number, container: Json) => total + bytes(container.resources?.requests?.['ephemeral-storage']), 0);\n\n    return {\n      id:    cluster.id,\n      name:  cluster.name || cluster.id,\n      state: cluster.state,\n      memoryFree,\n      diskFree: Math.max(0, allocatable - requested),\n    };\n  }));\n}\n\n/** A byte count as a person reads it, which is one number and one unit. */\nexport function readableBytes(value: number): string {\n  if (!value) {\n    return 'unknown';\n  }\n\n  const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB'];\n  let scaled = value;\n  let unit = 0;\n\n  while (scaled >= 1024 && unit < units.length - 1) {\n    scaled /= 1024;\n    unit += 1;\n  }\n\n  return `${ scaled >= 10 || unit === 0 ? Math.round(scaled) : scaled.toFixed(1) } ${ units[unit] }`;\n}\n\n/** Everything a workspace owns carries these, and the list is built by filtering on them. */\nexport const LABEL_WORKSPACE = 'dev.rancher.io/workspace';\nexport const LABEL_TEMPLATE = 'dev.rancher.io/template';\n/**\n * Which sidecar a Deployment, Service or pod is, when it is one.\n *\n * Declared here with the other two rather than beside the sidecar code, because its absence is\n * what identifies the workspace's own objects. See ownedByWorkspace.\n */\nexport const LABEL_SIDECAR = 'dev.rancher.io/sidecar';\n\n/**\n * Ask Steve for the labelled things only, rather than for everything.\n *\n * Two query parameters that look like the same feature, and only one of them is: Steve\n * ignores Kubernetes' `labelSelector` and answers with the whole collection anyway (asked for\n * this label, it hands back all two dozen namespaces of this cluster, workspace or not),\n * while its own `filter` does the work, and matches a value exactly rather than by substring.\n *\n * It is an optimisation and only that. Every caller of it filters what comes back as well,\n * because a Steve that ignored this parameter would answer with everything, and that\n * browser-side pass is what keeps such a Steve a slower list rather than a wrong one. Neither\n * half is redundant: this one is the saving, the one below it is the guarantee.\n */\nconst WORKSPACE_FILTER = `filter=metadata.labels[${ LABEL_WORKSPACE }]`;\n\n/**\n * The one container in a workspace's pod. Named here rather than after the template because\n * the terminal has to address it, and a name that varies would make that a lookup.\n */\nexport const WORKSPACE_CONTAINER = 'workspace';\n\n/** Kubernetes name rules, minus the parts a 63-character workspace name cannot reach. */\nconst NAME_PATTERN = /^[a-z0-9]([-a-z0-9]*[a-z0-9])?$/;\nconst MAX_NAME_LENGTH = 40;\n\nexport type WorkspaceState = 'running' | 'stopped' | 'starting' | 'creating' | 'removing' | 'error';\n\nexport interface DevWorkspace {\n  /** The cluster it is hosted on, from its namespace's label. See LABEL_CLUSTER. */\n  cluster: string;\n  name: string;\n  namespace: string;\n  /** The template id. Kept even when it names a template that no longer exists. */\n  template: string;\n  templateLabel: string;\n  state: WorkspaceState;\n  createdAt: string;\n  /**\n   * The image the Deployment actually runs, which is not always the template's: anything can\n   * edit a Deployment after this created it, and a page that reads the image back off the\n   * template would go on describing a container that is no longer there.\n   */\n  image: string;\n  /** What the Deployment is scaled to, and what it actually has. */\n  replicas: number;\n  ready: number;\n  /**\n   * Which minute of a long start this is in, in the pod's own words.\n   *\n   * A workspace that clones a repository, installs it and compiles it is Starting for several\n   * minutes, and \"Starting\" for four minutes is indistinguishable from broken. The pod knows\n   * the difference between pulling an image, waiting to be scheduled, crash-looping and simply\n   * taking a while, so this carries whichever of those it is.\n   */\n  detail: string;\n}\n\n/** A workspace's Service, as it exists rather than as its template described it. */\nexport interface DevService {\n  name: string;\n  port: number;\n  /** The port it is published on the node at, when the template asked for an origin of its own. */\n  nodePort: number;\n}\n\n// Steve hands back plain JSON with no types worth importing, and narrowing it here would only\n// be a second description of the same shapes. The accessors below are the narrowing.\n// eslint-disable-next-line @typescript-eslint/no-explicit-any\ntype Json = any;\n\nfunction csrfHeader(): Record<string, string> {\n  const match = document.cookie.match(/(?:^|;\\s*)CSRF=([^;]*)/);\n\n  return { 'X-Api-Csrf': match ? decodeURIComponent(match[1]) : 'CSRF' };\n}\n\n/**\n * Same-origin request to Rancher, with the CSRF header on anything that writes.\n *\n * Rancher rejects a write without it, and the value is the CSRF cookie the session already\n * set, so this needs nothing the page does not have.\n */\nexport async function devFetch(path: string, init?: RequestInit): Promise<Json> {\n  const write = !!init?.method && init.method !== 'GET';\n  const resp = await fetch(path, {\n    ...init,\n    headers: {\n      'Content-Type': 'application/json',\n      Accept:         'application/json',\n      ...(write ? csrfHeader() : {}),\n      ...(init?.headers || {}),\n    },\n  });\n  const data = await resp.json().catch(() => ({}));\n\n  if (!resp.ok) {\n    throw new Error(data.message || data.error || `HTTP ${ resp.status }`);\n  }\n\n  return data;\n}\n\n/**\n * The namespace a workspace lives in.\n *\n * Still `dev-`, deliberately, through the rename from project to workspace: the prefix says\n * which product owns the namespace, and that product is still Dev.\n */\nexport function workspaceNamespace(name: string): string {\n  return `dev-${ name }`;\n}\n\n/**\n * Why a name is not usable, or '' when it is.\n *\n * Checked before the create rather than left to the apiserver: its own message names the\n * generated namespace and quotes the RFC, which tells someone who typed a capital letter very\n * little about what to type instead.\n */\nexport function workspaceNameError(name: string): string {\n  if (!name) {\n    return 'A name is required';\n  }\n\n  if (name.length > MAX_NAME_LENGTH) {\n    return `A name can be at most ${ MAX_NAME_LENGTH } characters`;\n  }\n\n  if (!NAME_PATTERN.test(name)) {\n    return 'A name can contain only lowercase letters, numbers and dashes, and must start and end with a letter or number';\n  }\n\n  return '';\n}\n\n/**\n * What a pod is doing, from its own status, or '' when there is nothing worth saying.\n *\n * Only the container's own reasons, not a guess: `waiting.reason` is the apiserver's word for\n * it (ImagePullBackOff, CrashLoopBackOff, ContainerCreating), and a container that is running\n * but not ready is one whose startup probe has not passed yet, which for a workspace that\n * installs on boot is the ordinary case rather than a fault.\n */\nfunction podDetail(pod: Json | undefined): string {\n  if (!pod) {\n    return '';\n  }\n\n  if (pod.metadata?.deletionTimestamp) {\n    return 'Terminating';\n  }\n\n  const status = pod.status?.containerStatuses?.[0];\n  const waiting = status?.state?.waiting;\n\n  if (waiting?.reason) {\n    const restarts = status.restartCount ? `, restarted ${ status.restartCount } times` : '';\n\n    return `${ waiting.reason }${ restarts }`;\n  }\n\n  if (pod.status?.phase === 'Pending') {\n    return 'Waiting to be scheduled';\n  }\n\n  if (status?.state?.running && !status.ready) {\n    return status.restartCount ? `Starting up, restarted ${ status.restartCount } times` : 'Starting up';\n  }\n\n  return '';\n}\n\n/**\n * Why a Deployment has no pod at all, in the cluster's own words, or '' when it has one.\n *\n * A pod that never gets created leaves nothing for podDetail to read, so without this the page\n * has only \"Starting\" to show and shows it forever. The controller records the reason on the\n * Deployment as a ReplicaFailure condition, which is where a missing ServiceAccount, a quota and\n * a rejected pod spec all end up, and its message is the apiserver's own sentence.\n */\nfunction replicaFailure(deployment: Json | undefined): string {\n  const condition = (deployment?.status?.conditions || [])\n    .find((entry: Json) => entry.type === 'ReplicaFailure' && entry.status === 'True');\n\n  return condition?.message || '';\n}\n\n/**\n * Container reasons that are a failure rather than a stage of starting.\n *\n * `ImagePullBackOff` has to be named: an image that cannot be pulled alternates between\n * `ErrImagePull` and `ImagePullBackOff`, so a rule that catches only the first leaves the state\n * oscillating between Error and Starting rather than settling on the truth.\n */\nconst FAILED_REASONS = [\n  'CrashLoopBackOff',\n  'ImagePullBackOff',\n  'ErrImagePull',\n  'InvalidImageName',\n  'CreateContainerConfigError',\n  'CreateContainerError',\n];\n\nfunction isFailedReason(reason: string): boolean {\n  return FAILED_REASONS.some((failed) => reason.includes(failed));\n}\n\nfunction stateOf(namespace: Json, deployment: Json | undefined, pod?: Json): WorkspaceState {\n  // A namespace being collected still lists, and its Deployment may outlive it by a moment, so\n  // deletion is asked about first or a workspace would read as Running while it goes away.\n  if (namespace.metadata?.deletionTimestamp) {\n    return 'removing';\n  }\n\n  if (!deployment) {\n    return 'creating';\n  }\n\n  if ((deployment.spec?.replicas ?? 0) === 0) {\n    return 'stopped';\n  }\n\n  if ((deployment.status?.readyReplicas ?? 0) > 0) {\n    return 'running';\n  }\n\n  // A Deployment the controller cannot make a pod for is not starting either, and it is the\n  // case with nothing to look at: no pod, no logs, no events under a name anyone knows.\n  if (!pod && replicaFailure(deployment)) {\n    return 'error';\n  }\n\n  // A pod that keeps dying is not starting, however long you wait, and a workspace that says\n  // Starting through fifty restarts is a workspace nobody looks at the logs of.\n  const reason = pod?.status?.containerStatuses?.[0]?.state?.waiting?.reason || '';\n\n  return isFailedReason(reason) ? 'error' : 'starting';\n}\n\n/**\n * A workspace, out of the namespace that records it and the Deployment that runs it.\n *\n * One function for both readers, so the list and the detail page cannot come to describe the\n * same workspace differently while fetching it two different ways.\n */\nfunction workspaceFrom(namespace: Json, deployment: Json | undefined, pod?: Json, cluster?: string): DevWorkspace {\n  const name = namespace.metadata.labels[LABEL_WORKSPACE];\n  const template = namespace.metadata.labels[LABEL_TEMPLATE] || '';\n\n  return {\n    name,\n    namespace:     namespace.metadata.name,\n    // The label where there is one, and the cluster it was read from otherwise: a workspace made\n    // before this product could host them anywhere is in the cluster it is being listed from.\n    cluster:       namespace.metadata.labels[LABEL_CLUSTER] || cluster || activeCluster(),\n    template,\n    templateLabel: templateById(template)?.label || template || 'Unknown',\n    state:         stateOf(namespace, deployment, pod),\n    createdAt:     namespace.metadata.creationTimestamp,\n    image:         deployment?.spec?.template?.spec?.containers?.[0]?.image || '',\n    replicas:      deployment?.spec?.replicas ?? 0,\n    ready:         deployment?.status?.readyReplicas ?? 0,\n    // The pod's own words where there is a pod, and the controller's where there is not.\n    detail:        podDetail(pod) || (pod ? '' : replicaFailure(deployment)),\n  };\n}\n\n/**\n * Whether a Deployment or a pod is the workspace itself rather than one of its sidecars.\n *\n * A sidecar carries the workspace's label too, deliberately, so that everything a workspace owns\n * can be found by one filter. That makes the label alone the wrong question here, and the two\n * readers of it answered differently: the list built a map with `set` in a loop, so the last\n * sidecar in the collection won, while the detail page used `find`, so the first did. A workspace\n * that had been stopped for an hour read Running in the list, with Stop offered, while its own\n * page offered Start.\n *\n * One predicate for both, and the absence of the sidecar label is what it asks, so a sidecar can\n * never be mistaken for the workspace whatever order the collection arrives in.\n */\nfunction ownedByWorkspace(candidate: Json, name: string): boolean {\n  const labels = candidate?.metadata?.labels || {};\n\n  return labels[LABEL_WORKSPACE] === name && !labels[LABEL_SIDECAR];\n}\n\n/**\n * Every workspace in the cluster.\n *\n * The namespace is the record of a workspace and the Deployment is its state, so both are\n * fetched and joined here: a workspace that is being created has no Deployment yet, and one\n * being deleted has a namespace that outlives it. Both collections are asked for by label\n * (see WORKSPACE_FILTER) and filtered again below, which is a saving on a cluster of any size\n * and no change to what this returns.\n */\nexport async function listWorkspaces(cluster?: string): Promise<DevWorkspace[]> {\n  // Explicit rather than through BASE, because this is the one thing in the product that asks\n  // about a cluster other than the one being looked at: see listAllWorkspaces, which calls it\n  // once per cluster and must not move BASE under whatever else is in flight.\n  const from = clusterBase(cluster || activeCluster());\n  const [namespaces, deployments, pods] = await Promise.all([\n    devFetch(`${ from }/v1/namespaces?${ WORKSPACE_FILTER }`),\n    devFetch(`${ from }/v1/apps.deployments?${ WORKSPACE_FILTER }`),\n    // The third collection is what turns \"Starting\" into which part of starting. One request\n    // for every workspace's pod, not one per workspace, so the list costs the same as it did.\n    devFetch(`${ from }/v1/pods?${ WORKSPACE_FILTER }`).catch(() => null),\n  ]);\n\n  const byWorkspace = new Map<string, Json>();\n  const podByWorkspace = new Map<string, Json>();\n\n  for (const deployment of deployments.data || []) {\n    const workspace = deployment.metadata?.labels?.[LABEL_WORKSPACE];\n\n    if (workspace && ownedByWorkspace(deployment, workspace)) {\n      byWorkspace.set(workspace, deployment);\n    }\n  }\n\n  for (const pod of pods?.data || []) {\n    const workspace = pod.metadata?.labels?.[LABEL_WORKSPACE];\n\n    if (workspace && ownedByWorkspace(pod, workspace)) {\n      podByWorkspace.set(workspace, pod);\n    }\n  }\n\n  return (namespaces.data || [])\n    .filter((namespace: Json) => !!namespace.metadata?.labels?.[LABEL_WORKSPACE])\n    .map((namespace: Json) => {\n      const name = namespace.metadata.labels[LABEL_WORKSPACE];\n\n      return workspaceFrom(namespace, byWorkspace.get(name), podByWorkspace.get(name), cluster);\n    })\n    .sort((a: DevWorkspace, b: DevWorkspace) => a.name.localeCompare(b.name));\n}\n\n/**\n * Every workspace this person has, on every cluster.\n *\n * What the sidebar shows, because a workspace is a person's rather than a cluster's: somebody\n * with one on each of two clusters wants one list. A cluster that cannot be read contributes\n * nothing rather than taking the list down with it, which is the ordinary case for somebody with\n * access to one cluster out of several.\n */\nexport async function listAllWorkspaces(): Promise<DevWorkspace[]> {\n  const clusters = await listClusters().catch(() => []);\n  const lists = await Promise.all(\n    (clusters.length ? clusters.map((cluster) => cluster.id) : [activeCluster()])\n      .map((id) => listWorkspaces(id).catch(() => [] as DevWorkspace[])),\n  );\n\n  return lists.flat().sort((a, b) => a.name.localeCompare(b.name));\n}\n\n/**\n * One workspace, or null if it is not there.\n *\n * Its own namespace and that namespace's Deployment, not listWorkspaces filtered down: a\n * workspace already knows where it lives, and the detail page asks this every five seconds.\n * Through the list it would be every workspace in the cluster, twice, to read one back.\n *\n * The Deployment comes from the namespace's collection rather than by name for the reason\n * workspaceService does the same: a workspace in the moment between its namespace and its\n * Deployment answers 200 with nothing in it instead of a 404 the console keeps. The namespace\n * itself is asked for by name, where a 404 is the honest answer to a workspace that has been\n * deleted, and is what puts the page's \"there is no workspace called ...\" banner up.\n */\nexport async function getWorkspace(name: string): Promise<DevWorkspace | null> {\n  const namespace = workspaceNamespace(name);\n  const [record, deployments, pods] = await Promise.all([\n    devFetch(`${ BASE }/v1/namespaces/${ namespace }`).catch(() => null),\n    devFetch(`${ BASE }/v1/apps.deployments/${ namespace }`).catch(() => null),\n    devFetch(`${ BASE }/v1/pods/${ namespace }`).catch(() => null),\n  ]);\n\n  // A namespace without the label is not a workspace, whatever it is called.\n  if (record?.metadata?.labels?.[LABEL_WORKSPACE] !== name) {\n    return null;\n  }\n\n  const deployment = (deployments?.data || []).find((candidate: Json) => ownedByWorkspace(candidate, name));\n  const pod = (pods?.data || []).find((candidate: Json) => ownedByWorkspace(candidate, name));\n\n  return workspaceFrom(record, deployment, pod);\n}\n\n/**\n * The two things a template's environment cannot know until it is a workspace.\n *\n * `{{proxyPath}}` is where this dev server is reached, which is empty for a workspace served at\n * its own origin. `{{ownRancher}}` is the in-cluster address of the Rancher this workspace's own\n * sidecar serves, and it is written in from the moment the workspace is created rather than\n * swapped in when the sidecar starts.\n *\n * That ordering is the whole point. A workspace at its own origin publishes a node port, and the\n * dev server behind it proxies /v1 and /v3 to whatever API names. Pointed at the host by default,\n * that is an unauthenticated path from the node's address into the cluster this product runs in,\n * open for as long as nobody has started the workspace's own Rancher. Pointed at its own Rancher\n * from the start, the worst it can do before that Rancher exists is refuse the connection.\n */\nfunction substituteTemplateEnv(value: string, name: string, template: DevTemplate): string {\n  const owns = (template.sidecars || []).find((sidecar) => sidecar.providesApi);\n\n  return value\n    .replace('{{proxyPath}}', template.ownOrigin ? '' : workspaceProxyUrl(name, template.port, template.scheme))\n    .replace('{{ownRancher}}', owns ? sidecarServiceUrl(name, owns) : '');\n}\n\nfunction deploymentBody(name: string, template: DevTemplate): Json {\n  const namespace = workspaceNamespace(name);\n  const labels = { app: namespace, [LABEL_WORKSPACE]: name, [LABEL_TEMPLATE]: template.id };\n\n  return {\n    apiVersion: 'apps/v1',\n    kind:       'Deployment',\n    metadata:   { namespace, name: namespace, labels },\n    spec:       {\n      replicas: 1,\n      selector: { matchLabels: { app: namespace } },\n      // Recreate rather than RollingUpdate: the checkout is a hostPath, so two pods would be\n      // installing into the same directory at the same time.\n      strategy: { type: 'Recreate' },\n      template: {\n        metadata: { labels },\n        spec:     {\n          // Not the namespace's default ServiceAccount: a workspace runs whatever a template\n          // or a person put in it, and this is the identity that says what that is allowed to\n          // reach (see ensureDevRbac).\n          serviceAccountName: WORKSPACE_SERVICE_ACCOUNT,\n          containers:         [{\n            name:  WORKSPACE_CONTAINER,\n            image: template.image,\n            ...(template.command ? { command: template.command } : {}),\n            ports: [{ name: 'http', containerPort: template.port }],\n            // `{{proxyPath}}` is the one substitution a template gets: the path this workspace\n            // is reached at, which contains its own name.\n            env:   Object.entries(template.env || {}).map(([envName, value]) => ({\n              name:  envName,\n              value: substituteTemplateEnv(value, name, template),\n            })),\n            // The workspace's own secrets, by reference and as a whole Secret rather than key by\n            // key. A named list would be fixed at create time, so a key added in Settings later\n            // would need the Deployment rewritten; this way the mirror is the list, and it is\n            // rewritten before every start. `optional` so a workspace with nothing set still runs.\n            envFrom: [{ secretRef: { name: MIRROR_SECRET, optional: true } }],\n            volumeMounts: [\n              ...(template.hostPath ? [{ name: 'work', mountPath: '/workspace' }] : []),\n              // Read-only, and copied rather than mounted over the checkout: a workspace is an\n              // ordinary clone someone can edit, and a file mounted into it could not be.\n              { name: 'dev-config', mountPath: WORKSPACE_CONFIG_MOUNT, readOnly: true },\n              // What a terminal tab runs. Mounted rather than copied, and read straight out of\n              // the mount, so a workspace always starts the scripts the extension last wrote\n              // without needing a pod restart to pick them up.\n              { name: 'terminal', mountPath: WORKSPACE_TERMINAL_MOUNT, readOnly: true },\n            ],\n            // A first boot is a clone, an install and a compile, which is minutes. A startup\n            // probe with a long budget is what stops the kubelet killing a pod that is working,\n            // and killing it is not harmless: it throws away a part-finished install.\n            ...(template.hostPath ? {\n              // A TCP probe rather than an HTTP one: what this is waiting for is the dev server\n              // binding its port, and asking it for a page instead means knowing which paths it\n              // serves and on which scheme, which is the template's business and not the\n              // kubelet's.\n              startupProbe: {\n                tcpSocket:        { port: template.port },\n                periodSeconds:    10,\n                failureThreshold: 120,\n              },\n              readinessProbe: { tcpSocket: { port: template.port }, periodSeconds: 10 },\n            } : {}),\n          }],\n          volumes: [\n            ...(template.hostPath ? [{\n              name:     'work',\n              hostPath: { path: `${ template.hostPath }/${ name }`, type: 'DirectoryOrCreate' },\n            }] : []),\n            { name: 'dev-config', configMap: { name: WORKSPACE_CONFIG_MAP } },\n            // Executable: these are scripts run out of the mount, and a ConfigMap's default\n            // mode is 0644, which is a terminal that opens on \"permission denied\".\n            {\n              name: 'terminal', configMap: { name: WORKSPACE_TERMINAL_MAP, defaultMode: 0o555, optional: true }\n            },\n          ],\n        },\n      },\n    },\n  };\n}\n\n/**\n * Why this name cannot be used right now, or '' when it can.\n *\n * The companion to workspaceNameError, which answers the same question about the shape of a\n * name without asking the cluster. Left to the apiserver, all three cases below come back as\n * one sentence about namespaces, and the most confusing of them (a workspace still being\n * collected, which will free the name shortly) is the one it explains least.\n */\nasync function workspaceNameConflict(name: string): Promise<string> {\n  const namespace = workspaceNamespace(name);\n\n  // The collection rather than a GET of the one namespace, which would be the obvious way to\n  // ask. A namespace that is not there answers 404, and the browser prints every 404 to the\n  // console whether or not the caller expected it, so the obvious way leaves an error in the\n  // log of every successful create. Filtered to the one name, so keeping that quiet costs a\n  // request of a couple of hundred bytes rather than a list of every namespace in the\n  // cluster. As above the filter is the saving and the `find` is what decides.\n  const url = `${ BASE }/v1/namespaces?filter=metadata.name=${ namespace }`;\n  const namespaces = await devFetch(url);\n  const existing = (namespaces.data || []).find((ns: Json) => ns.metadata?.name === namespace);\n\n  if (!existing) {\n    return '';\n  }\n\n  if (existing.metadata?.labels?.[LABEL_WORKSPACE] !== name) {\n    return `The namespace ${ namespace } already exists and is not a workspace. Pick another name.`;\n  }\n\n  if (existing.metadata?.deletionTimestamp) {\n    return `A workspace called \"${ name }\" is still being deleted. Wait for it to finish, or pick another name.`;\n  }\n\n  return `A workspace called \"${ name }\" already exists.`;\n}\n\n/**\n * Create a workspace: the namespace, then the Deployment and the Service in it.\n *\n * In that order and awaited, because the other two cannot be created before the namespace\n * exists. Nothing is rolled back if a later step fails: the namespace is left, the list shows\n * the workspace as Creating, and deleting it is one click. Tearing down half a workspace on\n * the user's behalf would be a guess about which half they wanted.\n */\nexport async function createWorkspace(name: string, templateId: string, cluster?: string): Promise<void> {\n  // Everything below builds a URL from BASE, so the cluster is chosen once here rather than\n  // threaded through a dozen calls. It stays set afterwards, which is what the page wants: it\n  // navigates to the workspace it just made.\n  if (cluster) {\n    setCluster(cluster);\n  }\n\n  const template = templateById(templateId);\n\n  if (!template) {\n    throw new Error(`Unknown template \"${ templateId }\"`);\n  }\n\n  // A check, not a guarantee: two people creating the same name at once still race, and the\n  // loser gets the apiserver's 409. This is here so the ordinary case, one person picking a\n  // name that is taken, reads as a sentence about workspaces rather than one about namespaces.\n  const conflict = await workspaceNameConflict(name);\n\n  if (conflict) {\n    throw new Error(conflict);\n  }\n\n  const namespace = workspaceNamespace(name);\n  const labels = {\n    [LABEL_WORKSPACE]: name, [LABEL_TEMPLATE]: template.id, [LABEL_CLUSTER]: activeCluster(),\n  };\n\n  await devFetch(`${ BASE }/v1/namespaces`, {\n    method: 'POST',\n    body:   JSON.stringify({\n      apiVersion: 'v1',\n      kind:       'Namespace',\n      metadata:   { name: namespace, labels },\n    }),\n  });\n\n  // Before the Deployment, because a pod cannot start with a ServiceAccount that is not there\n  // yet, and after the namespace, because that is where most of it lives.\n  await ensureWorkspaceRbac(name);\n\n  // The dev server's config, which is the one file a workspace does not get from git. See\n  // workspace-config.ts for what is in it and why a clone's own config will not do.\n  await devFetch(`${ BASE }/v1/configmaps`, {\n    method: 'POST',\n    body:   JSON.stringify({\n      apiVersion: 'v1',\n      kind:       'ConfigMap',\n      metadata:   { namespace, name: WORKSPACE_CONFIG_MAP, labels },\n      data:       { 'vue.config.js': WORKSPACE_VUE_CONFIG },\n    }),\n  });\n\n  // What a terminal tab runs, before the pod that mounts it. See ensureWorkspaceTerminal.\n  await ensureWorkspaceTerminal(name);\n\n  // Before the Deployment, so the pod's first start already has whatever is in the store. It is\n  // rewritten on every start as well, since the store can change after this.\n  const store = await ensureGeneratedSecrets(template);\n\n  await mirrorSecrets(name, template, store);\n\n  await devFetch(`${ BASE }/v1/apps.deployments`, {\n    method: 'POST',\n    body:   JSON.stringify(deploymentBody(name, template)),\n  });\n\n  await devFetch(`${ BASE }/v1/services`, {\n    method: 'POST',\n    body:   JSON.stringify(workspaceServiceBody(name, template)),\n  });\n}\n\n/**\n * The workspace's Service.\n *\n * NodePort rather than ClusterIP when the template needs an origin of its own, which is the whole\n * of what \"its own origin\" costs: the port is open on the node to anyone who can reach it, with no\n * Rancher session in front of it. The Browser tab says so where it offers the link, and the\n * workspace's API address is its own Rancher rather than this cluster's precisely because of it.\n */\nfunction workspaceServiceBody(name: string, template: DevTemplate): Json {\n  const namespace = workspaceNamespace(name);\n  const labels = { [LABEL_WORKSPACE]: name, [LABEL_TEMPLATE]: template.id };\n\n  return {\n    apiVersion: 'v1',\n    kind:       'Service',\n    metadata:   { namespace, name: namespace, labels },\n    spec:       {\n      ...(template.ownOrigin ? { type: 'NodePort' } : {}),\n      selector: { app: namespace },\n      ports:    [{ name: 'http', port: template.port, targetPort: 'http' }],\n    },\n  };\n}\n\n/**\n * Start or stop a workspace by scaling its Deployment.\n *\n * Read-modify-write rather than a patch: Steve wants the whole object back on a PUT, and\n * sending the one it just handed out is what keeps the resourceVersion check meaningful, so a\n * second tab scaling the same workspace loses the race instead of silently winning it.\n */\nexport async function setWorkspaceRunning(name: string, running: boolean): Promise<void> {\n  const namespace = workspaceNamespace(name);\n  const url = `${ BASE }/v1/apps.deployments/${ namespace }/${ namespace }`;\n\n  if (running) {\n    // Every start, not only the first. The pod reads its environment once, when it starts, so\n    // this is the only moment a key set since the last start can reach it.\n    const template = templateById((await devFetch(url)).metadata?.labels?.[LABEL_TEMPLATE] || '');\n\n    await mirrorSecrets(name, template);\n    // And the same moment is when a workspace made before this version of the product can be\n    // brought into line, since all of it is read when the pod starts and only then.\n    await bringWorkspaceUpToDate(name, template);\n  }\n\n  // Read after all of that, never before it. bringWorkspaceUpToDate writes the same Deployment,\n  // so a copy fetched at the top of this function is stale by the time it gets here, and Steve\n  // answers a stale resourceVersion with a 409: the workspace is brought up to date and then\n  // does not start, with nothing on the page to say why. It was invisible for as long as that\n  // function usually found nothing to change.\n  const deployment = await devFetch(url);\n\n  deployment.spec.replicas = running ? 1 : 0;\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify(deployment) });\n}\n\n/**\n * Bring a workspace's Service and dev server into line with the origin its template asks for.\n *\n * Both halves have to agree or neither works: a dev server built with a router base of the proxy\n * prefix hangs on its loading spinner when it is loaded at a node port (measured, and it makes no\n * API calls at all), and one built with no prefix has every in-app link pointing at the root of\n * Rancher's origin when it is loaded through the proxy.\n *\n * Done at start rather than continuously, because both are read when the pod starts, and only\n * when something actually differs, so starting a workspace that is already right does not restart\n * it for nothing.\n */\n/**\n * The dev server config a workspace boots with, brought up to date.\n *\n * Written on every start rather than only at create, for the reason the sidecar scripts are: the\n * file is this repo's, the workspace copies it in on boot, and a workspace made a week ago would\n * otherwise go on booting last week's copy for ever. It is not academic. The version that only\n * wrote it at create left a workspace crash-looping on `DEV_PROXY_PATH must be set` after the\n * config learned to do without one, because the pod had the old file and the new environment.\n */\nasync function ensureWorkspaceConfig(name: string): Promise<void> {\n  const namespace = workspaceNamespace(name);\n  const url = `${ BASE }/v1/configmaps/${ namespace }/${ WORKSPACE_CONFIG_MAP }`;\n  const existing = await devFetch(url).catch(() => null);\n  const data = { 'vue.config.js': WORKSPACE_VUE_CONFIG };\n\n  // Created when it is not there, not skipped. A workspace whose ConfigMap has gone - deleted by\n  // hand, or lost with a create that got part way - crash-loops on `cp: cannot stat\n  // /dev-config/vue.config.js`, and the one function whose job is bringing a workspace up to\n  // date was walking past the reason.\n  if (!existing) {\n    await devFetch(`${ BASE }/v1/configmaps`, {\n      method: 'POST',\n      body:   JSON.stringify({\n        apiVersion: 'v1',\n        kind:       'ConfigMap',\n        metadata:   { namespace, name: WORKSPACE_CONFIG_MAP },\n        data,\n      }),\n    }).catch(() => null);\n\n    return;\n  }\n\n  if (existing.data?.['vue.config.js'] === WORKSPACE_VUE_CONFIG) {\n    return;\n  }\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data }) });\n}\n\n/**\n * The terminal scripts, in the workspace's namespace and up to date.\n *\n * Rewritten on every start rather than created once, for the reason the dev server config is:\n * the scripts are this repo's, and a workspace made a week ago would otherwise go on running\n * last week's copy of them for ever.\n *\n * It fails quietly. A person whose Rancher session cannot read the barn namespace can\n * still start a workspace; what they get is a pod without the scripts, which is a terminal that\n * says claude is not installed rather than a workspace that will not boot.\n */\nasync function ensureWorkspaceTerminal(name: string): Promise<void> {\n  const namespace = workspaceNamespace(name);\n  const seed = await devFetch(`${ BASE }/v1/configmaps/${ SEED_NAMESPACE }/${ SEED_CONFIG_MAP }`).catch(() => null);\n  const data: Record<string, string> = {};\n\n  for (const file of TERMINAL_FILES) {\n    if (seed?.data?.[file]) {\n      data[file] = seed.data[file];\n    }\n  }\n\n  // Nothing to write is not the same as writing nothing: an empty ConfigMap here would replace a\n  // good copy with one that cannot open a terminal.\n  if (!Object.keys(data).length) {\n    return;\n  }\n\n  const url = `${ BASE }/v1/configmaps/${ namespace }/${ WORKSPACE_TERMINAL_MAP }`;\n  const existing = await devFetch(url).catch(() => null);\n\n  if (!existing) {\n    await devFetch(`${ BASE }/v1/configmaps`, {\n      method: 'POST',\n      body:   JSON.stringify({\n        apiVersion: 'v1',\n        kind:       'ConfigMap',\n        metadata:   { namespace, name: WORKSPACE_TERMINAL_MAP },\n        data,\n      }),\n    }).catch(() => null);\n\n    return;\n  }\n\n  if (TERMINAL_FILES.every((file) => existing.data?.[file] === data[file])) {\n    return;\n  }\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data }) }).catch(() => null);\n}\n\n/**\n * Everything about a workspace that this product has since changed its mind about, applied.\n *\n * Called from both places a workspace's pod is about to start or restart, which is the only\n * moment any of it can take effect: starting the workspace, and starting the Rancher sidecar that\n * restarts it. Having it on only one of those is how starting a sidecar came to give somebody a\n * restarted workspace that was still in proxy mode with its dashboard calling the host.\n *\n * It reads and writes the Deployment itself rather than taking one, because its two callers reach\n * it from different directions, and it only writes when something is actually different, so a\n * workspace that is already right is not restarted for nothing.\n */\nasync function bringWorkspaceUpToDate(name: string, template: DevTemplate | undefined): Promise<void> {\n  const namespace = workspaceNamespace(name);\n\n  await ensureWorkspaceConfig(name);\n  await ensureWorkspaceTerminal(name);\n  await ensureWorkspaceService(name, template);\n\n  // The address a conversation in this workspace posts what it learns to. Written on every start\n  // for the same reason the rest of this function exists: the database is per person and outlives\n  // any one workspace, so a workspace made before it existed has to be told about it.\n  const insights = await insightsServiceUrl().catch(() => '');\n\n  const url = `${ BASE }/v1/apps.deployments/${ namespace }/${ namespace }`;\n  const deployment = await devFetch(url).catch(() => null);\n  const container = deployment?.spec?.template?.spec?.containers?.[0];\n\n  if (!container) {\n    return;\n  }\n\n  let changed = false;\n\n  // A workspace created before the mirror existed has no reference to it, so nothing in it ever\n  // sees a secret however many times the mirror is rewritten.\n  if (!container.envFrom) {\n    container.envFrom = [{ secretRef: { name: MIRROR_SECRET, optional: true } }];\n    changed = true;\n  }\n\n  // Not from the template: which database this is depends on who is looking, which a template\n  // cannot know. `INSIGHTS_URL` is the name the harness's own agents already use.\n  if (insights) {\n    const entry = (container.env || []).find((candidate: Json) => candidate.name === 'INSIGHTS_URL');\n\n    if (!entry) {\n      container.env = [...(container.env || []), { name: 'INSIGHTS_URL', value: insights }];\n      changed = true;\n    } else if (entry.value !== insights) {\n      entry.value = insights;\n      changed = true;\n    }\n  }\n\n  // The environment its template describes today, which is where the API address lives.\n  for (const [envName, value] of Object.entries(template?.env || {})) {\n    const wanted = substituteTemplateEnv(value, name, template!);\n    const entry = (container.env || []).find((candidate: Json) => candidate.name === envName);\n\n    if (entry && entry.value !== wanted) {\n      entry.value = wanted;\n      changed = true;\n    }\n  }\n\n  // The image and the command its template describes today, together and never one without the\n  // other. What a workspace runs is the template's, and a workspace made before the template\n  // learned to install claude would otherwise never learn it.\n  //\n  // Together is the part that is not a tidiness: they are one decision. The version that brought\n  // the command up to date and left the image alone put node's setpriv arguments in front of a\n  // busybox that has a different setpriv, and the workspace crash-looped printing that applet's\n  // usage. A container's command only means anything in the image it was written for.\n  if (template?.image && container.image !== template.image) {\n    container.image = template.image;\n    changed = true;\n  }\n\n  if (template?.command && JSON.stringify(container.command) !== JSON.stringify(template.command)) {\n    container.command = template.command;\n    changed = true;\n  }\n\n  // The terminal scripts, for a workspace whose Deployment predates them. Without the volume the\n  // ConfigMap this just wrote is in the namespace and reaches nothing.\n  const pod = deployment.spec.template.spec;\n\n  if (!(pod.volumes || []).some((volume: Json) => volume.name === 'terminal')) {\n    pod.volumes = [...(pod.volumes || []), {\n      name: 'terminal', configMap: { name: WORKSPACE_TERMINAL_MAP, defaultMode: 0o555, optional: true }\n    }];\n    container.volumeMounts = [...(container.volumeMounts || []), {\n      name: 'terminal', mountPath: WORKSPACE_TERMINAL_MOUNT, readOnly: true\n    }];\n    changed = true;\n  }\n\n  if (changed) {\n    await devFetch(url, { method: 'PUT', body: JSON.stringify(deployment) });\n  }\n}\n\n/**\n * The workspace's Service: present, and of the type its template needs.\n *\n * Created here as well as at create time, because a create that failed after the namespace left a\n * workspace permanently without one and nothing ever put it back.\n */\nasync function ensureWorkspaceService(name: string, template: DevTemplate | undefined): Promise<void> {\n  if (!template) {\n    return;\n  }\n\n  const namespace = workspaceNamespace(name);\n  const url = `${ BASE }/v1/services/${ namespace }/${ namespace }`;\n  const service = await devFetch(url).catch(() => null);\n\n  if (!service) {\n    await devFetch(`${ BASE }/v1/services`, {\n      method: 'POST',\n      body:   JSON.stringify(workspaceServiceBody(name, template)),\n    }).catch(() => null);\n\n    return;\n  }\n\n  if (template.ownOrigin && service.spec?.type !== 'NodePort') {\n    service.spec.type = 'NodePort';\n    await devFetch(url, { method: 'PUT', body: JSON.stringify(service) });\n  }\n}\n\n/**\n * Where a workspace answers inside the cluster, which is an origin of its own without a node port.\n *\n * The node port exists so that a person's own browser can reach a workspace at an origin that is\n * not Rancher's. A browser that is itself in the cluster does not need one: the Service is already\n * an origin of its own from in there, and it is one nothing outside the cluster can reach. So this\n * is what the browser sidecar is pointed at, and it is why that sidecar makes a workspace usable\n * without publishing anything.\n */\nexport function workspaceServiceUrl(name: string, template: DevTemplate): string {\n  const namespace = workspaceNamespace(name);\n\n  return `${ workspaceScheme(template) }://${ namespace }.${ namespace }.svc:${ template.port }/`;\n}\n\n/**\n * What a workspace's own port actually speaks, which is not what the template's `scheme` says.\n *\n * `scheme` is the proxy's half of the arrangement and stays http on purpose: Rancher terminates\n * the TLS and will not talk to the shell's self-signed dev certificate on the way through. At its\n * own origin there is no proxy in the way and the same dev server serves https instead (see\n * workspace-config.ts, which explains why: on http the session cookie Rancher issues is dropped).\n *\n * One function because two callers got this wrong in the same direction. The Ports tab asked the\n * proxy over http whether an own-origin workspace was answering, got the proxy's own failure back,\n * and printed \"Nothing yet\" beside a workspace that was serving.\n */\nexport function workspaceScheme(template: DevTemplate | undefined): string {\n  return template?.ownOrigin ? 'https' : (template?.scheme || 'http');\n}\n\n/**\n * The address a published port answers on, which is the node's own.\n *\n * This used to be `window.location.hostname`, on the argument that the browser had just reached\n * Rancher at it so it could reach a node port at it too. That argument is wrong the moment the\n * two are not the same machine, and here they never are: Rancher is reached at a name that\n * resolves on its own network and nowhere else, so every published port this product offered was\n * a link that only worked from inside. What a node port is *for* is being reachable from outside,\n * so the address has to be the node's.\n *\n * ExternalIP first and InternalIP after it, which is the order kubectl's own `-o wide` uses: a\n * cloud node has both and only the first is routable from off the cluster, and a bare-metal or\n * dev node has only the second, which is still the best address there is. Any node's will do,\n * because a NodePort is opened on every node, so this does not need to know which one the pod\n * landed on.\n *\n * Cached for the life of the page. Node addresses do not change, and this is asked once per row\n * of the Ports tab.\n */\nlet nodeAddressPromise: Promise<string> | null = null;\n\nexport function nodeAddress(): Promise<string> {\n  nodeAddressPromise = nodeAddressPromise || (async() => {\n    const nodes = await devFetch(`${ BASE }/v1/nodes`).catch(() => null);\n    const addresses = (nodes?.data || []).flatMap((node: Json) => node.status?.addresses || []);\n    const of = (type: string) => addresses.find((entry: Json) => entry.type === type)?.address;\n\n    // The page's own host is the last resort rather than the first. It is wrong, but a row with\n    // no address at all is worse, and this is the case where the person cannot read the nodes.\n    return of('ExternalIP') || of('InternalIP') || window.location.hostname;\n  })();\n\n  return nodeAddressPromise;\n}\n\n/**\n * Where a workspace is reachable when its template asked for an origin of its own.\n *\n * The host is passed in rather than awaited here, because the two callers are tables and a table\n * cell cannot await: they resolve nodeAddress() once when they refresh and hand it to every row.\n *\n * https, on the dev server's own self-signed certificate. See workspace-config.ts: over http the\n * session cookie Rancher issues is dropped and the login silently fails.\n */\nexport function workspaceOriginUrl(service: DevService | null, host: string): string {\n  if (!service?.nodePort || !host) {\n    return '';\n  }\n\n  return `https://${ host }:${ service.nodePort }/`;\n}\n\n/**\n * Delete the namespace, which takes the Deployment, the Service and the pod with it.\n *\n * The one thing the namespace does not take is the RoleBinding that let this workspace read the\n * shared credentials, since that lives in the product's own namespace. It is deleted here so a\n * deleted workspace leaves nothing behind that names it.\n */\nexport async function deleteWorkspace(name: string): Promise<void> {\n  const namespace = workspaceNamespace(name);\n  const binding = `creds-${ WORKSPACE_SERVICE_ACCOUNT }-${ namespace }`;\n\n  await devFetch(`${ BASE }/v1/namespaces/${ namespace }`, { method: 'DELETE' });\n  await devFetch(`${ BASE }/v1/rbac.authorization.k8s.io.rolebindings/${ DEV_SYSTEM_NAMESPACE }/${ binding }`, { method: 'DELETE' }).catch(() => null);\n}\n\n/**\n * A running pod in a namespace carrying all of the given labels, or null while there isn't\n * one.\n *\n * A terminal needs a pod by name because exec is a subresource of the pod, not of the\n * Deployment or the Service. `Running` is the bar rather than `Ready`: a pod that is up but\n * failing its probes is exactly the one someone wants a shell in, and the pod this dashboard\n * is served from is not Ready until it has finished compiling, which is minutes.\n *\n * Steve ignores labelSelector (see WORKSPACE_FILTER), so the matching is done here.\n */\nexport async function findPod(namespace: string, labels: Record<string, string>, own?: string): Promise<string | null> {\n  const pods = await devFetch(`${ BASE }/v1/pods/${ namespace }`).catch(() => null);\n\n  const running = (pods?.data || []).find((pod: Json) => (\n    Object.entries(labels).every(([key, value]) => pod.metadata?.labels?.[key] === value) &&\n    // A workspace's sidecars are in its namespace and carry its label, so without this a terminal\n    // could open in whichever of them the collection happened to list first.\n    (!own || ownedByWorkspace(pod, own)) &&\n    pod.status?.phase === 'Running' &&\n    !pod.metadata?.deletionTimestamp\n  ));\n\n  return running?.metadata?.name || null;\n}\n\n/** The pod running a workspace itself, or null while there isn't one. */\nexport function workspacePod(name: string): Promise<string | null> {\n  return findPod(workspaceNamespace(name), { [LABEL_WORKSPACE]: name }, name);\n}\n\n/**\n * How long each workspace took to become ready, and how often it has restarted.\n *\n * The Deployment records when it last became Available, and the namespace records when the\n * workspace was created, so the difference is the boot this cluster actually delivered. It is\n * the Deployment's own history rather than anything kept here, which is why it survives this\n * page never having been open before.\n */\nexport async function workspaceReadyTimes(names: string[]): Promise<Record<string, { seconds: number | null; restarts: number }>> {\n  if (!names.length) {\n    return {};\n  }\n\n  const [namespaces, deployments, pods] = await Promise.all([\n    devFetch(`${ BASE }/v1/namespaces?${ WORKSPACE_FILTER }`).catch(() => null),\n    devFetch(`${ BASE }/v1/apps.deployments?${ WORKSPACE_FILTER }`).catch(() => null),\n    devFetch(`${ BASE }/v1/pods?${ WORKSPACE_FILTER }`).catch(() => null),\n  ]);\n\n  const createdAt: Record<string, number> = {};\n  const out: Record<string, { seconds: number | null; restarts: number }> = {};\n\n  for (const namespace of namespaces?.data || []) {\n    const name = namespace.metadata?.labels?.[LABEL_WORKSPACE];\n\n    if (name) {\n      createdAt[name] = Date.parse(namespace.metadata.creationTimestamp);\n    }\n  }\n\n  for (const name of names) {\n    out[name] = { seconds: null, restarts: 0 };\n  }\n\n  for (const deployment of deployments?.data || []) {\n    const name = deployment.metadata?.labels?.[LABEL_WORKSPACE];\n\n    // The workspace's own Deployment, not a sidecar's. See ownedByWorkspace.\n    if (!name || !ownedByWorkspace(deployment, name)) {\n      continue;\n    }\n\n    const available = (deployment.status?.conditions || [])\n      .find((condition: Json) => condition.type === 'Available' && condition.status === 'True');\n\n    if (name && available && createdAt[name]) {\n      const seconds = Math.round((Date.parse(available.lastTransitionTime) - createdAt[name]) / 1000);\n\n      // A workspace that was stopped and started again transitions to Available a second time,\n      // which is not a boot from nothing. Only a positive, plausible first interval is kept.\n      out[name] = { ...out[name], seconds: seconds > 0 ? seconds : null };\n    }\n  }\n\n  for (const pod of pods?.data || []) {\n    const name = pod.metadata?.labels?.[LABEL_WORKSPACE];\n    const restarts = pod.status?.containerStatuses?.[0]?.restartCount || 0;\n\n    if (name && ownedByWorkspace(pod, name) && out[name]) {\n      out[name] = { ...out[name], restarts };\n    }\n  }\n\n  return out;\n}\n\n/** Warnings from the workspaces' namespaces, newest first. */\nexport async function workspaceEvents(names: string[]): Promise<Json[]> {\n  const results = await Promise.all(names.map((name) => (\n    devFetch(`${ BASE }/v1/events/${ workspaceNamespace(name) }`)\n      .then((events: Json) => ({ name, events }))\n      .catch(() => ({ name, events: { data: [] } }))\n  )));\n\n  const out: Json[] = [];\n\n  for (const { name, events } of results) {\n    for (const event of events.data || []) {\n      // `_type`, not `type`. Steve puts its own schema id in `type` on everything it returns\n      // (here, the string \"event\") and moves the Kubernetes value out to `_type`, so a filter\n      // written against `type` matches nothing and the page reports that nothing has gone wrong.\n      if (event._type !== 'Warning') {\n        continue;\n      }\n\n      out.push({\n        id:        event.id || `${ name }-${ event.metadata?.name }`,\n        workspace: name,\n        reason:    event.reason,\n        message:   event.message,\n        count:     event.count || 1,\n        last:      event.lastTimestamp || event.metadata?.creationTimestamp,\n      });\n    }\n  }\n\n  return out.sort((a, b) => Date.parse(b.last) - Date.parse(a.last));\n}\n\n/**\n * The last line the workspace's container printed, or '' if there is nothing to read.\n *\n * Asked for only while a workspace is starting, and only by the page that is showing one, since\n * this is the pod's log rather than a summary and a list of them would be a request per row. It\n * is the difference between \"Starting up\" and knowing it is four minutes into a yarn install.\n */\nexport async function workspaceLogTail(name: string, pod: string): Promise<string> {\n  return podLogTail(workspaceNamespace(name), pod, WORKSPACE_CONTAINER);\n}\n\n/**\n * The last line a container printed, or '' if there is nothing to read.\n *\n * Not through devFetch: this is the apiserver's log subresource, which answers text rather than\n * JSON, and a 404 from it (a pod that has just gone) is an ordinary answer rather than an error.\n */\nexport async function podLogTail(namespace: string, pod: string, container: string): Promise<string> {\n  const url = `${ BASE }/api/v1/namespaces/${ namespace }/pods/${ pod }/log?container=${ container }&tailLines=1&timestamps=false`;\n\n  try {\n    const resp = await fetch(url, { cache: 'no-store' });\n\n    if (!resp.ok) {\n      return '';\n    }\n\n    return (await resp.text()).trim().split('\\n').pop() || '';\n  } catch {\n    return '';\n  }\n}\n\n/**\n * A workspace's Service, or null if it has none.\n *\n * Fetched on its own rather than folded into listWorkspaces, because the list has no column\n * for it and the detail page is already fetching the pod. The alternative, describing the\n * Service from the template, is how the detail page came to report a port nothing was\n * listening on.\n */\nexport async function workspaceService(name: string): Promise<DevService | null> {\n  const namespace = workspaceNamespace(name);\n  // The namespace's collection rather than the one Service by name, so a workspace that has\n  // none (a create that failed after the namespace) answers 200 with nothing in it. Asked\n  // for by name it would answer 404, and the detail page asks every five seconds.\n  const services = await devFetch(`${ BASE }/v1/services/${ namespace }`).catch(() => null);\n  const service = (services?.data || []).find((svc: Json) => svc.metadata?.name === namespace);\n\n  if (!service) {\n    return null;\n  }\n\n  return {\n    name:     service.metadata?.name,\n    port:     service.spec?.ports?.[0]?.port,\n    nodePort: service.spec?.ports?.[0]?.nodePort || 0,\n  };\n}\n\n/**\n * The identities the terminals run as, and the one thing they share.\n *\n * Two ServiceAccounts, deliberately, rather than one that can do everything:\n *\n *   - the global terminal is the product's own tooling. It genuinely needs to see the cluster:\n *     list workspaces, read their pods and logs, and get a shell inside one. It is bound to a\n *     ClusterRole scoped to exactly that and no further, so it is refused secrets, nodes and\n *     RBAC itself.\n *   - a workspace pod runs whatever a template or a person put in it, which is not the product's\n *     code and should not carry the product's rights. It gets its own namespace and nothing\n *     else.\n *\n * The temptation is one cluster-admin token mounted everywhere, because it is one object and it\n * always works. It is also the kind of thing that is only ever noticed later, from the outside.\n *\n * What both sides do share is the claude login, as one Secret in a namespace of this product's\n * own. Each side reaches it through a RoleBinding naming that one Secret by name, rather than by\n * the extension copying the Secret into every workspace: a copy goes stale the moment the token\n * refreshes, and a stale copy of a credential is worse than no copy, because nothing looks\n * wrong until it stops working.\n */\nexport const DEV_SYSTEM_NAMESPACE = 'dev-system';\nexport const CREDENTIALS_SECRET = 'claude-credentials';\nexport const CREDENTIALS_KEY = 'credentials.json';\n/** The hand-made Secret the store replaced. Only the migration that folds it in still names it. */\nexport const GITHUB_SECRET = 'github-token';\n\n/**\n * How a template's own secrets are namespaced inside the one store.\n *\n * The key carries its scope, so one flat Secret holds both kinds without a nested format that\n * has to be parsed: `GH_TOKEN` is global, `rancher.FIGMA_API_KEY` belongs to the rancher\n * template. The prefix is the template's own id rather than a constant, or a second template's\n * key of the same name would be the first one's.\n */\nexport function templateSecretKey(templateId: string, key: string): string {\n  return `${ templateId }.${ key }`;\n}\n\n/**\n * Where a workspace and its sidecars read the keys they were given, in their own namespace.\n *\n * Named for the workspace rather than for sidecars because both use it now: a secretKeyRef can\n * only name a Secret in the pod's own namespace, so one mirror per workspace serves everything\n * running in it.\n */\nconst MIRROR_SECRET = 'dev-secrets';\n\n/** The dev server config a workspace boots with, in the workspace's own namespace. */\nconst WORKSPACE_CONFIG_MAP = 'dev-workspace-config';\n\n/**\n * The terminal scripts a workspace's pod runs, in the workspace's own namespace.\n *\n * They are not written here and they are not a second copy of anything. The dev server pod is\n * seeded with them by the barn extension (`dev-extension.ts`), into a ConfigMap in that\n * extension's namespace, and this copies the terminal half of that ConfigMap into each\n * workspace. A workspace cannot mount the original: a ConfigMap volume only reaches pods in its\n * own namespace, which is exactly the reason a workspace's Conversations tab was a bare shell\n * for as long as it was.\n *\n * Copying rather than re-deriving keeps one source of truth. Edit `dev-extension/pod/*`, run\n * `gen-dev-extension-seed.mjs` and `apply-dev-extension-seed.mjs`, and every workspace picks the\n * new version up on its next start, the same way the dev pod's own tabs do.\n */\nconst WORKSPACE_TERMINAL_MAP = 'dev-terminal';\nconst WORKSPACE_TERMINAL_MOUNT = '/seed';\n\n\n/**\n * Where the originals live: this pod's own seed ConfigMap.\n *\n * Not a constant, because there is one of these per named extension and this dashboard has to\n * copy from the one it was itself seeded from. Both come from the URL it is served at - see\n * DEV_POD_SERVICE in config/constants.\n */\nconst SEED_NAMESPACE = POD_NAMESPACE;\nconst SEED_CONFIG_MAP = POD_SERVICE;\n\n/**\n * The keys to copy, named rather than filtered.\n *\n * The seed also carries the whole dev-extension source tree (flattened, `pkg__dev-extension__…`),\n * which is hundreds of kilobytes and has nothing to do with running a terminal. A ConfigMap is\n * capped at a megabyte, so \"copy everything\" is not a smaller decision than this list.\n */\nconst TERMINAL_FILES = [\n  'shell.sh', 'terminal-tools.sh', 'claude-session.sh', 'claude-credentials.mjs',\n  'claude-defaults.mjs', 'tmux.conf', 'session-claude.md',\n];\n\n/** Where the dev server's pod lives, which is the pod the global terminals attach to. */\nconst DEV_POD_NAMESPACE = POD_NAMESPACE;\nexport const GLOBAL_SERVICE_ACCOUNT = 'dev-global-terminal';\n\n/** The ServiceAccount every workspace pod runs as, one per workspace namespace. */\nexport const WORKSPACE_SERVICE_ACCOUNT = 'dev-workspace';\n\n/** Create if it is not there; leave it alone if it is. */\nasync function ensure(type: string, namespace: string | null, name: string, body: Json): Promise<void> {\n  const path = namespace ? `${ BASE }/v1/${ type }/${ namespace }/${ name }` : `${ BASE }/v1/${ type }/${ name }`;\n  const existing = await devFetch(path).catch(() => null);\n\n  if (existing) {\n    return;\n  }\n\n  await devFetch(`${ BASE }/v1/${ type }`, { method: 'POST', body: JSON.stringify(body) }).catch(() => null);\n}\n\n/**\n * Let one ServiceAccount read and write the shared credentials Secret, and nothing else in that\n * namespace.\n *\n * `resourceNames` is what keeps this to the one Secret: without it this would be read access to\n * every Secret in the namespace, which today is the same thing and tomorrow is not.\n */\nfunction credentialsRoleBinding(name: string, namespace: string): Json {\n  return {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'RoleBinding',\n    metadata:   { namespace: DEV_SYSTEM_NAMESPACE, name: `creds-${ name }-${ namespace }` },\n    roleRef:    {\n      apiGroup: 'rbac.authorization.k8s.io', kind: 'Role', name: CREDENTIALS_SECRET\n    },\n    subjects: [{ kind: 'ServiceAccount', name, namespace }],\n  };\n}\n\n/**\n * The ServiceAccounts, roles and bindings the terminals need.\n *\n * Idempotent and create-if-missing, the way everything else this extension puts in the cluster\n * is, and it swallows its own failures: it runs for every user on every load, including ones\n * with no rights to create RBAC, and an extension that throws here would take the product down\n * for them.\n */\nexport async function ensureDevRbac(): Promise<void> {\n  await ensure('namespaces', null, DEV_SYSTEM_NAMESPACE, {\n    apiVersion: 'v1',\n    kind:       'Namespace',\n    metadata:   { name: DEV_SYSTEM_NAMESPACE },\n  });\n\n  // Created empty, and only ever written by a pod pushing a token it already had. It exists up\n  // front so that the Role below can name it, which is what lets the Role be about one Secret\n  // rather than about all of them.\n  await ensure('secrets', DEV_SYSTEM_NAMESPACE, CREDENTIALS_SECRET, {\n    apiVersion: 'v1',\n    kind:       'Secret',\n    metadata:   { namespace: DEV_SYSTEM_NAMESPACE, name: CREDENTIALS_SECRET },\n    type:       'Opaque',\n  });\n\n  // Nothing ensures the old `github-token` Secret any more. It is what the store replaced, and\n  // an extension that recreated it on load would put an empty one back the moment the migration\n  // deleted it, leaving two places a GitHub token could live for ever.\n\n  await ensure('rbac.authorization.k8s.io.roles', DEV_SYSTEM_NAMESPACE, CREDENTIALS_SECRET, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'Role',\n    metadata:   { namespace: DEV_SYSTEM_NAMESPACE, name: CREDENTIALS_SECRET },\n    rules:      [{\n      apiGroups:     [''],\n      resources:     ['secrets'],\n      resourceNames: [CREDENTIALS_SECRET],\n      verbs:         ['get', 'update', 'patch'],\n    }],\n  });\n\n  await ensure('serviceaccounts', DEV_POD_NAMESPACE, GLOBAL_SERVICE_ACCOUNT, {\n    apiVersion: 'v1',\n    kind:       'ServiceAccount',\n    metadata:   { namespace: DEV_POD_NAMESPACE, name: GLOBAL_SERVICE_ACCOUNT },\n  });\n\n  await ensure('rbac.authorization.k8s.io.clusterroles', null, GLOBAL_SERVICE_ACCOUNT, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'ClusterRole',\n    metadata:   { name: GLOBAL_SERVICE_ACCOUNT },\n    rules:      [\n      // Workspaces are namespaces, so creating and deleting one is creating and deleting a\n      // namespace. This is the widest rule here and it is the product's actual job.\n      {\n        apiGroups: [''], resources: ['namespaces'], verbs: ['get', 'list', 'watch', 'create', 'delete']\n      },\n      {\n        apiGroups: ['apps'],\n        resources: ['deployments', 'deployments/scale', 'replicasets'],\n        verbs:     ['get', 'list', 'watch', 'create', 'update', 'patch', 'delete'],\n      },\n      {\n        apiGroups: [''],\n        resources: ['services', 'configmaps', 'serviceaccounts'],\n        verbs:     ['get', 'list', 'watch', 'create', 'update', 'patch', 'delete'],\n      },\n      {\n        apiGroups: [''], resources: ['pods', 'pods/log', 'events'], verbs: ['get', 'list', 'watch']\n      },\n      // A shell in a workspace, which is a create on the pod's exec subresource rather than\n      // anything that reads like \"exec\".\n      {\n        apiGroups: [''], resources: ['pods/exec'], verbs: ['create', 'get']\n      },\n    ],\n  });\n\n  await ensure('rbac.authorization.k8s.io.clusterrolebindings', null, GLOBAL_SERVICE_ACCOUNT, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'ClusterRoleBinding',\n    metadata:   { name: GLOBAL_SERVICE_ACCOUNT },\n    roleRef:    {\n      apiGroup: 'rbac.authorization.k8s.io', kind: 'ClusterRole', name: GLOBAL_SERVICE_ACCOUNT\n    },\n    subjects: [{ kind: 'ServiceAccount', name: GLOBAL_SERVICE_ACCOUNT, namespace: DEV_POD_NAMESPACE }],\n  });\n\n  const binding = credentialsRoleBinding(GLOBAL_SERVICE_ACCOUNT, DEV_POD_NAMESPACE);\n\n  await ensure('rbac.authorization.k8s.io.rolebindings', DEV_SYSTEM_NAMESPACE, binding.metadata.name, binding);\n}\n\n/**\n * The ServiceAccount a workspace's pod runs as: its own namespace, and the shared login.\n *\n * Created with the workspace rather than by ensureDevRbac, because it is per workspace and the\n * namespace it lives in does not exist until the workspace does.\n */\nasync function ensureWorkspaceRbac(name: string): Promise<void> {\n  const namespace = workspaceNamespace(name);\n\n  await ensure('serviceaccounts', namespace, WORKSPACE_SERVICE_ACCOUNT, {\n    apiVersion: 'v1',\n    kind:       'ServiceAccount',\n    metadata:   { namespace, name: WORKSPACE_SERVICE_ACCOUNT },\n  });\n\n  // Whatever the workspace runs can manage the workspace's own namespace. It is a sandbox, and\n  // this is the edge of it: `edit` is Kubernetes' own aggregated role for exactly this, so the\n  // rules do not have to be maintained here as the API grows.\n  await ensure('rbac.authorization.k8s.io.rolebindings', namespace, WORKSPACE_SERVICE_ACCOUNT, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'RoleBinding',\n    metadata:   { namespace, name: WORKSPACE_SERVICE_ACCOUNT },\n    roleRef:    {\n      apiGroup: 'rbac.authorization.k8s.io', kind: 'ClusterRole', name: 'edit'\n    },\n    subjects: [{ kind: 'ServiceAccount', name: WORKSPACE_SERVICE_ACCOUNT, namespace }],\n  });\n\n  const binding = credentialsRoleBinding(WORKSPACE_SERVICE_ACCOUNT, namespace);\n\n  await ensure('rbac.authorization.k8s.io.rolebindings', DEV_SYSTEM_NAMESPACE, binding.metadata.name, binding);\n}\n\n/**\n * base64 of the UTF-8 bytes, which is what a Kubernetes Secret holds.\n *\n * `btoa` is defined over Latin-1 and throws a DOMException on anything outside it, so a pasted\n * token or a password with one non-Latin1 character in it would take the whole Save with it, and\n * the error it throws says nothing about which field caused it.\n */\nfunction encodeSecret(value: string): string {\n  const bytes = new TextEncoder().encode(value);\n  let binary = '';\n\n  for (const byte of bytes) {\n    binary += String.fromCharCode(byte);\n  }\n\n  return btoa(binary);\n}\n\nfunction decodeSecret(value: string): string {\n  const binary = atob(value);\n  const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));\n\n  return new TextDecoder().decode(bytes);\n}\n\n/**\n * A Secret's data, decoded, or null when it is not there or cannot be read.\n *\n * Through Steve on the browser's own session, so what comes back is what this user is allowed\n * to see. Nothing here returns a token to anywhere it could be displayed: the callers take the\n * one field they need and the pages show identities rather than credentials.\n */\nasync function readSecret(name: string): Promise<Record<string, string> | null> {\n  const secret = await devFetch(`${ BASE }/v1/secrets/${ DEV_SYSTEM_NAMESPACE }/${ name }`).catch(() => null);\n\n  if (!secret) {\n    return null;\n  }\n\n  const out: Record<string, string> = {};\n\n  for (const [key, value] of Object.entries(secret.data || {})) {\n    out[key] = value ? decodeSecret(value as string) : '';\n  }\n\n  return out;\n}\n\n/**\n * The GitHub token, for the caller to send. Never rendered and never logged.\n *\n * Out of the one store rather than the hand-made `github-token` Secret that used to hold it: the\n * migration folded that one in as `GH_TOKEN` and deleted it, so there is one place a secret\n * lives. See migrateGithubToken.\n */\nexport async function githubToken(): Promise<string> {\n  return secretValue('GH_TOKEN');\n}\n\n/** What the shared claude login is, without the tokens: enough to say whose it is. */\nexport interface ClaudeIdentity {\n  subscriptionType: string;\n  expiresAt: number;\n  scopes: string[];\n}\n\nexport async function claudeIdentity(): Promise<ClaudeIdentity | null> {\n  const data = await readSecret(CREDENTIALS_SECRET);\n\n  if (!data?.[CREDENTIALS_KEY]) {\n    return null;\n  }\n\n  try {\n    const oauth = JSON.parse(data[CREDENTIALS_KEY])?.claudeAiOauth;\n\n    if (!oauth?.accessToken) {\n      return null;\n    }\n\n    return {\n      subscriptionType: oauth.subscriptionType || 'unknown',\n      expiresAt:        Number(oauth.expiresAt) || 0,\n      scopes:           oauth.scopes || [],\n    };\n  } catch {\n    return null;\n  }\n}\n\n/**\n * Whether the dev server's pod is running as the ServiceAccount the global terminals need.\n *\n * A pod takes its ServiceAccount at start, so setting one on the Deployment restarts the pod,\n * and that pod is the one someone has a terminal in. So the extension does not do it: this\n * reports the state and Settings offers it as something to do deliberately.\n */\nexport async function devPodServiceAccount(): Promise<{ current: string; wanted: string }> {\n  const deployment = await devFetch(`${ BASE }/v1/apps.deployments/${ DEV_POD_NAMESPACE }/${ POD_SERVICE }`).catch(() => null);\n\n  return {\n    current: deployment?.spec?.template?.spec?.serviceAccountName || 'default',\n    wanted:  GLOBAL_SERVICE_ACCOUNT,\n  };\n}\n\n/**\n * Put the global terminal's ServiceAccount on the dev server's Deployment.\n *\n * This restarts the pod, which is why nothing calls it on its own. Everything in the pod's\n * `/app` survives (it is a volume), but a tmux session does not, and neither does an install\n * that is part way through.\n */\nexport async function setDevPodServiceAccount(): Promise<void> {\n  const url = `${ BASE }/v1/apps.deployments/${ DEV_POD_NAMESPACE }/${ POD_SERVICE }`;\n  const deployment = await devFetch(url);\n\n  deployment.spec.template.spec.serviceAccountName = GLOBAL_SERVICE_ACCOUNT;\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify(deployment) });\n}\n\n/**\n * The one Secret this extension keeps, per user.\n *\n * Named and labelled with the owning Rancher user, following the secret sets in the\n * barn extension (listSecretSets and friends), which already solved this: the principal\n * comes from /v3/users?me=true, is sanitised to something a Kubernetes name accepts, and goes in\n * the name and in a label. Per-user costs the same to write as shared and cannot be retrofitted\n * without migrating whatever a shared one has accumulated, so it is per-user from the start,\n * with one user in this cluster today.\n *\n * Keys are flat and carry their own scope: `GH_TOKEN` is global, `rancher.FIGMA_API_KEY`\n * belongs to the rancher template. One Secret holds both without a nested format to parse.\n */\nconst SECRET_KIND_LABEL = 'dev.rancher.io/kind';\nconst SECRET_OWNER_LABEL = 'dev.rancher.io/owner';\n\nlet secretOwner = '';\n\n/**\n * A principal id, as something a Secret can actually be named after.\n *\n * A Secret name is an RFC 1123 subdomain: lowercase letters, digits, dashes and dots, starting\n * and ending on a letter or a digit. Underscore is not in that set, and it is not a theoretical\n * omission: every principal that is not a local user has one. `github_user://12345678` became\n * `dev-secrets-github_user---12345678`, which the apiserver rejects, so the save failed and every\n * key in Settings read \"Not set\" for anyone who had signed in through an auth provider. Which is\n * exactly the person the Keycloak and OpenLDAP sidecars exist for.\n *\n * The trim is after the truncation as well as before it, because a principal cut at forty\n * characters can land on a dash or a dot, and a name that ends in one is rejected too.\n */\nfunction sanitiseOwner(value: string): string {\n  const cleaned = (value || 'anonymous')\n    .toLowerCase()\n    .replace(/[^a-z0-9.-]/g, '-');\n  const trim = (text: string) => text.replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, '');\n\n  if (cleaned.length <= MAX_OWNER_LENGTH) {\n    return trim(cleaned) || 'anonymous';\n  }\n\n  // Long principals keep a fingerprint of the whole thing rather than only their first forty\n  // characters. Active Directory principals are a distinguished name, so two people in the same\n  // organisational unit agree for far longer than that: truncated, they become one Secret, and\n  // the second person to save silently overwrites the first person's tokens and then reads them.\n  // On exactly the providers the auth sidecars exist to make usable.\n  const stem = cleaned.slice(0, MAX_OWNER_LENGTH - 9);\n\n  return `${ trim(stem) }-${ fingerprint(value) }`;\n}\n\n/** Kubernetes' name limit is 63; this leaves room for the `dev-secrets-` the store prefixes. */\nconst MAX_OWNER_LENGTH = 40;\n\n/**\n * A short, stable fingerprint of a string, as lowercase base 36.\n *\n * FNV-1a, because it needs to be synchronous (SubtleCrypto is not) and it is disambiguating\n * names rather than protecting anything. Eight characters of it is enough that two principals\n * sharing a forty character prefix do not also share this.\n */\nfunction fingerprint(value: string): string {\n  let hash = 0x811c9dc5;\n\n  for (let i = 0; i < value.length; i++) {\n    hash ^= value.charCodeAt(i);\n    hash = Math.imul(hash, 0x01000193) >>> 0;\n  }\n\n  return hash.toString(36).padStart(7, '0').slice(0, 8);\n}\n\n/** Who is asking, from Rancher's own answer, cached for the life of the page. */\nexport async function currentOwner(): Promise<string> {\n  if (secretOwner) {\n    return secretOwner;\n  }\n\n  const me = await devFetch('/v3/users?me=true').catch(() => null);\n  const principal = me?.data?.[0]?.principalIds?.[0] || me?.data?.[0]?.id || '';\n\n  secretOwner = sanitiseOwner(principal);\n\n  return secretOwner;\n}\n\nasync function secretStoreName(): Promise<string> {\n  return `dev-secrets-${ await currentOwner() }`;\n}\n\n/** The store as it is, or an empty one. Values included, since the caller is the browser. */\nasync function readSecretStore(): Promise<Record<string, string>> {\n  const name = await secretStoreName();\n  const secret = await devFetch(`${ BASE }/v1/secrets/${ DEV_SYSTEM_NAMESPACE }/${ name }`).catch(() => null);\n  const out: Record<string, string> = {};\n\n  for (const [key, value] of Object.entries(secret?.data || {})) {\n    out[key] = value ? decodeSecret(value as string) : '';\n  }\n\n  return out;\n}\n\n/**\n * Which keys are set, and nothing else.\n *\n * This is what Settings and the sidecar cards ask, because neither of them has any business\n * with the value: a stored secret is never rendered back, only replaced or cleared.\n */\nexport async function setSecretKeys(): Promise<string[]> {\n  const store = await readSecretStore();\n\n  return Object.entries(store).filter(([, value]) => !!value).map(([key]) => key);\n}\n\n/** One value, for the browser to use at the point of use. Never rendered, never logged. */\nexport async function secretValue(key: string): Promise<string> {\n  return (await readSecretStore())[key] || '';\n}\n\n/**\n * Write only the keys that changed.\n *\n * A key whose field was left alone is not in `changes` and is not touched, which is what stops\n * opening Settings and saving from blanking a value nobody could see. A key set to '' is a\n * deliberate clear.\n */\nexport async function saveSecrets(changes: Record<string, string>): Promise<void> {\n  if (!Object.keys(changes).length) {\n    return;\n  }\n\n  const name = await secretStoreName();\n  const url = `${ BASE }/v1/secrets/${ DEV_SYSTEM_NAMESPACE }/${ name }`;\n  const existing = await devFetch(url).catch(() => null);\n  const data: Record<string, string> = { ...(existing?.data || {}) };\n\n  for (const [key, value] of Object.entries(changes)) {\n    if (value === '') {\n      delete data[key];\n    } else {\n      data[key] = encodeSecret(value);\n    }\n  }\n\n  const body = {\n    apiVersion: 'v1',\n    kind:       'Secret',\n    type:       'Opaque',\n    metadata:   {\n      namespace: DEV_SYSTEM_NAMESPACE,\n      name,\n      labels:    { [SECRET_KIND_LABEL]: 'secrets', [SECRET_OWNER_LABEL]: await currentOwner() },\n    },\n    data,\n  };\n\n  if (existing) {\n    await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data: body.data, metadata: { ...existing.metadata, labels: body.metadata.labels } }) });\n  } else {\n    await devFetch(`${ BASE }/v1/secrets`, { method: 'POST', body: JSON.stringify(body) });\n  }\n}\n\n/**\n * A password nobody has to think of, made once and then kept.\n *\n * The chart does this with `randAlphaNum 15` and a `lookup` that reuses whatever the last install\n * generated, and the reason is the same here: an admin password written into the code as\n * `admin`/`admin` is a literal credential in the repo, and one regenerated on every start is one\n * nobody can write down. Alphanumeric only, because these end up typed into a login form.\n */\nconst GENERATED_ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';\n\nfunction generatedValue(length = 15): string {\n  const bytes = new Uint8Array(length);\n\n  window.crypto.getRandomValues(bytes);\n\n  return [...bytes].map((byte) => GENERATED_ALPHABET[byte % GENERATED_ALPHABET.length]).join('');\n}\n\n/**\n * Fill in any declared secret the product generates for itself, once.\n *\n * Only the ones that are missing, so a password that has already been generated is the password\n * it stays, which is the property `lookup` gives the chart: something that has been used to log\n * in once goes on working.\n */\nexport async function ensureGeneratedSecrets(template: DevTemplate | undefined): Promise<Record<string, string>> {\n  const declared = [\n    ...GLOBAL_SECRETS.map((secret) => ({ secret, key: secret.key })),\n    ...(template?.secrets || []).map((secret) => ({ secret, key: templateSecretKey(template!.id, secret.key) })),\n  ].filter(({ secret }) => secret.generated);\n\n  const store = await readSecretStore();\n\n  if (!declared.length) {\n    return store;\n  }\n\n  const changes: Record<string, string> = {};\n\n  for (const { key } of declared) {\n    if (!store[key]) {\n      changes[key] = generatedValue();\n    }\n  }\n\n  await saveSecrets(changes);\n\n  // The store as it now is, returned rather than left to be read back.\n  //\n  // Reading it again is a read of something written a moment ago, and the very first write is a\n  // create: Steve can answer that read from before it and hand back a store without the key just\n  // generated. What follows is a mirror written without it, a pod started without it, a Rancher\n  // installed with an empty password that therefore invents one of its own, and a bootstrap that\n  // cannot log in. That is a great deal of consequence for a cache, and none of it happens if the\n  // value is carried forward instead of asked for again.\n  return { ...store, ...changes };\n}\n\n/**\n * Copy the keys this workspace is entitled to into the workspace's own namespace.\n *\n * A secretKeyRef can only name a Secret in the pod's own namespace, and the store is one Secret\n * per user in this product's namespace, so the values have to be mirrored. What a pod spec\n * carries either way is the reference, which is the property that matters: `kubectl get deploy\n * -o yaml` shows a name and a key rather than a token.\n *\n * Rewritten every time anything here is started, not only when the workspace is created. A key\n * set in Settings after the workspace was made would otherwise never reach it, and because the\n * references are `optional` the pod would come up without it and say nothing.\n *\n * The mirror lands in a namespace where the workspace's own ServiceAccount holds `edit`, so\n * anyone with a shell in the workspace can read these values. That is deliberate rather than\n * overlooked: they are that workspace's credentials, and the code they are for is what runs\n * there. A secret that must not be readable by the workspace does not belong in its template.\n */\nasync function mirrorSecrets(workspace: string, template: DevTemplate | undefined, known?: Record<string, string>): Promise<void> {\n  const namespace = workspaceNamespace(workspace);\n  // `known` is the store as the caller has just seen it, which is what stops a value generated\n  // moments ago from being lost to a stale read. See ensureGeneratedSecrets.\n  const store = known || await readSecretStore();\n  const mirrored: Record<string, string> = {};\n\n  // Only the template's own keys, never the global ones. A global secret is the person's rather\n  // than the workspace's: section 9 has the browser read those through Steve at the point of use,\n  // and mirroring GH_TOKEN into every workspace namespace put a personal GitHub token inside every\n  // pod a template happened to run, in a namespace where the workspace account holds `edit`.\n  //\n  // The template's keys lose the template prefix on the way in, since inside the workspace there\n  // is only one template and `rancher.FIGMA_API_KEY` is not a name an environment variable can\n  // have.\n  for (const secret of template?.secrets || []) {\n    const value = store[templateSecretKey(template!.id, secret.key)];\n\n    if (value) {\n      mirrored[secret.key] = encodeSecret(value);\n    }\n  }\n\n  const url = `${ BASE }/v1/secrets/${ namespace }/${ MIRROR_SECRET }`;\n  const existing = await devFetch(url).catch(() => null);\n\n  if (existing) {\n    await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data: mirrored }) });\n\n    return;\n  }\n\n  await devFetch(`${ BASE }/v1/secrets`, {\n    method: 'POST',\n    body:   JSON.stringify({\n      apiVersion: 'v1',\n      kind:       'Secret',\n      type:       'Opaque',\n      metadata:   { namespace, name: MIRROR_SECRET, labels: { [LABEL_WORKSPACE]: workspace } },\n      data:       mirrored,\n    }),\n  });\n}\n\n/**\n * Fold the hand-made github-token Secret into the store, once.\n *\n * It was injected by hand before there was a store. Moving it means there is one place a secret\n * lives rather than two, and the one-off is deleted so nothing reads the stale copy later.\n */\nexport async function migrateGithubToken(): Promise<void> {\n  const legacy = await devFetch(`${ BASE }/v1/secrets/${ DEV_SYSTEM_NAMESPACE }/${ GITHUB_SECRET }`).catch(() => null);\n  const token = legacy?.data?.token ? decodeSecret(legacy.data.token) : '';\n\n  if (!token) {\n    return;\n  }\n\n  const already = await secretValue('GH_TOKEN');\n\n  if (already && already !== token) {\n    // Two different tokens, and nothing here knows which one is wanted. Both are left where they\n    // are: deleting the legacy one would destroy the only copy of a credential this code did not\n    // put anywhere, on the strength of a guess.\n    return;\n  }\n\n  if (!already) {\n    await saveSecrets({ GH_TOKEN: token });\n  }\n\n  // Only now, when the value is certainly in the store, so a failed save cannot take the original\n  // with it.\n  await devFetch(`${ BASE }/v1/secrets/${ DEV_SYSTEM_NAMESPACE }/${ GITHUB_SECRET }`, { method: 'DELETE' }).catch(() => null);\n}\n\n/** A sidecar as it exists in the cluster, joined to what the template declared. */\nexport interface DevSidecarState {\n  id: string;\n  state: WorkspaceState;\n  /** Keys the sidecar declared that are not in the secret store. */\n  missing: string[];\n  /**\n   * What the cluster says about it, when there is something to say.\n   *\n   * The card showed Starting for every kind of failure before this existed, including the ones\n   * where no pod is ever created and so nothing has a log to read. This is the pod's own reason\n   * or the controller's, whichever there is.\n   */\n  detail: string;\n  /** The last line it printed, while it is still starting. See listSidecars. */\n  log: string;\n}\n\nfunction sidecarName(workspace: string, id: string): string {\n  return `${ workspaceNamespace(workspace) }-${ id }`;\n}\n\n/** Every declared sidecar's state in one workspace, whether or not it has ever been started. */\nexport async function listSidecars(workspace: string, sidecars: DevSidecar[], template?: DevTemplate): Promise<Record<string, DevSidecarState>> {\n  const namespace = workspaceNamespace(workspace);\n  const [deployments, pods, keys] = await Promise.all([\n    devFetch(`${ BASE }/v1/apps.deployments/${ namespace }`).catch(() => null),\n    devFetch(`${ BASE }/v1/pods/${ namespace }`).catch(() => null),\n    setSecretKeys().catch(() => [] as string[]),\n  ]);\n\n  const out: Record<string, DevSidecarState> = {};\n\n  for (const sidecar of sidecars) {\n    const name = sidecarName(workspace, sidecar.id);\n    const deployment = (deployments?.data || []).find((candidate: Json) => candidate.metadata?.name === name);\n    const pod = (pods?.data || []).find((candidate: Json) => candidate.metadata?.labels?.[LABEL_SIDECAR] === sidecar.id);\n\n    const state = deployment ? stateOf({ metadata: {} }, deployment, pod) : 'stopped';\n\n    out[sidecar.id] = {\n      id: sidecar.id,\n      // A sidecar that has never been started has no Deployment, which is 'stopped' rather than\n      // anything more dramatic: it is declared, and starting it is what creates it.\n      state,\n      missing: missingSecrets(sidecar, template, keys),\n      detail:  podDetail(pod) || (pod ? '' : replicaFailure(deployment)),\n      // Only while it is still coming up, and only for a sidecar that takes long enough for the\n      // question to arise. Ten minutes of \"Starting up\" says nothing about which minute it is in,\n      // and the manager's own log is a running account of it: which helm install, and how it went.\n      log: state === 'starting' && pod && sidecar.readyPort\n        ? await podLogTail(namespace, pod.metadata.name, 'sidecar')\n        : '',\n    };\n  }\n\n  return out;\n}\n\n/**\n * The keys this sidecar needs that the store does not have.\n *\n * The template is what says how a key is named in the store, so a sidecar declaring\n * `FIGMA_API_KEY` on the rancher template is asking about `rancher.FIGMA_API_KEY`. Without the\n * template there is no way to name the key, and answering \"nothing is missing\" would be a\n * guess, so the declaration is reported as missing instead.\n */\nfunction missingSecrets(sidecar: DevSidecar, template: DevTemplate | undefined, keys: string[]): string[] {\n  return (sidecar.secrets || []).filter((key) => {\n    // A generated secret is never missing, whatever the store holds: starting the sidecar is what\n    // creates it. Counting it as missing would disable the only control that could fill it in.\n    if ((template?.secrets || []).find((secret) => secret.key === key)?.generated) {\n      return false;\n    }\n\n    return !template || !keys.includes(templateSecretKey(template.id, key));\n  });\n}\n\n/**\n * The Chromium extension the browser sidecar runs with, built for one workspace.\n *\n * Written on every start, like the terminal scripts and for the same reason: it carries this\n * workspace's own addresses and its own generated passwords, and both can change after the\n * sidecar was created. A Secret rather than a ConfigMap because of what is in it.\n */\nconst BROWSER_EXTENSION_SECRET = 'dev-browser-extension';\nexport const BROWSER_EXTENSION_MOUNT = '/extension';\n\nasync function ensureBrowserExtension(workspace: string, template: DevTemplate, store: Record<string, string>): Promise<void> {\n  const namespace = workspaceNamespace(workspace);\n  const rancher = (template.sidecars || []).find((sidecar) => sidecar.providesApi);\n\n  // The pages the content scripts run on: this workspace's own Rancher, and the dashboard it\n  // serves. Both are in-cluster addresses, so the extension is inert anywhere else, which is the\n  // point - it carries passwords and it should not offer them to a page that merely looks like a\n  // Rancher login.\n  const matches = [\n    rancher ? `${ sidecarServiceUrl(workspace, rancher) }/*` : '',\n    `${ workspaceServiceUrl(workspace, template).replace(/\\/$/, '') }/*`,\n  ].filter(Boolean);\n\n  // The accounts the workspace's own Rancher is bootstrapped with. admin is the generated\n  // bootstrap password; user1 to user3 are the auth sidecars' shared one. See AUTH_SCRIPT.\n  const admin = store[templateSecretKey(template.id, 'RANCHER_BOOTSTRAP_PASSWORD')] || '';\n  const user = store[templateSecretKey(template.id, 'AUTH_USER_PASSWORD')] || '';\n  const creds = [\n    { label: 'Admin', username: 'admin', password: admin },\n    ...[1, 2, 3].map((n) => ({ label: `User ${ n }`, username: `user${ n }`, password: user })),\n  ].filter((entry) => !!entry.password);\n\n  const data: Record<string, string> = {};\n\n  for (const [file, body] of Object.entries(BROWSER_EXTENSION_FILES)) {\n    data[file] = encodeSecret(body\n      .replace('{{matches}}', matches.join('\",\\n        \"'))\n      .replace('{{creds}}', JSON.stringify(creds, null, 2)));\n  }\n\n  const url = `${ BASE }/v1/secrets/${ namespace }/${ BROWSER_EXTENSION_SECRET }`;\n  const existing = await devFetch(url).catch(() => null);\n\n  if (!existing) {\n    await devFetch(`${ BASE }/v1/secrets`, {\n      method: 'POST',\n      body:   JSON.stringify({\n        apiVersion: 'v1',\n        kind:       'Secret',\n        metadata:   { namespace, name: BROWSER_EXTENSION_SECRET },\n        type:       'Opaque',\n        data,\n      }),\n    }).catch(() => null);\n\n    return;\n  }\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data }) }).catch(() => null);\n}\n\n/**\n * The values a workspace's sidecars have been configured with.\n *\n * One ConfigMap for all of them, keyed `<sidecar>.<param>`, because that is the shape the secret\n * store already uses for the same kind of question and because a ConfigMap per sidecar would be\n * five objects saying one thing each. Values only: what a parameter *is* lives in the template,\n * which is code, and a value with no declaration behind it is ignored.\n */\nconst SIDECAR_PARAMS_MAP = 'dev-sidecar-params';\n\nexport async function sidecarParams(workspace: string, sidecar: DevSidecar): Promise<Record<string, string>> {\n  const namespace = workspaceNamespace(workspace);\n  const config = await devFetch(`${ BASE }/v1/configmaps/${ namespace }/${ SIDECAR_PARAMS_MAP }`).catch(() => null);\n  const out: Record<string, string> = {};\n\n  for (const param of sidecar.params || []) {\n    out[param.id] = config?.data?.[`${ sidecar.id }.${ param.id }`] ?? (param.default || '');\n  }\n\n  return out;\n}\n\n/**\n * Save what a sidecar is configured with.\n *\n * Applying it is the caller's next step, and that step is a restart: a container reads its\n * environment when it starts and at no other time.\n */\nexport async function setSidecarParams(workspace: string, sidecar: DevSidecar, values: Record<string, string>): Promise<void> {\n  const namespace = workspaceNamespace(workspace);\n  const url = `${ BASE }/v1/configmaps/${ namespace }/${ SIDECAR_PARAMS_MAP }`;\n  const existing = await devFetch(url).catch(() => null);\n  const data: Record<string, string> = { ...(existing?.data || {}) };\n\n  for (const [id, value] of Object.entries(values)) {\n    data[`${ sidecar.id }.${ id }`] = value;\n  }\n\n  if (!existing) {\n    await devFetch(`${ BASE }/v1/configmaps`, {\n      method: 'POST',\n      body:   JSON.stringify({\n        apiVersion: 'v1',\n        kind:       'ConfigMap',\n        metadata:   { namespace, name: SIDECAR_PARAMS_MAP },\n        data,\n      }),\n    });\n\n    return;\n  }\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data }) });\n}\n\n/**\n * The whole of a sidecar's log, for the card's log window.\n *\n * podLogTail next door answers a different question - what is it doing right now, in one line, on\n * a card - and takes the last line for it. This is what someone opens when that line was not\n * enough, so it is the last few hundred.\n */\nexport async function sidecarLog(workspace: string, sidecar: DevSidecar, lines = 500): Promise<string> {\n  const namespace = workspaceNamespace(workspace);\n  const pods = await devFetch(`${ BASE }/v1/pods/${ namespace }`).catch(() => null);\n  const pod = (pods?.data || []).find((candidate: Json) => candidate.metadata?.labels?.[LABEL_SIDECAR] === sidecar.id);\n\n  if (!pod) {\n    return '';\n  }\n\n  // `timestamps` because a log line on its own says what happened and not when, and a sidecar\n  // that takes ten minutes to install two helm charts is one where the gap between two lines is\n  // the interesting part. The apiserver prefixes each line with an RFC3339 time; what to do with\n  // that is the caller's.\n  const url = `${ BASE }/api/v1/namespaces/${ namespace }/pods/${ pod.metadata.name }/log?container=sidecar&tailLines=${ lines }&timestamps=true`;\n\n  // No Accept header, deliberately. The log subresource answers in plain text and negotiates\n  // against a list that does not include it: asking for `text/plain` is a 406 saying \"only the\n  // following media types are accepted\", and asking for JSON gets a log wrapped in nothing.\n  const response = await fetch(url);\n\n  if (!response.ok) {\n    throw new Error(`The log could not be read: ${ response.status }.`);\n  }\n\n  return response.text();\n}\n\n/**\n * The prompts this person's queued conversations open with.\n *\n * Per user and next to the secret store, for the same reason it is: two people using this\n * product have different ideas about what a review should say, and neither should be editing the\n * other's. Defaults are written in the first time they are asked for, so the page has something\n * to show and to edit rather than an empty box.\n */\nasync function promptsName(): Promise<string> {\n  return `dev-prompts-${ await currentOwner() }`;\n}\n\nexport async function listPrompts(): Promise<DevPrompt[]> {\n  const name = await promptsName();\n  const config = await devFetch(`${ BASE }/v1/configmaps/${ DEV_SYSTEM_NAMESPACE }/${ name }`).catch(() => null);\n\n  // The declaration is what says which prompts exist and what they are for; the ConfigMap only\n  // holds the text. So a prompt added to the code appears for everyone, with its default, and a\n  // prompt removed from the code stops being offered even if someone's copy still has the text.\n  return DEFAULT_PROMPTS.map((prompt) => ({\n    ...prompt,\n    text: config?.data?.[prompt.id] ?? prompt.text,\n  }));\n}\n\nexport async function savePrompts(texts: Record<string, string>): Promise<void> {\n  const name = await promptsName();\n  const url = `${ BASE }/v1/configmaps/${ DEV_SYSTEM_NAMESPACE }/${ name }`;\n  const existing = await devFetch(url).catch(() => null);\n  const data = { ...(existing?.data || {}), ...texts };\n\n  if (!existing) {\n    await devFetch(`${ BASE }/v1/configmaps`, {\n      method: 'POST',\n      body:   JSON.stringify({\n        apiVersion: 'v1',\n        kind:       'ConfigMap',\n        metadata:   { namespace: DEV_SYSTEM_NAMESPACE, name },\n        data,\n      }),\n    });\n\n    return;\n  }\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data }) });\n}\n\n/**\n * Queue a conversation in a workspace: a prompt the next pane to open will start on.\n *\n * A file in the pod rather than a message to something, because there is nothing to send it to:\n * a conversation is a tmux session that may not exist yet, in a workspace that may still be\n * pulling. The file waits, and shell.sh hands it to claude when the pane starts, once. See\n * claude-session.sh.\n *\n * The text is base64 on the way in. It is somebody's prose, it will contain quotes and newlines,\n * and building a shell command out of it any other way is a quoting bug waiting for the first\n * apostrophe.\n */\nexport async function queueConversation(workspace: string, session: string | number, prompt: string): Promise<void> {\n  const namespace = workspaceNamespace(workspace);\n  const pod = await workspacePod(workspace);\n\n  if (!pod) {\n    throw new Error('This workspace has no pod yet, so there is nothing to queue a conversation in.');\n  }\n\n  const encoded = encodeSecret(prompt);\n  const file = `${ WORKSPACE_QUEUE }/${ workspaceSession(session) }`;\n\n  await podExecOnce(namespace, pod, WORKSPACE_CONTAINER, asWorkspaceUser(\n    `mkdir -p ${ WORKSPACE_QUEUE } && echo ${ encoded } | base64 -d > ${ file }`,\n  ));\n}\n\n/**\n * The workspace API: one service, for everything that is not a person.\n *\n * A page cannot be the only way to make a workspace. An action that has just been told to fix\n * something has no browser and no Rancher session, and it should not need either: see\n * WORKSPACE_API_SERVER, which is the service, and this, which puts it in the cluster.\n *\n * One for everybody rather than one each, because it is infrastructure rather than somebody's:\n * what it holds is the templates, and what it makes is a namespace. The rights that needs are\n * cluster-scoped, which is the reason it is a service at all and not something the page does.\n */\nconst API_NAME = 'dev-api';\nconst API_PORT = 8080;\n\n/** Where the extension leaves the templates for it, so what a workspace runs is decided once. */\nconst API_TEMPLATES = 'dev-api-templates';\n\n/** Where a pod reaches it, which is what an action inside a workspace is given. */\nexport function workspaceApiUrl(): string {\n  return `http://${ API_NAME }.${ DEV_SYSTEM_NAMESPACE }.svc:${ API_PORT }`;\n}\n\n/**\n * The templates as data, which is what the service renders from.\n *\n * Published rather than reimplemented: the service makes the same Deployment the page does, from\n * the same declaration, so a template that changes here changes there. Only what it needs -\n * everything about a sidecar except its identity is the page's business.\n */\nfunction publishedTemplates(): Record<string, Json> {\n  const out: Record<string, Json> = {};\n\n  for (const template of TEMPLATES) {\n    out[template.id] = {\n      label:      template.label,\n      image:      template.image,\n      command:    template.command,\n      port:       template.port,\n      scheme:     template.scheme,\n      ownOrigin:  template.ownOrigin,\n      hostPath:   template.hostPath,\n      env:        template.env,\n      sidecars:   (template.sidecars || []).map((sidecar) => ({\n        id: sidecar.id, scheme: sidecar.scheme, providesApi: sidecar.providesApi,\n      })),\n      // The two ConfigMaps a workspace boots from, by name, so the service writes the same ones.\n      configMaps: {\n        [WORKSPACE_CONFIG_MAP]: { 'vue.config.js': WORKSPACE_VUE_CONFIG },\n      },\n    };\n  }\n\n  return out;\n}\n\n/**\n * Create the service if it is not there, and keep its script and its templates current.\n *\n * Quiet, like everything else this extension puts in the cluster: it runs on load for every user\n * including ones who cannot create any of it, and a page that threw here would be a page that\n * never rendered for them.\n */\nexport async function ensureWorkspaceApi(): Promise<void> {\n  const namespace = DEV_SYSTEM_NAMESPACE;\n  const labels = { app: API_NAME };\n\n  // The script, and the templates it renders from. Both rewritten whenever they differ, so an\n  // edit in this repo reaches a service that already exists.\n  for (const [name, data] of [\n    [API_NAME, { 'server.mjs': WORKSPACE_API_SERVER }],\n    [API_TEMPLATES, { 'templates.json': JSON.stringify(publishedTemplates(), null, 2) }],\n  ] as [string, Record<string, string>][]) {\n    const url = `${ BASE }/v1/configmaps/${ namespace }/${ name }`;\n    const existing = await devFetch(url).catch(() => null);\n\n    if (!existing) {\n      await devFetch(`${ BASE }/v1/configmaps`, {\n        method: 'POST',\n        body:   JSON.stringify({\n          apiVersion: 'v1', kind: 'ConfigMap', metadata: { namespace, name, labels }, data,\n        }),\n      }).catch(() => null);\n    } else if (JSON.stringify(existing.data) !== JSON.stringify(data)) {\n      await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data }) }).catch(() => null);\n    }\n  }\n\n  await ensure('serviceaccounts', namespace, API_NAME, {\n    apiVersion: 'v1', kind: 'ServiceAccount', metadata: { namespace, name: API_NAME },\n  });\n\n  // Cluster-scoped, because a workspace is a namespace and nothing namespaced can make one. The\n  // verbs are the ones it uses and no others: it never deletes anything, and deleting a\n  // workspace stays a thing a person does from the page.\n  await ensure('rbac.authorization.k8s.io.clusterroles', null, API_NAME, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'ClusterRole',\n    metadata:   { name: API_NAME },\n    rules:      [\n      { apiGroups: [''], resources: ['namespaces'], verbs: ['get', 'list', 'create'] },\n      {\n        apiGroups: [''], resources: ['serviceaccounts', 'configmaps', 'secrets', 'services'], verbs: ['get', 'create']\n      },\n      {\n        apiGroups: ['apps'], resources: ['deployments'], verbs: ['get', 'create']\n      },\n      {\n        apiGroups: ['rbac.authorization.k8s.io'], resources: ['rolebindings'], verbs: ['get', 'create']\n      },\n    ],\n  });\n\n  await ensure('rbac.authorization.k8s.io.clusterrolebindings', null, API_NAME, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'ClusterRoleBinding',\n    metadata:   { name: API_NAME },\n    roleRef:    { apiGroup: 'rbac.authorization.k8s.io', kind: 'ClusterRole', name: API_NAME },\n    subjects:   [{ kind: 'ServiceAccount', name: API_NAME, namespace }],\n  });\n\n  // It binds `edit` into each workspace it makes, and Kubernetes refuses to grant rights the\n  // granter does not hold. So it holds them, which is the price of making a workspace whose\n  // conversations can manage their own namespace.\n  await ensure('rbac.authorization.k8s.io.clusterrolebindings', null, `${ API_NAME }-edit`, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'ClusterRoleBinding',\n    metadata:   { name: `${ API_NAME }-edit` },\n    roleRef:    { apiGroup: 'rbac.authorization.k8s.io', kind: 'ClusterRole', name: 'edit' },\n    subjects:   [{ kind: 'ServiceAccount', name: API_NAME, namespace }],\n  });\n\n  await ensure('apps.deployments', namespace, API_NAME, {\n    apiVersion: 'apps/v1',\n    kind:       'Deployment',\n    metadata:   { namespace, name: API_NAME, labels },\n    spec:       {\n      replicas: 1,\n      selector: { matchLabels: labels },\n      template: {\n        metadata: { labels },\n        spec:     {\n          serviceAccountName: API_NAME,\n          containers:         [{\n            name:    'api',\n            image:   'node:24',\n            command: ['node', '/seed/server.mjs'],\n            ports:   [{ name: 'http', containerPort: API_PORT }],\n            env:     [\n              { name: 'PORT', value: String(API_PORT) },\n              // The apiserver's own CA, so node verifies it rather than being told not to.\n              { name: 'NODE_EXTRA_CA_CERTS', value: '/var/run/secrets/kubernetes.io/serviceaccount/ca.crt' },\n            ],\n            volumeMounts: [\n              { name: 'seed', mountPath: '/seed', readOnly: true },\n              { name: 'templates', mountPath: '/templates', readOnly: true },\n            ],\n            readinessProbe: { httpGet: { path: '/', port: API_PORT }, periodSeconds: 10 },\n          }],\n          volumes: [\n            { name: 'seed', configMap: { name: API_NAME } },\n            { name: 'templates', configMap: { name: API_TEMPLATES } },\n          ],\n        },\n      },\n    },\n  });\n\n  await ensure('services', namespace, API_NAME, {\n    apiVersion: 'v1',\n    kind:       'Service',\n    metadata:   { namespace, name: API_NAME, labels },\n    spec:       { selector: labels, ports: [{ name: 'http', port: API_PORT, targetPort: 'http' }] },\n  });\n}\n\n/**\n * The Insights database, which is one per person rather than one per workspace.\n *\n * That is the whole shape of the feature: what someone wants to ask is \"what have my agents been\n * doing\", and the answer spans every workspace they have. So it lives in dev-system beside the\n * secret store, named after the same owner, and every workspace is told where it is.\n *\n * It is a plain node:24 with a script from a ConfigMap and a hostPath for the file. There is no\n * image to build and nothing to install: node has carried a SQLite driver in core since 22.5.\n * See INSIGHTS_SERVER.\n */\nconst INSIGHTS_PORT = 8080;\nconst INSIGHTS_HOST_PATH = '/var/lib/rancher/dev-insights';\n\n/** The Deployment, Service and ConfigMap are all called this. */\nexport async function insightsName(): Promise<string> {\n  return `dev-insights-${ await currentOwner() }`;\n}\n\n/**\n * Where a pod reaches it, which is what a workspace's agents are given.\n *\n * A cluster-internal address, so it is reachable from any namespace and from nowhere outside the\n * cluster. Nothing authenticates it beyond that: it holds what this person's own agents chose to\n * record, in a cluster they already have a workspace in.\n */\nexport async function insightsServiceUrl(): Promise<string> {\n  return `http://${ await insightsName() }.${ DEV_SYSTEM_NAMESPACE }.svc:${ INSIGHTS_PORT }`;\n}\n\n/** Where the browser reaches it: the same door every other in-cluster address uses. */\nexport async function insightsProxyUrl(): Promise<string> {\n  const name = await insightsName();\n\n  return `${ BASE }/api/v1/namespaces/${ DEV_SYSTEM_NAMESPACE }/services/http:${ name }:${ INSIGHTS_PORT }/proxy`;\n}\n\n/**\n * Create it if it is not there, and bring its script up to date if it is.\n *\n * Idempotent and quiet, the way everything else this extension puts in the cluster is: it runs\n * when the Insights page loads, for every user, including ones who cannot create anything in\n * dev-system, and a page that threw here would be a page that never rendered.\n */\nexport async function ensureInsights(): Promise<void> {\n  const name = await insightsName();\n  const namespace = DEV_SYSTEM_NAMESPACE;\n  const labels = { app: name };\n  const url = `${ BASE }/v1/configmaps/${ namespace }/${ name }`;\n  const existing = await devFetch(url).catch(() => null);\n  const data = { 'server.mjs': INSIGHTS_SERVER };\n\n  if (!existing) {\n    await devFetch(`${ BASE }/v1/configmaps`, {\n      method: 'POST',\n      body:   JSON.stringify({\n        apiVersion: 'v1', kind: 'ConfigMap', metadata: { namespace, name, labels }, data,\n      }),\n    }).catch(() => null);\n  } else if (existing.data?.['server.mjs'] !== INSIGHTS_SERVER) {\n    await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data }) }).catch(() => null);\n  }\n\n  await ensure('apps.deployments', namespace, name, {\n    apiVersion: 'apps/v1',\n    kind:       'Deployment',\n    metadata:   { namespace, name, labels },\n    spec:       {\n      replicas: 1,\n      selector: { matchLabels: labels },\n      // Recreate: the database is one file on a hostPath, and two writers of one SQLite file is\n      // the one arrangement it is not built for.\n      strategy: { type: 'Recreate' },\n      template: {\n        metadata: { labels },\n        spec:     {\n          containers: [{\n            name:         'insights',\n            image:        'node:24',\n            command:      ['node', '/seed/server.mjs'],\n            ports:        [{ name: 'http', containerPort: INSIGHTS_PORT }],\n            env:          [{ name: 'PORT', value: String(INSIGHTS_PORT) }],\n            volumeMounts: [\n              { name: 'seed', mountPath: '/seed', readOnly: true },\n              { name: 'data', mountPath: '/data' },\n            ],\n            readinessProbe: { tcpSocket: { port: INSIGHTS_PORT }, periodSeconds: 10 },\n          }],\n          volumes: [\n            { name: 'seed', configMap: { name } },\n            // Per owner, so two people's databases are two files, and on the node so a restart\n            // is not the end of what was recorded.\n            {\n              name: 'data', hostPath: { path: `${ INSIGHTS_HOST_PATH }/${ name }`, type: 'DirectoryOrCreate' }\n            },\n          ],\n        },\n      },\n    },\n  });\n\n  await ensure('services', namespace, name, {\n    apiVersion: 'v1',\n    kind:       'Service',\n    metadata:   { namespace, name, labels },\n    spec:       { selector: labels, ports: [{ name: 'http', port: INSIGHTS_PORT, targetPort: 'http' }] },\n  });\n}\n\nexport interface InsightsTable {\n  name: string;\n  columns: string[];\n  rows: number;\n}\n\n/** The tables, with their row counts, which is what the page's tabs are. */\nexport async function insightsTables(): Promise<InsightsTable[]> {\n  const response = await fetch(`${ await insightsProxyUrl() }/api/tables`, { cache: 'no-store' });\n\n  if (!response.ok) {\n    throw new Error('The insights database is not answering yet.');\n  }\n\n  return (await response.json()).tables || [];\n}\n\n/** One query, run in the pod. See the server: it refuses anything that is not a SELECT. */\nexport async function insightsQuery(sql: string): Promise<{ columns: string[]; rows: Json[] }> {\n  const response = await fetch(`${ await insightsProxyUrl() }/api/query`, {\n    method:  'POST',\n    headers: { 'content-type': 'application/json' },\n    body:    JSON.stringify({ sql }),\n  });\n  const body = await response.json().catch(() => ({}));\n\n  if (!response.ok) {\n    throw new Error(body.error || `The query failed: ${ response.status }.`);\n  }\n\n  return body;\n}\n\n/**\n * The account a manager sidecar runs as, in the workspace's own namespace.\n *\n * Not the workspace's account, which is bound to Kubernetes' aggregated `edit`. `edit`\n * deliberately excludes RBAC, and a helm install of vcluster creates a ServiceAccount, a Role and\n * a RoleBinding of its own, so a manager running as the workspace account fails part-way through\n * with a message about roles and leaves half a control plane behind.\n */\nexport const MANAGER_SERVICE_ACCOUNT = 'dev-manager';\n\n/**\n * The scripts a sidecar declared, as a ConfigMap beside it.\n *\n * Rewritten rather than created once, so editing a script in this repo reaches a sidecar that\n * already exists. The pod picks it up on its next start, which is what Restart is for.\n */\nasync function ensureSidecarScripts(workspace: string, sidecar: DevSidecar): Promise<void> {\n  if (!sidecar.scripts) {\n    return;\n  }\n\n  const namespace = workspaceNamespace(workspace);\n  const name = `${ sidecarName(workspace, sidecar.id) }-scripts`;\n  const data: Record<string, string> = {};\n\n  for (const [file, body] of Object.entries(sidecar.scripts)) {\n    data[file] = body\n      .replace(/{{namespace}}/g, namespace)\n      .replace(/{{workspace}}/g, workspace);\n  }\n\n  const url = `${ BASE }/v1/configmaps/${ namespace }/${ name }`;\n  const existing = await devFetch(url).catch(() => null);\n\n  if (existing) {\n    await devFetch(url, { method: 'PUT', body: JSON.stringify({ ...existing, data }) });\n\n    return;\n  }\n\n  await devFetch(`${ BASE }/v1/configmaps`, {\n    method: 'POST',\n    body:   JSON.stringify({\n      apiVersion: 'v1',\n      kind:       'ConfigMap',\n      metadata:   { namespace, name, labels: { [LABEL_WORKSPACE]: workspace, [LABEL_SIDECAR]: sidecar.id } },\n      data,\n    }),\n  });\n}\n\n/**\n * The rights a manager sidecar needs, which are the chart's `rancher-manager` Role verbatim.\n *\n * Namespaced, and wide within the namespace. That is the trade the chart makes and it is the\n * right one: what runs here installs a Kubernetes distribution into a namespace, so it needs\n * everything a helm install of one needs, and the boundary that matters is that it is one\n * workspace's namespace rather than the cluster.\n */\nasync function ensureManagerRbac(workspace: string, sidecar: DevSidecar): Promise<void> {\n  if (!sidecar.manager) {\n    return;\n  }\n\n  const namespace = workspaceNamespace(workspace);\n\n  await ensure('serviceaccounts', namespace, MANAGER_SERVICE_ACCOUNT, {\n    apiVersion: 'v1',\n    kind:       'ServiceAccount',\n    metadata:   { namespace, name: MANAGER_SERVICE_ACCOUNT },\n  });\n\n  await ensure('rbac.authorization.k8s.io.roles', namespace, MANAGER_SERVICE_ACCOUNT, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'Role',\n    metadata:   { namespace, name: MANAGER_SERVICE_ACCOUNT },\n    rules:      MANAGER_RULES,\n  });\n\n  await ensure('rbac.authorization.k8s.io.rolebindings', namespace, MANAGER_SERVICE_ACCOUNT, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'RoleBinding',\n    metadata:   { namespace, name: MANAGER_SERVICE_ACCOUNT },\n    roleRef:    {\n      apiGroup: 'rbac.authorization.k8s.io', kind: 'Role', name: MANAGER_SERVICE_ACCOUNT\n    },\n    subjects: [{ kind: 'ServiceAccount', name: MANAGER_SERVICE_ACCOUNT, namespace }],\n  });\n}\n\n/**\n * Where a sidecar answers inside the cluster, which is not the same as where a browser reaches it.\n *\n * The proxy URL is for a person with a Rancher session; this is for one pod talking to another,\n * and it is what the workspace's dev server is pointed at.\n */\nexport function sidecarServiceUrl(workspace: string, sidecar: DevSidecar): string {\n  const namespace = workspaceNamespace(workspace);\n\n  return `${ sidecar.scheme || 'http' }://${ sidecarName(workspace, sidecar.id) }.${ namespace }.svc`;\n}\n\n/**\n * Start a sidecar, creating it the first time.\n *\n * Three things happen before either path, and all three have to happen on both, which is what\n * the version that only did them on create got wrong:\n *\n *   - the ServiceAccount. A workspace created before this product had one has no `dev-workspace`\n *     in its namespace, and a Deployment naming one that does not exist never produces a pod at\n *     all: the ReplicaSet is refused, and the card reads Starting for ever with nothing to read.\n *   - the generated secrets, so an admin password exists before something asks for it.\n *   - the mirror, because the pod reads its environment when it starts, and a key set in Settings\n *     since the last start reaches it at this moment or not at all.\n *\n * The values arrive by reference either way, so `kubectl get deploy -o yaml` shows a Secret name\n * and a key rather than a token.\n */\nexport async function startSidecar(workspace: string, sidecar: DevSidecar, template: DevTemplate): Promise<void> {\n  const namespace = workspaceNamespace(workspace);\n  const name = sidecarName(workspace, sidecar.id);\n  const url = `${ BASE }/v1/apps.deployments/${ namespace }/${ name }`;\n\n  await ensureWorkspaceRbac(workspace);\n\n  // The store as it stands once anything generated has been filled in, carried from here rather\n  // than read again at each step. See ensureGeneratedSecrets.\n  const store = await ensureGeneratedSecrets(template);\n\n  // Refused rather than started without it. The reference is `optional`, so a sidecar started\n  // without a key it declared comes up, answers nothing and looks healthy, which is the failure\n  // this is here to make impossible. The card disables Start for the same reason; this is the\n  // half that a second tab or a stale page cannot get around.\n  const keys = Object.entries(store).filter(([, value]) => !!value).map(([key]) => key);\n  const missing = missingSecrets(sidecar, template, keys)\n    .filter((key) => (template.secrets || []).find((secret) => secret.key === key)?.required !== false);\n\n  if (missing.length) {\n    throw new Error(`${ sidecar.label } needs ${ missing.join(', ') }, which is not set. Set it in Settings first.`);\n  }\n\n  await mirrorSecrets(workspace, template, store);\n\n  // Every key this sidecar declared, present in the store the mirror was just written from.\n  //\n  // The reference is optional, so a key that did not make it arrives as an empty variable and the\n  // container carries on with it. For a generated password that means the thing it protects is\n  // installed with no password at all, and the failure surfaces minutes later as a login that\n  // cannot succeed and a reset that has nothing to reset to. Checked here, where it is still a\n  // sentence rather than a mystery.\n  const blank = (sidecar.secrets || []).filter((key) => !store[templateSecretKey(template.id, key)]);\n\n  if (blank.length) {\n    throw new Error(`${ sidecar.label } cannot be started: ${ blank.join(', ') } has no value in the secret store.`);\n  }\n\n  // Both of these are rewritten on every start, not created once. A script edited in this repo\n  // has to reach a sidecar that already exists, and a manager's rights have to be there before\n  // its ReplicaSet is admitted rather than after.\n  await ensureSidecarScripts(workspace, sidecar);\n  await ensureManagerRbac(workspace, sidecar);\n\n  // What the gear was last saved with, read here rather than in the pod spec so both the create\n  // and the update path get the same answer from one fetch.\n  const params = await sidecarParams(workspace, sidecar);\n\n  // The browser's own extension, built for this workspace. See ensureBrowserExtension.\n  if (sidecar.extension) {\n    await ensureBrowserExtension(workspace, template, store);\n  }\n\n  // The workspace itself, brought up to date. A workspace made before its template asked for an\n  // origin of its own is still in proxy mode, and starting its Rancher is exactly the moment\n  // somebody expects that to have been sorted out: without this they get a restart and a\n  // workspace whose dashboard still calls the Rancher this page is served from.\n  await bringWorkspaceUpToDate(workspace, template);\n\n  const existing = await devFetch(url).catch(() => null);\n\n  if (existing) {\n    // The declaration as it stands today, not as it stood when this Deployment was made. A sidecar\n    // created before its declaration asked for a variable never gains it otherwise, which is not\n    // academic: the auth switch added five secrets and the node's address to a manager that already\n    // existed, and a manager without them starts, says nothing, and cannot configure anything.\n    existing.spec.replicas = 1;\n    existing.spec.template.spec = sidecarPodSpec(workspace, sidecar, template, params);\n    await devFetch(url, { method: 'PUT', body: JSON.stringify(existing) });\n\n    return;\n  }\n\n  const labels = { app: name, [LABEL_WORKSPACE]: workspace, [LABEL_SIDECAR]: sidecar.id };\n\n  await devFetch(`${ BASE }/v1/apps.deployments`, {\n    method: 'POST',\n    body:   JSON.stringify({\n      apiVersion: 'apps/v1',\n      kind:       'Deployment',\n      metadata:   { namespace, name, labels },\n      spec:       {\n        replicas: 1,\n        selector: { matchLabels: { app: name } },\n        // Recreate rather than RollingUpdate, as the chart has it for the same containers. A\n        // sidecar is one instance of one thing, often holding a port or a directory, and during a\n        // rolling update there are two of them: the card would read the older pod's state and\n        // report Running while the new one cannot start at all.\n        strategy: { type: 'Recreate' },\n        template: { metadata: { labels }, spec: sidecarPodSpec(workspace, sidecar, template, params) },\n      },\n    }),\n  });\n\n  await ensureSidecarService(workspace, sidecar);\n}\n\n/**\n * The pod a sidecar's declaration describes.\n *\n * One function rather than an object literal inside the create path, because the update path needs\n * the same answer: what a sidecar's pod should be is a property of the declaration, and a\n * Deployment that already exists is just as entitled to today's version of it as a new one.\n */\nfunction sidecarPodSpec(workspace: string, sidecar: DevSidecar, template: DevTemplate, params: Record<string, string> = {}): Json {\n  const namespace = workspaceNamespace(workspace);\n  const name = sidecarName(workspace, sidecar.id);\n  const owns = (template.sidecars || []).find((candidate) => candidate.providesApi);\n  const substitute = (value: string) => value\n    .replace(/{{namespace}}/g, namespace)\n    .replace(/{{workspace}}/g, workspace)\n    .replace(/{{workspaceUrl}}/g, workspaceServiceUrl(workspace, template))\n    // The workspace's own Rancher, by the address it will answer on whether or not it is running\n    // yet. Written in from the moment the sidecar that uses it is created, for the reason\n    // substituteTemplateEnv gives: an address that appears only once something is up is an\n    // address nothing can be pointed at in advance.\n    .replace(/{{ownRancher}}/g, owns ? sidecarServiceUrl(workspace, owns) : '');\n\n  return {\n    // A manager runs as an account of its own. See ensureManagerRbac.\n    serviceAccountName: sidecar.manager ? MANAGER_SERVICE_ACCOUNT : WORKSPACE_SERVICE_ACCOUNT,\n    containers:         [{\n      name:  'sidecar',\n      image: sidecar.image,\n      ...(sidecar.command ? { command: sidecar.command } : {}),\n      ...(sidecar.args ? { args: sidecar.args } : {}),\n      ...(sidecar.port ? { ports: [{ name: 'http', containerPort: sidecar.port }] } : {}),\n      env: [\n        ...Object.entries(sidecar.env || {}).map(([envName, value]) => ({\n          name: envName, value: substitute(value)\n        })),\n        // What the card's gear was last saved with. Declared values only, so a key left in the\n        // ConfigMap by a parameter that has since been removed reaches nothing. See sidecarParams.\n        ...(sidecar.params || []).map((param) => ({\n          name: param.env, value: params[param.id] ?? (param.default || ''),\n        })),\n        // By reference, never by value: the token is not in the pod spec, so it is not\n        // in `kubectl get deploy -o yaml` either.\n        ...(sidecar.secrets || []).map((key) => ({\n          name:      key,\n          valueFrom: { secretKeyRef: { name: MIRROR_SECRET, key, optional: true } },\n        })),\n        // The same values under whatever name the image actually reads. See secretEnv.\n        ...Object.entries(sidecar.secretEnv || {}).map(([envName, key]) => ({\n          name:      envName,\n          valueFrom: { secretKeyRef: { name: MIRROR_SECRET, key, optional: true } },\n        })),\n        // Read off the pod rather than out of the declaration, because nothing on this\n        // side of the API knows it. See fieldEnv.\n        ...Object.entries(sidecar.fieldEnv || {}).map(([envName, fieldPath]) => ({\n          name:      envName,\n          valueFrom: { fieldRef: { fieldPath } },\n        })),\n      ],\n      // The chart's own budget: half an hour of ten-second-apart attempts, starting a\n      // minute in. What it is waiting for is two helm installs into a cluster this pod has\n      // to create first, and a probe that gave up sooner would kill the thing it is\n      // measuring part-way through.\n      ...(sidecar.readyPort ? {\n        readinessProbe: {\n          tcpSocket:           { port: sidecar.readyPort },\n          initialDelaySeconds: 60,\n          periodSeconds:       20,\n          failureThreshold:    90,\n        },\n      } : {}),\n      ...(sidecar.preStop ? { lifecycle: { preStop: { exec: { command: sidecar.preStop } } } } : {}),\n      volumeMounts: [\n        ...(sidecar.scripts ? [{ name: 'scripts', mountPath: '/scripts', readOnly: true }] : []),\n        ...(sidecar.shm ? [{ name: 'shm', mountPath: '/dev/shm' }] : []),\n        // One mount per file, with subPath, rather than the whole Secret at one path.\n        //\n        // A Secret volume is a directory of symlinks into a hidden `..data` directory, and\n        // Chromium will not load an unpacked extension whose manifest is one: it reports nothing\n        // and runs without it, which is exactly what it did. A subPath mount is a real file. The\n        // cost is that these no longer update in place, which does not matter here because the\n        // Secret is rewritten and the pod rolled in the same breath. See ensureBrowserExtension.\n        ...(sidecar.extension ? Object.keys(BROWSER_EXTENSION_FILES).map((file) => ({\n          name: 'extension', mountPath: `${ BROWSER_EXTENSION_MOUNT }/${ file }`, subPath: file, readOnly: true,\n        })) : []),\n      ],\n    }],\n    volumes: [\n      ...(sidecar.scripts ? [{ name: 'scripts', configMap: { name: `${ name }-scripts`, defaultMode: 0o555 } }] : []),\n      // A container gets 64MB of shared memory by default, and Chromium's renderers pass their\n      // surfaces through it: the documented symptom of leaving it at 64MB is tabs dying as \"Aw,\n      // Snap\" on pages of any size. The closet's compose file says the same thing to the same\n      // image as `shm_size: 1gb`. Memory-backed, so it is the pod's own memory rather than the\n      // node's disk.\n      ...(sidecar.shm ? [{ name: 'shm', emptyDir: { medium: 'Memory', sizeLimit: '1Gi' } }] : []),\n      // The extension's files, as a directory Chromium can be pointed at. `optional`, so a\n      // sidecar that starts before the Secret is written comes up without it rather than\n      // staying in ContainerCreating for ever.\n      ...(sidecar.extension ? [{\n        name: 'extension', secret: { secretName: BROWSER_EXTENSION_SECRET, optional: true }\n      }] : []),\n    ],\n  };\n}\n\n/**\n * A sidecar's Service, of the type its declaration asks for.\n *\n * Written on every start rather than only on the first, and upgraded in place, for the same reason\n * the workspace's own Service is: a sidecar started before its declaration wanted a node port\n * already has a ClusterIP Service, and nothing else would ever put that right.\n */\nasync function ensureSidecarService(workspace: string, sidecar: DevSidecar): Promise<void> {\n  if (!sidecar.port) {\n    return;\n  }\n\n  const namespace = workspaceNamespace(workspace);\n  const name = sidecarName(workspace, sidecar.id);\n  const labels = { app: name, [LABEL_WORKSPACE]: workspace, [LABEL_SIDECAR]: sidecar.id };\n  const url = `${ BASE }/v1/services/${ namespace }/${ name }`;\n  const service = await devFetch(url).catch(() => null);\n\n  if (!service) {\n    await devFetch(`${ BASE }/v1/services`, {\n      method: 'POST',\n      body:   JSON.stringify({\n        apiVersion: 'v1',\n        kind:       'Service',\n        metadata:   { namespace, name, labels },\n        spec:       {\n          ...(sidecar.nodePort ? { type: 'NodePort' } : {}),\n          selector: { app: name },\n          ports:    [{ name: sidecar.scheme || 'http', port: sidecar.port, targetPort: 'http' }],\n        },\n      }),\n    });\n\n    return;\n  }\n\n  let changed = false;\n\n  if (sidecar.nodePort && service.spec?.type !== 'NodePort') {\n    service.spec.type = 'NodePort';\n    changed = true;\n  }\n\n  // The port the declaration now names. Figma was declared on 3000 and listens on 8000, so its\n  // Service pointed at a port nothing was bound to and every link to it was dead; correcting the\n  // declaration has to correct the Service too, or the fix reaches only new workspaces. The\n  // existing entry is edited rather than replaced, so an assigned nodePort is not given up.\n  const entry = service.spec?.ports?.[0];\n\n  if (entry && entry.port !== sidecar.port) {\n    entry.port = sidecar.port;\n    entry.name = sidecar.scheme || 'http';\n    entry.targetPort = 'http';\n    changed = true;\n  }\n\n  if (changed) {\n    await devFetch(url, { method: 'PUT', body: JSON.stringify(service) });\n  }\n}\n\n/** Where a sidecar with a node port answers, for the browser rather than for a pod. */\nexport async function sidecarNodePort(workspace: string, sidecar: DevSidecar): Promise<number> {\n  const namespace = workspaceNamespace(workspace);\n  const url = `${ BASE }/v1/services/${ namespace }/${ sidecarName(workspace, sidecar.id) }`;\n  const service = await devFetch(url).catch(() => null);\n\n  return service?.spec?.ports?.[0]?.nodePort || 0;\n}\n\n/**\n * The auth provider a workspace has asked its own Rancher to use, and what came of it.\n *\n * A ConfigMap rather than a call, because the thing that carries it out is the manager sidecar and\n * it is not always running: a choice made while it is down has to still be there when it comes\n * back, exactly as the closet keeps it in `.env` so its bootstraps re-apply it. See AUTH_SCRIPT.\n */\nexport const AUTH_CONFIG_MAP = 'dev-auth';\n\nexport interface DevAuthState {\n  /** What was asked for. Empty means local users only. */\n  wanted: string;\n  /** What the manager last got this Rancher to accept, which is empty until it has. */\n  applied: string;\n  /** The manager's own sentence about the last attempt. */\n  message: string;\n  at: string;\n}\n\nexport async function workspaceAuth(workspace: string): Promise<DevAuthState> {\n  const namespace = workspaceNamespace(workspace);\n  const config = await devFetch(`${ BASE }/v1/configmaps/${ namespace }/${ AUTH_CONFIG_MAP }`).catch(() => null);\n  const data = config?.data || {};\n\n  return {\n    wanted:  data.provider || '',\n    applied: data.applied || '',\n    message: data.message || '',\n    at:      data.at || '',\n  };\n}\n\n/**\n * Ask for a provider. Only the request is written here.\n *\n * `applied` is deliberately left alone rather than cleared: it is the manager's, and blanking it\n * would make the card claim nothing is configured during the twenty seconds before the manager\n * notices, which is the opposite of what is true.\n */\nexport async function setWorkspaceAuth(workspace: string, provider: string): Promise<void> {\n  const namespace = workspaceNamespace(workspace);\n  const url = `${ BASE }/v1/configmaps/${ namespace }/${ AUTH_CONFIG_MAP }`;\n  const existing = await devFetch(url).catch(() => null);\n\n  if (existing) {\n    await devFetch(url, {\n      method: 'PUT',\n      body:   JSON.stringify({ ...existing, data: { ...(existing.data || {}), provider } }),\n    });\n\n    return;\n  }\n\n  await devFetch(`${ BASE }/v1/configmaps`, {\n    method: 'POST',\n    body:   JSON.stringify({\n      apiVersion: 'v1',\n      kind:       'ConfigMap',\n      metadata:   { namespace, name: AUTH_CONFIG_MAP, labels: { [LABEL_WORKSPACE]: workspace } },\n      data:       { provider },\n    }),\n  });\n}\n\n/**\n * Restart a sidecar: roll its pod, without ever stopping it.\n *\n * Not stop-then-start, which is what this was. That is two writes with a gap between them, and\n * everything that can go wrong in the gap does: if the second half fails the sidecar is left\n * stopped with the reason showing only as a banner that the next poll replaces, and for a sidecar\n * that owns the workspace's API the two halves point the workspace at the host Rancher and back\n * again, restarting it twice for a change that ends where it began. Observed: a Restart that\n * reported Running and left the Deployment at zero replicas, because the badge was still reading\n * the terminating pod.\n *\n * An annotation on the pod template is how Kubernetes' own `rollout restart` does it: one write,\n * the Deployment's own strategy carries it out, and a sidecar that was running is running\n * throughout. It also picks up whatever the scripts ConfigMap now says, which is the usual reason\n * to press it.\n */\nexport async function restartSidecar(workspace: string, sidecar: DevSidecar, template: DevTemplate): Promise<void> {\n  const namespace = workspaceNamespace(workspace);\n  const url = `${ BASE }/v1/apps.deployments/${ namespace }/${ sidecarName(workspace, sidecar.id) }`;\n  const deployment = await devFetch(url).catch(() => null);\n\n  if (!deployment) {\n    // Never started, so there is nothing to roll and starting it is what was meant.\n    await startSidecar(workspace, sidecar, template);\n\n    return;\n  }\n\n  // The scripts and the secrets are rewritten first, since picking up a change to them is what a\n  // restart is usually for. Generated keys are filled in here as well as on the start path,\n  // because a template that has since declared a new one (the auth switch added two) would\n  // otherwise mirror nothing for it, and the sidecar would come back without a value it needs.\n  await ensureSidecarScripts(workspace, sidecar);\n\n  const store = await ensureGeneratedSecrets(template);\n\n  await mirrorSecrets(workspace, template, store);\n  await ensureSidecarService(workspace, sidecar);\n\n  // The same rewrite the start path does. Restart is what someone presses when the product has\n  // changed its mind about what this pod should be, and the extension is part of that: without\n  // this, a browser that was already running when the extension was added comes back with the\n  // volume declared and nothing in it.\n  if (sidecar.extension) {\n    await ensureBrowserExtension(workspace, template, store);\n  }\n\n  const meta = deployment.spec.template.metadata;\n\n  meta.annotations = { ...(meta.annotations || {}), 'dev.rancher.io/restarted-at': new Date().toISOString() };\n  deployment.spec.replicas = 1;\n  // Today's declaration, for the reason the start path takes it: a restart is what someone presses\n  // when the product has changed its mind about what this pod should be.\n  deployment.spec.template.spec = sidecarPodSpec(workspace, sidecar, template, await sidecarParams(workspace, sidecar));\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify(deployment) });\n}\n\n/**\n * Stop a sidecar by scaling it to nothing, leaving it declared and restartable.\n *\n * Its Service is left behind on purpose: a stopped sidecar keeps the address it will answer on\n * again, so a link to it is still the right link, and a Service with nothing behind it routes\n * nowhere rather than somewhere wrong. The mirrored Secret is left for a different reason, which\n * is that it is the workspace's rather than this sidecar's; both go when the namespace does.\n */\nexport async function stopSidecar(workspace: string, id: string, template?: DevTemplate): Promise<void> {\n  const namespace = workspaceNamespace(workspace);\n  const url = `${ BASE }/v1/apps.deployments/${ namespace }/${ sidecarName(workspace, id) }`;\n  const deployment = await devFetch(url).catch(() => null);\n\n  if (!deployment) {\n    return;\n  }\n\n  deployment.spec.replicas = 0;\n  await devFetch(url, { method: 'PUT', body: JSON.stringify(deployment) });\n\n  // Nothing to put back. The workspace is pointed at this sidecar's address from the day it was\n  // created, so stopping it leaves a dashboard whose API refuses the connection, which is the\n  // truth. The version that swapped the address to the host on stop restarted the workspace twice\n  // per Restart and, in between, pointed a published node port at the host cluster's API.\n  void template;\n}\n\n/** Where a sidecar's own UI is served, on Rancher's origin, the same door a workspace uses. */\nexport function sidecarProxyUrl(workspace: string, sidecar: DevSidecar): string {\n  const namespace = workspaceNamespace(workspace);\n  const scheme = sidecar.scheme || 'http';\n\n  return `${ BASE }/api/v1/namespaces/${ namespace }/services/${ scheme }:${ sidecarName(workspace, sidecar.id) }:${ sidecar.port }/proxy/`;\n}\n\n/** A socket the workspace's own process is listening on, as its pod reports it. */\nexport interface DevListening {\n  port: number;\n  /**\n   * Bound to loopback, so publishing it would not help: a Service routes to the pod's address,\n   * and a server listening only on 127.0.0.1 refuses that connection. Worth saying rather than\n   * hiding, because the fix is one flag on whatever is being run.\n   */\n  loopback: boolean;\n}\n\n/** Whether an address in /proc/net/tcp is a loopback one, in either family. */\nfunction isLoopback(address: string): boolean {\n  // Little-endian hex, so 127.0.0.1 is 0100007F. The v6 form is ::1, which is fifteen zero bytes\n  // and a one, written by the kernel in this order.\n  return address === '0100007F' || address === '00000000000000000000000001000000';\n}\n\n/**\n * What the workspace is actually listening on, rather than what its Service says.\n *\n * From /proc/net/tcp in the pod, which is the one source that needs nothing installed: `ss` and\n * `netstat` are both absent from the image a workspace runs, and a detection that depends on a\n * package the person has to install first is not automatic.\n *\n * `0A` is TCP_LISTEN. Everything else in those files is a connection, including the ones this\n * page's own request makes, so a state filter is what separates a server from its traffic.\n */\nexport async function workspaceListening(name: string): Promise<DevListening[]> {\n  const namespace = workspaceNamespace(name);\n  const pod = await workspacePod(name);\n\n  if (!pod) {\n    return [];\n  }\n\n  const out = await podExecOnce(namespace, pod, WORKSPACE_CONTAINER, [\n    '/bin/sh', '-c', 'cat /proc/net/tcp /proc/net/tcp6 2>/dev/null || true',\n  ]);\n\n  const found = new Map<number, boolean>();\n\n  for (const line of out.split('\\n')) {\n    const fields = line.trim().split(/\\s+/);\n\n    if (fields[3] !== '0A' || !fields[1]) {\n      continue;\n    }\n\n    const [address, hexPort] = fields[1].split(':');\n    const port = parseInt(hexPort, 16);\n\n    if (!port) {\n      continue;\n    }\n\n    // A port bound on both a real address and loopback is reachable, so the reachable answer wins.\n    found.set(port, (found.get(port) ?? true) && isLoopback(address));\n  }\n\n  return [...found.entries()]\n    .map(([port, loopback]) => ({ port, loopback }))\n    .sort((a, b) => a.port - b.port);\n}\n\n/**\n * The ports a workspace has shared, read back from the proxy's own config.\n *\n * Kept on the Deployment as an annotation rather than in a store of this product's own: the\n * shares are what the proxy is running, so the proxy is where they are recorded, and a share that\n * exists in a list but not in nginx would be a link that 502s.\n */\nconst SHARE_ANNOTATION = 'dev.rancher.io/shares';\n\nexport async function listWorkspaceShares(name: string): Promise<DevShare[]> {\n  const namespace = workspaceNamespace(name);\n  const url = `${ BASE }/v1/apps.deployments/${ namespace }/${ shareName(namespace) }`;\n  const deployment = await devFetch(url).catch(() => null);\n\n  try {\n    return JSON.parse(deployment?.metadata?.annotations?.[SHARE_ANNOTATION] || '[]');\n  } catch {\n    return [];\n  }\n}\n\n/**\n * Share a workspace port, or stop sharing it.\n *\n * One function for both because they are the same write: the list of shares is rendered into an\n * nginx config, a password file and a Service, and every one of those is replaced wholesale each\n * time. Sharing the third port and unsharing the second are the same operation on a different\n * list, which is what keeps the four things from drifting apart.\n */\nexport async function setWorkspaceShares(name: string, shares: DevShare[]): Promise<void> {\n  const namespace = workspaceNamespace(name);\n  const proxy = shareName(namespace);\n  const labels = { app: proxy, [LABEL_WORKSPACE]: name };\n\n  await ensureWorkspaceRbac(name);\n\n  // Nothing shared: the proxy is scaled away rather than deleted, so unsharing and sharing again\n  // does not have to wait for an image pull, and so its Service keeps the node ports it was given.\n  if (!shares.length) {\n    const url = `${ BASE }/v1/apps.deployments/${ namespace }/${ proxy }`;\n    const existing = await devFetch(url).catch(() => null);\n\n    if (existing) {\n      existing.spec.replicas = 0;\n      existing.metadata.annotations = { ...(existing.metadata.annotations || {}), [SHARE_ANNOTATION]: '[]' };\n      await devFetch(url, { method: 'PUT', body: JSON.stringify(existing) });\n    }\n\n    return;\n  }\n\n  await upsert('configmaps', namespace, proxy, {\n    apiVersion: 'v1',\n    kind:       'ConfigMap',\n    metadata:   { namespace, name: proxy, labels },\n    data:       { 'nginx.conf': nginxConf(namespace, name, shares) },\n  });\n\n  await upsert('secrets', namespace, proxy, {\n    apiVersion: 'v1',\n    kind:       'Secret',\n    metadata:   { namespace, name: proxy, labels },\n    type:       'Opaque',\n    data:       { htpasswd: encodeSecret(htpasswd(shares)) },\n  }, (secret) => {\n    secret.data = { htpasswd: encodeSecret(htpasswd(shares)) };\n  });\n\n  await upsert('services', namespace, proxy, {\n    apiVersion: 'v1',\n    kind:       'Service',\n    metadata:   { namespace, name: proxy, labels },\n    spec:       {\n      type:     'NodePort',\n      selector: { app: proxy },\n      ports:    shares.map((share) => ({\n        name: `p${ share.listen }`, port: share.listen, targetPort: share.listen,\n      })),\n    },\n  }, (service) => {\n    // The existing entries are kept rather than replaced, so a node port the cluster already\n    // assigned to a share is not given up and every link already sent out keeps working.\n    const before = service.spec?.ports || [];\n\n    service.spec.type = 'NodePort';\n    service.spec.ports = shares.map((share) => {\n      const kept = before.find((entry: Json) => entry.port === share.listen);\n\n      return kept || { name: `p${ share.listen }`, port: share.listen, targetPort: share.listen };\n    });\n  });\n\n  await upsert('apps.deployments', namespace, proxy, {\n    apiVersion: 'apps/v1',\n    kind:       'Deployment',\n    metadata:   {\n      namespace, name: proxy, labels, annotations: { [SHARE_ANNOTATION]: JSON.stringify(shares) }\n    },\n    spec: {\n      replicas: 1,\n      selector: { matchLabels: { app: proxy } },\n      strategy: { type: 'Recreate' },\n      template: { metadata: { labels }, spec: sharePodSpec(namespace, WORKSPACE_SERVICE_ACCOUNT) },\n    },\n  }, (deployment) => {\n    deployment.spec.replicas = 1;\n    deployment.spec.template.spec = sharePodSpec(namespace, WORKSPACE_SERVICE_ACCOUNT);\n    deployment.metadata.annotations = {\n      ...(deployment.metadata.annotations || {}), [SHARE_ANNOTATION]: JSON.stringify(shares),\n    };\n\n    // nginx reads its config once, at start, so a config that changed under a running pod is a\n    // proxy still serving the old set of ports. This is Kubernetes' own `rollout restart`.\n    const meta = deployment.spec.template.metadata;\n\n    meta.annotations = { ...(meta.annotations || {}), 'dev.rancher.io/restarted-at': new Date().toISOString() };\n  });\n}\n\n/** Where a share answers, once the cluster has assigned its Service a node port. */\nexport async function shareNodePorts(name: string): Promise<Record<number, number>> {\n  const namespace = workspaceNamespace(name);\n  const service = await devFetch(`${ BASE }/v1/services/${ namespace }/${ shareName(namespace) }`).catch(() => null);\n  const out: Record<number, number> = {};\n\n  for (const entry of service?.spec?.ports || []) {\n    if (entry.nodePort) {\n      out[entry.port] = entry.nodePort;\n    }\n  }\n\n  return out;\n}\n\n/**\n * Create it, or bring the one that is there up to date.\n *\n * `ensure` next door deliberately leaves an existing object alone, which is right for the things\n * it makes once and wrong for every object here: a share's config is rewritten every time the set\n * of shares changes. The mutate callback is how a caller keeps the parts of an existing object\n * that Kubernetes assigned rather than this code, which is what stops a node port moving under a\n * link somebody has already been given.\n */\nasync function upsert(type: string, namespace: string, name: string, body: Json, mutate?: (existing: Json) => void): Promise<void> {\n  const url = `${ BASE }/v1/${ type }/${ namespace }/${ name }`;\n  const existing = await devFetch(url).catch(() => null);\n\n  if (!existing) {\n    await devFetch(`${ BASE }/v1/${ type }`, { method: 'POST', body: JSON.stringify(body) });\n\n    return;\n  }\n\n  if (mutate) {\n    mutate(existing);\n  } else {\n    existing.data = body.data;\n  }\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify(existing) });\n}\n\n/**\n * The node ports the cluster has already given out.\n *\n * Asked so that a suggestion is a port that will actually be accepted rather than one the\n * apiserver rejects a moment later. It reads every Service the person can see, which for an\n * admin is all of them and for anyone else is a subset - a suggestion built from a subset is\n * still better than one built from nothing, and the cluster has the final say either way.\n */\nexport async function usedNodePorts(): Promise<number[]> {\n  const services = await devFetch(`${ BASE }/v1/services`).catch(() => null);\n\n  return (services?.data || [])\n    .flatMap((service: Json) => service.spec?.ports || [])\n    .map((port: Json) => port.nodePort)\n    .filter((port: number) => !!port);\n}\n\n/** The range Kubernetes assigns node ports from, and refuses anything outside. */\nexport const NODE_PORT_RANGE = { first: 30000, last: 32767 };\n\n/**\n * A published port for a local one: free, and the same answer every time it is asked.\n *\n * Derived from the local port rather than taken from the bottom of the range, so a workspace's\n * 8005 lands somewhere memorable and lands there again after it is unforwarded and forwarded.\n * Collisions walk forward from there.\n */\nexport function suggestNodePort(port: number, used: number[]): number {\n  const span = NODE_PORT_RANGE.last - NODE_PORT_RANGE.first + 1;\n  const taken = new Set(used);\n\n  for (let i = 0; i < span; i++) {\n    const candidate = NODE_PORT_RANGE.first + ((port + i) % span);\n\n    if (!taken.has(candidate)) {\n      return candidate;\n    }\n  }\n\n  // Every port in the range is spoken for, which is not a thing that happens in a cluster with\n  // room for another workspace. Nothing suggested is better than a number that cannot work.\n  return 0;\n}\n\n/** One entry in a workspace's Service. */\nexport interface DevPort {\n  name: string;\n  port: number;\n  /** The published port, or 0 where the Service does not publish this one. */\n  nodePort?: number;\n}\n\n/** Kubernetes' own limit on a Service port name, which is a DNS label of at most 15 characters. */\nconst PORT_NAME_PATTERN = /^[a-z0-9]([-a-z0-9]*[a-z0-9])?$/;\nconst MAX_PORT_NAME_LENGTH = 15;\n\n/**\n * Every port a workspace's Service carries.\n *\n * The template's port is the first of these rather than a special case, which is what makes\n * \"the port a workspace serves on\" a list rather than a fact: a workspace can be running a dev\n * server, an app and a debugger, and the harness's answer to that is a route per port.\n */\nexport async function listWorkspacePorts(name: string): Promise<DevPort[]> {\n  const namespace = workspaceNamespace(name);\n  const services = await devFetch(`${ BASE }/v1/services/${ namespace }`).catch(() => null);\n  const service = (services?.data || []).find((svc: Json) => svc.metadata?.name === namespace);\n\n  return (service?.spec?.ports || []).map((port: Json) => ({\n    name:     port.name || '',\n    port:     port.port,\n    // What it is published on, when the Service is a NodePort. This is the public half of the\n    // mapping the Ports tab draws.\n    nodePort: port.nodePort || 0,\n  }));\n}\n\n/** Why a port cannot be added, or '' when it can. */\nexport function portError(port: number, existing: DevPort[]): string {\n  if (!Number.isInteger(port) || port < 1 || port > 65535) {\n    return 'A port is a number between 1 and 65535';\n  }\n\n  if (existing.some((entry) => entry.port === port)) {\n    return `This workspace already serves port ${ port }`;\n  }\n\n  return '';\n}\n\n/**\n * A name for a port that Kubernetes will accept.\n *\n * Every port in a Service with more than one has to be named, and the name is a DNS label, so\n * `8080` on its own is not one. `p8080` is, and it is derived rather than asked for: a name is\n * something Kubernetes needs and nobody using this has an opinion about.\n */\nfunction portName(port: number): string {\n  const name = `p${ port }`;\n\n  return PORT_NAME_PATTERN.test(name) && name.length <= MAX_PORT_NAME_LENGTH ? name : `p${ port }`.slice(0, MAX_PORT_NAME_LENGTH);\n}\n\n/**\n * Add or remove a port on a workspace's Service.\n *\n * Read-modify-write through Steve, the same shape as scaling a Deployment, so a second tab\n * editing the same Service loses the resourceVersion check rather than silently winning it.\n *\n * This does not touch the pod. A Service is a set of routing rules in front of whatever the\n * pod already listens on, so adding a port here publishes something that is already there and\n * removing one takes the route away rather than the server. Whether anything answers on it is\n * a separate question, which is why the ports list asks it separately.\n */\nasync function editWorkspacePorts(name: string, edit: (ports: Json[]) => Json[]): Promise<void> {\n  const namespace = workspaceNamespace(name);\n  const url = `${ BASE }/v1/services/${ namespace }/${ namespace }`;\n  const service = await devFetch(url);\n\n  service.spec.ports = edit(service.spec.ports || []);\n\n  await devFetch(url, { method: 'PUT', body: JSON.stringify(service) });\n}\n\n/**\n * Add a port, and optionally say which published one it should answer on.\n *\n * The harness maps a public port to a local one, and this is that mapping in Kubernetes: the\n * local port is the one the workspace is listening on, and the public one is the node port. A\n * node port left out is chosen by the cluster from its own range, which is the ordinary case; a\n * node port asked for is one somebody wants to keep stable across rebuilds, and the cluster\n * refuses it if it is outside the range or already taken.\n */\nexport function addWorkspacePort(name: string, port: number, nodePort?: number): Promise<void> {\n  return editWorkspacePorts(name, (ports) => [\n    ...ports,\n    // targetPort is the number rather than a named port: a name only exists if the\n    // Deployment's container declared it, and a port added after the fact has not been.\n    {\n      name: portName(port), port, targetPort: port, protocol: 'TCP', ...(nodePort ? { nodePort } : {}),\n    },\n  ]);\n}\n\nexport function removeWorkspacePort(name: string, port: number): Promise<void> {\n  return editWorkspacePorts(name, (ports) => ports.filter((entry) => entry.port !== port));\n}\n\n/**\n * Where a workspace's own server is served, on Rancher's origin.\n *\n * The Kubernetes apiserver's service proxy, which is the same door the dev server this\n * dashboard is served through comes out of. Root-relative on purpose: the browser resolves it\n * against whatever host Rancher is on, so nothing here ever learns or hardcodes a hostname,\n * and the URL works for anyone whose Rancher session can reach the namespace.\n *\n * `http:` is the scheme the proxy should speak to the Service in, not part of its name.\n */\nexport function workspaceProxyUrl(name: string, port: number, scheme = 'http'): string {\n  const namespace = workspaceNamespace(name);\n\n  return `${ BASE }/api/v1/namespaces/${ namespace }/services/${ scheme }:${ namespace }:${ port }/proxy/`;\n}\n\n/**\n * Whether anything is answering on that port yet.\n *\n * A workspace can be Running with nothing listening: the image is still starting, the server\n * inside it is still compiling, or the template's command is wrong. The proxy's own answer to\n * that is a 503 with a Kubernetes Status in it, and framing that is how a page ends up\n * showing someone an apiserver error page and calling it their app.\n *\n * Only the proxy's own failures count as not serving. A 404 or a 500 from the workspace is the\n * workspace answering, which is something to show rather than something to wait through.\n */\nexport function workspaceServing(name: string, port: number, scheme = 'http'): Promise<boolean> {\n  return proxyServing(workspaceProxyUrl(name, port, scheme));\n}\n\n/**\n * The same question about a sidecar, which has the same two answers for the same reasons.\n *\n * A running pod is not a served page: the browser sidecar's Deployment is Available a second or\n * two before its UI answers, and framing it in that window shows an apiserver 503 that nothing\n * afterwards clears, because an iframe on another origin's path cannot be told to reload.\n */\nexport function sidecarServing(workspace: string, sidecar: DevSidecar): Promise<boolean> {\n  return proxyServing(sidecarProxyUrl(workspace, sidecar));\n}\n\n/**\n * Whether a sidecar is up and answering: both halves, because neither alone is the answer.\n *\n * The Deployment is asked about first, and it is not redundant. A sidecar that has never been\n * started has no Service either, and the apiserver's proxy answers a missing Service with a 404,\n * which serving deliberately counts as \"answering\" — a 404 from a running app is the app talking.\n * So without this, a browser nobody has started would read as up.\n */\nexport async function sidecarReady(workspace: string, sidecar: DevSidecar): Promise<boolean> {\n  const namespace = workspaceNamespace(workspace);\n  const url = `${ BASE }/v1/apps.deployments/${ namespace }/${ sidecarName(workspace, sidecar.id) }`;\n  const deployment = await devFetch(url).catch(() => null);\n\n  if (!deployment?.status?.readyReplicas) {\n    return false;\n  }\n\n  return sidecarServing(workspace, sidecar);\n}\n\nasync function proxyServing(url: string): Promise<boolean> {\n  try {\n    const resp = await fetch(url, { cache: 'no-store' });\n\n    return ![502, 503, 504].includes(resp.status);\n  } catch {\n    // A network-level failure, which here means the request never reached Rancher.\n    return false;\n  }\n}\n\n/**\n * WebSocket URL for running a command in a pod, on a TTY.\n *\n * This is the Kubernetes exec subresource, the same one the dashboard's own container shell\n * uses, so it carries the browser's Rancher session and needs nothing else to authenticate.\n * The protocol is `base64.channel.k8s.io`: every frame is a channel digit (0 stdin, 1 stdout,\n * 2 stderr, 3 error, 4 resize) followed by base64.\n */\nexport function podExecUrl(namespace: string, pod: string, container: string, command: string[], tty = true): string {\n  const origin = window.location.origin.replace(/^http/, 'ws');\n  const params = new URLSearchParams({\n    container,\n    stdin:  tty ? '1' : '0',\n    stdout: '1',\n    stderr: '1',\n    tty:    tty ? '1' : '0',\n  });\n\n  // Repeated, not comma-joined: this is argv.\n  for (const arg of command) {\n    params.append('command', arg);\n  }\n\n  return `${ origin }${ BASE }/api/v1/namespaces/${ namespace }/pods/${ pod }/exec?${ params }`;\n}\n\n/**\n * Run one command in a pod and wait for it to finish, with nobody watching the output.\n *\n * The same exec subresource the terminals use, without the TTY and without a component around\n * it: what this is for is the housekeeping a terminal cannot do for itself, which today is\n * killing the tmux session behind a conversation that has been deleted.\n *\n * It resolves rather than rejects on failure. Every caller is tidying up after something the\n * person has already done, and there is nothing useful to say to them about a pod that has gone\n * away in the meantime — the session went with it.\n */\nexport function podExecOnce(namespace: string, pod: string, container: string, command: string[]): Promise<string> {\n  return new Promise((resolve) => {\n    let out = '';\n\n    try {\n      const socket = new WebSocket(podExecUrl(namespace, pod, container, command, false), 'base64.channel.k8s.io');\n\n      // Every frame is a channel digit then base64. 1 is stdout, which is the only one a caller\n      // has asked about so far; 2 is stderr and 3 is the apiserver's own status, and a command\n      // that writes to either has nothing to say to a caller that only wanted its output.\n      socket.onmessage = (event) => {\n        const frame = String(event.data || '');\n\n        if (frame.startsWith('1')) {\n          try {\n            out += atob(frame.slice(1));\n          } catch { /* a frame that is not base64 is not output */ }\n        }\n      };\n\n      socket.onclose = () => resolve(out);\n      socket.onerror = () => resolve(out);\n    } catch {\n      resolve(out);\n    }\n  });\n}\n\n/**\n * What a workspace's conversation runs, which is the same thing the dev server pod's tabs run.\n *\n * It was a bare shell, and that was not a design: nothing installed claude into a workspace and\n * nothing shared a login with one, so the tab landed in `sh` and said so. Both halves are now\n * the workspace's own — the scripts are mounted at /seed (ensureWorkspaceTerminal) and the\n * template installs claude on boot — so this is `shell.sh`, exactly as the dev pod calls it:\n * tmux, so a conversation outlives the browser tab, then claude in a loop.\n *\n * The three arguments are the session, the directory, and the home:\n *\n *   - the session names the tmux session, so conversation 2 is a different pane from\n *     conversation 1 and both survive a page reload.\n *   - the directory is the checkout, because that is the thing a workspace exists to work on.\n *     The dev pod gives each of its global terminals a directory of its own instead, since\n *     claude keys its history by working directory and those sessions have nothing in common;\n *     here they do, and a second conversation continuing the first one's history in the same\n *     repository is the behaviour to want rather than one to design around.\n *   - the home is on the workspace's own hostPath, so a login survives a restart.\n */\nexport function workspaceTerminalCommand(session: string | number): string[] {\n  return ['/bin/sh', `${ WORKSPACE_TERMINAL_MOUNT }/shell.sh`, workspaceSession(session), WORKSPACE_WORKDIR, WORKSPACE_HOME];\n}\n\n/**\n * A command, run as the user the workspace's conversations belong to.\n *\n * The exec subresource runs as the container's user, which is root, and tmux is not a service:\n * its server is a socket under /tmp owned by whoever started it, and the panes were started as\n * the node user (see shell.sh). So `tmux ls` as root finds no server and answers that a workspace\n * with two conversations in it has none. The same drop shell.sh does, for the same reason.\n */\nfunction asWorkspaceUser(command: string): string[] {\n  return ['/bin/sh', '-c', `if [ \"$(id -u)\" = 0 ]; then setpriv --reuid=1000 --regid=1000 --init-groups /bin/sh -c '${ command }'; else /bin/sh -c '${ command }'; fi`];\n}\n\n/** The tmux session one conversation is, named the same way in both places that need it. */\nfunction workspaceSession(session: string | number): string {\n  return `ws-${ session }`;\n}\n\n/**\n * The conversations a workspace actually has, which is what its pod says rather than what this\n * page last remembered.\n *\n * A conversation is a tmux session, so it outlives the browser tab that made it. The list used to\n * be component state that started at one row on every load, which meant a reload lost every\n * conversation but the first: they carried on in the pod with claude in them, invisible, and the\n * delete on a row had nothing to act on. So the pod is asked.\n *\n * Nothing yet, a pod with no tmux, and a pod that has gone away all answer the same way here, and\n * the caller shows one conversation, which is what a workspace nobody has opened has.\n */\nexport async function listWorkspaceConversations(name: string): Promise<number[]> {\n  const namespace = workspaceNamespace(name);\n  const pod = await workspacePod(name);\n\n  if (!pod) {\n    return [];\n  }\n\n  const out = await podExecOnce(namespace, pod, WORKSPACE_CONTAINER, asWorkspaceUser(\n    'tmux ls -F \"#{session_name}\" 2>/dev/null || true',\n  ));\n\n  // `mc-ws-2` is conversation 2. The prefix is shell.sh's (`mc-$SESSION`) and the `ws-` is\n  // workspaceSession's, so a global terminal's session in some other pod could never be read as\n  // one of these even if it were listed here.\n  const numbers = out.split('\\n')\n    .map((line) => /^mc-ws-(\\d+)$/.exec(line.trim())?.[1])\n    .filter((found): found is string => !!found)\n    .map(Number);\n\n  return [...new Set(numbers)].sort((a, b) => a - b);\n}\n\n/**\n * End a conversation in the pod, not only in the browser.\n *\n * Closing the pane closes a socket, and tmux is the whole reason that is not enough: the session\n * carries on in the pod with claude in it, and creating a conversation with the same number\n * later would reattach to it. So a deleted conversation is one whose session is killed, which is\n * what makes the delete on its row mean what the delete on a workspace's row means.\n */\nexport async function deleteWorkspaceConversation(name: string, session: string | number): Promise<void> {\n  const namespace = workspaceNamespace(name);\n  // The workspace's own pod, not one of its sidecars: they are in the same namespace and carry\n  // the same label, and none of them has the session to kill. See findPod.\n  const pod = await workspacePod(name);\n\n  if (!pod) {\n    return;\n  }\n\n  // `|| true` so a session that was never started, or a pod with no tmux in it yet, is a command\n  // that succeeds at doing nothing rather than an error nobody is listening for.\n  await podExecOnce(namespace, pod, WORKSPACE_CONTAINER, asWorkspaceUser(\n    `tmux kill-session -t mc-${ workspaceSession(session) } 2>/dev/null || true`,\n  ));\n}\n\n/** WebSocket URL for a conversation in a workspace's pod. */\nexport function workspaceShellUrl(name: string, pod: string): string {\n  return podExecUrl(workspaceNamespace(name), pod, WORKSPACE_CONTAINER, workspaceTerminalCommand(1));\n}\n",
    "pkg/dev-extension/babel.config.js": "module.exports = require('./.shell/pkg/babel.config.js');\n",
    "pkg/dev-extension/browser-extension.ts": "/**\n * The Chromium extension the workspace's browser sidecar runs with.\n *\n * The same one the harness loads into its own browser: a Quick Login bar on Rancher's login page,\n * and a command menu for the things that are several clicks otherwise. It is here rather than in\n * an image because it has to be built per workspace - the accounts it offers are that workspace's\n * own Rancher's, and the pages it runs on are that workspace's two addresses.\n *\n * The files are the harness's, copied verbatim, with two substitutions:\n *\n *   {{matches}}  the pages the content scripts run on\n *   {{creds}}    the accounts the Quick Login bar offers, as a JSON array\n *\n * The passwords are in there in plain text, which is what a content script needs and what the\n * harness's own copy does. They travel in a Secret rather than a ConfigMap and they are the\n * generated passwords of a Rancher that answers inside one namespace, so the exposure is the same\n * as the Secret they come from - but it is worth knowing that they are readable by anything that\n * can read that Secret, which includes the workspace's own conversations.\n */\nexport const BROWSER_EXTENSION_FILES: Record<string, string> = {\n  \"manifest.json\": `{\n  \"manifest_version\": 3,\n  \"name\": \"Dev workspace helper\",\n  \"version\": \"1.0\",\n  \"content_scripts\": [\n    {\n      \"matches\": [\n        \"{{matches}}\"\n      ],\n      \"js\": [\n        \"autofill.js\",\n        \"command-menu.js\"\n      ],\n      \"css\": [\n        \"styles.css\",\n        \"command-menu.css\"\n      ],\n      \"run_at\": \"document_idle\"\n    }\n  ]\n}\n`,\n\n  \"autofill.js\": `// Add user/password pairs here\nconst CREDS = {{creds}};\n\nlet bar = null;\n\nfunction createBar() {\n  if (bar) return bar;\n\n  bar = document.createElement('div');\n  bar.id = 'autofill-bar';\n\n  const label = document.createElement('span');\n  label.textContent = 'Quick Login:';\n  bar.appendChild(label);\n\n  const select = document.createElement('select');\n  select.id = 'autofill-select';\n\n  const placeholder = document.createElement('option');\n  placeholder.value = '';\n  placeholder.textContent = 'Select account\\\\u2026';\n  select.appendChild(placeholder);\n\n  CREDS.forEach((cred, i) => {\n    const opt = document.createElement('option');\n    opt.value = i;\n    opt.textContent = cred.label + ' (' + cred.username + ')';\n    select.appendChild(opt);\n  });\n\n  select.addEventListener('change', () => {\n    if (select.value === '') return;\n    const cred = CREDS[select.value];\n    fillForm(cred.username, cred.password);\n    bar.classList.remove('visible');\n    select.value = '';\n  });\n\n  bar.appendChild(select);\n\n  const closeBtn = document.createElement('button');\n  closeBtn.className = 'close-btn';\n  closeBtn.textContent = '\\\\u00d7';\n  closeBtn.addEventListener('click', () => bar.classList.remove('visible'));\n  bar.appendChild(closeBtn);\n\n  document.body.appendChild(bar);\n  return bar;\n}\n\nfunction fillForm(username, password) {\n  const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;\n  const u = document.querySelector('input[name=\"username\"], input[type=\"text\"]');\n  const p = document.querySelector('input[type=\"password\"]');\n\n  if (u) {\n    setter.call(u, username);\n    u.dispatchEvent(new Event('input', { bubbles: true }));\n  }\n  if (p) {\n    setter.call(p, password);\n    p.dispatchEvent(new Event('input', { bubbles: true }));\n  }\n}\n\nfunction isLoginPage() {\n  return location.pathname === '/auth/login' ||\n    location.pathname.startsWith('/dashboard/auth/login') ||\n    !!document.querySelector('form.login');\n}\n\nfunction attachListeners() {\n  if (!isLoginPage()) return;\n  const inputs = document.querySelectorAll(\n    'input[name=\"username\"], input[type=\"text\"], input[type=\"password\"]'\n  );\n  inputs.forEach(el => {\n    if (el.dataset.autofillBound) return;\n    el.dataset.autofillBound = '1';\n    el.addEventListener('focus', () => {\n      createBar();\n      bar.classList.add('visible');\n    });\n  });\n}\n\nattachListeners();\nnew MutationObserver(attachListeners).observe(document.body, {\n  childList: true,\n  subtree: true,\n});\n`,\n\n  \"styles.css\": `#autofill-bar {\n  position: fixed;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  background: #1b1c21;\n  border-top: 1px solid #4a4b52;\n  padding: 8px 16px;\n  display: flex;\n  align-items: center;\n  z-index: 999999;\n  font-size: 13px;\n  color: #ccc;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;\n  transform: translateY(100%);\n  transition: transform 0.2s ease;\n}\n\n#autofill-bar.visible {\n  transform: translateY(0);\n}\n\n#autofill-bar span {\n  margin-right: 8px;\n  white-space: nowrap;\n}\n\n#autofill-select {\n  background: #2b2c31;\n  color: #eee;\n  border: 1px solid #4a4b52;\n  border-radius: 4px;\n  padding: 4px 8px;\n  font-size: 13px;\n  cursor: pointer;\n  min-width: 180px;\n}\n\n#autofill-select:hover {\n  border-color: #6a6b72;\n}\n\n#autofill-bar .close-btn {\n  margin-left: auto;\n  background: none;\n  border: none;\n  color: #888;\n  font-size: 16px;\n  cursor: pointer;\n  padding: 0 4px;\n}\n\n#autofill-bar .close-btn:hover {\n  color: #eee;\n}\n`,\n\n  \"command-menu.js\": `// Command registry — add new commands here\nconst COMMANDS = [\n  {\n    id: 'create-ec2-cluster',\n    icon: '\\\\u2601\\\\uFE0F',\n    label: 'Create EC2 Cluster',\n    description: 'Single-node RKE2 cluster on EC2 (c5d.xlarge, us-west-2, Canal)',\n    execute: createEc2Cluster,\n  },\n  {\n    id: 'create-appco-repo',\n    icon: '\\\\ud83d\\\\udce6',\n    label: 'Create AppCo Chart Repository',\n    description: 'Add OCI chart repository for oci://dp.apps.rancher.io/charts',\n    execute: createAppCoRepo,\n    show: function() { return window.location.pathname.includes('/explorer'); },\n  },\n];\n\n// --- API helper ---\n\nconst API_BASE = window.location.origin;\n\nfunction getCsrfToken() {\n  var match = document.cookie.match(/(?:^|;\\\\s*)CSRF=([^;]*)/);\n  return match ? decodeURIComponent(match[1]) : 'CSRF';\n}\n\nasync function rancherApi(method, path, body) {\n  const opts = {\n    method,\n    headers: {\n      'Content-Type': 'application/json',\n      'Accept': 'application/json',\n      'X-Api-Csrf': getCsrfToken(),\n    },\n    credentials: 'include',\n  };\n  if (body) opts.body = JSON.stringify(body);\n\n  const resp = await fetch(API_BASE + path, opts);\n  if (!resp.ok) {\n    let message;\n    try {\n      const json = await resp.json();\n      message = json.message || json.error || resp.statusText;\n    } catch {\n      message = resp.statusText;\n    }\n    throw new Error(method + ' ' + path + ' failed (' + resp.status + '): ' + message);\n  }\n  return resp.json();\n}\n\n// --- EC2 cluster creation ---\n\nasync function createEc2Cluster(setStatus) {\n  var suffix = Math.random().toString(36).substring(2, 6);\n  var clusterName = 'cjackson-' + suffix;\n  var ns = 'fleet-default';\n\n  // 1. Find AWS cloud credential\n  setStatus('pending', 'Finding AWS credential...');\n  var credsResp = await rancherApi('GET', '/v3/cloudcredentials');\n  var awsCred = credsResp.data.find(function (c) {\n    return c.amazonec2credentialConfig || c.name === 'aws-credential';\n  });\n  if (!awsCred) throw new Error('No AWS cloud credential found. Create one in Cluster Management > Cloud Credentials first.');\n\n  // 2. Create machine config\n  setStatus('pending', 'Creating machine config...');\n  var machineConfigName = clusterName + '-machine';\n  await rancherApi('POST', '/v1/rke-machine-config.cattle.io.amazonec2configs', {\n    metadata: {\n      namespace: ns,\n      name: machineConfigName,\n    },\n    region: 'us-west-2',\n    zone: 'a',\n    instanceType: 'c5d.xlarge',\n    rootSize: '50',\n    securityGroup: ['default', 'rancher-nodes'],\n    securityGroupReadonly: true,\n    subnetId: 'subnet-0c97a9f441ca3c895',\n    vpcId: 'vpc-0c618e3a2ec9df47b',\n  });\n\n  // 3. Create RKE2 cluster with machine pool\n  setStatus('pending', 'Creating cluster \"' + clusterName + '\"...');\n  await rancherApi('POST', '/v1/provisioning.cattle.io.clusters', {\n    type: 'provisioning.cattle.io.cluster',\n    metadata: {\n      namespace: ns,\n      name: clusterName,\n    },\n    spec: {\n      cloudCredentialSecretName: awsCred.id,\n      kubernetesVersion: 'v1.34.4+rke2r1',\n      defaultPodSecurityAdmissionConfigurationTemplateName: '',\n      rkeConfig: {\n        chartValues: {},\n        machineGlobalConfig: {\n          cni: 'canal',\n        },\n        machinePools: [\n          {\n            name: 'pool1',\n            controlPlaneRole: true,\n            etcdRole: true,\n            workerRole: true,\n            quantity: 1,\n            machineConfigRef: {\n              kind: 'Amazonec2Config',\n              name: machineConfigName,\n            },\n          },\n        ],\n      },\n    },\n  });\n\n  setStatus('success', 'Cluster \"' + clusterName + '\" creation initiated!');\n}\n\n// --- Cluster helpers ---\n\nfunction getClusterFromUrl() {\n  var match = window.location.pathname.match(/\\\\/c\\\\/([^/]+)\\\\//);\n  return match ? match[1] : 'local';\n}\n\nfunction clusterApiPrefix(clusterId) {\n  return clusterId === 'local' ? '' : '/k8s/clusters/' + clusterId;\n}\n\n// --- AppCo chart repository creation ---\n\nasync function createAppCoRepo(setStatus) {\n  var email = 'cjackson@suse.com';\n  var token = 'aXducXNvb3R1am9hZmpmYXZnYmppdXppY2ZkcW5yc2R3d21rdmlraXdoaXN5c2hqY2RjY25ib3Nsb3Vyc3NhdA==';\n\n  if (!email || !token) {\n    throw new Error('AppCo email and token not configured. Set them in portal settings.');\n  }\n\n  var clusterId = getClusterFromUrl();\n  var apiPrefix = clusterApiPrefix(clusterId);\n  var secretName = 'appco-auth';\n  var repoName = 'appco';\n  var secretNs = 'cattle-system';\n\n  // 1. Create auth secret\n  setStatus('pending', 'Creating AppCo auth secret...');\n  await rancherApi('POST', apiPrefix + '/v1/secrets', {\n    type: 'kubernetes.io/basic-auth',\n    metadata: {\n      name: secretName,\n      namespace: secretNs,\n    },\n    data: {\n      username: btoa(email),\n      password: btoa(token),\n    },\n  });\n\n  // 2. Create OCI chart repository\n  setStatus('pending', 'Creating AppCo chart repository...');\n  await rancherApi('POST', apiPrefix + '/v1/catalog.cattle.io.clusterrepos', {\n    type: 'catalog.cattle.io.clusterrepo',\n    metadata: {\n      name: repoName,\n    },\n    spec: {\n      url: 'oci://dp.apps.rancher.io/charts',\n      clientSecret: {\n        name: secretName,\n        namespace: secretNs,\n      },\n    },\n  });\n\n  setStatus('success', 'AppCo chart repository created!');\n}\n\n// --- Menu UI ---\n\nvar menu = null;\nvar executing = false;\n\nfunction createMenu() {\n  if (menu) return menu;\n\n  menu = document.createElement('div');\n  menu.id = 'command-menu';\n\n  // Header\n  var header = document.createElement('div');\n  header.className = 'cm-header';\n\n  var title = document.createElement('span');\n  title.className = 'cm-title';\n  title.textContent = 'Commands';\n  header.appendChild(title);\n\n  var hint = document.createElement('span');\n  hint.className = 'cm-hint';\n  hint.textContent = 'Ctrl+M to toggle \\\\u00b7 Esc to close';\n  header.appendChild(hint);\n\n  var closeBtn = document.createElement('button');\n  closeBtn.className = 'cm-close';\n  closeBtn.textContent = '\\\\u00d7';\n  closeBtn.addEventListener('click', function () { hideMenu(); });\n  header.appendChild(closeBtn);\n\n  menu.appendChild(header);\n\n  // Command items\n  var items = document.createElement('div');\n  items.className = 'cm-items';\n\n  COMMANDS.forEach(function (cmd) {\n    var item = document.createElement('div');\n    item.className = 'cm-item';\n\n    var icon = document.createElement('span');\n    icon.className = 'cm-icon';\n    icon.textContent = cmd.icon;\n    item.appendChild(icon);\n\n    var textCol = document.createElement('div');\n    textCol.className = 'cm-text';\n\n    var label = document.createElement('span');\n    label.className = 'cm-label';\n    label.textContent = cmd.label;\n    textCol.appendChild(label);\n\n    var desc = document.createElement('span');\n    desc.className = 'cm-desc';\n    desc.textContent = cmd.description;\n    textCol.appendChild(desc);\n\n    item.setAttribute('data-cmd-id', cmd.id);\n    item.appendChild(textCol);\n    item.addEventListener('click', function () { executeCommand(cmd); });\n    items.appendChild(item);\n  });\n\n  menu.appendChild(items);\n\n  // Status area\n  var status = document.createElement('div');\n  status.className = 'cm-status';\n  status.id = 'cm-status';\n  status.style.display = 'none';\n  menu.appendChild(status);\n\n  document.body.appendChild(menu);\n  return menu;\n}\n\nfunction updateCommandVisibility() {\n  if (!menu) return;\n  COMMANDS.forEach(function (cmd) {\n    var item = menu.querySelector('[data-cmd-id=\"' + cmd.id + '\"]');\n    if (!item) return;\n    item.style.display = (cmd.show ? cmd.show() : true) ? '' : 'none';\n  });\n}\n\nfunction showMenu() {\n  createMenu();\n  updateCommandVisibility();\n  menu.classList.add('visible');\n}\n\nfunction hideMenu() {\n  if (menu) menu.classList.remove('visible');\n}\n\nfunction toggleMenu() {\n  createMenu();\n  menu.classList.contains('visible') ? hideMenu() : showMenu();\n}\n\nasync function executeCommand(cmd) {\n  if (executing) return;\n  executing = true;\n\n  var statusEl = document.getElementById('cm-status');\n  statusEl.style.display = 'block';\n  statusEl.className = 'cm-status';\n\n  function setStatus(state, message) {\n    statusEl.textContent = message;\n    statusEl.className = 'cm-status ' + state;\n  }\n\n  try {\n    await cmd.execute(setStatus);\n  } catch (err) {\n    setStatus('error', 'Error: ' + err.message);\n  } finally {\n    executing = false;\n  }\n}\n\n// --- Keyboard listener ---\n\ndocument.addEventListener('keydown', function (e) {\n  if (e.ctrlKey && e.key === 'm') {\n    e.preventDefault();\n    toggleMenu();\n  }\n  if (e.key === 'Escape' && menu && menu.classList.contains('visible')) {\n    e.preventDefault();\n    hideMenu();\n  }\n});\n`,\n\n  \"command-menu.css\": `#command-menu {\n  position: fixed;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  background: #1b1c21;\n  border-top: 1px solid #4a4b52;\n  z-index: 999999;\n  font-size: 13px;\n  color: #ccc;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;\n  transform: translateY(100%);\n  transition: transform 0.2s ease;\n  max-height: 350px;\n  display: flex;\n  flex-direction: column;\n}\n\n#command-menu.visible {\n  transform: translateY(0);\n}\n\n#command-menu .cm-header {\n  display: flex;\n  align-items: center;\n  padding: 8px 16px;\n  border-bottom: 1px solid #333;\n}\n\n#command-menu .cm-title {\n  font-weight: 600;\n  color: #eee;\n  margin-right: 12px;\n}\n\n#command-menu .cm-hint {\n  color: #666;\n  font-size: 11px;\n}\n\n#command-menu .cm-close {\n  margin-left: auto;\n  background: none;\n  border: none;\n  color: #888;\n  font-size: 16px;\n  cursor: pointer;\n  padding: 0 4px;\n}\n\n#command-menu .cm-close:hover {\n  color: #eee;\n}\n\n#command-menu .cm-items {\n  overflow-y: auto;\n  flex: 1;\n}\n\n#command-menu .cm-item {\n  display: flex;\n  align-items: center;\n  padding: 10px 16px;\n  cursor: pointer;\n  transition: background 0.1s;\n}\n\n#command-menu .cm-item:hover {\n  background: #2b2c31;\n}\n\n#command-menu .cm-icon {\n  font-size: 18px;\n  margin-right: 12px;\n  width: 24px;\n  text-align: center;\n}\n\n#command-menu .cm-text {\n  display: flex;\n  flex-direction: column;\n}\n\n#command-menu .cm-label {\n  color: #eee;\n  font-weight: 500;\n}\n\n#command-menu .cm-desc {\n  color: #888;\n  font-size: 11px;\n  margin-top: 2px;\n}\n\n#command-menu .cm-status {\n  padding: 8px 16px;\n  border-top: 1px solid #333;\n  font-size: 12px;\n}\n\n#command-menu .cm-status.pending {\n  color: #f0c674;\n}\n\n#command-menu .cm-status.success {\n  color: #6abf69;\n}\n\n#command-menu .cm-status.error {\n  color: #e06c75;\n}\n`,\n\n};\n",
    "pkg/dev-extension/components/ConfirmDeleteWorkspace.vue": "<script>\n// The confirmation in front of deleting a workspace.\n//\n// Its own component because both the list and the detail page delete, and a second copy of a\n// modal is how the two would come to say different things about what deleting means. It owns\n// the call as well as the markup, so the pages only have to say which workspace and what to do\n// afterwards.\nimport AppModal from '@shell/components/AppModal';\nimport AsyncButton from '@shell/components/AsyncButton';\nimport { Card } from '@components/Card';\nimport { RcButton } from '@components/RcButton';\nimport { deleteWorkspace } from '../api';\n\nexport default {\n  name: 'ConfirmDeleteWorkspace',\n\n  components: {\n    AppModal, AsyncButton, Card, RcButton\n  },\n\n  props: {\n    workspace: {\n      type:     Object,\n      required: true,\n    },\n  },\n\n  emits: ['close', 'deleted', 'error'],\n\n  methods: {\n    async remove(done) {\n      try {\n        await deleteWorkspace(this.workspace.name);\n        // The button is told before anything closes the modal, because closing it unmounts\n        // the button and `done` would then be reporting to something no longer there.\n        done(true);\n        this.$emit('deleted');\n      } catch (e) {\n        done(false);\n        this.$emit('error', e.message || String(e));\n      }\n    },\n  },\n};\n</script>\n\n<template>\n  <AppModal\n    name=\"dev-delete-workspace\"\n    :width=\"480\"\n    @close=\"$emit('close')\"\n  >\n    <Card :show-highlight-border=\"false\">\n      <template #title>\n        <h4 class=\"text-default-text\">\n          Delete {{ workspace.name }}?\n        </h4>\n      </template>\n      <template #body>\n        <p>\n          This deletes the namespace <b>{{ workspace.namespace }}</b> and everything in it. It\n          cannot be undone.\n        </p>\n      </template>\n      <template #actions>\n        <div class=\"dev-confirm__actions\">\n          <RcButton\n            variant=\"secondary\"\n            @click=\"$emit('close')\"\n          >\n            Cancel\n          </RcButton>\n          <AsyncButton\n            mode=\"delete\"\n            class=\"btn bg-error\"\n            @click=\"remove\"\n          />\n        </div>\n      </template>\n    </Card>\n  </AppModal>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-confirm__actions {\n    display:         flex;\n    gap:             var(--dev-space-4);\n    justify-content: flex-end;\n    width:           100%;\n  }\n</style>\n",
    "pkg/dev-extension/components/DevList.vue": "<script>\n// One titled column of rows: a heading with a create control, rows with a state dot and a\n// delete, and a line for when there are none.\n//\n// It exists because the product has two of these columns and they were two different pieces of\n// markup. The sidebar's workspaces had a dot, a create and a two-step delete; the conversation\n// list beside a workspace had a dot it computed itself, a create button in a different place and\n// no delete at all, so a conversation could be opened and never closed. They are the same thing\n// and they are now the same component.\n//\n// The metrics are Rancher's own, kept from the sidebar this was lifted out of: the shell's nav\n// rows are 33px tall with a 16px left inset and 14px labels on a 16px line\n// (components/nav/Group.vue), and $space-s is its small step. Nothing here is picked to match a\n// screenshot.\n//\n// Not the shell's `nav/Type.vue` or `nav/Group.vue`, and both were tried. Type renders its own\n// `<li>`, so a row that needs a dot before the link and a delete after it ends up with an `<li>`\n// inside an `<li>`; Group renders its children through Type with no slot between them, so\n// neither a dot nor a delete can reach a row at all.\nimport BrandImage from '@shell/components/BrandImage';\nimport { colorForState, stateDisplay } from '@shell/plugins/dashboard-store/resource-class';\n\nexport default {\n  name: 'DevList',\n\n  components: { BrandImage },\n\n  emits: ['select', 'create', 'delete'],\n\n  props: {\n    /**\n     * The heading. Uppercased by the stylesheet, so pass it in its ordinary case.\n     *\n     * Empty is allowed and means the column is named by whatever is above it: the heading row\n     * stays, because the create control lives in it, and only the words go.\n     */\n    label: {\n      type:    String,\n      default: '',\n    },\n\n    /** The heading's glyph, from Rancher's icon font. */\n    icon: {\n      type:    String,\n      default: '',\n    },\n\n    /**\n     * A brand image for the heading instead of a glyph, by file name in the shell's assets.\n     *\n     * Which is the only way to use Rancher's own mark: it is an SVG rather than a character in\n     * the icon font, so there is no class that draws it. BrandImage is what the shell's own\n     * header uses, so a Rancher with custom branding gets its logo here too.\n     */\n    logo: {\n      type:    String,\n      default: '',\n    },\n\n    /**\n     * The rows: `{ key, label, state, to }`.\n     *\n     * `state` is a Rancher state name, so the dot is the same colour it would be in a table.\n     * `to` makes the row a link; a row without one is a button and selecting it is an event,\n     * which is the difference between a workspace (a page) and a conversation (a pane).\n     */\n    rows: {\n      type:    Array,\n      default: () => [],\n    },\n\n    /** The key of the row that is selected. */\n    current: {\n      type:    [String, Number],\n      default: '',\n    },\n\n    /** Where the heading's create control goes, when it is a link rather than an event. */\n    createTo: {\n      type:    Object,\n      default: null,\n    },\n\n    /** What the create control says. No label, no control. */\n    createLabel: {\n      type:    String,\n      default: '',\n    },\n\n    /** Whether rows can be deleted. The confirm step is this component's. */\n    deletable: {\n      type:    Boolean,\n      default: false,\n    },\n\n    empty: {\n      type:    String,\n      default: 'None yet',\n    },\n\n    /**\n     * A word about the heading's state, which colours it. '' is the ordinary case.\n     *\n     * The sidebar uses it to say that a cluster is running out of room, which is a thing worth\n     * seeing without opening anything.\n     */\n    tone: {\n      type:    String,\n      default: '',\n    },\n  },\n\n  data() {\n    return {\n      // The row a delete has been asked for, so the row can ask before it does it.\n      confirming: '',\n    };\n  },\n\n  methods: {\n    /**\n     * The dot's colour, from Rancher's own state colours, with one deliberate exception.\n     *\n     * `colorForState('stopped')` is error red, because in the rest of Rancher a stopped thing is\n     * a thing that stopped. Here it is something someone pressed Stop on, which is the ordinary\n     * way to leave one, and a red dot next to it says the same thing as the red dot next to a\n     * crash loop. Muted is what the nav already uses for \"nothing to report\".\n     */\n    dotClass(row) {\n      return row.state === 'stopped' ? 'text-muted' : colorForState(row.state);\n    },\n\n    stateLabel(row) {\n      return stateDisplay(row.state);\n    },\n\n    remove(row) {\n      this.confirming = '';\n      this.$emit('delete', row.key);\n    },\n  },\n};\n</script>\n\n<template>\n  <section class=\"dev-list\">\n    <div class=\"dev-list__head\">\n      <BrandImage\n        v-if=\"logo\"\n        class=\"dev-list__glyph dev-list__logo\"\n        :file-name=\"logo\"\n      />\n      <i\n        v-else\n        class=\"dev-list__glyph icon\"\n        :class=\"icon\"\n      />\n      <span\n        class=\"dev-list__label\"\n        :class=\"tone ? `text-${ tone }` : ''\"\n      >{{ label }}</span>\n\n      <!-- Whatever the heading has to say when the pointer is on it. See the sidebar's clusters. -->\n      <div\n        v-if=\"$slots.popover\"\n        class=\"dev-list__popover\"\n      >\n        <slot name=\"popover\" />\n      </div>\n      <!--\n        Quiet until the pointer is in the section, or until it is focused, which is the same rule\n        the row's delete follows. It keeps its place in the layout either way, so the label does\n        not move when it appears, and it stays in the tab order, because hidden-until-hover is\n        unusable from a keyboard if it is the only way to create something.\n      -->\n      <router-link\n        v-if=\"createLabel && createTo\"\n        v-clean-tooltip=\"createLabel\"\n        class=\"dev-list__control dev-list__control--bordered dev-list__reveal\"\n        :aria-label=\"createLabel\"\n        :to=\"createTo\"\n      >\n        <i class=\"icon icon-plus\" />\n      </router-link>\n      <button\n        v-else-if=\"createLabel\"\n        v-clean-tooltip=\"createLabel\"\n        type=\"button\"\n        class=\"dev-list__control dev-list__control--bordered dev-list__reveal\"\n        :aria-label=\"createLabel\"\n        @click=\"$emit('create')\"\n      >\n        <i class=\"icon icon-plus\" />\n      </button>\n    </div>\n\n    <ul>\n      <li\n        v-for=\"row in rows\"\n        :key=\"row.key\"\n        :class=\"{ 'dev-list__row--current': row.key === current }\"\n        class=\"dev-list__row\"\n      >\n        <!--\n          The state class goes on the wrapper and the glyph reads it back through currentColor,\n          which is what lets the stylesheet adjust it for the theme without knowing which state\n          it is. See the __dot rule.\n        -->\n        <component\n          :is=\"row.to ? 'router-link' : 'button'\"\n          class=\"dev-list__link\"\n          :to=\"row.to\"\n          :type=\"row.to ? null : 'button'\"\n          @click=\"row.to ? null : $emit('select', row.key)\"\n        >\n          <span\n            v-clean-tooltip=\"stateLabel(row)\"\n            class=\"dev-list__glyph dev-list__dot\"\n            :class=\"dotClass(row)\"\n          ><i class=\"icon icon-dot\" /></span>\n          <span class=\"dev-list__name\">{{ row.label }}</span>\n        </component>\n        <template v-if=\"deletable\">\n          <button\n            v-if=\"confirming !== row.key\"\n            v-clean-tooltip=\"`Delete ${ row.label }`\"\n            type=\"button\"\n            class=\"dev-list__control dev-list__reveal dev-list__delete\"\n            :aria-label=\"`Delete ${ row.label }`\"\n            @click=\"confirming = row.key\"\n          >\n            <i class=\"icon icon-trash\" />\n          </button>\n          <button\n            v-else\n            v-clean-tooltip=\"`Confirm deleting ${ row.label }`\"\n            type=\"button\"\n            class=\"dev-list__control dev-list__delete dev-list__delete--confirm\"\n            :aria-label=\"`Confirm deleting ${ row.label }`\"\n            @click=\"remove(row)\"\n          >\n            <i class=\"icon icon-checkmark\" />\n          </button>\n        </template>\n      </li>\n\n      <li\n        v-if=\"!rows.length\"\n        class=\"dev-list__empty\"\n      >\n        {{ empty }}\n      </li>\n    </ul>\n  </section>\n</template>\n\n<style lang=\"scss\" scoped>\n  $row-height: 33px;\n  $rail: 16px;      // the left inset, and the width of the icon slot\n  // The scale, not a number of this file's own. See design/tokens.css.\n  $gap: var(--dev-space-3);\n  $control: 22px;   // the right-hand control, the same box in both kinds of row\n\n  .dev-list {\n    // The rule between two stacked lists, and only between them. It used to be a border on every\n    // heading, which is the same thing as long as a list is one of several in a column: on its\n    // own, under something that already draws a line (a tab strip, a page header), it is a second\n    // line a pixel below the first.\n    & + & {\n      border-top: 1px solid var(--nav-border, var(--border));\n    }\n\n    ul {\n      margin:     0;\n      padding:    0;\n      list-style: none;\n    }\n\n    // The two kinds of row are the same box: same height, same insets, same three columns.\n    // A div rather than a <header> element, because the shell styles bare HEADERs globally and\n    // one of those rules is a 48px height.\n    &__head,\n    &__row {\n      display:       flex;\n      align-items:   center;\n      box-sizing:    border-box;\n      width:         100%;\n      height:        $row-height;\n      margin:        0;\n      padding:       0 $gap 0 $rail;\n    }\n\n    &__head {\n      // The mark, boxed to the same rail everything else in the column lines up on.\n      .dev-list__logo {\n        height:     14px;\n        object-fit: contain;\n      }\n\n      .dev-list__glyph {\n        color:     var(--primary);\n        font-size: 14px;\n      }\n    }\n\n    // The left rail: the section's icon and a row's state dot are the same box, so they share\n    // one vertical line, and the labels after them share another.\n    &__glyph {\n      flex:         0 0 $rail;\n      width:        $rail;\n      margin-right: $gap;\n      text-align:   left;\n    }\n\n    &__label {\n      flex:            1 1 auto;\n      min-width:       0;\n      overflow:        hidden;\n      color:           var(--muted);\n      font-size:       12px;\n      font-weight:     600;\n      letter-spacing:  0.05em;\n      text-transform:  uppercase;\n      text-overflow:   ellipsis;\n      white-space:     nowrap;\n      // A section heading is not a link and must not pick one's underline up from anywhere.\n      text-decoration: none;\n    }\n\n    // One colour for every name, whatever state it is in: a stopped workspace is still one whose\n    // name you are trying to read. State is the dot's job and only the dot's.\n    //\n    // The reset is here rather than only on the link, because a row without a route is a BUTTON\n    // and the shell gives every one of those a border, a background and a 40px minimum height.\n    &__link {\n      display:         flex;\n      align-items:     center;\n      flex:            1 1 auto;\n      min-width:       0;\n      height:          100%;\n      min-height:      0;\n      margin:          0;\n      padding:         0;\n      border:          none;\n      background:      transparent;\n      color:           var(--body-text);\n      font-family:     inherit;\n      font-size:       14px;\n      line-height:     16px;\n      text-align:      left;\n      text-decoration: none;\n      appearance:      none;\n      cursor:          pointer;\n\n      &:hover,\n      &:focus {\n        text-decoration: none;\n      }\n    }\n\n    &__row {\n      .icon-dot {\n        font-size:   8px;\n        line-height: 1;\n      }\n\n      &:hover {\n        background: var(--nav-hover, var(--accent-btn));\n      }\n\n      // Selected is a background and a weight, not a colour. Rancher's own nav pairs\n      // --active-nav with --on-active, but only the second is defined in every theme here, and\n      // taking one without the other is how a selected row ends up white on white.\n      &--current {\n        background: var(--nav-hover, var(--accent-btn));\n\n        .dev-list__link {\n          font-weight: 600;\n        }\n      }\n    }\n\n    // The state dot, pulled toward the body text until it is legible on the body background.\n    //\n    // Rancher's state colours are not theme-aware: --success is rgb(0, 112, 50) in both themes,\n    // and only the background moves, so on the dark nav it measures 2.36:1 where a graphical\n    // object needs 3:1. --error and --primary have the same problem. There is no token to switch\n    // to either: the click-badge family is white for error and info in both themes, and the gauge\n    // colours are a different vocabulary.\n    //\n    // So the state colour is kept and mixed toward --body-text, which is the one colour each\n    // theme guarantees against its own background. In dark that lightens it, in light it deepens\n    // it, and the direction is right in both without this file knowing which theme it is in or\n    // inventing a colour of its own. A browser without color-mix ignores the declaration and gets\n    // the state colour unchanged, which is where this started.\n    // currentColor in a `color` declaration is the inherited value, so this is the state colour\n    // the span carries (text-success and the rest) mixed toward the theme's body text, rather\n    // than a second copy of Rancher's palette written out here.\n    &__dot .icon-dot {\n      color: color-mix(in srgb, currentColor, var(--body-text) 45%);\n    }\n\n    // The name, truncated rather than wrapped: a row is one line and a workspace name can be\n    // forty characters. It shrinks before the control does, so a long name never runs under it.\n    &__name {\n      overflow:      hidden;\n      text-overflow: ellipsis;\n      white-space:   nowrap;\n    }\n\n    // The right-hand control of either row: one box, one column, one place.\n    //\n    // `min-height` as well as `height`, because one of the shell's global BUTTON rules sets a\n    // 40px minimum and a minimum beats a height. Without it the row's delete is a 22x40 box\n    // against the section's 22x22 plus, and the two rails stop lining up.\n    &__control {\n      display:         flex;\n      align-items:     center;\n      justify-content: center;\n      flex:            0 0 $control;\n      width:           $control;\n      height:          $control;\n      min-height:      $control;\n      padding:         0;\n      border:          none;\n      border-radius:   var(--border-radius);\n      background:      transparent;\n      color:           var(--muted);\n      cursor:          pointer;\n\n      .icon {\n        font-size: 12px;\n      }\n    }\n\n    // The create control, outlined so it reads as a button rather than as another row icon.\n    //\n    // Both colours here are foreground tokens rather than --primary and --border, and that is\n    // the point: --primary on the nav background is 2.93:1 in dark, and --border is about 1.4:1\n    // in both themes, which is a control nobody can see with a glyph nobody can read. --muted\n    // and --body-text are the two colours this nav already uses for text, so they are legible on\n    // it by construction.\n    &__control--bordered {\n      border: 1px solid var(--muted);\n      color:  var(--body-text);\n\n      &:hover {\n        background: var(--nav-hover, var(--accent-btn));\n      }\n    }\n\n    // Quiet until you are on the thing it acts on, and always there for a keyboard. Opacity\n    // rather than display, so the row's layout is the same whether it is showing or not.\n    &__reveal {\n      opacity: 0;\n\n      &:focus-visible {\n        opacity: 1;\n      }\n    }\n\n    // The heading for the create control, the row for that row's delete: each control appears\n    // when the pointer is on the thing it acts on.\n    //\n    // Hovering the whole list is what this used to be, and it read differently in the two places\n    // this component is used. In the sidebar a list is as tall as its rows, so \"the list\" and\n    // \"near the heading\" are the same place; in the conversations column it fills a 210px column,\n    // so the create control was showing whenever the pointer was anywhere in that column, which\n    // is to say always.\n    &__head:hover &__reveal,\n    &__row:hover &__reveal {\n      opacity: 1;\n    }\n\n    &__delete {\n      &:hover,\n      &:focus-visible {\n        opacity: 1;\n        color:   var(--error);\n      }\n\n      &--confirm {\n        opacity: 1;\n        color:   var(--error);\n      }\n    }\n\n    // A panel under the heading, shown while the pointer is on it. Absolute, so it does not\n    // move the rows underneath, and above them, so it is not clipped by the next section.\n    &__popover {\n      position:      absolute;\n      top:           100%;\n      left:          0;\n      z-index:       10;\n      display:       none;\n      // As wide as it needs and no wider than the column: absolutely positioned or not, a panel\n      // wider than its scroll container gives that container a horizontal scrollbar, which in a\n      // sidebar is a bar under the workspaces that scrolls nothing anybody wants.\n      width:         max-content;\n      max-width:     100%;\n      padding:       var(--dev-space-3) var(--dev-space-4);\n      border:        1px solid var(--border);\n      border-radius: var(--border-radius);\n      background:    var(--body-bg);\n      box-shadow:    0 2px 8px rgba(0, 0, 0, 0.2);\n    }\n\n    &__head {\n      position: relative;\n\n      &:hover .dev-list__popover {\n        display: block;\n      }\n    }\n\n    &__empty {\n      padding:   0 $gap ($gap / 2) calc(#{$rail} + #{$rail} + #{$gap});\n      color:     var(--muted);\n      font-size: 12px;\n    }\n  }\n</style>\n",
    "pkg/dev-extension/components/DevSidebar.vue": "<script>\n// The product's navigation: templates as sections, workspaces as rows.\n//\n// It is not Rancher's product nav, because that nav cannot draw these rows: it builds each\n// entry's label itself through `escapeHtml` and its entries have no icon field, so a state dot\n// is impossible, and it has no per-row slot, so a delete control is impossible. Both are on\n// every row of the thing this is a port of.\n//\n// The rows themselves are DevList, which is also the conversation list inside a workspace. What\n// is left here is what is particular to the nav: which sections there are, what a row links to,\n// and the strip of everything that is not a workspace along the foot.\nimport {\n  listAllWorkspaces, deleteWorkspace, listClusters, readableBytes\n} from '../api';\nimport { showTerminal } from '../terminals';\nimport { TEMPLATES } from '../templates';\nimport DevList from './DevList.vue';\nimport Stack from '../design/Stack.vue';\nimport Row from '../design/Row.vue';\nimport {\n  DEV_PRODUCT, BLANK_CLUSTER, WORKSPACE_ROUTE, CREATE_ROUTE, WORKSPACES_ROUTE,\n  MY_WORK_ROUTE, INSIGHTS_ROUTE, SETTINGS_ROUTE\n} from '../config/constants';\n\nconst REFRESH_MS = 5000;\n\n/**\n * What counts as a cluster running low.\n *\n * A workspace clones rancher/dashboard, installs it and compiles it: that is gigabytes of disk\n * and a compile that has been given four of memory. These are the numbers under which starting\n * one is a thing that fails partway rather than a thing that is slow.\n */\nconst LOW_MEMORY = 4 * 1024 ** 3;\nconst LOW_DISK = 20 * 1024 ** 3;\n\n// The sidebar is rebuilt on every navigation, because the router-view above it is keyed on the\n// path. Without this the list blinks empty and fills in again on every click, which is the\n// difference between a sidebar and a page element that happens to be on the left.\nlet cached = [];\n\nexport default {\n  name: 'DevSidebar',\n\n  components: { DevList, Stack, Row },\n\n  data() {\n    return {\n      workspaces:   cached,\n      clusters:     [],\n      templates:    TEMPLATES,\n      error:        '',\n      refreshTimer: null,\n      /**\n       * The entries that are not workspaces, as an icon row at the foot.\n       *\n       * Icons rather than labelled rows because the column is about workspaces, and these are\n       * the things that are not one. `list-flat` for My Work is the honest pick of what the\n       * shell has: it is a list, and Rancher's `user` icon already means an account elsewhere\n       * in the product, which My Work is not.\n       *\n       * My Work first, because it is the page somebody opens the product to look at. Terminal is\n       * in the row rather than before it, and it is the one entry that is not a page: it opens\n       * the drawer in place, which is why it carries an action instead of a route.\n       */\n      globals: [\n        {\n          label: 'My Work', icon: 'icon-list-flat', route: MY_WORK_ROUTE\n        },\n        { label: 'Terminal', icon: 'icon-terminal', action: 'terminal' },\n        {\n          label: 'Insights', icon: 'icon-monitoring', route: INSIGHTS_ROUTE\n        },\n        {\n          label: 'Settings', icon: 'icon-gear', route: SETTINGS_ROUTE\n        },\n      ],\n    };\n  },\n\n  computed: {\n    /**\n     * A section per cluster, with the workspaces hosted on it.\n     *\n     * By cluster rather than by template, because that is the thing a person is choosing between\n     * when they have workspaces in two places: a template says what a workspace runs, which the\n     * row's own page says too, and a cluster says where it is, which nothing else did.\n     *\n     * Every cluster gets a section even with nothing in it, so the plus that makes one there is\n     * somewhere to press.\n     */\n    sections() {\n      const clusters = this.clusters.length ? this.clusters : [{ id: 'local', name: 'local' }];\n      const known = new Set(clusters.map((cluster) => cluster.id));\n      const strays = [...new Set(this.workspaces.map((workspace) => workspace.cluster))]\n        .filter((id) => id && !known.has(id))\n        .map((id) => ({\n          id, name: id, memoryFree: 0, diskFree: 0\n        }));\n      const all = [...clusters, ...strays];\n\n      // Template, then cluster, then workspaces. Two levels because they answer two questions\n      // that are both worth asking: a template says what a workspace runs, and a cluster says\n      // where it is. A cluster with nothing of this template in it is still listed, because the\n      // plus on it is how one gets made there.\n      return this.templates.map((template) => ({\n        ...template,\n        clusters: all.map((cluster) => ({\n          ...cluster,\n          rows: this.rowsFor(this.workspaces.filter((workspace) => (\n            workspace.cluster === cluster.id && workspace.template === template.id\n          ))),\n        })),\n      }));\n    },\n\n    /**\n     * Workspaces whose template is gone, grouped the same way.\n     *\n     * A template removed from the code must not take its workspaces off the page with it: they\n     * are still running and somebody still has to be able to delete them.\n     */\n    orphans() {\n      const known = new Set(this.templates.map((template) => template.id));\n      const lost = this.workspaces.filter((workspace) => !known.has(workspace.template));\n\n      if (!lost.length) {\n        return [];\n      }\n\n      return [...new Set(lost.map((workspace) => workspace.cluster))].map((id) => ({\n        id,\n        name:       id,\n        memoryFree: 0,\n        diskFree:   0,\n        rows:       this.rowsFor(lost.filter((workspace) => workspace.cluster === id)),\n      }));\n    },\n\n    /**\n     * The most any one cluster has, which is what the bars are drawn against.\n     *\n     * A bar has to be a proportion of something. Against a cluster's own capacity every cluster\n     * would look equally full; against the largest, two clusters side by side compare.\n     */\n    biggest() {\n      return {\n        memory: Math.max(...this.sections.map((section) => section.memoryFree || 0), 1),\n        disk:   Math.max(...this.sections.map((section) => section.diskFree || 0), 1),\n      };\n    },\n\n    currentWorkspace() {\n      return this.$route.params.workspace || '';\n    },\n  },\n\n  async fetch() {\n    await this.refresh();\n  },\n\n  mounted() {\n    this.refreshTimer = setInterval(() => this.refresh(), REFRESH_MS);\n  },\n\n  beforeUnmount() {\n    clearInterval(this.refreshTimer);\n  },\n\n  methods: {\n    async refresh() {\n      try {\n        const [workspaces, clusters] = await Promise.all([\n          listAllWorkspaces(),\n          listClusters().catch(() => this.clusters),\n        ]);\n\n        this.workspaces = workspaces;\n        this.clusters = clusters;\n        cached = workspaces;\n      } catch { /* the next poll will say if it is more than a blip */ }\n    },\n\n    /**\n     * Whether a cluster is running out of room, which is what colours its name.\n     *\n     * The thresholds are what a workspace of this product actually needs rather than a round\n     * number: a checkout, an install and a compile of rancher/dashboard want a few gigabytes of\n     * each, and a cluster under that will take one and then fail in the middle of yarn.\n     */\n    low(cluster) {\n      return (cluster.memoryFree && cluster.memoryFree < LOW_MEMORY) ||\n        (cluster.diskFree && cluster.diskFree < LOW_DISK);\n    },\n\n    /** How full a bar is, as a percentage of the largest cluster's own capacity. */\n    bar(free, total) {\n      return `${ Math.max(2, Math.min(100, Math.round((free / (total || free || 1)) * 100))) }%`;\n    },\n\n    readable(value) {\n      return readableBytes(value);\n    },\n\n    /** Every workspace, asked for rather than landed on. See the Workspaces page. */\n    listTo() {\n      return {\n        name:   WORKSPACES_ROUTE,\n        params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER },\n        query:  { all: null },\n      };\n    },\n\n    /** The create page, with this cluster already chosen. */\n    createIn(cluster, template) {\n      return {\n        name:   CREATE_ROUTE,\n        params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER },\n        query:  { cluster: cluster.id, template },\n      };\n    },\n\n    /** A workspace as a row: its name, its state, and the page it opens. */\n    rowsFor(workspaces) {\n      return workspaces.map((workspace) => ({\n        key:   workspace.name,\n        label: workspace.name,\n        state: workspace.state,\n        to:    {\n          name:   WORKSPACE_ROUTE,\n          params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER, workspace: workspace.name },\n        },\n      }));\n    },\n\n\n    /** The drawer, not a page. See showTerminal. */\n    openTerminal() {\n      showTerminal(this.$store);\n    },\n\n    globalTo(route) {\n      return { name: route, params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER } };\n    },\n\n    isGlobalActive(route) {\n      return this.$route.name === route;\n    },\n\n    async remove(name) {\n      this.error = '';\n\n      try {\n        await deleteWorkspace(name);\n        await this.refresh();\n\n        // Standing on a workspace that has just been deleted is standing on a page that is\n        // about to say it does not exist.\n        if (this.currentWorkspace === name) {\n          this.$router.push({ name: WORKSPACES_ROUTE, params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER } });\n        }\n      } catch (e) {\n        this.error = e.message || String(e);\n      }\n    },\n  },\n};\n</script>\n\n<template>\n  <nav class=\"dev-sidebar\">\n    <div class=\"dev-sidebar__scroll\">\n      <!--\n        The template, and under it the clusters its workspaces are on. The heading is not a\n        DevList: a template has no rows of its own, and a list with nothing in it would draw an\n        empty line under every one of them.\n      -->\n      <div\n        v-for=\"template in sections\"\n        :key=\"template.id\"\n        class=\"dev-sidebar__template\"\n      >\n        <!--\n          The heading is a link to the list of every workspace, which is where one is stopped or\n          deleted. The landing route redirects into a workspace, so without this the list is a\n          page nothing reaches.\n        -->\n        <router-link\n          class=\"dev-sidebar__template-head\"\n          :to=\"listTo\"\n        >\n          <i\n            class=\"dev-sidebar__template-icon icon\"\n            :class=\"template.icon\"\n          />\n          <span class=\"dev-sidebar__template-label\">{{ template.label }}</span>\n        </router-link>\n\n        <DevList\n          v-for=\"section in template.clusters\"\n          :key=\"section.id\"\n          class=\"dev-sidebar__cluster\"\n          :label=\"section.name\"\n          icon=\"icon-cluster\"\n        :tone=\"low(section) ? 'warning' : ''\"\n        :rows=\"section.rows\"\n        :current=\"currentWorkspace\"\n        :create-to=\"createIn(section, template.id)\"\n        :create-label=\"`New ${ template.label } workspace on ${ section.name }`\"\n        deletable\n        @delete=\"remove\"\n      >\n        <!-- What is left on it, as two bars, while the pointer is on the name. -->\n        <template #popover>\n          <Stack gap=\"2\">\n            <Row\n              class=\"dev-sidebar__meter\"\n              gap=\"3\"\n            >\n              <span class=\"dev-sidebar__meter-label\">MEM</span>\n              <span class=\"dev-sidebar__meter-track\"><span\n                class=\"dev-sidebar__meter-fill\"\n                :style=\"{ width: bar(section.memoryFree, biggest.memory) }\"\n              /></span>\n              <span class=\"dev-sidebar__meter-value\">{{ readable(section.memoryFree) }}</span>\n            </Row>\n            <Row\n              class=\"dev-sidebar__meter\"\n              gap=\"3\"\n            >\n              <span class=\"dev-sidebar__meter-label\">DISK</span>\n              <span class=\"dev-sidebar__meter-track\"><span\n                class=\"dev-sidebar__meter-fill\"\n                :style=\"{ width: bar(section.diskFree, biggest.disk) }\"\n              /></span>\n              <span class=\"dev-sidebar__meter-value\">{{ readable(section.diskFree) }}</span>\n            </Row>\n          </Stack>\n        </template>\n        </DevList>\n      </div>\n\n      <!-- A workspace whose template has been removed from the code still has to be reachable. -->\n      <div\n        v-if=\"orphans.length\"\n        class=\"dev-sidebar__template\"\n      >\n        <div class=\"dev-sidebar__template-head\">\n          <i class=\"dev-sidebar__template-icon icon icon-warning\" />\n          <span class=\"dev-sidebar__template-label\">Unknown template</span>\n        </div>\n        <DevList\n          v-for=\"section in orphans\"\n          :key=\"section.id\"\n          class=\"dev-sidebar__cluster\"\n          :label=\"section.name\"\n          icon=\"icon-cluster\"\n          :rows=\"section.rows\"\n          :current=\"currentWorkspace\"\n          deletable\n          @delete=\"remove\"\n        />\n      </div>\n    </div>\n\n    <div\n      v-if=\"error\"\n      class=\"dev-sidebar__error\"\n    >\n      {{ error }}\n    </div>\n\n    <!-- The things that are not workspaces, out of the way of the things that are. -->\n    <div class=\"dev-sidebar__globals\">\n      <template\n        v-for=\"global in globals\"\n        :key=\"global.label\"\n      >\n        <button\n          v-if=\"global.action\"\n          v-clean-tooltip=\"global.label\"\n          type=\"button\"\n          :aria-label=\"global.label\"\n          @click=\"openTerminal\"\n        >\n          <i\n            class=\"icon\"\n            :class=\"global.icon\"\n          />\n        </button>\n        <router-link\n          v-else\n          v-clean-tooltip=\"global.label\"\n          :to=\"globalTo(global.route)\"\n          :aria-label=\"global.label\"\n          :class=\"{ 'dev-sidebar__globals--current': isGlobalActive(global.route) }\"\n        >\n          <i\n            class=\"icon\"\n            :class=\"global.icon\"\n          />\n        </router-link>\n      </template>\n    </div>\n  </nav>\n</template>\n\n<style lang=\"scss\" scoped>\n  // Rancher's own step, the same one DevList's metrics come from.\n  $rail: 16px;\n  // The scale, not a number of this file's own: this was 8px and the list beside it was 8px\n  // for the same reason, which is what a scale is for.\n  $gap: var(--dev-space-3);\n\n  .dev-sidebar {\n    display:        flex;\n    flex-direction: column;\n    height:         100%;\n    min-height:     0;\n    overflow:       hidden;\n    border-right:   1px solid var(--nav-border, var(--border));\n    background:     var(--nav-bg, var(--body-bg));\n\n    &__scroll {\n      flex:       1 1 auto;\n      overflow-y: auto;\n      // Nothing here is meant to be scrolled sideways: a name too long for the column is\n      // truncated, and a popover is sized to fit it.\n      overflow-x: hidden;\n    }\n\n    // The template, above the clusters its workspaces are on. Same metrics as a DevList heading,\n    // because it is the same kind of line one level up.\n    &__template-head {\n      display:         flex;\n      align-items:     center;\n      height:          33px;\n      padding:         0 $gap 0 $rail;\n      border-top:      1px solid var(--nav-border, var(--border));\n      text-decoration: none;\n\n      &:hover {\n        background:      var(--nav-hover, var(--accent-btn));\n        text-decoration: none;\n      }\n    }\n\n    &__template-icon {\n      flex:         0 0 $rail;\n      width:        $rail;\n      margin-right: $gap;\n      color:        var(--primary);\n      font-size:    14px;\n    }\n\n    &__template-label {\n      overflow:        hidden;\n      color:           var(--body-text);\n      font-size:       12px;\n      font-weight:     600;\n      letter-spacing:  0.05em;\n      text-transform:  uppercase;\n      text-overflow:   ellipsis;\n      white-space:     nowrap;\n    }\n\n    // The clusters under it, indented by one rail so the nesting is visible without a line.\n    &__cluster {\n      padding-left: $rail;\n    }\n\n    // The two bars in a cluster's popover: a label, a track, and the number, on one line each.\n\n    &__meter-label {\n      flex:        0 0 34px;\n      color:       var(--muted);\n      font-family: monospace;\n      font-size:   11px;\n    }\n\n    &__meter-track {\n      flex:          1 1 auto;\n      overflow:      hidden;\n      height:        6px;\n      border-radius: 3px;\n      background:    var(--border);\n    }\n\n    &__meter-fill {\n      display:    block;\n      height:     100%;\n      background: var(--primary);\n    }\n\n    &__meter-value {\n      flex:      0 0 auto;\n      font-size: 11px;\n    }\n\n    &__error {\n      padding:   $gap $rail;\n      color:     var(--error);\n      font-size: 12px;\n    }\n\n    &__globals {\n      display:         flex;\n      align-items:     center;\n      justify-content: center;\n      gap:             $gap;\n      padding:         $gap;\n      border-top:      1px solid var(--nav-border, var(--border));\n\n      // One box for all four, so they read as a set: same size, same radius, same hover, and\n      // the button reset so it cannot inherit a different weight from the user agent. The\n      // min-height is part of that reset: a shell rule gives every BUTTON a 40px minimum, which\n      // beats a height and left the Terminal button 28x40 in a row of 28x28 links.\n      a,\n      button {\n        display:         flex;\n        align-items:     center;\n        justify-content: center;\n        width:           28px;\n        height:          28px;\n        min-height:      28px;\n        margin:          0;\n        padding:         0;\n        border:          none;\n        border-radius:   var(--border-radius);\n        background:      transparent;\n        color:           var(--body-text);\n        font:            inherit;\n        line-height:     1;\n        appearance:      none;\n        cursor:          pointer;\n        // These are icons, and the shell underlines every anchor on hover. An underline under a\n        // glyph is a line under a picture.\n        text-decoration: none;\n\n        &:hover,\n        &:focus {\n          text-decoration: none;\n        }\n\n        .icon {\n          font-size: 16px;\n        }\n\n        &:hover {\n          background: var(--nav-hover, var(--accent-btn));\n        }\n      }\n\n      &--current {\n        background:  var(--nav-hover, var(--accent-btn));\n        font-weight: 600;\n      }\n    }\n  }\n</style>\n",
    "pkg/dev-extension/components/DevTerminal.vue": "<script>\n// A terminal in a pod, ported from pkg/barn/components/PodTerminal.vue.\n//\n// The harness gives every project a persistent shell; here there is no server to run a pty,\n// so the pty comes from Kubernetes: the exec subresource is a real TTY in the pod, reached\n// through Rancher's cluster proxy and authenticated by the session cookie the page already\n// has (see api.ts, podExecUrl).\n//\n// Which pod, and what to run in it, are the caller's to say: a workspace's Conversations tab\n// and the global terminal are the same TTY on two different pods, and the only difference\n// between them is a namespace, a label to find the pod by, and an argv.\n//\n// The protocol is `base64.channel.k8s.io`, the one the dashboard's own container shell\n// speaks: each frame is a channel digit followed by base64. Channel 0 is stdin, 1 stdout,\n// 2 stderr, 3 error, and 4 carries a JSON {Width, Height} on resize.\n//\n// The imports are `@xterm/*` rather than `xterm/*`: this dashboard is shell 3.x, which moved\n// to the scoped packages, and the unscoped ones are not installed.\nimport { allHash } from '@shell/utils/promise';\nimport { base64Decode, base64Encode } from '@shell/utils/crypto';\nimport Socket, {\n  EVENT_CONNECTED,\n  EVENT_CONNECTING,\n  EVENT_DISCONNECTED,\n  EVENT_MESSAGE,\n  EVENT_CONNECT_ERROR,\n} from '@shell/utils/socket';\nimport { RcButton } from '@components/RcButton';\nimport { findPod, podExecUrl } from '../api';\n\n// Channel prefixes, as above.\nconst STDIN = '0';\nconst STDOUT = '1';\nconst STDERR = '2';\nconst ERROR = '3';\nconst RESIZE = '4';\n\n// How often to look for a running pod while there isn't one. A workspace that was just\n// created is pulling an image, so this is a wait of seconds rather than an error.\nconst POD_POLL_MS = 3000;\n\nexport default {\n  name: 'DevTerminal',\n\n  components: { RcButton },\n\n  // So a caller showing several of these can say which one is connected without reaching into\n  // this component's state. The conversation list uses it for the dot on each row.\n  emits: ['state'],\n\n  props: {\n    // Where to look for the pod, rather than which pod: a pod name changes across a stop and\n    // start, and this is expected to survive that by finding the new one.\n    namespace: {\n      type:     String,\n      required: true,\n    },\n\n    /** Every one of these has to match for a pod to be the one. */\n    labels: {\n      type:     Object,\n      required: true,\n    },\n\n    /**\n     * The workspace whose own pod this is, when it is a workspace's.\n     *\n     * A workspace's sidecars live in its namespace and carry its label, so the labels alone are\n     * not enough to say which pod is the workspace: without this a conversation opens in\n     * whichever of them the collection happens to list first, and asks for a container called\n     * `workspace` that a browser sidecar does not have. See findPod.\n     */\n    own: {\n      type:    String,\n      default: '',\n    },\n\n    container: {\n      type:     String,\n      required: true,\n    },\n\n    /** argv, run on a TTY. */\n    command: {\n      type:     Array,\n      required: true,\n    },\n  },\n\n  data() {\n    return {\n      // 'waiting' (no pod yet) | 'connecting' | 'open' | 'closed'\n      state:          'waiting',\n      error:          '',\n      pod:            '',\n      terminal:       null,\n      fitAddon:       null,\n      canvasAddon:    null,\n      socket:         null,\n      // Input typed before the socket opened, replayed on connect.\n      backlog:        [],\n      resizeObserver: null,\n      podPollTimer:   null,\n      unmounted:      false,\n      // Which attempt at attaching speaks for this pane. Everything that starts one takes the\n      // next number and carries it through its awaits, so an attempt that has been superseded\n      // can tell, and does nothing. See reconnect for what that is protecting against.\n      generation:     0,\n      // Set while recoverIfPodChanged has not yet worked out why the socket closed.\n      deciding:       false,\n    };\n  },\n\n  computed: {\n    statusText() {\n      return {\n        waiting:    'Waiting for the pod',\n        connecting: 'Connecting',\n        closed:     'Disconnected',\n      }[this.state] || '';\n    },\n\n    /**\n     * What the overlay says: the reason the connection ended, or failing that the state.\n     *\n     * The exec's parting words are held back while recoverIfPodChanged is still deciding why\n     * the socket closed. On the ordinary Stop path they are the apiserver reporting a SIGKILL\n     * as `exit code 137`, which describes nothing the person did not just ask for, and a beat\n     * later this pane is waiting for a pod anyway. They are worth showing only in the case\n     * that survives that decision: the pod is still there and its shell exited.\n     */\n    statusMessage() {\n      return (this.deciding ? '' : this.error) || this.statusText;\n    },\n  },\n\n  watch: {\n    // Being pointed at a different pod is a different terminal, so the socket onto the old one\n    // is dropped rather than left open behind a pane that has moved on.\n    namespace() {\n      this.reconnect();\n    },\n\n    state(state) {\n      this.$emit('state', state);\n    },\n  },\n\n  async mounted() {\n    await this.setupTerminal();\n    this.connectWhenPodIsUp(this.nextGeneration());\n  },\n\n  beforeUnmount() {\n    this.unmounted = true;\n    clearTimeout(this.podPollTimer);\n    this.resizeObserver?.disconnect();\n    this.socket?.disconnect();\n    // The renderer addon goes first. Disposing the terminal out from under it is what makes\n    // xterm throw on the way out of the page, which is the shell's own lesson in\n    // components/Window/ContainerShell.vue.\n    this.canvasAddon?.dispose();\n    this.canvasAddon = null;\n    this.terminal?.dispose();\n  },\n\n  methods: {\n    /** Claim the pane for a new attempt at attaching, which supersedes every earlier one. */\n    nextGeneration() {\n      this.generation += 1;\n\n      return this.generation;\n    },\n\n    /**\n     * Whether an attempt still speaks for the pane.\n     *\n     * Every await below is a place the pane can be restarted underneath the caller: Reconnect\n     * clicked, the pod pointed somewhere else, the page gone. Asking this after each one is what\n     * keeps a superseded attempt from opening a second socket onto the pod.\n     */\n    isCurrent(generation) {\n      return !this.unmounted && generation === this.generation;\n    },\n\n    async setupTerminal() {\n      const style = getComputedStyle(document.body);\n      const color = (name) => style.getPropertyValue(name).trim() || undefined;\n\n      const xterm = await import(/* webpackChunkName: \"xterm\" */ '@xterm/xterm');\n      const addons = await allHash({\n        fit:    import(/* webpackChunkName: \"xterm\" */ '@xterm/addon-fit'),\n        canvas: import(/* webpackChunkName: \"xterm\" */ '@xterm/addon-canvas'),\n      });\n\n      // The two imports above are the only slow thing in here, and a pane can be gone by the\n      // time they resolve: the shell keys its router-view on the path, so moving to another of\n      // a workspace's tabs unmounts this page while it is still loading xterm. Opening a\n      // Terminal on the element that pane no longer has throws inside xterm (\"Terminal\n      // requires a parent element\"), which is a crash rather than a tab change.\n      if (this.unmounted || !this.$refs.xterm) {\n        return;\n      }\n\n      const terminal = new xterm.Terminal({\n        allowProposedApi: true,\n        cursorBlink:      true,\n        fontSize:         13,\n        fontFamily:       'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',\n        // Rancher's own terminal colours, so this matches the dashboard's theme and follows\n        // it between light and dark.\n        theme:            {\n          background:          color('--terminal-bg'),\n          foreground:          color('--terminal-text'),\n          cursor:              color('--terminal-cursor'),\n          selectionBackground: color('--terminal-selection'),\n        },\n      });\n\n      this.fitAddon = new addons.fit.FitAddon();\n      terminal.loadAddon(this.fitAddon);\n\n      // open() before the renderer addon, not after: the canvas renderer builds its layers\n      // out of services that only exist once the terminal has an element, and loading it\n      // first throws inside xterm rather than here. Canvas rather than webgl because webgl\n      // contexts are a limited per-page resource, and this dashboard is itself framed inside\n      // another one.\n      terminal.open(this.$refs.xterm);\n      this.canvasAddon = new addons.canvas.CanvasAddon();\n      terminal.loadAddon(this.canvasAddon);\n\n      terminal.onData((input) => this.send(STDIN + base64Encode(input)));\n\n      this.terminal = terminal;\n\n      // The page is a detail page whose other half can grow, and the window resizes too, so\n      // the size is watched rather than taken once.\n      this.resizeObserver = new ResizeObserver(() => this.fit());\n      this.resizeObserver.observe(this.$refs.xterm);\n      this.fit();\n    },\n\n    // Wait for a pod, then connect. A workspace that has just been created or started is\n    // pulling and scheduling, so this is a wait rather than an error.\n    async connectWhenPodIsUp(generation) {\n      // Whatever the last connection died of stops being the news the moment this starts\n      // looking for a new pod. Stopping a workspace kills the exec, which arrives on channel\n      // 3 as `exit code 137`, and without this that sentence is what the pane says for as\n      // long as the workspace stays stopped, instead of saying it is waiting for a pod.\n      this.error = '';\n      // Nor is there a question left about why the last socket closed: starting again is the\n      // answer, whoever was asking.\n      this.deciding = false;\n\n      while (this.isCurrent(generation)) {\n        const pod = await findPod(this.namespace, this.labels, this.own).catch(() => null);\n\n        if (!this.isCurrent(generation)) {\n          return;\n        }\n\n        if (pod) {\n          this.pod = pod;\n          this.connect(pod, generation);\n\n          return;\n        }\n\n        this.state = 'waiting';\n        await new Promise((resolve) => {\n          this.podPollTimer = setTimeout(resolve, POD_POLL_MS);\n        });\n      }\n    },\n\n    connect(pod, generation) {\n      const url = podExecUrl(this.namespace, pod, this.container, this.command);\n      const socket = new Socket(url, false, 0, 'base64.channel.k8s.io');\n\n      socket.addEventListener(EVENT_CONNECTING, () => {\n        this.state = 'connecting';\n        this.error = '';\n      });\n\n      socket.addEventListener(EVENT_CONNECTED, () => {\n        this.state = 'open';\n        this.fit();\n        this.flush();\n        this.terminal?.focus();\n      });\n\n      socket.addEventListener(EVENT_CONNECT_ERROR, () => {\n        this.state = 'closed';\n        this.error = 'Could not open a shell in the pod';\n      });\n\n      socket.addEventListener(EVENT_DISCONNECTED, () => {\n        // A socket from a superseded attempt has nothing to say about the pane: reconnect\n        // takes the next generation before it closes one, so a close this component asked for\n        // arrives here already answered.\n        if (!this.isCurrent(generation)) {\n          return;\n        }\n\n        this.state = 'closed';\n        this.deciding = true;\n        this.recoverIfPodChanged(pod, generation);\n      });\n\n      socket.addEventListener(EVENT_MESSAGE, (event) => {\n        const data = event.detail.data;\n        const channel = data.substr(0, 1);\n        const message = base64Decode(data.substr(1));\n\n        // stdout and stderr are both the pane; there is one TTY behind them.\n        if (channel === STDOUT || channel === STDERR) {\n          this.terminal?.write(message);\n\n          return;\n        }\n\n        if (channel === ERROR && message) {\n          // Not output: a Status object saying how the exec ended. Printing it would put\n          // `{\"status\":\"Success\"}` on screen every time a shell exits normally, so only a\n          // failure is worth surfacing, and as a status rather than as terminal output.\n          try {\n            const status = JSON.parse(message);\n\n            if (status.status !== 'Success') {\n              this.error = status.message || 'The shell exited with an error';\n            }\n          } catch {\n            this.error = message;\n          }\n        }\n      });\n\n      this.socket = socket;\n      socket.connect();\n    },\n\n    /**\n     * Follow the workspace when a stop and start replaces its pod.\n     *\n     * Losing the socket is two different events wearing the same clothes: the pod went away,\n     * or the shell in it exited. Reconnecting on both would make `exit` an infinite loop of\n     * shells nobody asked for, and reconnecting on neither would leave the pane dead after\n     * every stop and start. Which one happened is answered by asking whether the pod this was\n     * attached to is still there, after a beat, since the API takes a moment to admit a pod\n     * is terminating.\n     *\n     * The answer is only worth having while the attempt that asked the question is still the\n     * live one, which is what the generation is checked for on the way out of each await.\n     */\n    async recoverIfPodChanged(pod, generation) {\n      await new Promise((resolve) => {\n        this.podPollTimer = setTimeout(resolve, POD_POLL_MS);\n      });\n\n      if (!this.isCurrent(generation)) {\n        return;\n      }\n\n      const current = await findPod(this.namespace, this.labels, this.own).catch(() => null);\n\n      if (!this.isCurrent(generation)) {\n        return;\n      }\n\n      // Decided either way, so whatever the exec said is either about to be replaced by the\n      // wait for a new pod, or is the only explanation this pane has for sitting closed.\n      this.deciding = false;\n\n      if (current !== pod) {\n        this.reconnect();\n      }\n    },\n\n    /**\n     * Throw away this attachment and start again from wherever the workspace is now.\n     *\n     * The generation is taken on the first line, before anything is awaited, because the\n     * click that gets here can land while recoverIfPodChanged is asleep in the middle of\n     * deciding why the last socket closed. Taking it here is what makes that decision moot:\n     * it wakes, finds it is no longer the live attempt, and returns. The flag this replaces\n     * was cleared as soon as the disconnect resolved, so whether it caught that decision came\n     * down to which of two timers fired first, and when it missed the pane ended up with two\n     * poll loops, two sockets and two shells in the pod, only one of them taking keystrokes.\n     */\n    async reconnect() {\n      const generation = this.nextGeneration();\n\n      // A disconnect that ends in an error is still a disconnect: the socket has been closed\n      // by the time it says so, and a rejection here would leave the pane holding a\n      // generation nothing will ever finish, which is the one state Reconnect cannot fix.\n      await this.socket?.disconnect().catch(() => {});\n\n      if (!this.isCurrent(generation)) {\n        return;\n      }\n\n      this.socket = null;\n      this.pod = '';\n      this.terminal?.reset();\n      this.connectWhenPodIsUp(generation);\n    },\n\n    send(frame) {\n      if (this.state === 'open') {\n        this.socket.send(frame);\n      } else {\n        this.backlog.push(frame);\n      }\n    },\n\n    flush() {\n      const backlog = this.backlog;\n\n      this.backlog = [];\n      backlog.forEach((frame) => this.socket.send(frame));\n    },\n\n    fit() {\n      if (!this.fitAddon || !this.$refs.xterm?.clientWidth) {\n        return;\n      }\n\n      this.fitAddon.fit();\n\n      if (this.state !== 'open') {\n        return;\n      }\n\n      const { cols, rows } = this.fitAddon.proposeDimensions() || {};\n\n      // The far side is a TTY with a size of its own; without this frame it keeps the 80x24\n      // it was opened with and wraps everything in the wrong place.\n      if (cols && rows) {\n        this.send(RESIZE + base64Encode(JSON.stringify({ Width: Math.floor(cols), Height: Math.floor(rows) })));\n      }\n    },\n  },\n};\n</script>\n\n<template>\n  <div class=\"dev-terminal\">\n    <div\n      ref=\"xterm\"\n      class=\"dev-terminal__xterm\"\n    />\n    <div\n      v-if=\"state !== 'open'\"\n      class=\"dev-terminal__status\"\n    >\n      <span>{{ statusMessage }}</span>\n      <RcButton\n        v-if=\"state === 'closed'\"\n        variant=\"link\"\n        size=\"small\"\n        @click=\"reconnect\"\n      >\n        Reconnect\n      </RcButton>\n    </div>\n  </div>\n</template>\n\n<style lang=\"scss\">\n// Not scoped. The shell prepends xterm's own stylesheet to every scss block it compiles (see\n// its vue.config.js), and scoping this one would rewrite those rules to match only elements\n// the template rendered - which is none of xterm's, since it builds its DOM at runtime.\n.dev-terminal {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  height: 100%;\n  padding: 6px 0 0 8px;\n  border: 1px solid var(--border);\n  border-radius: var(--border-radius);\n  background: var(--terminal-bg, var(--body-bg));\n\n  &__xterm {\n    flex: 1 1 auto;\n    min-height: 0;\n    // A stacking context of its own, so xterm's render layers stay inside it. They carry\n    // z-indexes up to 11, and without this they are peers of the status overlay below and\n    // the cursor layer ends up on top of the Reconnect button, swallowing the click. The\n    // pane then has no way back short of a page reload.\n    position: relative;\n    z-index: 0;\n  }\n\n  &__status {\n    // Above the box that contains xterm, which is all it has to beat now.\n    z-index: 1;\n    position: absolute;\n    right: 10px;\n    bottom: 8px;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    padding: 4px 10px;\n    border: 1px solid var(--border);\n    border-radius: var(--border-radius);\n    background: var(--body-bg);\n    color: var(--muted);\n    font-size: 12px;\n  }\n}\n</style>\n",
    "pkg/dev-extension/components/DevTerminalTab.vue": "<script>\n// One terminal in Rancher's window manager drawer.\n//\n// The window manager owns the tab strip, the close buttons, the drag handle and keeping this\n// alive across navigation. What is left for this component is the pane itself, which is the\n// same DevTerminal the rest of the product uses, pointed at the dev server's pod with this\n// tab's own tmux session.\n//\n// It is wrapped in the shell's own Window, which is what Rancher's container shell and logs\n// use, so the strip along the bottom is in the place and the styling someone already expects\n// per-tab controls to be in.\nimport Window from '@shell/components/Window/Window';\nimport DevTerminal from './DevTerminal.vue';\nimport { openTerminal } from '../terminals';\n\n/**\n * The window manager's own tab strip, by the id the shell gives its bottom panel.\n *\n * Not `.tabs` on its own: that class is Rancher's for every tabbed thing on the page, including\n * the workspace's own tab strip, and a teleport to it would land the plus wherever the first one\n * happened to be.\n */\nconst STRIP = '#horizontal-window-manager .tabs';\n\nexport default {\n  name: 'DevTerminalTab',\n\n  components: { Window, DevTerminal },\n\n  props: {\n    // The window manager's own description of this tab.\n    tab: {\n      type:     Object,\n      required: true,\n    },\n\n    // Whether the drawer is showing this tab rather than one of its siblings.\n    active: {\n      type:     Boolean,\n      default:  false,\n    },\n\n    // Everything below arrives from the tab's attrs (see terminals.ts).\n    session: {\n      type:     String,\n      required: true,\n    },\n\n    number: {\n      type:     Number,\n      required: true,\n    },\n\n    namespace: {\n      type:     String,\n      required: true,\n    },\n\n    labels: {\n      type:     Object,\n      required: true,\n    },\n\n    container: {\n      type:     String,\n      required: true,\n    },\n  },\n\n  computed: {\n    /**\n     * What the exec runs: the pod's own tab entrypoint, with this terminal's session and a\n     * directory of its own, which is what makes it a conversation of its own.\n     */\n    command() {\n      return ['/bin/sh', '/seed/shell.sh', this.session, `/app/.sessions/${ this.session }`];\n    },\n  },\n\n  data() {\n    return {\n      // The teleport's target, in data so the template can name it.\n      STRIP,\n      stripTimer: null,\n      // Whether the tab strip is on the page yet. The teleport below needs its target to exist\n      // when it renders, and this component is itself teleported into the panel, so the first\n      // render can happen before the strip is there.\n      striped: false,\n    };\n  },\n\n  watch: {\n    // A tab becoming the active one is the other moment the strip can appear, and the first tab\n    // in a fresh drawer is mounted before the panel around it exists.\n    active() {\n      this.findStrip();\n    },\n  },\n\n  mounted() {\n    this.findStrip();\n  },\n\n  beforeUnmount() {\n    clearTimeout(this.stripTimer);\n  },\n\n  methods: {\n    /**\n     * Wait for the tab strip to exist, then let the teleport render into it.\n     *\n     * This component is itself teleported into the panel, and on the first terminal of a session\n     * that happens as the panel is being built: a single nextTick is sometimes too early, and a\n     * teleport whose target is missing renders nothing and does not try again. So it looks a few\n     * times and then stops, which is the difference between a plus that appears and one that\n     * appears only on the second terminal.\n     */\n    findStrip(attempt = 0) {\n      clearTimeout(this.stripTimer);\n      this.striped = !!document.querySelector(STRIP);\n\n      if (!this.striped && attempt < 10) {\n        this.stripTimer = setTimeout(() => this.findStrip(attempt + 1), 100);\n      }\n    },\n\n    /**\n     * Add another terminal, from the end of the tab strip.\n     *\n     * Where the harness puts it, and where a plus belongs: beside the things it makes another of.\n     * The window manager's strip is the shell's own and has no slot, so this is a teleport into\n     * it rather than a component the shell renders. Only the active tab draws one, or there would\n     * be a plus per terminal stacked on top of each other.\n     */\n    newTerminal() {\n      openTerminal(this.$store);\n    },\n  },\n};\n</script>\n\n<template>\n  <Window :active=\"active\">\n    <template #title>\n      <div class=\"dev-terminal-tab__bar\">\n        <span class=\"dev-terminal-tab__session\">\n          Terminal {{ number }}, session <code>{{ session }}</code> in the dev server's pod.\n          Closing this tab leaves it running.\n        </span>\n      </div>\n    </template>\n    <template #body>\n      <!--\n        The plus, at the end of the strip the tabs are in. Inside the body slot rather than beside\n        it: Window renders the slots it names and nothing else, so a teleport sitting as a bare\n        child of it is never rendered at all and the plus never appears. See newTerminal.\n      -->\n      <Teleport\n        v-if=\"active && striped\"\n        :to=\"STRIP\"\n      >\n        <button\n          v-clean-tooltip=\"'New terminal'\"\n          type=\"button\"\n          class=\"dev-terminal-tab__new\"\n          aria-label=\"New terminal\"\n          @click=\"newTerminal\"\n        >\n          <i class=\"icon icon-plus\" />\n        </button>\n      </Teleport>\n      <DevTerminal\n        class=\"dev-terminal-tab__terminal\"\n        :namespace=\"namespace\"\n        :labels=\"labels\"\n        :container=\"container\"\n        :command=\"command\"\n      />\n    </template>\n  </Window>\n</template>\n\n<style lang=\"scss\">\n  // Not scoped to the component's own tree: the plus is teleported into the shell's tab strip,\n  // which is outside it, so a scoped rule would not reach it.\n  .dev-terminal-tab__new {\n    display:         flex;\n    align-items:     center;\n    justify-content: center;\n    width:           28px;\n    min-height:      0;\n    margin:          0;\n    padding:         0;\n    border:          none;\n    background:      transparent;\n    color:           var(--body-text);\n    cursor:          pointer;\n\n    &:hover {\n      color: var(--primary);\n    }\n  }\n\n  .dev-terminal-tab {\n    &__bar {\n      display:     flex;\n      align-items: center;\n      gap:         10px;\n      height:      100%;\n    }\n\n    &__session {\n      color:     var(--muted);\n      font-size: 12px;\n\n      code {\n        padding:     1px 4px;\n        background:  transparent;\n        font-family: monospace;\n      }\n    }\n\n    &__terminal {\n      height: 100%;\n      // The drawer supplies the frame, so the pane inside it does not need a second one.\n      border: none;\n    }\n  }\n</style>\n",
    "pkg/dev-extension/components/WorkspaceBrowser.vue": "<script>\n// The Browser tab: a frame, and nothing else.\n//\n// There is no address bar, no Reload and no Open, and no banner explaining any of it. The tab\n// exists only when there is something in it (see WorkspaceDetail, which is what decides that),\n// so everything this used to say about why the frame was empty had nothing left to describe.\n// Starting and stopping the browser is on the Sidecars tab, with every other sidecar's, rather\n// than duplicated here.\n//\n// What is framed depends on the template, and the difference is not cosmetic:\n//\n//   - a template with a browser sidecar frames the browser, which is in the cluster with the\n//     workspace. That is the only way to show a workspace served at an origin of its own: it is\n//     on a development certificate nothing has accepted, and a subframe gets no certificate\n//     interstitial to click through, so framing it directly shows nothing at all. Reload and an\n//     address bar are the browser's own, inside the frame, which is why this has neither.\n//   - a template without one frames the workspace through the apiserver's service proxy, on\n//     Rancher's origin. A dashboard framed that way sends its API calls to Rancher rather than\n//     to the dev server it came from, which is why the rancher template does not do this.\nimport { workspaceProxyUrl, sidecarProxyUrl } from '../api';\nimport { templateById, templateBrowser } from '../templates';\n\nexport default {\n  name: 'WorkspaceBrowser',\n\n  props: {\n    workspace: {\n      type:     Object,\n      required: true,\n    },\n  },\n\n  computed: {\n    template() {\n      return templateById(this.workspace.template);\n    },\n\n    /** The browser this frames, when the template has one. */\n    browser() {\n      return templateBrowser(this.template);\n    },\n\n    src() {\n      if (this.browser) {\n        return sidecarProxyUrl(this.workspace.name, this.browser);\n      }\n\n      return this.template ? workspaceProxyUrl(this.workspace.name, this.template.port, this.template.scheme) : '';\n    },\n  },\n};\n</script>\n\n<template>\n  <iframe\n    class=\"workspace-browser\"\n    :src=\"src\"\n    title=\"What this workspace serves\"\n  />\n</template>\n\n<style lang=\"scss\" scoped>\n  .workspace-browser {\n    flex:       1 1 auto;\n    min-height: 0;\n    border:     0;\n  }\n</style>\n",
    "pkg/dev-extension/components/WorkspaceConversations.vue": "<script>\n// A workspace's conversations: a list down the left, the open one filling the rest.\n//\n// The harness gives a project many conversations rather than one terminal, and this is that. A\n// conversation is claude in the workspace's own pod, numbered by the same function the drawer's\n// terminals are numbered with, so the two cannot come to disagree about what the numbers mean.\n//\n// It is claude in every workspace and there is no other kind. It used to be a bare shell with a\n// paragraph above it explaining that it was one; what was missing was never the install, which is\n// seconds, but the two things around it, and both are now the workspace's own: the scripts are\n// mounted at /seed (see ensureWorkspaceTerminal) and the template hands the tree to an ordinary\n// user and installs the CLI on boot.\n//\n// Every conversation that has been opened stays mounted, hidden rather than destroyed, so\n// switching between them keeps both alive. Closing one is what the row's delete does, and it is\n// only the browser's end: the pane is a tmux session in the pod, so a conversation outlives the\n// page and reopening the tab lands back in it.\nimport { RcButton } from '@components/RcButton';\nimport { Banner } from '@components/Banner';\nimport DevTerminal from './DevTerminal.vue';\nimport DevList from './DevList.vue';\nimport { nextNumber } from '../terminals';\nimport {\n  LABEL_WORKSPACE, WORKSPACE_CONTAINER, workspaceTerminalCommand, deleteWorkspaceConversation,\n  listWorkspaceConversations\n} from '../api';\n\n/**\n * A pane's own connection state, as one of Rancher's, so the row's dot is the same dot a\n * workspace's row has. DevList knows about states, not about sockets.\n */\nconst ROW_STATE = {\n  open: 'running', connecting: 'starting', waiting: 'starting', closed: 'stopped'\n};\n\nexport default {\n  name: 'WorkspaceConversations',\n\n  components: {\n    RcButton, Banner, DevTerminal, DevList\n  },\n\n  props: {\n    workspace: {\n      type:     Object,\n      required: true,\n    },\n\n    // The last line the container printed, while it is still coming up. The page fetches it,\n    // because it is the only honest answer to \"what is it doing\" during a five minute boot.\n    logTail: {\n      type:    String,\n      default: '',\n    },\n\n  },\n\n  data() {\n    return {\n      // The numbers that have been opened, in order, and which one is showing. Seeded from the\n      // pod on the way up, since a conversation is a tmux session that was probably already\n      // there before this page was. See adopt.\n      conversations: [1],\n      current:       1,\n      // number -> the pane's own connection state, for the dot on its row.\n      states:        {},\n    };\n  },\n\n  async fetch() {\n    await this.adopt();\n  },\n\n  computed: {\n    /**\n     * Whether there is anything to talk to yet.\n     *\n     * Conversations is the first tab and the default, so it is the tab that has to explain a\n     * workspace which is not ready: cloning, installing, compiling, crash-looping, or stopped.\n     * Showing a terminal that will never connect would be the same page saying nothing.\n     */\n    ready() {\n      return this.workspace.state === 'running' || this.workspace.state === 'starting';\n    },\n\n\n    failing() {\n      return this.workspace.state === 'error';\n    },\n\n    /** What the pod itself says it is doing, with the log line under it when there is one. */\n    progress() {\n      return this.workspace.detail || 'Starting';\n    },\n\n    podLabels() {\n      return { [LABEL_WORKSPACE]: this.workspace.name };\n    },\n\n    container() {\n      return WORKSPACE_CONTAINER;\n    },\n\n    rows() {\n      return this.conversations.map((number) => ({\n        key:   number,\n        label: `chat-${ number }`,\n        // The pane's own socket, as a state, so the dot means what it means everywhere else.\n        state: ROW_STATE[this.states[number]] || 'stopped',\n      }));\n    },\n  },\n\n  methods: {\n    /**\n     * Take on whatever conversations the workspace already has.\n     *\n     * Once, on the way up, rather than on a poll: after this the page is the thing creating and\n     * deleting them, and a poll would be asking the pod to confirm what this component just did.\n     */\n    async adopt() {\n      const existing = await listWorkspaceConversations(this.workspace.name).catch(() => []);\n\n      if (!existing.length) {\n        return;\n      }\n\n      this.conversations = existing;\n      this.current = existing[0];\n    },\n\n    /** The next number, from the same function the drawer's terminals are numbered with. */\n    newConversation() {\n      const number = nextNumber(this.conversations);\n\n      this.conversations = [...this.conversations, number];\n      this.current = number;\n    },\n\n/**\n     * Delete a conversation, in the pod as well as here.\n     *\n     * Unmounting the pane only closes a socket. The conversation is a tmux session in the\n     * workspace, so it would carry on without it, and since numbers are reused a later\n     * conversation with the same number would reattach to it — a delete that turns out to have\n     * been a hide. See deleteWorkspaceConversation.\n     *\n     * The last one is not deletable: an empty column with no pane beside it is a tab with\n     * nothing in it, and New conversation would be the only thing on the page.\n     */\n    closeConversation(number) {\n      if (this.conversations.length < 2) {\n        return;\n      }\n\n      const remaining = this.conversations.filter((entry) => entry !== number);\n\n      this.conversations = remaining;\n\n      if (this.current === number) {\n        this.current = remaining[remaining.length - 1];\n      }\n\n      const states = { ...this.states };\n\n      delete states[number];\n      this.states = states;\n\n      // After the pane is gone, so the socket it holds is not the thing being killed underneath\n      // it, and unawaited: the column has already moved on and there is nothing to report.\n      deleteWorkspaceConversation(this.workspace.name, number);\n    },\n\n    /** What one conversation runs, which is its own tmux session in the workspace's pod. */\n    commandFor(number) {\n      return workspaceTerminalCommand(number);\n    },\n\n    onState(number, state) {\n      this.states = { ...this.states, [number]: state };\n    },\n  },\n};\n</script>\n\n<template>\n  <div class=\"workspace-conversations\">\n    <!--\n      The same column the sidebar's workspaces are, and for the same reasons: a conversation has\n      a state worth a dot, is created from the heading, and can be closed from its own row.\n    -->\n    <!--\n      No heading text. The tab above this says Conversations, and a column that repeats its own\n      tab's name is a line of chrome saying nothing. The row itself stays, because it is where\n      the control that makes another one lives.\n    -->\n    <DevList\n      class=\"workspace-conversations__list\"\n      label=\"\"\n      icon=\"icon-comment\"\n      :rows=\"rows\"\n      :current=\"current\"\n      create-label=\"New conversation\"\n      empty=\"No conversations\"\n      deletable\n      @select=\"current = $event\"\n      @create=\"newConversation\"\n      @delete=\"closeConversation\"\n    />\n\n    <div class=\"workspace-conversations__pane\">\n      <Banner\n        v-if=\"failing\"\n        color=\"error\"\n      >\n        <p>This workspace is not staying up: {{ progress }}.</p>\n        <p\n          v-if=\"logTail\"\n          class=\"workspace-conversations__log\"\n        >\n          {{ logTail }}\n        </p>\n      </Banner>\n\n      <Banner\n        v-else-if=\"!ready\"\n        color=\"info\"\n      >\n        <p>{{ progress }}. A workspace that clones a repository and installs it takes a few minutes on its first start.</p>\n        <p\n          v-if=\"logTail\"\n          class=\"workspace-conversations__log\"\n        >\n          {{ logTail }}\n        </p>\n      </Banner>\n\n      <DevTerminal\n        v-for=\"row in (ready ? rows : [])\"\n        v-show=\"row.key === current\"\n        :key=\"row.key\"\n        class=\"workspace-conversations__terminal\"\n        :namespace=\"workspace.namespace\"\n        :labels=\"podLabels\"\n        :own=\"workspace.name\"\n        :container=\"container\"\n        :command=\"commandFor(row.key)\"\n        @state=\"onState(row.key, $event)\"\n      />\n    </div>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .workspace-conversations {\n    display:    flex;\n    flex:       1 1 auto;\n    min-height: 0;\n    // No gap: the column's own right border is the divider between the two, and a gap as well\n    // put a strip of page between that line and the pane's, which reads as two edges rather\n    // than one. The pane's padding is what keeps the terminal off it.\n\n    // The column is DevList's, so everything about a row is its stylesheet's. What is left here\n    // is the column's place on the tab: a fixed rail down the left, scrolling on its own when\n    // there are more conversations than fit.\n    &__list {\n      // Wide enough for the heading and its create control side by side, which 180px was not:\n      // the word CONVERSATIONS ran under the plus.\n      flex:         0 0 210px;\n      overflow-y:   auto;\n      border-right: 1px solid var(--border);\n    }\n\n    &__pane {\n      display:        flex;\n      flex-direction: column;\n      flex:           1 1 auto;\n      min-width:      0;\n    }\n\n    &__note {\n      max-width:     80ch;\n      margin-bottom: var(--dev-space-4);\n      color:         var(--muted);\n    }\n\n\n    // The container's own last line. Monospace because it is output, and truncated to one line\n    // because this is a status, not a log viewer: the terminal is the log viewer.\n    &__log {\n      overflow:      hidden;\n      margin:        var(--dev-space-3) 0 0 0;\n      font-family:   monospace;\n      font-size:     12px;\n      white-space:   nowrap;\n      text-overflow: ellipsis;\n    }\n\n    // Flush: the column's right border and the tab strip's bottom border are already the two\n    // edges this pane has, so the terminal's own frame and any padding around it would be a\n    // second edge a few pixels inside the first. It is the whole of the pane here, the way the\n    // Browser tab's frame is the whole of that one.\n    // The class lands on DevTerminal's own root element, which is where its frame is drawn, so\n    // this overrides it rather than reaching into it.\n    &__terminal {\n      flex:          1 1 auto;\n      min-height:    320px;\n      border:        0;\n      border-radius: 0;\n    }\n  }\n</style>\n",
    "pkg/dev-extension/components/WorkspacePorts.vue": "<script>\n// The ports a workspace is listening on, and whether each one is forwarded.\n//\n// The list is the pod's, not the Service's. Everything the workspace has bound is read out of\n// /proc/net/tcp (see workspaceListening), so a server somebody started in a conversation shows up\n// here without anyone declaring it, which is the thing this tab exists to do. A port the Service\n// carries that nothing is listening on is still shown, because that is a port somebody asked for\n// and the honest answer is that nothing has bound it yet.\n//\n// Forwarding is the one action, and there is no add form: a port exists because something is\n// serving on it, not because somebody typed its number. A forwarded port is on the workspace's\n// Service with a node port, which is what makes it reachable from outside the cluster, and\n// unforwarding takes it off again. The published port is suggested rather than asked for -\n// derived from the local one, checked against what the cluster has already given out, and\n// overridable in the row for anyone who needs a stable address. Forwarded rows sort to the top,\n// because they are the ones with an address.\n//\n// Share is the other half, and it is not the same thing: a forwarded port is open to anyone who\n// can reach the node, and a shared one has an nginx with a username and a password in front of\n// it. See share.ts.\nimport SortableTable from '@shell/components/SortableTable';\nimport AsyncButton from '@shell/components/AsyncButton';\nimport { Banner } from '@components/Banner';\nimport { RcButton } from '@components/RcButton';\nimport { LabeledInput } from '@components/Form/LabeledInput';\nimport {\n  listWorkspacePorts, addWorkspacePort, removeWorkspacePort, workspaceProxyUrl,\n  workspaceService, nodeAddress, workspaceScheme, workspaceListening,\n  listWorkspaceShares, setWorkspaceShares, shareNodePorts, usedNodePorts, suggestNodePort,\n  NODE_PORT_RANGE\n} from '../api';\nimport { nextListen, generatedPassword } from '../share';\nimport { templateById } from '../templates';\n\nexport default {\n  name: 'WorkspacePorts',\n\n  components: {\n    SortableTable, AsyncButton, Banner, RcButton, LabeledInput\n  },\n\n  props: {\n    workspace: {\n      type:     Object,\n      required: true,\n    },\n  },\n\n  async fetch() {\n    await this.refresh();\n  },\n\n  data() {\n    return {\n      // What the Service carries, what the pod is listening on, and what has been shared.\n      ports:      [],\n      listening:  [],\n      shares:     [],\n      // The workspace's Service as it is, which is where the node port comes from.\n      service:    null,\n      // The node's own address, which is what a forwarded port is reachable at. Resolved on\n      // refresh rather than per row: it is one fetch and every row wants the same answer.\n      node:       '',\n      // The node ports the cluster has already given out, so a suggestion is one that will be\n      // accepted rather than one the apiserver rejects a moment later.\n      used:       [],\n      // Local port -> what is in that row's published-port box. Only holds what somebody typed;\n      // a row nobody has touched shows its suggestion.\n      chosen:     {},\n      // The node ports the cluster gave the share proxy, by the listener they belong to.\n      sharePorts: {},\n      // The port whose link was last copied, so the button can say it worked. There is no\n      // other feedback for a clipboard write.\n      copied:     0,\n      // Local port -> what was last asked for on that row, which is the only thing the success\n      // label can be built from. See forwardLabels.\n      acting:     {},\n      copyTimer:  null,\n      error:      '',\n      headers:    [\n        // Not sortable, and that is the point: the order is forwarded first, which is the\n        // component's and not a column's. A sortable header here would offer to undo the one\n        // thing the order is for, and SortableTable sorts by the first sortable column when it\n        // is given one, which is how the forwarded row ended up underneath.\n        {\n          name: 'port', label: 'Port', value: 'port', width: 130\n        },\n        {\n          name: 'answering', label: 'Answering', value: 'port', width: 110\n        },\n        // The published port: the assigned one when it is forwarded, and an editable suggestion\n        // when it is not. One column, because it is one fact in two states.\n        {\n          name: 'public', label: 'Public port', value: 'port', width: 150\n        },\n        { name: 'url', label: 'Address', value: 'port' },\n        {\n          name: 'actions', label: '', align: 'right', width: 300\n        },\n      ],\n    };\n  },\n\n  computed: {\n    /**\n     * Every port worth a row, forwarded ones first.\n     *\n     * The two sources overlap and neither contains the other, so this is their union. Inside each\n     * half the order is the port number, which is the only order a list of ports has.\n     */\n    rows() {\n      const all = new Map();\n\n      for (const entry of this.listening) {\n        all.set(entry.port, {\n          port: entry.port, loopback: entry.loopback, listening: true, nodePort: 0\n        });\n      }\n\n      for (const entry of this.ports) {\n        all.set(entry.port, {\n          ...(all.get(entry.port) || { port: entry.port, loopback: false, listening: false }),\n          nodePort: entry.nodePort || 0,\n        });\n      }\n\n      return [...all.values()].sort((a, b) => (\n        Number(!!b.nodePort) - Number(!!a.nodePort) || a.port - b.port\n      ));\n    },\n  },\n\n  beforeUnmount() {\n    clearTimeout(this.copyTimer);\n  },\n\n  methods: {\n    async refresh() {\n      const [declared, service, node, listening, shares, sharePorts, used] = await Promise.all([\n        listWorkspacePorts(this.workspace.name),\n        workspaceService(this.workspace.name).catch(() => null),\n        nodeAddress(),\n        workspaceListening(this.workspace.name).catch(() => []),\n        listWorkspaceShares(this.workspace.name).catch(() => []),\n        shareNodePorts(this.workspace.name).catch(() => ({})),\n        usedNodePorts().catch(() => []),\n      ]);\n\n      this.ports = declared;\n      this.service = service;\n      this.node = node;\n      this.listening = listening;\n      this.shares = shares;\n      this.sharePorts = sharePorts;\n      this.used = used;\n    },\n\n    /**\n     * What one port speaks. The template's own port speaks whatever the template's server does;\n     * anything else is http until there is a reason to ask which.\n     */\n    scheme(port) {\n      const template = templateById(this.workspace.template);\n\n      return port === template?.port ? workspaceScheme(template) : 'http';\n    },\n\n    forwarded(row) {\n      return !!row.nodePort;\n    },\n\n    /**\n     * What the forward button says, in its three states.\n     *\n     * The first two come from where the row is now, so the button always offers the next thing.\n     * The third cannot: by the time a success label is drawn the row has been refreshed and the\n     * state has flipped, so binding it to the same expression made a successful Forward announce\n     * itself as \"Unforwarded\". It comes from what was asked for instead.\n     */\n    forwardLabels(row) {\n      const asked = this.acting[row.port];\n\n      return {\n        action:  this.forwarded(row) ? 'Unforward' : 'Forward',\n        waiting: this.forwarded(row) ? 'Unforwarding' : 'Forwarding',\n        success: asked === 'unforward' ? 'Unforwarded' : 'Forwarded',\n      };\n    },\n\n    /** What is in a row's published-port box: what was typed, or the suggestion. */\n    publicPort(row) {\n      return this.chosen[row.port] ?? String(suggestNodePort(row.port, this.used) || '');\n    },\n\n    /** Why that box's contents cannot be used, or '' when they can. */\n    publicError(row) {\n      const port = Number(this.publicPort(row));\n\n      if (!port) {\n        return 'A published port is needed.';\n      }\n\n      if (port < NODE_PORT_RANGE.first || port > NODE_PORT_RANGE.last) {\n        return `Between ${ NODE_PORT_RANGE.first } and ${ NODE_PORT_RANGE.last }.`;\n      }\n\n      return this.used.includes(port) ? 'Already in use.' : '';\n    },\n\n    /**\n     * Publish a port on the node, which is what makes it reachable from outside the cluster.\n     *\n     * The published port is what the row's box says. Nothing beyond that is checked here: two\n     * people forwarding at once is what the apiserver's own conflict is for, and it says so\n     * better than a guess made a moment earlier would.\n     */\n    async forward(row, done) {\n      this.error = '';\n      this.acting = { ...this.acting, [row.port]: 'forward' };\n\n      try {\n        await addWorkspacePort(this.workspace.name, row.port, Number(this.publicPort(row)) || undefined);\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /**\n     * Take it off the Service again.\n     *\n     * A share on that port goes with it: what a share proxies to is a port on this Service, so\n     * leaving the share behind would leave a link that answers 502 to whoever was sent it.\n     */\n    async unforward(row, done) {\n      this.error = '';\n      this.acting = { ...this.acting, [row.port]: 'unforward' };\n\n      try {\n        if (this.shareOf(row.port)) {\n          await setWorkspaceShares(this.workspace.name, this.shares.filter((entry) => entry.port !== row.port));\n        }\n\n        await removeWorkspacePort(this.workspace.name, row.port);\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /**\n     * Where this row answers.\n     *\n     * A forwarded port is the node's address, because that is what forwarding it was for and it\n     * is the address somebody would be given. Anything else is the service proxy, on Rancher's\n     * origin and behind a Rancher session, which is only an address at all for a port the Service\n     * carries; a detected port that has not been forwarded has none, and the row says so.\n     */\n    url(row) {\n      if (row.nodePort) {\n        return this.node ? `${ this.scheme(row.port) }://${ this.node }:${ row.nodePort }/` : '';\n      }\n\n      if (!this.ports.some((entry) => entry.port === row.port)) {\n        return '';\n      }\n\n      return workspaceProxyUrl(this.workspace.name, row.port, this.scheme(row.port));\n    },\n\n    /** The address as somebody else would have to type it, which is what goes on the clipboard. */\n    absoluteUrl(row) {\n      const url = this.url(row);\n\n      return url.startsWith('http') ? url : `${ window.location.origin }${ url }`;\n    },\n\n    async copy(text, port) {\n      this.error = '';\n\n      try {\n        await navigator.clipboard.writeText(text);\n        this.copied = port;\n        clearTimeout(this.copyTimer);\n        this.copyTimer = setTimeout(() => {\n          this.copied = 0;\n        }, 4000);\n      } catch {\n        // Writing to the clipboard needs a secure context and a user gesture, and this has\n        // both, but a browser can still refuse. Saying so beats a button that did nothing.\n        this.error = 'The browser would not let this page write to the clipboard. The address is in the table, and can be copied by hand.';\n      }\n    },\n\n    /** The share on a port, if it has one. */\n    shareOf(port) {\n      return this.shares.find((entry) => entry.port === port) || null;\n    },\n\n    /** Where a share answers: the node again, but the proxy's port rather than the workspace's. */\n    shareUrl(port) {\n      const share = this.shareOf(port);\n      const published = share && this.sharePorts[share.listen];\n\n      return published && this.node ? `http://${ this.node }:${ published }/` : '';\n    },\n\n    /**\n     * Share a port, or stop sharing it.\n     *\n     * The credentials are made here and never asked for. A share is a link you hand to somebody\n     * for an afternoon, so a password nobody chose is both safer and one fewer thing to decide;\n     * the username is the port so that two shares are told apart in a password manager.\n     *\n     * Sharing ends with the address, the username and the password on the clipboard, which is\n     * the only thing anybody was going to do with them. They were shown in a panel under the\n     * table before, which is a thing to read and then copy by hand.\n     */\n    async setShared(port, shared, done) {\n      this.error = '';\n\n      try {\n        const others = this.shares.filter((entry) => entry.port !== port);\n        const share = {\n          port,\n          listen:   nextListen(others),\n          scheme:   this.scheme(port),\n          username: `port-${ port }`,\n          password: generatedPassword(),\n        };\n\n        await setWorkspaceShares(this.workspace.name, shared ? [...others, share] : others);\n        await this.refresh();\n\n        if (shared) {\n          await this.copy(await this.shareText(share), port);\n        }\n\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /**\n     * The three lines that are the share, waiting for the address if it is not there yet.\n     *\n     * The node port is assigned by the cluster when the Service is written, and the write and the\n     * assignment are not the same instant: copying a moment too early puts a link with no port in\n     * it on somebody's clipboard, which they then paste to a colleague.\n     */\n    async shareText(share) {\n      for (let attempt = 0; attempt < 10 && !this.shareUrl(share.port); attempt++) {\n        await new Promise((resolve) => setTimeout(resolve, 500));\n        this.sharePorts = await shareNodePorts(this.workspace.name).catch(() => this.sharePorts);\n      }\n\n      return [\n        this.shareUrl(share.port) || 'the cluster has not published it yet',\n        `username: ${ share.username }`,\n        `password: ${ share.password }`,\n      ].join('\\n');\n    },\n  },\n};\n</script>\n\n<template>\n  <div class=\"workspace-ports\">\n    <Banner\n      v-if=\"error\"\n      color=\"error\"\n      :label=\"error\"\n    />\n\n    <!--\n      No sorting from the table: the order is forwarded first, which is this component's and not\n      a column's. A sortable header here would offer to undo the one thing the order is for.\n    -->\n    <SortableTable\n      :headers=\"headers\"\n      :rows=\"rows\"\n      key-field=\"port\"\n      :table-actions=\"false\"\n      :row-actions=\"false\"\n      :search=\"false\"\n      :paging=\"false\"\n    >\n      <template #cell:port=\"{ row }\">\n        <span class=\"workspace-ports__port\">:{{ row.port }}</span>\n        <span\n          v-if=\"row.loopback\"\n          v-clean-tooltip=\"'Bound to 127.0.0.1 only. A Service routes to the pod\\'s address, which this refuses, so forwarding it would not help.'\"\n          class=\"workspace-ports__loopback\"\n        >loopback</span>\n      </template>\n\n      <!--\n        What the pod itself says, which is the whole of the question. This used to ask the service\n        proxy whether the port answered, and the proxy can only reach a port the Service carries -\n        so a port that was plainly listening but not forwarded was reported as answering nothing.\n        /proc/net/tcp already knows, and it costs no request.\n      -->\n      <template #cell:answering=\"{ row }\">\n        <span :class=\"row.listening ? 'text-success' : 'text-muted'\">\n          {{ row.listening ? 'Yes' : 'Nothing yet' }}\n        </span>\n      </template>\n\n      <!--\n        Forwarded: the port it was given, which is not editable because changing it would move an\n        address somebody may already have. Not forwarded: a suggestion, in a box, because the\n        whole point of suggesting is that it can be overridden.\n      -->\n      <template #cell:public=\"{ row }\">\n        <span\n          v-if=\"forwarded(row)\"\n          class=\"workspace-ports__port\"\n        >:{{ row.nodePort }}</span>\n        <LabeledInput\n          v-else\n          class=\"workspace-ports__public\"\n          type=\"number\"\n          :value=\"publicPort(row)\"\n          :status=\"publicError(row) ? 'error' : null\"\n          @update:value=\"(value) => chosen = { ...chosen, [row.port]: value }\"\n        />\n      </template>\n\n      <template #cell:url=\"{ row }\">\n        <span class=\"workspace-ports__url\">{{ url(row) || '&mdash;' }}</span>\n        <span\n          v-if=\"shareUrl(row.port)\"\n          class=\"workspace-ports__url workspace-ports__url--share\"\n        >{{ shareUrl(row.port) }}</span>\n      </template>\n\n      <template #cell:actions=\"{ row }\">\n        <div class=\"workspace-ports__actions\">\n          <RcButton\n            v-if=\"url(row)\"\n            variant=\"tertiary\"\n            size=\"small\"\n            left-icon=\"external-link\"\n            :href=\"url(row)\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >\n            Open\n          </RcButton>\n          <RcButton\n            v-if=\"url(row)\"\n            variant=\"tertiary\"\n            size=\"small\"\n            left-icon=\"copy\"\n            @click=\"copy(absoluteUrl(row), row.port)\"\n          >\n            {{ copied === row.port ? 'Copied' : 'Copy' }}\n          </RcButton>\n          <!-- Only for a forwarded port: a share proxies to the Service, so there has to be one. -->\n          <AsyncButton\n            v-if=\"forwarded(row)\"\n            mode=\"apply\"\n            :action-label=\"shareOf(row.port) ? 'Unshare' : 'Share'\"\n            :waiting-label=\"shareOf(row.port) ? 'Unsharing' : 'Sharing'\"\n            :success-label=\"shareOf(row.port) ? 'Unshared' : 'Shared'\"\n            size=\"sm\"\n            @click=\"(done) => setShared(row.port, !shareOf(row.port), done)\"\n          />\n          <AsyncButton\n            mode=\"apply\"\n            :action-label=\"forwardLabels(row).action\"\n            :waiting-label=\"forwardLabels(row).waiting\"\n            :success-label=\"forwardLabels(row).success\"\n            size=\"sm\"\n            :disabled=\"!forwarded(row) && !!publicError(row)\"\n            @click=\"(done) => forwarded(row) ? unforward(row, done) : forward(row, done)\"\n          />\n        </div>\n      </template>\n\n      <template #no-rows>\n        <tr>\n          <td :colspan=\"headers.length\">\n            <span class=\"text-muted\">This workspace is not listening on anything yet.</span>\n          </td>\n        </tr>\n      </template>\n    </SortableTable>\n\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .workspace-ports {\n    // The tab pane has no padding of its own: WorkspaceDetail takes it off so that the two tabs\n    // whose content is one rectangle, the terminal and the browser frame, can fill it. A table is\n    // not one of those, so it puts its own back, the same 20px the Sidecars tab uses.\n    overflow-y: auto;\n    padding:    var(--dev-space-5);\n\n    &__port {\n      font-family: monospace;\n    }\n\n    &__loopback {\n      margin-left: var(--dev-space-3);\n      color:       var(--warning);\n      font-size:   11px;\n    }\n\n    // Narrow: it holds five digits and sits in a table row, so the shell's full-width input would\n    // push the columns beside it off the page.\n    &__public {\n      width: 110px;\n    }\n\n    // The address is long and the table is inside a tab pane, so it is truncated rather than\n    // allowed to push the page sideways. The whole of it is one click away on Copy, and on\n    // Open, which are the two things anyone wants it for.\n    &__url {\n      display:       block;\n      max-width:     320px;\n      overflow:      hidden;\n      color:         var(--muted);\n      font-family:   monospace;\n      font-size:     12px;\n      white-space:   nowrap;\n      text-overflow: ellipsis;\n    }\n\n    &__url--share {\n      color: var(--success);\n    }\n\n    &__actions {\n      display:         flex;\n      align-items:     center;\n      gap:             var(--dev-space-3);\n      justify-content: flex-end;\n    }\n\n  }\n</style>\n",
    "pkg/dev-extension/components/WorkspaceSidecars.vue": "<script>\n// The optional containers a workspace can run beside itself.\n//\n// A sidecar is what a workspace already is, one level down: a Deployment in the workspace's own\n// namespace, a Service when it serves something, started and stopped by scaling, and reached\n// through the same service proxy. So nothing new is invented here. The card is Rancher's Card,\n// the badge is the same state badge the tables use, and Launch and Share are the same two\n// things the Ports tab does.\n//\n// They are declared by the template (see templates.ts) and default to stopped, because a\n// workspace should be cheap to make: the Deployment is created the first time someone presses\n// Start. Groups come from the declarations, so a template with one group renders one group.\nimport { Card } from '@components/Card';\nimport { Banner } from '@components/Banner';\nimport { BadgeState } from '@components/BadgeState';\nimport { RcButton } from '@components/RcButton';\nimport AsyncButton from '@shell/components/AsyncButton';\nimport { colorForState, stateDisplay } from '@shell/plugins/dashboard-store/resource-class';\nimport LabeledSelect from '@shell/components/form/LabeledSelect';\nimport { Checkbox } from '@components/Form/Checkbox';\nimport { LabeledInput } from '@components/Form/LabeledInput';\nimport {\n  listSidecars, startSidecar, stopSidecar, restartSidecar, sidecarProxyUrl, sidecarServiceUrl,\n  templateSecretKey, workspaceAuth, setWorkspaceAuth, sidecarNodePort, nodeAddress,\n  sidecarParams, setSidecarParams, sidecarLog\n} from '../api';\nimport { templateById } from '../templates';\n\nconst REFRESH_MS = 5000;\n\n/**\n * How often an open log window asks again.\n *\n * Faster than the card poll, because a log is what someone opens when they are watching\n * something happen, and slower than a stream, because this is a fetch of the last five hundred\n * lines rather than a follow.\n */\nconst LOG_REFRESH_MS = 3000;\n\nexport default {\n  name: 'WorkspaceSidecars',\n\n  components: {\n    Card, Banner, BadgeState, RcButton, AsyncButton, LabeledSelect, Checkbox, LabeledInput\n  },\n\n  props: {\n    workspace: {\n      type:     Object,\n      required: true,\n    },\n  },\n\n  async fetch() {\n    await this.refresh();\n  },\n\n  data() {\n    return {\n      states:       {},\n      // What the workspace has asked its own Rancher to use, and what the manager made of it.\n      auth:         {\n        wanted: '', applied: '', message: '', at: ''\n      },\n      // The mode each auth card is offering, which is the applied one where there is one so that\n      // the control opens on what is true rather than on the first entry in the list.\n      chosen:       {},\n      // The node port the cluster assigned a sidecar that asked for one, by id.\n      nodePorts:    {},\n      // The node's own address, which is where those ports answer. One fetch, on refresh.\n      node:         '',\n      error:        '',\n      // The sidecar whose Configure dialog is open, and the values being edited in it. The\n      // values are a copy: closing without saving has to leave the saved ones alone.\n      configuring:  null,\n      values:       {},\n      saved:        {},\n      // The auth provider the open dialog is offering, which is Rancher's card's and no other's.\n      provider:     '',\n      // The sidecar whose log is open, and what it said when it was asked.\n      logging:      null,\n      // The log as rows rather than as text: each line carries the time the container wrote it.\n      logLines:     [],\n      logNote:      '',\n      logTimer:     null,\n      copied:       '',\n      copyTimer:    null,\n      refreshTimer: null,\n    };\n  },\n\n  computed: {\n    template() {\n      return templateById(this.workspace.template);\n    },\n\n    sidecars() {\n      return this.template?.sidecars || [];\n    },\n\n    /** The declarations, grouped as they were declared. */\n    groups() {\n      const groups = new Map();\n\n      for (const sidecar of this.sidecars) {\n        groups.set(sidecar.group, [...(groups.get(sidecar.group) || []), sidecar]);\n      }\n\n      return [...groups.entries()].map(([name, items]) => ({ name, items }));\n    },\n\n    /**\n     * Every provider any of this workspace's sidecars can back, and no provider at all.\n     *\n     * Gathered from the declarations rather than listed, which is what makes a new auth sidecar a\n     * data change. It is offered on the Rancher card because Rancher is what the choice is about:\n     * the closet's dashboard puts the same list in the same place, for the same reason.\n     */\n    authModes() {\n      return [\n        { value: '', label: 'Local users only' },\n        ...this.sidecars.flatMap((sidecar) => sidecar.auth || []),\n      ];\n    },\n\n    /** The sidecar that owns this workspace's Rancher, which is the one that applies an auth choice. */\n    rancherSidecar() {\n      return this.sidecars.find((sidecar) => sidecar.providesApi) || null;\n    },\n  },\n\n  mounted() {\n    this.refreshTimer = setInterval(() => this.refresh(), REFRESH_MS);\n  },\n\n  beforeUnmount() {\n    clearInterval(this.refreshTimer);\n    clearInterval(this.logTimer);\n    clearTimeout(this.copyTimer);\n  },\n\n  methods: {\n    async refresh() {\n      try {\n        const [states, auth] = await Promise.all([\n          listSidecars(this.workspace.name, this.sidecars, this.template),\n          workspaceAuth(this.workspace.name),\n        ]);\n\n        this.states = states;\n        this.auth = auth;\n        this.node = await nodeAddress();\n\n        // Only for the sidecars that asked for one, and only while they are running: an assigned\n        // node port is the cluster's answer rather than anything declared here.\n        for (const sidecar of this.sidecars.filter((candidate) => candidate.nodePort)) {\n          this.nodePorts = { ...this.nodePorts, [sidecar.id]: await sidecarNodePort(this.workspace.name, sidecar) };\n        }\n\n        for (const sidecar of this.sidecars.filter((candidate) => candidate.auth)) {\n          if (!this.chosen[sidecar.id]) {\n            const mine = sidecar.auth.find((mode) => mode.value === auth.wanted);\n\n            this.chosen = { ...this.chosen, [sidecar.id]: (mine || sidecar.auth[0]).value };\n          }\n        }\n      } catch (e) {\n        this.error = e.message || String(e);\n      }\n    },\n\n    /**\n     * Whether this card can offer to point Rancher at itself.\n     *\n     * Both sides have to be up, and it is the manager that carries it out, so a request made while\n     * either is down would sit unapplied with nothing to say why.\n     */\n    canApplyAuth(sidecar) {\n      return this.stateOf(sidecar) === 'running' && !!this.rancherSidecar &&\n        this.stateOf(this.rancherSidecar) === 'running';\n    },\n\n    /** The mode of this card's that Rancher is actually using, if any. */\n    appliedMode(sidecar) {\n      return (sidecar.auth || []).find((mode) => mode.value === this.auth.applied) || null;\n    },\n\n    /** Asked for, not yet reported back by the manager. */\n    pendingAuth(sidecar) {\n      return (sidecar.auth || []).some((mode) => mode.value === this.auth.wanted) &&\n        this.auth.applied !== this.auth.wanted;\n    },\n\n    async applyAuth(sidecar, done) {\n      this.error = '';\n\n      try {\n        await setWorkspaceAuth(this.workspace.name, this.chosen[sidecar.id]);\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /** Back to local users only, which is also how the other provider gets disabled. */\n    async clearAuth(done) {\n      this.error = '';\n\n      try {\n        await setWorkspaceAuth(this.workspace.name, '');\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    stateOf(sidecar) {\n      return this.states[sidecar.id]?.state || 'stopped';\n    },\n\n    badgeColor(sidecar) {\n      return colorForState(this.stateOf(sidecar)).replace('text-', 'bg-');\n    },\n\n    badgeLabel(sidecar) {\n      return stateDisplay(this.stateOf(sidecar));\n    },\n\n    /** Keys this sidecar declared that are not in the secret store yet. */\n    missing(sidecar) {\n      return this.states[sidecar.id]?.missing || [];\n    },\n\n    /**\n     * The declarations behind those keys, so the card can tell the two cases apart: a key the\n     * sidecar cannot work without stops it being started, and one it merely prefers does not.\n     */\n    missingRequired(sidecar) {\n      return this.missing(sidecar)\n        .filter((key) => (this.template?.secrets || []).find((secret) => secret.key === key)?.required !== false);\n    },\n\n    /**\n     * Why this sidecar cannot start, or '' when it can.\n     *\n     * Only the keys it cannot work without. An optional key that is unset used to be reported\n     * here too, on the argument that a person should know a value is not in use; what that\n     * actually produced was three lines of warning on the Rancher card about cloud credentials\n     * nobody had asked it to use. A sidecar works without an optional key by definition, and\n     * Settings is where which keys are set is a question worth answering.\n     */\n    missingLabel(sidecar) {\n      const keys = this.missingRequired(sidecar)\n        .map((key) => templateSecretKey(this.workspace.template, key));\n\n      if (!keys.length) {\n        return '';\n      }\n\n      return `Cannot start: ${ keys.join(', ') } ${ keys.length > 1 ? 'are' : 'is' } not set. Set ${ keys.length > 1 ? 'them' : 'it' } in Settings, then start this.`;\n    },\n\n    /** What the cluster says about a sidecar that is not running, when it says anything. */\n    detail(sidecar) {\n      return this.states[sidecar.id]?.detail || '';\n    },\n\n    /** The last line it printed, while it is still coming up. */\n    log(sidecar) {\n      return this.states[sidecar.id]?.log || '';\n    },\n\n    /** Where one pod reaches another, which is what a sidecar that serves no UI is for. */\n    address(sidecar) {\n      return sidecar.port ? sidecarServiceUrl(this.workspace.name, sidecar) : '';\n    },\n\n    /**\n     * Where to send a browser for this sidecar.\n     *\n     * A node port when the declaration asks for one, and that is not a preference: Keycloak\n     * rewrites itself out of a path prefix, so the service proxy can only ever serve it a 404,\n     * which is why it has a node port in the first place. The host is the node's own, for the\n     * reason nodeAddress gives: a published port is one that has to work from off the cluster,\n     * and this page's own hostname is a name that resolves on Rancher's network and nowhere else.\n     */\n    url(sidecar) {\n      if (!sidecar.port) {\n        return '';\n      }\n\n      const published = this.nodePorts[sidecar.id];\n\n      if (published && this.node) {\n        return `${ sidecar.scheme || 'http' }://${ this.node }:${ published }/`;\n      }\n\n      return sidecarProxyUrl(this.workspace.name, sidecar);\n    },\n\n    /** How a conversation in this workspace adds an MCP sidecar, once it is running. */\n    mcpCommand(sidecar) {\n      if (!sidecar.mcpPath || this.stateOf(sidecar) !== 'running') {\n        return '';\n      }\n\n      return `claude mcp add --transport http ${ sidecar.id } ${ this.address(sidecar) }:${ sidecar.port }${ sidecar.mcpPath }`;\n    },\n\n    /**\n     * Whether this card has a gear at all.\n     *\n     * Params, or an auth provider it can back. The closet's own card asks exactly this question,\n     * and for the same reason: a gear that opens an empty dialog is worse than no gear.\n     */\n    hasConfig(sidecar) {\n      return !!(sidecar.params || []).length || !!sidecar.providesApi;\n    },\n\n    async openConfig(sidecar) {\n      this.error = '';\n\n      try {\n        const values = await sidecarParams(this.workspace.name, sidecar);\n\n        // Two copies: one being edited and one to compare it against, so Save can say whether\n        // there is anything to save rather than restarting a sidecar over an opened dialog.\n        this.values = { ...values };\n        this.saved = { ...values };\n        this.provider = this.auth.wanted || '';\n        this.configuring = sidecar;\n      } catch (e) {\n        this.error = e.message || String(e);\n      }\n    },\n\n    closeConfig() {\n      this.configuring = null;\n    },\n\n    /**\n     * Save, and apply.\n     *\n     * Applying is a restart, because a container reads its environment once. A sidecar that is\n     * not running is started instead, which is the same write and the same result: what it comes\n     * up with is what was just saved.\n     */\n    async saveConfig(done) {\n      this.error = '';\n\n      const sidecar = this.configuring;\n\n      try {\n        await setSidecarParams(this.workspace.name, sidecar, this.values);\n\n        // The auth choice is Rancher's card, so it is only ever saved from that dialog, and only\n        // when it actually changed: setWorkspaceAuth writes a request the manager then acts on,\n        // and rewriting the same request would have it applied again for nothing.\n        if (sidecar.providesApi && this.provider !== this.auth.wanted) {\n          await setWorkspaceAuth(this.workspace.name, this.provider);\n        }\n\n        if (this.stateOf(sidecar) === 'stopped') {\n          await startSidecar(this.workspace.name, sidecar, this.template);\n        } else {\n          await restartSidecar(this.workspace.name, sidecar, this.template);\n        }\n\n        this.configuring = null;\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /**\n     * Open the log, and keep it open on the current one.\n     *\n     * There is no Refresh button on either the log or the list, deliberately: both are already\n     * polling, and a button beside something that updates itself is a button that only ever\n     * confirms what is already on screen. The log's poll stops when the window closes, so a\n     * dialog nobody has open costs nothing.\n     */\n    openLog(sidecar) {\n      this.logging = sidecar;\n      this.logLines = [];\n      this.logNote = '';\n      clearInterval(this.logTimer);\n      this.logTimer = setInterval(() => this.readLog(sidecar), LOG_REFRESH_MS);\n\n      return this.readLog(sidecar);\n    },\n\n    async readLog(sidecar) {\n      try {\n        const log = await sidecarLog(this.workspace.name, sidecar);\n\n        this.logNote = log ? '' : 'This sidecar has no pod yet, so it has not said anything.';\n\n        // Newest first. A container's log is written oldest-first and read the other way round:\n        // what someone opens this for is the last thing it said, and scrolling to the bottom of\n        // five hundred lines to find it is the whole of the friction this removes.\n        this.logLines = (log ? log.replace(/\\n$/, '').split('\\n') : [])\n          .reverse()\n          .map((line, index) => {\n            // The apiserver writes `2026-08-14T19:48:15.123456789Z the line`. The date is the\n            // same for everything on screen, so only the time is kept; a line with no timestamp\n            // in front of it is passed through as it is rather than being carved up.\n            const match = /^(\\d{4}-\\d\\d-\\d\\dT)(\\d\\d:\\d\\d:\\d\\d)\\.\\d+Z (.*)$/.exec(line);\n\n            return { key: index, at: match ? match[2] : '', text: match ? match[3] : line };\n          });\n      } catch (e) {\n        this.logLines = [];\n        this.logNote = e.message || String(e);\n      }\n    },\n\n    closeLog() {\n      clearInterval(this.logTimer);\n      this.logTimer = null;\n      this.logging = null;\n    },\n\n    async start(sidecar, done) {\n      this.error = '';\n\n      try {\n        await startSidecar(this.workspace.name, sidecar, this.template);\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    async stop(sidecar, done) {\n      this.error = '';\n\n      try {\n        await stopSidecar(this.workspace.name, sidecar.id, this.template);\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /** A rollout, not a stop and a start. See restartSidecar for why that distinction matters. */\n    async restart(sidecar, done) {\n      this.error = '';\n\n      try {\n        await restartSidecar(this.workspace.name, sidecar, this.template);\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    async share(sidecar) {\n      try {\n        await navigator.clipboard.writeText(`${ window.location.origin }${ this.url(sidecar) }`);\n        this.copied = sidecar.id;\n        clearTimeout(this.copyTimer);\n        this.copyTimer = setTimeout(() => {\n          this.copied = '';\n        }, 4000);\n      } catch {\n        this.error = 'The browser would not let this page write to the clipboard.';\n      }\n    },\n  },\n};\n</script>\n\n<template>\n  <div class=\"workspace-sidecars\">\n    <!--\n      No heading and no count. The tab strip already says Sidecars, and every card already carries\n      its own state badge, so a line saying how many of them are running was arithmetic over what\n      is on screen underneath it.\n    -->\n\n    <Banner\n      v-if=\"error\"\n      color=\"error\"\n      :label=\"error\"\n    />\n\n    <Banner\n      v-if=\"!sidecars.length\"\n      color=\"info\"\n      label=\"This workspace's template declares no sidecars.\"\n    />\n\n    <section\n      v-for=\"group in groups\"\n      :key=\"group.name\"\n      class=\"workspace-sidecars__group\"\n    >\n      <h4>{{ group.name }}</h4>\n      <div class=\"workspace-sidecars__cards\">\n        <Card\n          v-for=\"sidecar in group.items\"\n          :key=\"sidecar.id\"\n          class=\"workspace-sidecars__card\"\n          :show-highlight-border=\"false\"\n          :show-actions=\"false\"\n        >\n          <template #title>\n            <div class=\"workspace-sidecars__title\">\n              <h5>{{ sidecar.label }}</h5>\n              <BadgeState\n                :color=\"badgeColor(sidecar)\"\n                :label=\"badgeLabel(sidecar)\"\n              />\n              <!--\n                The two icons the closet's card has, in the same corner: what it is doing, and\n                what it is set to. Both are quiet, because a card is mostly read rather than\n                operated, and both are only there when they have something behind them.\n              -->\n              <button\n                v-if=\"stateOf(sidecar) !== 'stopped'\"\n                v-clean-tooltip=\"'Logs'\"\n                type=\"button\"\n                class=\"workspace-sidecars__icon\"\n                :aria-label=\"`Logs for ${ sidecar.label }`\"\n                @click=\"openLog(sidecar)\"\n              >\n                <i class=\"icon icon-file\" />\n              </button>\n              <button\n                v-if=\"hasConfig(sidecar)\"\n                v-clean-tooltip=\"'Configure'\"\n                type=\"button\"\n                class=\"workspace-sidecars__icon\"\n                :aria-label=\"`Configure ${ sidecar.label }`\"\n                @click=\"openConfig(sidecar)\"\n              >\n                <i class=\"icon icon-gear\" />\n              </button>\n            </div>\n          </template>\n\n          <template #body>\n            <p>{{ sidecar.description }}</p>\n            <p class=\"workspace-sidecars__image\">\n              {{ sidecar.image }}\n            </p>\n            <p\n              v-if=\"missingLabel(sidecar)\"\n              class=\"workspace-sidecars__missing\"\n            >\n              {{ missingLabel(sidecar) }}\n            </p>\n            <!--\n              The cluster's own sentence, which is the difference between a card that says\n              Starting for four minutes and one that says the image cannot be pulled.\n            -->\n            <p\n              v-if=\"detail(sidecar) && stateOf(sidecar) !== 'running'\"\n              class=\"workspace-sidecars__detail\"\n            >\n              {{ detail(sidecar) }}\n            </p>\n\n            <!--\n              While it is coming up, the last thing it said. A sidecar that installs two helm\n              charts is Starting for about ten minutes, and this is the difference between that\n              and something being wrong.\n            -->\n            <p\n              v-if=\"log(sidecar)\"\n              class=\"workspace-sidecars__log\"\n            >\n              {{ log(sidecar) }}\n            </p>\n\n            <!--\n              What the workspace itself talks to, for a sidecar whose whole point is being reached\n              from inside the cluster rather than opened in a tab.\n            -->\n            <p\n              v-if=\"address(sidecar) && sidecar.providesApi\"\n              class=\"workspace-sidecars__image\"\n            >\n              {{ address(sidecar) }}\n              <span v-if=\"stateOf(sidecar) === 'running'\">is what this workspace's dashboard is pointed at.</span>\n              <span v-else>is what this workspace's dashboard will be pointed at while this runs.</span>\n            </p>\n\n            <!--\n              An MCP server has nothing to open, so what its card offers is the line that adds it\n              to a conversation in this workspace. In-cluster address, because the thing that will\n              use it is the workspace's own container.\n            -->\n            <p\n              v-if=\"mcpCommand(sidecar)\"\n              class=\"workspace-sidecars__image\"\n            >\n              {{ mcpCommand(sidecar) }}\n            </p>\n\n            <!--\n              What Rancher is using now, when this card is what it is using. The choosing has\n              moved behind the gear, where the rest of a sidecar's configuration is; this is the\n              one line about it that is worth having on the card itself.\n            -->\n            <p\n              v-if=\"sidecar.auth\"\n              class=\"workspace-sidecars__detail\"\n            >\n              <template v-if=\"appliedMode(sidecar)\">Rancher auth: {{ appliedMode(sidecar).label }}. {{ auth.message }}</template>\n              <template v-else-if=\"pendingAuth(sidecar)\">Rancher auth: asked for, waiting for the Rancher sidecar to apply it.</template>\n              <template v-else>Not in use - turn it on with the auth provider setting on the Rancher card.</template>\n            </p>\n\n            <div class=\"workspace-sidecars__links\">\n              <!--\n                Only where the service proxy can actually serve the thing. Rancher and Keycloak\n                both rewrite themselves out of a path prefix, and a Launch that opens a page which\n                redirects itself to a 404 is worse than no Launch.\n              -->\n              <RcButton\n                v-if=\"sidecar.port && sidecar.launchable !== false && stateOf(sidecar) === 'running'\"\n                variant=\"link\"\n                size=\"small\"\n                left-icon=\"external-link\"\n                :href=\"url(sidecar)\"\n                target=\"_blank\"\n                rel=\"noopener noreferrer\"\n              >\n                Launch\n              </RcButton>\n              <RcButton\n                v-if=\"sidecar.port && sidecar.launchable !== false && stateOf(sidecar) === 'running'\"\n                variant=\"link\"\n                size=\"small\"\n                left-icon=\"copy\"\n                @click=\"share(sidecar)\"\n              >\n                {{ copied === sidecar.id ? 'Copied' : 'Share' }}\n              </RcButton>\n            </div>\n\n            <div class=\"workspace-sidecars__actions\">\n              <!--\n                Disabled rather than allowed to fail. A sidecar started without a key it needs\n                comes up, answers nothing and looks healthy, so the card says it cannot work and\n                then does not let you do it anyway.\n              -->\n              <AsyncButton\n                v-if=\"stateOf(sidecar) === 'stopped'\"\n                mode=\"apply\"\n                action-label=\"Start\"\n                waiting-label=\"Starting\"\n                success-label=\"Started\"\n                :disabled=\"missingRequired(sidecar).length > 0\"\n                @click=\"(done) => start(sidecar, done)\"\n              />\n              <template v-else>\n                <AsyncButton\n                  mode=\"apply\"\n                  action-label=\"Stop\"\n                  waiting-label=\"Stopping\"\n                  success-label=\"Stopped\"\n                  @click=\"(done) => stop(sidecar, done)\"\n                />\n                <AsyncButton\n                  mode=\"apply\"\n                  action-label=\"Restart\"\n                  waiting-label=\"Restarting\"\n                  success-label=\"Restarted\"\n                  @click=\"(done) => restart(sidecar, done)\"\n                />\n              </template>\n            </div>\n          </template>\n        </Card>\n      </div>\n    </section>\n\n    <!--\n      Configure: the sidecar's own settings, and for the one that backs an auth provider, which\n      provider Rancher should use. One dialog and one button, as the closet has it, because the\n      two are applied by the same restart and asking twice would be asking about the same pod.\n    -->\n    <div\n      v-if=\"configuring\"\n      class=\"workspace-sidecars__modal\"\n      @click.self=\"closeConfig\"\n    >\n      <div class=\"workspace-sidecars__dialog\">\n        <header>\n          <h3>Configure {{ configuring.label }}</h3>\n          <RcButton\n            variant=\"tertiary\"\n            size=\"small\"\n            left-icon=\"close\"\n            aria-label=\"Close\"\n            @click=\"closeConfig\"\n          />\n        </header>\n\n        <div class=\"workspace-sidecars__fields\">\n          <div\n            v-for=\"param in (configuring.params || [])\"\n            :key=\"param.id\"\n            class=\"workspace-sidecars__field\"\n          >\n            <Checkbox\n              v-if=\"param.type === 'boolean'\"\n              :value=\"values[param.id] === 'true'\"\n              :label=\"param.label\"\n              @update:value=\"(on) => values = { ...values, [param.id]: on ? 'true' : '' }\"\n            />\n            <LabeledInput\n              v-else\n              :value=\"values[param.id]\"\n              :label=\"param.label\"\n              @update:value=\"(value) => values = { ...values, [param.id]: value }\"\n            />\n            <p class=\"workspace-sidecars__help\">\n              {{ param.description }}\n            </p>\n          </div>\n\n          <!--\n            The auth provider, for the card that can back one. It is stored rather than performed:\n            what carries it out is the manager inside the workspace's Rancher. See setWorkspaceAuth.\n          -->\n          <div\n            v-if=\"configuring.providesApi\"\n            class=\"workspace-sidecars__field\"\n          >\n            <LabeledSelect\n              :value=\"provider\"\n              :options=\"authModes\"\n              label=\"Auth provider\"\n              option-label=\"label\"\n              option-key=\"value\"\n              :reduce=\"(mode) => mode.value\"\n              :clearable=\"false\"\n              @update:value=\"(value) => provider = value\"\n            />\n            <p class=\"workspace-sidecars__help\">\n              Rancher allows one provider at a time, so choosing one turns the others off. The\n              sidecar behind the choice is started with it, and this Rancher restarts to pick it up.\n            </p>\n          </div>\n        </div>\n\n        <footer>\n          <RcButton\n            variant=\"secondary\"\n            @click=\"closeConfig\"\n          >\n            Cancel\n          </RcButton>\n          <AsyncButton\n            mode=\"apply\"\n            :action-label=\"stateOf(configuring) === 'stopped' ? 'Save and start' : 'Save and restart'\"\n            waiting-label=\"Applying\"\n            success-label=\"Applied\"\n            @click=\"saveConfig\"\n          />\n        </footer>\n      </div>\n    </div>\n\n    <!-- The container's own log, which is the answer to most of what a card cannot say. -->\n    <div\n      v-if=\"logging\"\n      class=\"workspace-sidecars__modal\"\n      @click.self=\"closeLog\"\n    >\n      <div class=\"workspace-sidecars__dialog workspace-sidecars__dialog--wide\">\n        <header>\n          <h3>{{ logging.label }} log</h3>\n          <RcButton\n            variant=\"tertiary\"\n            size=\"small\"\n            left-icon=\"close\"\n            aria-label=\"Close\"\n            @click=\"closeLog\"\n          />\n        </header>\n        <!-- Newest first, each line with the time the container wrote it. See readLog. -->\n        <div class=\"workspace-sidecars__log-body\">\n          <p\n            v-if=\"logNote\"\n            class=\"workspace-sidecars__log-note\"\n          >\n            {{ logNote }}\n          </p>\n          <div\n            v-for=\"line in logLines\"\n            :key=\"line.key\"\n            class=\"workspace-sidecars__log-line\"\n          >\n            <span class=\"workspace-sidecars__log-at\">{{ line.at }}</span>\n            <span class=\"workspace-sidecars__log-text\">{{ line.text }}</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .workspace-sidecars {\n    overflow-y: auto;\n    padding:    var(--dev-space-5);\n    // Nothing here is meant to be scrolled sideways: the cards wrap, and the one thing wider\n    // than the pane is a dialog that covers it anyway.\n    overflow-x: hidden;\n\n    &__group {\n      margin-top: var(--dev-space-5);\n\n      &:first-of-type {\n        margin-top: 0;\n      }\n\n      h4 {\n        margin:         0 0 var(--dev-space-3) 0;\n        color:          var(--muted);\n        font-size:      12px;\n        letter-spacing: 0.05em;\n        text-transform: uppercase;\n      }\n    }\n\n    // Two to a row, as the harness has them, and one on a narrow window.\n    //\n    // auto-fill rather than auto-fit, which is the difference between a group of one and a group\n    // of two having cards of the same width: auto-fit collapses the tracks nothing is in, so a\n    // group with a single card stretched it across the whole row while its neighbours were half\n    // that. auto-fill keeps the empty track, so every card in every group is one column wide.\n    &__cards {\n      display:               grid;\n      grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));\n      gap:                   var(--dev-space-4);\n      max-width:             1000px;\n    }\n\n    &__title {\n      display:     flex;\n      align-items: center;\n      gap:         var(--dev-space-4);\n\n      h5 {\n        margin: 0;\n      }\n    }\n\n    &__image {\n      color:       var(--muted);\n      font-family: monospace;\n      font-size:   12px;\n    }\n\n    &__missing {\n      color: var(--warning);\n    }\n\n    &__detail {\n      color:     var(--muted);\n      font-size: 12px;\n    }\n\n    // One line, whatever it says: a helm install prints lines of any length and the card is a\n    // card. What matters is that it is moving and what it is doing, not the whole line.\n    &__log {\n      overflow:      hidden;\n      color:         var(--muted);\n      font-family:   monospace;\n      font-size:     11px;\n      text-overflow: ellipsis;\n      white-space:   nowrap;\n    }\n\n    &__auth {\n      margin-top:  var(--dev-space-4);\n      padding-top: var(--dev-space-4);\n      border-top:  1px solid var(--border);\n    }\n\n    &__auth-row {\n      display:     flex;\n      align-items: center;\n      gap:         var(--dev-space-4);\n    }\n\n    &__auth-label {\n      color:     var(--muted);\n      font-size: 12px;\n    }\n\n    // Wide enough for the longest provider name and no wider: the row it sits in is a card's.\n    &__auth-select {\n      width: 140px;\n    }\n\n    &__auth-state {\n      margin-top: var(--dev-space-3);\n      color:      var(--muted);\n      font-size:  12px;\n    }\n\n    &__links {\n      display: flex;\n      gap:     var(--dev-space-4);\n    }\n\n    &__actions {\n      display:   flex;\n      gap:       var(--dev-space-4);\n      margin-top: var(--dev-space-4);\n    }\n\n    // The card's own corner controls: quiet, and the same box as each other.\n    &__icon {\n      display:         flex;\n      align-items:     center;\n      justify-content: center;\n      width:           22px;\n      height:          22px;\n      min-height:      22px;\n      padding:         0;\n      border:          none;\n      border-radius:   var(--border-radius);\n      background:      transparent;\n      color:           var(--muted);\n      cursor:          pointer;\n\n      &:hover {\n        background: var(--nav-hover, var(--accent-btn));\n        color:      var(--body-text);\n      }\n\n      .icon {\n        font-size: 14px;\n      }\n    }\n\n    // The second icon sits at the card's right edge, and the first beside it, so the two are a\n    // pair in the corner rather than two things after the badge.\n    &__title &__icon:first-of-type {\n      margin-left: auto;\n    }\n\n    // A dialog of this component's own rather than the shell's modal, which is driven through\n    // Vuex and expects a registered component. This is a panel over the tab, and the click on the\n    // backdrop closes it, which is the whole of the behaviour.\n    &__modal {\n      position:        fixed;\n      inset:           0;\n      z-index:         100;\n      display:         flex;\n      align-items:     center;\n      justify-content: center;\n      background:      rgba(0, 0, 0, 0.5);\n    }\n\n    &__dialog {\n      display:        flex;\n      flex-direction: column;\n      width:          560px;\n      max-width:      90vw;\n      max-height:     80vh;\n      border:         1px solid var(--border);\n      border-radius:  var(--border-radius);\n      background:     var(--body-bg);\n\n      &--wide {\n        width: 900px;\n      }\n\n      header {\n        display:       flex;\n        align-items:   center;\n        gap:           var(--dev-space-4);\n        padding:       var(--dev-space-4) var(--dev-space-5);\n        border-bottom: 1px solid var(--border);\n\n        h3 {\n          flex:   1 1 auto;\n          margin: 0;\n        }\n      }\n\n      footer {\n        display:         flex;\n        justify-content: flex-end;\n        gap:             var(--dev-space-4);\n        padding:         var(--dev-space-4) var(--dev-space-5);\n        border-top:      1px solid var(--border);\n      }\n    }\n\n    &__fields {\n      overflow-y: auto;\n      padding:    var(--dev-space-5);\n    }\n\n    &__field {\n      margin-bottom: var(--dev-space-5);\n\n      &:last-child {\n        margin-bottom: 0;\n      }\n    }\n\n    // The sentence under a field, which is the declaration's own description.\n    &__help {\n      max-width: 70ch;\n      margin:    var(--dev-space-3) 0 0 0;\n      color:     var(--muted);\n      font-size: 12px;\n    }\n\n    &__log-body {\n      overflow:    auto;\n      flex:        1 1 auto;\n      margin:      0;\n      padding:     var(--dev-space-4) var(--dev-space-5);\n      background:  var(--body-bg);\n      color:       var(--body-text);\n      font-family: monospace;\n      font-size:   12px;\n    }\n\n    // Time and text as two columns, so the times line up down the left and a wrapped line stays\n    // under its own text rather than under the clock.\n    &__log-line {\n      display: flex;\n      gap:     var(--dev-space-4);\n    }\n\n    &__log-at {\n      flex:  0 0 auto;\n      color: var(--muted);\n    }\n\n    &__log-text {\n      flex:        1 1 auto;\n      min-width:   0;\n      white-space: pre-wrap;\n      word-break:  break-all;\n    }\n\n    &__log-note {\n      margin: 0;\n      color:  var(--muted);\n    }\n  }\n</style>\n",
    "pkg/dev-extension/config/constants.ts": "export const PRODUCT_NAME = 'devextension';\nexport const CUSTOM_PAGE_NAME = 'home';\n\n// Rancher's stand-in cluster id for a product that has no cluster of its own.\nexport const BLANK_CLUSTER = '_';\n\nexport const HOME_ROUTE = `${ PRODUCT_NAME }-c-cluster-${ CUSTOM_PAGE_NAME }`;\n\n/**\n * The Floof page, which lives in Rancher's Cluster Explorer rather than in this extension's\n * own product.\n *\n * Hence the naming: explorer pages are `c-cluster-<product>-<page>`, matching the shell's own\n * (`c-cluster-explorer-tools`, `c-cluster-explorer-workload-dashboard`). Getting this wrong\n * is the usual reason an extension page renders without the cluster nav around it - the route\n * has to sit under the explorer's parent for the surrounding chrome to come with it.\n */\nexport const EXPLORER_PRODUCT = 'explorer';\nexport const FLOOF_PAGE = 'floof';\nexport const FLOOF_ROUTE = `c-cluster-${ EXPLORER_PRODUCT }-${ FLOOF_PAGE }`;\n\n/**\n * The Dev product: the Claude Harness, rebuilt on Kubernetes.\n *\n * A second product in the same extension rather than more pages in the first one, because the\n * two have nothing to do with each other: `devextension` exists to prove the live-reload loop\n * works, this one is a tool with its own nav. Its routes follow the same\n * `/{product}/c/:cluster/` shape and the same BLANK_CLUSTER param, since it owns no cluster\n * either.\n *\n * The thing this product manages is a workspace, not a project. The harness calls it a\n * project, but Rancher already means something specific by that word - a group of namespaces\n * inside a cluster, with its own members and quotas - and it means it in the very nav this\n * product sits next to. So the harness's word is dropped at the border rather than carried\n * in and left to collide.\n */\nexport const DEV_PRODUCT = 'dev';\n\nexport const WORKSPACES_PAGE = 'workspaces';\nexport const CREATE_PAGE = 'create';\nexport const MY_WORK_PAGE = 'my-work';\nexport const INSIGHTS_PAGE = 'insights';\nexport const SETTINGS_PAGE = 'settings';\n\n/** The product's own page template, which every page below is a child of. */\nexport const DEV_SHELL_ROUTE = `${ DEV_PRODUCT }-c-cluster`;\n\nexport const WORKSPACES_ROUTE = `${ DEV_PRODUCT }-c-cluster-${ WORKSPACES_PAGE }`;\nexport const WORKSPACE_ROUTE = `${ DEV_PRODUCT }-c-cluster-${ WORKSPACES_PAGE }-workspace`;\nexport const CREATE_ROUTE = `${ DEV_PRODUCT }-c-cluster-${ CREATE_PAGE }`;\nexport const MY_WORK_ROUTE = `${ DEV_PRODUCT }-c-cluster-${ MY_WORK_PAGE }`;\nexport const INSIGHTS_ROUTE = `${ DEV_PRODUCT }-c-cluster-${ INSIGHTS_PAGE }`;\nexport const SETTINGS_ROUTE = `${ DEV_PRODUCT }-c-cluster-${ SETTINGS_PAGE }`;\n\n/**\n * The tabs a workspace opens as, and the one a link with no tab in it means.\n *\n * Conversations is first and is the default, because it is the reason to open a workspace at\n * all. There is no Overview: what it held was the namespace, the Deployment, the Service and\n * the pod, which are plumbing, and the two facts on it anyone acts on are elsewhere already,\n * the state on the sidebar's row and the ports in the Ports tab. A link to `#overview` lands on\n * Conversations, since an unknown tab falls back to the default.\n *\n * Named here rather than in the page because the route carries a tab (see routing/index.ts):\n * the tab is part of the address so that a tab can be linked to and shared, which is the whole\n * reason it is not component state. The list is also what the page validates against, so a URL\n * naming a tab that does not exist lands on Overview instead of on an empty pane.\n */\nexport const WORKSPACE_TABS = ['conversations', 'browser', 'ports', 'sidecars'];\nexport const DEFAULT_WORKSPACE_TAB = 'conversations';\n\n/**\n * The pod this dashboard is served from, which is what the global terminal attaches to.\n *\n * Read out of the URL rather than written down. There can be several of these pods - barn\n * makes one per named extension - and each is reached through a Service of its own, so a\n * constant here would be the name of whichever one happened to be first and every other copy\n * would open a terminal in the wrong pod.\n *\n * The browser is always on the apiserver's service proxy:\n *\n *   /k8s/clusters/<cluster>/api/v1/namespaces/<ns>/services/http:<service>:8005/proxy/...\n *\n * and <ns>/<service> is exactly the pair this needs, because barn names the Deployment, the\n * Service and the pod's `app` label the same thing.\n *\n * The fallback is for a build served any other way - a plain `yarn dev` against a Rancher, on\n * somebody's laptop - where there is no pod to attach to and the terminal cannot work anyway.\n */\nfunction servedFrom(): { namespace: string; service: string } {\n  const match = window.location.pathname.match(\n    /\\/api\\/v1\\/namespaces\\/([^/]+)\\/services\\/[^:/]+:([^:/]+):\\d+\\/proxy/\n  );\n\n  return match ? { namespace: match[1], service: match[2] } : { namespace: 'barn', service: 'barn-dev-extension' };\n}\n\nconst SERVED_FROM = servedFrom();\n\nexport const DEV_POD_NAMESPACE = SERVED_FROM.namespace;\n/** The Deployment, the Service and the seed ConfigMap all carry this name. */\nexport const DEV_POD_SERVICE = SERVED_FROM.service;\nexport const DEV_POD_LABELS = { app: SERVED_FROM.service };\nexport const DEV_POD_CONTAINER = 'devserver';\n\n/**\n * The tmux session prefix for a global terminal.\n *\n * `/seed/shell.sh <id> <dir>` starts or reattaches `mc-<id>`, and the editor's pane in the\n * barn extension uses `editor`, so anything not called that is a session of its own.\n * The numbers after it are the drawer's terminal numbers, so Terminal 2 is always the same\n * conversation, whether it was closed and reopened or reached from a link (see terminals.ts).\n */\nexport const TERMINAL_SESSION_PREFIX = 'global';\n",
    "pkg/dev-extension/design/Panel.vue": "<script>\n// A bordered box with a fixed head and a body that scrolls.\n//\n// Four places in this product had grown their own version of this - the commits list, the file\n// tree, the file view, the log window - and they disagreed about the padding, the header\n// background and whether the header scrolled away with the content. The header not scrolling is\n// the part worth having: the name of what you are looking at is least useful at the moment you\n// have scrolled far enough to forget it.\nimport { SPACE, spaceVar } from './tokens';\n\nexport default {\n  name: 'Panel',\n\n  props: {\n    /** Shown in the head. A panel with no title and no `head` slot has no head at all. */\n    title: {\n      type:    String,\n      default: '',\n    },\n\n    /** Padding inside the body, as a step on the space scale. */\n    pad: {\n      type:      [String, Number],\n      default:   4,\n      validator: (value) => SPACE.includes(Number(value)),\n    },\n\n    /** Take the leftover height of the column this is in, and scroll inside it. */\n    fill: {\n      type:    Boolean,\n      default: false,\n    },\n  },\n\n  computed: {\n    bodyStyle() {\n      return { padding: spaceVar(this.pad) };\n    },\n  },\n};\n</script>\n\n<template>\n  <div\n    class=\"panel\"\n    :class=\"{ 'panel--fill': fill }\"\n  >\n    <div\n      v-if=\"title || $slots.head\"\n      class=\"panel__head\"\n    >\n      <slot name=\"head\">\n        {{ title }}\n      </slot>\n    </div>\n    <div\n      class=\"panel__body\"\n      :style=\"bodyStyle\"\n    >\n      <slot />\n    </div>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n.panel {\n  display:        flex;\n  flex-direction: column;\n  min-height:     0;\n  border:         1px solid var(--border);\n  border-radius:  var(--border-radius);\n  background:     var(--body-bg);\n  // So the head's own background does not square off the corners it sits in.\n  overflow:       hidden;\n\n  &--fill {\n    flex: 1 1 auto;\n  }\n\n  &__head {\n    flex:          0 0 auto;\n    padding:       var(--dev-space-3) var(--dev-space-4);\n    border-bottom: 1px solid var(--border);\n    background:    var(--accent-btn);\n    color:         var(--muted);\n    font-size:     11px;\n    overflow:      hidden;\n    text-overflow: ellipsis;\n    white-space:   nowrap;\n  }\n\n  &__body {\n    flex:       1 1 auto;\n    min-height: 0;\n    overflow:   auto;\n  }\n}\n</style>\n",
    "pkg/dev-extension/design/README.md": "# design/\n\nThe spacing and sizing this product is built from, and the components that apply it.\n\nBefore this there were eleven pixel values doing the work of six -- 2, 4, 5, 6, 8, 10, 12, 16,\n20 and 30 for gaps alone -- each chosen a component at a time. None of them was wrong on its\nown, which is exactly why it happened: the result was two panes almost aligned and a dialog\nwhose columns were almost in step.\n\n## The scale\n\n`tokens.css` is the whole of it, as CSS custom properties on `:root`. Six steps of space, three\ncontrol heights, four widths, each with a line saying what it is for. Arithmetic is\n`calc(var(--dev-space-4) * 2)`; there is deliberately no SCSS copy of the numbers, because two\ndefinitions of one scale is the problem the file exists to end.\n\nIt is plain CSS imported from `tokens.ts` rather than SCSS `@use`d from a component. The shell\nprepends its own SCSS to every component stylesheet through `additionalData`, so a `@use`\nwritten in one is never the first rule in the sheet and sass refuses it.\n\nThe middle of the scale is 10px, which is Rancher's own `$space-s`. This product renders inside\nRancher's chrome, and a rhythm of its own would read as a mistake beside the header and nav it\nsits between.\n\n## The components\n\n| Component | For |\n| --- | --- |\n| `Stack` | things in a column, one gap apart |\n| `Row` | things in a line, one gap apart, with an alignment |\n| `Spacer` | nothing, that takes the leftover room |\n| `Panel` | a bordered box with a head that stays put and a body that scrolls |\n\nThey exist because `display: flex` is not the hard part. Writing it in thirty components means\nchoosing the gap thirty times, and the gap is the thing that was never the same twice. Here it\nis a step on the scale, so the only gaps that exist are the ones on it.\n\nTwo of them also carry a fix for a bug this codebase hit twice. `Stack` sets `min-height: 0` and\n`Row` sets `min-width: 0`, because a flex child's default is to shrink to its content: without\nthem a fixed-height row gets squeezed and a long name makes its container wider than the page.\nBoth took a measurement to find, and neither is obvious from reading the markup.\n\n## Using them\n\n```vue\n<Row gap=\"4\">\n  <span>This workspace is stopped.</span>\n  <RcButton>Start it</RcButton>\n</Row>\n```\n\nA raw `padding: 10px` is not a crime, but it should be `var(--dev-space-4)`, and if it is a gap\nbetween two elements it should probably be a `Stack` or a `Row`.\n",
    "pkg/dev-extension/design/Row.vue": "<script>\n// Things in a line, one gap apart.\n//\n// The horizontal half of Stack, and it exists for the same reason: a row of controls is the\n// most common thing in this product and every one of them was choosing its own gap, its own\n// alignment and its own answer to \"which of these takes the leftover width\".\n//\n// `spread` is worth naming rather than leaving to `justify-content`, because what people\n// actually want is almost always one of three things: everything at the start, everything at\n// the start with one thing pushed to the end, or the two ends apart. `justify` covers the\n// first and third; the second is what `<Spacer />` inside a Row is for.\nimport { SPACE, spaceVar } from './tokens';\n\nexport default {\n  name: 'Row',\n\n  props: {\n    /** A step on the space scale: 1 (hairline) to 6 (between blocks). */\n    gap: {\n      type:      [String, Number],\n      default:   4,\n      validator: (value) => SPACE.includes(Number(value)),\n    },\n\n    align: {\n      type:      String,\n      default:   'center',\n      validator: (value) => ['stretch', 'start', 'center', 'end', 'baseline'].includes(value),\n    },\n\n    justify: {\n      type:      String,\n      default:   'start',\n      validator: (value) => ['start', 'center', 'end', 'between'].includes(value),\n    },\n\n    /** Let the line wrap. Off by default: a toolbar that wraps is usually a toolbar too small. */\n    wrap: {\n      type:    Boolean,\n      default: false,\n    },\n\n    /** Fill the parent's remaining space rather than being as wide as the contents. */\n    fill: {\n      type:    Boolean,\n      default: false,\n    },\n  },\n\n  computed: {\n    style() {\n      const justify = {\n        start: 'flex-start', center: 'center', end: 'flex-end', between: 'space-between'\n      }[this.justify];\n      const align = {\n        stretch: 'stretch', start: 'flex-start', center: 'center', end: 'flex-end', baseline: 'baseline'\n      }[this.align];\n\n      return {\n        gap:            spaceVar(this.gap),\n        justifyContent: justify,\n        alignItems:     align,\n        flexWrap:       this.wrap ? 'wrap' : 'nowrap',\n      };\n    },\n  },\n};\n</script>\n\n<template>\n  <div\n    class=\"row\"\n    :class=\"{ 'row--fill': fill }\"\n    :style=\"style\"\n  >\n    <slot />\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n.row {\n  display:   flex;\n  // The horizontal twin of Stack's `min-height: 0`, and needed as often: without it a long\n  // name or a wide table inside a Row makes the Row wider than its parent instead of\n  // ellipsising or scrolling.\n  min-width: 0;\n\n  &--fill {\n    flex: 1 1 auto;\n  }\n}\n</style>\n",
    "pkg/dev-extension/design/Spacer.vue": "<script>\n// Nothing, that takes up the leftover room.\n//\n// A Row with one of these in it puts what follows at the far end without anybody reaching for\n// `margin-left: auto` on a component that should not have to know where it is. It is one line\n// of CSS, and the reason it is a component is that `margin-left: auto` on the third of four\n// children is invisible until you go looking for why the fourth moved.\nexport default { name: 'Spacer' };\n</script>\n\n<template>\n  <div class=\"spacer\" />\n</template>\n\n<style lang=\"scss\" scoped>\n.spacer {\n  flex: 1 1 auto;\n  // Nothing to see and nothing to click through to whatever is behind it.\n  min-width: 0;\n  min-height: 0;\n}\n</style>\n",
    "pkg/dev-extension/design/Stack.vue": "<script>\n// Things in a column, one gap apart.\n//\n// The point is not that `display: flex; flex-direction: column` is hard to write. It is that\n// writing it in thirty components means choosing the gap thirty times, and the gap is the thing\n// that was never the same twice. Here it is a token name, so the only gaps that exist are the\n// ones on the scale.\n//\n// `grow` is the other half of the same problem: a flex child's default is to shrink, which is\n// what squeezed a fixed-height row down to its content twice in this codebase before anyone\n// noticed. A Stack says which of its children takes the leftover room, and the rest keep the\n// size they asked for.\nimport { SPACE, spaceVar } from './tokens';\n\nexport default {\n  name: 'Stack',\n\n  props: {\n    /** A step on the space scale: 1 (hairline) to 6 (between blocks). */\n    gap: {\n      type:      [String, Number],\n      default:   4,\n      validator: (value) => SPACE.includes(Number(value)),\n    },\n\n    /** Fill the parent rather than being as tall as the contents. */\n    fill: {\n      type:    Boolean,\n      default: false,\n    },\n\n    align: {\n      type:      String,\n      default:   'stretch',\n      validator: (value) => ['stretch', 'start', 'center', 'end'].includes(value),\n    },\n  },\n\n  computed: {\n    style() {\n      return { gap: spaceVar(this.gap), alignItems: this.align };\n    },\n  },\n};\n</script>\n\n<template>\n  <div\n    class=\"stack\"\n    :class=\"{ 'stack--fill': fill }\"\n    :style=\"style\"\n  >\n    <slot />\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n.stack {\n  display:        flex;\n  flex-direction: column;\n  // A flex container that is itself a flex child, which most of these are: without this its\n  // children can push it past its parent instead of scrolling inside it.\n  min-height:     0;\n\n  &--fill {\n    flex: 1 1 auto;\n  }\n}\n</style>\n",
    "pkg/dev-extension/design/tokens.css": "/*\n * The spacing and sizing this product is built from.\n *\n * Before this there were eleven different pixel values doing the work of five: 4, 5, 6, 8, 10,\n * 12, 16, 20 and 30 for gaps alone, chosen a component at a time. None of them was wrong on its\n * own, which is exactly why it happened, and the result is two panes that are almost aligned and\n * a dialog whose columns are almost in step.\n *\n * Plain CSS rather than SCSS, and imported from tokens.ts rather than `@use`d from a component.\n * The shell prepends its own SCSS to every component stylesheet through `additionalData`, so a\n * `@use` written in one is never the first rule in the sheet and sass refuses it. Importing the\n * file from the module the layout components already import puts it in the bundle exactly once,\n * with nothing to get in the wrong order.\n *\n * Arithmetic on these is `calc(var(--dev-space-4) * 2)`, which is why they do not also exist as\n * SCSS variables: two definitions of one scale is the problem this file was written to end.\n *\n * The middle of the scale is 10px, which is Rancher's own `$space-s`. That is deliberate: this\n * product renders inside Rancher's chrome, and a rhythm of its own would read as a mistake next\n * to the header and the nav it sits between.\n */\n:root {\n  /* 1  hairline    a dot and its label, a badge's own padding */\n  --dev-space-1: 2px;\n  /* 2  tight       inside a control */\n  --dev-space-2: 4px;\n  /* 3  snug        between controls that belong together */\n  --dev-space-3: 6px;\n  /* 4  default     between controls, list rows, table cells - most things */\n  --dev-space-4: 10px;\n  /* 5  section     between the sections of a page or a dialog */\n  --dev-space-5: 20px;\n  /* 6  block       between major blocks, and a page's own outer padding */\n  --dev-space-6: 30px;\n\n  /*\n   * Control heights: a row in a list, a compact control, and a control on a toolbar. The shell's\n   * own buttons are 24px (small) and 30px (default), and neither is a size these rows want,\n   * which is why they are written down rather than inherited.\n   */\n  --dev-control-row: 22px;\n  --dev-control-sm:  28px;\n  --dev-control:     32px;\n\n  /* Dialog widths, and the one fixed column this product has. */\n  --dev-modal-sm: 560px;\n  --dev-modal:    720px;\n  --dev-modal-lg: 900px;\n  --dev-side-col: 300px;\n}\n",
    "pkg/dev-extension/design/tokens.ts": "// The scale itself. Imported here rather than from a component, so it lands in the bundle once\n// and every layout component gets it by importing the module it already imports.\nimport './tokens.css';\n\n/**\n * The space scale, for the components that take a step of it as a prop.\n *\n * The values themselves live in tokens.css. This file only knows the names, because a component\n * that took `gap=\"4\"` and turned it into `10px` here would be a second place for the scale to be\n * defined, and the two would eventually disagree.\n */\nexport const SPACE = [1, 2, 3, 4, 5, 6];\n\nexport type Space = 1 | 2 | 3 | 4 | 5 | 6;\n\n/** The custom property for a step, or `0` for no gap at all. */\nexport function spaceVar(step: string | number): string {\n  const value = Number(step);\n\n  return SPACE.includes(value) ? `var(--dev-space-${ value })` : '0';\n}\n\n/** Control heights, by the same rule: named here, valued in the stylesheet. */\nexport const CONTROL = ['row', 'sm', 'md'];\n\nexport function controlVar(size: string): string {\n  return { row: 'var(--dev-control-row)', sm: 'var(--dev-control-sm)', md: 'var(--dev-control)' }[size] || 'auto';\n}\n",
    "pkg/dev-extension/github.ts": "/**\n * What GitHub is asked for My Work, and what comes back.\n *\n * From the browser, not from a pod. A page served through Rancher's service proxy can talk to\n * api.github.com directly: it answers with `access-control-allow-origin: *`, and a request\n * carrying an Authorization header survives its CORS preflight. So there is no server of ours in\n * this path, and the token never leaves the person's own browser except to GitHub.\n *\n * GraphQL rather than the REST search API, and that is not a preference. My Work wants, per pull\n * request: the CI verdict, how many checks are failing, the issue it closes, and whether you have\n * reviewed it. Over REST that is a search, then a fetch per PR for its head commit, then a fetch\n * per commit for its checks, then a fetch per PR for its reviews - somewhere over sixty requests\n * for two lists of twenty. Here it is one.\n */\nimport { githubToken } from './api';\n\nconst ENDPOINT = 'https://api.github.com/graphql';\n\n/** How many of each list to ask for. The harness shows about this many and it fits a screen. */\nconst PAGE = 25;\n\n/**\n * Issues are asked for in bulk, because they are paged five at a time on the page itself.\n *\n * Thirty-one assigned issues is an ordinary number and a person scrolls through them; asking for\n * twenty-five and drawing \"1 of 4 pages\" over a list that is missing the rest would be a lie the\n * page tells about its own paging.\n */\nconst ISSUE_PAGE = 100;\n\n/**\n * The checks on the head commit.\n *\n * `state` is GitHub's own rollup - SUCCESS, PENDING, FAILURE, ERROR - which is what the tick or\n * the cross is. The counts are worked out here rather than asked for, because GitHub counts check\n * runs by *status* (queued, in progress, completed) and what a person wants to know is how many\n * came back red, which is a conclusion. A run with no conclusion has not finished, so it is\n * pending; a status context has no conclusion at all and reports a state instead.\n */\nexport interface GithubChecks {\n  state: string;\n  failing: number;\n  pending: number;\n  total: number;\n}\n\n/** What a Rerun needs: the workflow runs behind the failing checks. */\nexport interface GithubRun {\n  id: number;\n  url: string;\n}\n\nexport interface GithubPr {\n  /** Unique across both lists and across repositories, which the number alone is not. */\n  key: string;\n  number: number;\n  url: string;\n  title: string;\n  repo: string;\n  draft: boolean;\n  /** Whether the review the PR is waiting on has been given, from GitHub's own decision. */\n  approved: boolean;\n  /** The issue this closes, where the PR says so. Null is the ordinary case, not an error. */\n  issue: { number: number; url: string } | null;\n  checks: GithubChecks | null;\n  /** The failing workflow runs, which is what Rerun acts on. Empty when nothing is red. */\n  runs: GithubRun[];\n  updatedAt: string;\n  /** When you last reviewed it, for the list of things waiting on you. '' when you never have. */\n  reviewedAt: string;\n  /** The last comment on it, which is the other clock a person watches. */\n  commentedAt: string;\n}\n\n/** One issue assigned to you, which is the other half of what a person comes to My Work for. */\nexport interface GithubIssue {\n  key: string;\n  number: number;\n  url: string;\n  title: string;\n  repo: string;\n  /** The labels, which is what the harness calls Area. */\n  labels: string[];\n  createdAt: string;\n}\n\n/**\n * One Dependabot advisory, with every alert it raised folded into it.\n *\n * GitHub reports an alert per package per manifest, so one advisory about a transitive\n * dependency arrives three times for a repository with three lockfiles. What a person acts on is\n * the advisory, and how many files it touches is a number on it rather than three rows.\n */\nexport interface GithubAlert {\n  key: string;\n  severity: string;\n  summary: string;\n  ghsa: string;\n  cve: string;\n  packages: string[];\n  url: string;\n  /** How many alerts, and how many distinct manifests they are in. */\n  alerts: number;\n  files: number;\n  /** The version that fixes it, or '' when there is not one yet. */\n  patched: string;\n}\n\nexport interface GithubWork {\n  login: string;\n  /** Waiting on you: review requested, or reviewed by you and still open. */\n  reviewing: GithubPr[];\n  mine: GithubPr[];\n  issues: GithubIssue[];\n}\n\n/**\n * The one query.\n *\n * `latestReviews` rather than a review filtered by author, because filtering needs the login and\n * the login is in the same response: asking for the last few and picking yours out here costs one\n * round trip fewer than asking twice.\n */\nconst QUERY = `\n  fragment pr on PullRequest {\n    number\n    title\n    url\n    isDraft\n    updatedAt\n    repository { nameWithOwner }\n    reviewDecision\n    closingIssuesReferences(first: 1) { nodes { number url } }\n    latestReviews(first: 20) { nodes { author { login } submittedAt } }\n    comments(last: 1) { nodes { createdAt } }\n    commits(last: 1) {\n      nodes {\n        commit {\n          statusCheckRollup {\n            state\n            contexts(first: 100) {\n              totalCount\n              nodes {\n                __typename\n                ... on CheckRun {\n                  conclusion\n                  # The workflow run this check belongs to, which is what a rerun acts on: GitHub\n                  # reruns a run, not a check. The databaseId, because the REST endpoint that does\n                  # it takes a number and a node id is not one.\n                  checkSuite { workflowRun { databaseId url } }\n                }\n                ... on StatusContext { state }\n              }\n            }\n          }\n        }\n      }\n    }\n  }\n\n  query MyWork($page: Int!, $issues: Int!) {\n    viewer { login }\n    reviewing: search(query: \"is:open is:pr review-requested:@me archived:false\", type: ISSUE, first: $page) {\n      nodes { ...pr }\n    }\n    reviewed: search(query: \"is:open is:pr reviewed-by:@me archived:false\", type: ISSUE, first: $page) {\n      nodes { ...pr }\n    }\n    mine: search(query: \"is:open is:pr author:@me archived:false\", type: ISSUE, first: $page) {\n      nodes { ...pr }\n    }\n    issues: search(query: \"is:open is:issue assignee:@me archived:false\", type: ISSUE, first: $issues) {\n      nodes {\n        ... on Issue {\n          number\n          title\n          url\n          createdAt\n          repository { nameWithOwner }\n          labels(first: 10) { nodes { name } }\n        }\n      }\n    }\n  }\n`;\n\ninterface Json { [key: string]: any }\n\n/** The checks on one PR, or null where GitHub has nothing to say about it. */\nfunction checksOf(node: Json): GithubChecks | null {\n  const rollup = node.commits?.nodes?.[0]?.commit?.statusCheckRollup;\n\n  if (!rollup) {\n    return null;\n  }\n\n  const contexts: Json[] = rollup.contexts?.nodes || [];\n  let failing = 0;\n  let pending = 0;\n\n  for (const context of contexts) {\n    // A check run reports a conclusion once it has one; until then it is still running. A status\n    // context has no conclusion and reports a state instead, where PENDING means the same thing.\n    const outcome = context.__typename === 'CheckRun' ? context.conclusion : context.state;\n\n    if (!outcome || outcome === 'PENDING') {\n      pending += 1;\n    } else if (outcome === 'FAILURE' || outcome === 'ERROR' || outcome === 'TIMED_OUT' || outcome === 'CANCELLED') {\n      failing += 1;\n    }\n  }\n\n  return {\n    state: rollup.state || '', failing, pending, total: rollup.contexts?.totalCount || contexts.length\n  };\n}\n\n/**\n * The workflow runs behind a PR's failing checks, deduplicated.\n *\n * One rerun covers every failing job in a run, so a PR with four red jobs in one workflow is one\n * button and not four. A PR whose failures are in two workflows is two runs, and rerunning is\n * both.\n */\nfunction failedRuns(node: Json): GithubRun[] {\n  const contexts: Json[] = node.commits?.nodes?.[0]?.commit?.statusCheckRollup?.contexts?.nodes || [];\n  const runs = new Map<number, GithubRun>();\n\n  for (const context of contexts) {\n    const failed = context.__typename === 'CheckRun' &&\n      ['FAILURE', 'TIMED_OUT', 'CANCELLED', 'STARTUP_FAILURE'].includes(context.conclusion);\n    const run = context.checkSuite?.workflowRun;\n\n    if (failed && run?.databaseId) {\n      runs.set(run.databaseId, { id: run.databaseId, url: run.url });\n    }\n  }\n\n  return [...runs.values()];\n}\n\nfunction prFrom(node: Json, login: string): GithubPr {\n  const repo = node.repository?.nameWithOwner || '';\n  const mine = (node.latestReviews?.nodes || []).find((review: Json) => review.author?.login === login);\n\n  return {\n    key:         `${ repo }#${ node.number }`,\n    number:      node.number,\n    url:         node.url,\n    title:       node.title,\n    repo,\n    draft:       !!node.isDraft,\n    approved:    node.reviewDecision === 'APPROVED',\n    issue:       node.closingIssuesReferences?.nodes?.[0] || null,\n    checks:      checksOf(node),\n    runs:        failedRuns(node),\n    updatedAt:   node.updatedAt || '',\n    reviewedAt:  mine?.submittedAt || '',\n    commentedAt: node.comments?.nodes?.[0]?.createdAt || '',\n  };\n}\n\nfunction issueFrom(node: Json): GithubIssue {\n  const repo = node.repository?.nameWithOwner || '';\n\n  return {\n    key:       `${ repo }#${ node.number }`,\n    number:    node.number,\n    url:       node.url,\n    title:     node.title,\n    repo,\n    labels:    (node.labels?.nodes || []).map((label: Json) => label.name),\n    createdAt: node.createdAt || '',\n  };\n}\n\n/**\n * The open Dependabot alerts on one repository, folded by advisory.\n *\n * REST rather than GraphQL: `vulnerabilityAlerts` on the GraphQL side needs the same permission\n * and returns the same thing in a shape that still has to be folded, and this is one request\n * either way. It is a separate request from the rest of My Work because it is about a repository\n * rather than about a person.\n *\n * A token without access to a repository's security tab gets a 403 here, which is not an error\n * worth stopping the page for: the section says it cannot see them and the rest still renders.\n */\nexport async function dependabotAlerts(repo: string): Promise<GithubAlert[]> {\n  const token = await githubToken();\n\n  if (!token || !repo) {\n    return [];\n  }\n\n  const response = await fetch(`https://api.github.com/repos/${ repo }/dependabot/alerts?state=open&per_page=100`, {\n    headers: { authorization: `Bearer ${ token }`, accept: 'application/vnd.github+json' },\n  });\n\n  if (!response.ok) {\n    throw new Error(response.status === 403\n      ? `The token cannot read ${ repo }'s Dependabot alerts. That needs a token with security_events, and access to that repository's security tab.`\n      : `GitHub answered ${ response.status } for ${ repo }'s Dependabot alerts.`);\n  }\n\n  const alerts: Json[] = await response.json();\n  const byAdvisory = new Map<string, GithubAlert & { manifests: Set<string>; names: Set<string> }>();\n\n  for (const alert of alerts) {\n    const advisory = alert.security_advisory || {};\n    const key = advisory.ghsa_id || String(alert.number);\n    const found = byAdvisory.get(key) || {\n      key,\n      severity: advisory.severity || '',\n      summary:  advisory.summary || '',\n      ghsa:     advisory.ghsa_id || '',\n      cve:      advisory.cve_id || '',\n      packages: [],\n      // The advisory's own page on the repository, which is where a person goes to read it.\n      url:      alert.html_url || '',\n      alerts:   0,\n      files:    0,\n      patched:  alert.security_vulnerability?.first_patched_version?.identifier || '',\n      manifests: new Set<string>(),\n      names:     new Set<string>(),\n    };\n\n    found.alerts += 1;\n    found.manifests.add(alert.dependency?.manifest_path || '');\n    found.names.add(alert.dependency?.package?.name || '');\n    byAdvisory.set(key, found);\n  }\n\n  return [...byAdvisory.values()].map((entry) => ({\n    ...entry,\n    files:    entry.manifests.size,\n    packages: [...entry.names].filter(Boolean),\n  }));\n}\n\n/**\n * Ask GitHub to run the failed jobs again.\n *\n * `rerun-failed-jobs` rather than `rerun`, which is the difference between running the two that\n * went red and running all fifty again. It is a REST call because there is no mutation for it,\n * and it answers 201 with no body.\n */\nexport async function rerunFailed(repo: string, run: GithubRun): Promise<void> {\n  const token = await githubToken();\n  const response = await fetch(`https://api.github.com/repos/${ repo }/actions/runs/${ run.id }/rerun-failed-jobs`, {\n    method:  'POST',\n    headers: { authorization: `Bearer ${ token }`, accept: 'application/vnd.github+json' },\n  });\n\n  if (!response.ok) {\n    const body = await response.json().catch(() => ({}));\n\n    throw new Error(body.message || `GitHub answered ${ response.status }.`);\n  }\n}\n\n/**\n * Both lists, and who you are.\n *\n * The two searches behind `reviewing` are one list to a person: a pull request stops being\n * review-requested the moment you review it, and one you have reviewed and are waiting on is\n * still yours to watch. GitHub has no single query for the union, so it is two and a merge.\n */\nexport async function myWork(): Promise<GithubWork> {\n  const token = await githubToken();\n\n  if (!token) {\n    throw new Error('No GitHub token is set. Add one in Settings.');\n  }\n\n  const response = await fetch(ENDPOINT, {\n    method:  'POST',\n    headers: {\n      authorization:  `Bearer ${ token }`,\n      'content-type': 'application/json',\n    },\n    body: JSON.stringify({ query: QUERY, variables: { page: PAGE, issues: ISSUE_PAGE } }),\n  });\n\n  if (!response.ok) {\n    // 401 is the one worth naming: a token that has expired or been revoked looks exactly like a\n    // token that was never set unless the page says which.\n    throw new Error(response.status === 401\n      ? 'GitHub rejected the token. It may have expired, or it may not have the repo scope.'\n      : `GitHub answered ${ response.status }.`);\n  }\n\n  const body = await response.json();\n\n  // A GraphQL error is a 200 with an errors array, so this is the only place a bad query or a\n  // missing scope surfaces at all.\n  if (body.errors?.length) {\n    throw new Error(body.errors.map((error: Json) => error.message).join(' '));\n  }\n\n  const login = body.data?.viewer?.login || '';\n  const seen = new Set<string>();\n  const reviewing: GithubPr[] = [];\n\n  for (const node of [...(body.data?.reviewing?.nodes || []), ...(body.data?.reviewed?.nodes || [])]) {\n    const pr = prFrom(node, login);\n\n    // The two searches overlap by design. First one wins, which is the review-requested one.\n    if (!seen.has(pr.key)) {\n      seen.add(pr.key);\n      reviewing.push(pr);\n    }\n  }\n\n  return {\n    login,\n    reviewing,\n    mine:   (body.data?.mine?.nodes || []).map((node: Json) => prFrom(node, login)),\n    issues: (body.data?.issues?.nodes || []).map(issueFrom),\n  };\n}\n",
    "pkg/dev-extension/index.ts": "import { defineAsyncComponent } from 'vue';\nimport { importTypes } from '@rancher/auto-import';\nimport { IPlugin } from '@shell/core/types';\nimport routes from './routing';\n\n// Init the package\nexport default function(plugin: IPlugin): void {\n  // Auto-import model, detail, edit from the folders\n  importTypes(plugin);\n\n  // Provide plugin metadata from package.json\n  plugin.metadata = require('./package.json');\n\n  plugin.addRoutes(routes);\n\n  // The product module is passed whole, not its init function: addProduct treats any\n  // argument with a truthy `.name` as the newer metadata API, and a named function has one.\n  plugin.addProduct(require('./product'));\n\n  // The body of a terminal tab in Rancher's window manager, the drawer along the bottom of the\n  // page. The window manager resolves a tab's component by name through this registry whenever\n  // the tab names an extension (see its composables/useComponentsMount.ts), which is why this\n  // is registered rather than imported by whoever opens the tab.\n  //\n  // Async because the drawer is opened rarely and pulls xterm in with it, and because a tab is\n  // resolved when it is opened rather than when the extension loads.\n  plugin.register(\n    'component',\n    'DevTerminalTab',\n    defineAsyncComponent(() => import('./components/DevTerminalTab.vue')) as unknown as Function\n  );\n}\n",
    "pkg/dev-extension/insights-server.ts": "/**\n * The server behind Insights: one SQLite database per person, written by their agents and read\n * by their Insights page.\n *\n * Kept here as text rather than as a file, for the reason the workspace's vue.config.js is (see\n * workspace-config.ts): it has to end up inside a container this code only ever talks to through\n * the Kubernetes API, so it travels as a ConfigMap.\n *\n * It is plain `node:24` and nothing else. Node has had a SQLite driver in core since 22.5\n * (`node:sqlite`), so there is no image to build, no dependency to install and nothing that can\n * be older than this file. That is the same trade every other container in this product makes.\n *\n * The API is the harness's, because the agents that will write to it already know that shape:\n *\n *   POST /api/insights/<table>   a JSON object, one row\n *   GET  /api/tables             every table, with its row count and columns\n *   POST /api/query              { sql } -> { columns, rows }\n *\n * Schema on write. An agent that posts `{\"project\":\"x\",\"tool\":\"jq\"}` to `/api/insights/missing-tool`\n * creates `missing_tools` if it is not there and adds a column for a key it has not seen before.\n * That is what makes it usable from a shell script in a workspace without anyone declaring a\n * schema first, and it is the only way a table like `queued_actions` comes to exist at all.\n */\nexport const INSIGHTS_SERVER = `// Written by the Dev extension. See pkg/dev-extension/insights-server.ts.\nimport http from 'node:http';\nimport { DatabaseSync } from 'node:sqlite';\n\nconst PORT = Number(process.env.PORT || 8080);\nconst FILE = process.env.INSIGHTS_DB || '/data/insights.db';\n\nconst db = new DatabaseSync(FILE);\n\n// Every write is one row and every read is one query, so the durability that matters is \"it is\n// there after the pod restarts\" rather than throughput. WAL is what gives that without the\n// synchronous cost of the default journal.\ndb.exec('PRAGMA journal_mode = WAL');\n\n/**\n * Table and column names, made safe by construction rather than by escaping.\n *\n * These arrive from the body of a POST, so they are the one thing here that a caller controls\n * and that cannot be a bound parameter: SQLite has no placeholder for an identifier. Anything\n * outside this alphabet is replaced, so the worst a caller can do is create a table with a dull\n * name.\n */\nfunction identifier(value, fallback) {\n  const cleaned = String(value || '').toLowerCase().replace(/[^a-z0-9_]/g, '_').replace(/^_+/, '');\n\n  return cleaned || fallback;\n}\n\nfunction tableNames() {\n  return db.prepare(\"SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name\")\n    .all()\n    .map((row) => row.name);\n}\n\nfunction columnsOf(table) {\n  return db.prepare(\\`PRAGMA table_info(\"\\${ table }\")\\`).all().map((row) => row.name);\n}\n\n/**\n * Add the row, and the table and columns it implies.\n *\n * Values are bound; only the names are interpolated, and only after identifier() has been over\n * them. Everything is TEXT apart from the id: a value that arrives as a number today and as a\n * string tomorrow is an ordinary thing for an agent to send, and a column that changes type\n * under it would be an insert that fails for a reason nobody could act on.\n */\nfunction insert(table, row) {\n  const name = identifier(table, 'rows');\n  const keys = Object.keys(row).map((key) => identifier(key, 'value')).filter((key) => key !== 'id');\n\n  if (!tableNames().includes(name)) {\n    db.exec(\\`CREATE TABLE \"\\${ name }\" (id INTEGER PRIMARY KEY AUTOINCREMENT, created_at TEXT NOT NULL)\\`);\n  }\n\n  const existing = columnsOf(name);\n\n  for (const key of keys) {\n    if (!existing.includes(key)) {\n      db.exec(\\`ALTER TABLE \"\\${ name }\" ADD COLUMN \"\\${ key }\" TEXT\\`);\n    }\n  }\n\n  const columns = ['created_at', ...keys];\n  const values = [new Date().toISOString(), ...keys.map((key, i) => {\n    const value = row[Object.keys(row).filter((k) => identifier(k, 'value') !== 'id')[i]];\n\n    // An object or an array is stored as the JSON it came as, rather than as [object Object].\n    return value === null || value === undefined ? null\n      : (typeof value === 'object' ? JSON.stringify(value) : String(value));\n  })];\n\n  const placeholders = columns.map(() => '?').join(', ');\n  const quoted = columns.map((column) => \\`\"\\${ column }\"\\`).join(', ');\n\n  db.prepare(\\`INSERT INTO \"\\${ name }\" (\\${ quoted }) VALUES (\\${ placeholders })\\`).run(...values);\n\n  return { table: name };\n}\n\n/**\n * Run a query, and refuse anything that is not one.\n *\n * The page is a SQL box, so this is the whole of its API, and read-only is not a nicety: the\n * page is the only thing that calls it and it has nothing to write. A statement is allowed if it\n * starts with SELECT or WITH and contains no semicolon, which is what stops a second statement\n * being appended to a first that looked innocent.\n */\nfunction query(sql) {\n  const text = String(sql || '').trim().replace(/;\\\\s*$/, '');\n\n  if (!/^(select|with)\\\\b/i.test(text)) {\n    throw new Error('Only SELECT is allowed here.');\n  }\n\n  if (text.includes(';')) {\n    throw new Error('One statement at a time.');\n  }\n\n  const rows = db.prepare(text).all();\n\n  // The columns of the first row, which is what a table needs to draw a header. A query that\n  // returns nothing has no columns to report, and the page says \"no rows\" rather than drawing an\n  // empty table with no headings.\n  return { columns: rows.length ? Object.keys(rows[0]) : [], rows };\n}\n\nfunction send(res, status, body) {\n  const text = JSON.stringify(body);\n\n  res.writeHead(status, {\n    'content-type':                 'application/json',\n    'content-length':               Buffer.byteLength(text),\n    // The page is served from Rancher's origin and this is reached through the apiserver's\n    // service proxy, so it is same-origin by the time a browser sees it. This is for the agents,\n    // which are curl and do not care, and for anyone driving it from somewhere else.\n    'access-control-allow-origin':  '*',\n    'access-control-allow-headers': 'content-type',\n    'access-control-allow-methods': 'GET, POST, OPTIONS',\n  });\n  res.end(text);\n}\n\nfunction readBody(req) {\n  return new Promise((resolve, reject) => {\n    let body = '';\n\n    req.on('data', (chunk) => {\n      body += chunk;\n\n      // A row is a handful of fields. Anything past this is a mistake or an attempt, and either\n      // way it is not something to buffer.\n      if (body.length > 1_000_000) {\n        reject(new Error('That is too big to be a row.'));\n      }\n    });\n    req.on('end', () => {\n      try {\n        resolve(body ? JSON.parse(body) : {});\n      } catch {\n        reject(new Error('The body is not JSON.'));\n      }\n    });\n    req.on('error', reject);\n  });\n}\n\nhttp.createServer(async(req, res) => {\n  const url = new URL(req.url, 'http://insights');\n\n  try {\n    if (req.method === 'OPTIONS') {\n      return send(res, 204, {});\n    }\n\n    if (req.method === 'GET' && url.pathname === '/api/tables') {\n      return send(res, 200, {\n        tables: tableNames().map((name) => ({\n          name,\n          columns: columnsOf(name),\n          rows:    db.prepare(\\`SELECT COUNT(*) AS n FROM \"\\${ name }\"\\`).get().n,\n        })),\n      });\n    }\n\n    if (req.method === 'POST' && url.pathname === '/api/query') {\n      const body = await readBody(req);\n\n      return send(res, 200, query(body.sql));\n    }\n\n    if (req.method === 'POST' && url.pathname.startsWith('/api/insights/')) {\n      const body = await readBody(req);\n      // The harness posts to /api/insights/missing-tool and the table is missing_tools. The\n      // pluralisation is the harness's own and it is kept, so a script written against one works\n      // against the other.\n      const singular = url.pathname.slice('/api/insights/'.length);\n      const table = singular.endsWith('s') ? singular : \\`\\${ singular }s\\`;\n\n      return send(res, 200, insert(table, body));\n    }\n\n    // A liveness answer that is also the one-line description of what this is, for whoever\n    // opens the address in a browser expecting a page.\n    if (req.method === 'GET' && url.pathname === '/') {\n      return send(res, 200, { insights: 'ok', file: FILE, tables: tableNames() });\n    }\n\n    return send(res, 404, { error: 'No such path.' });\n  } catch (e) {\n    return send(res, 400, { error: e.message });\n  }\n}).listen(PORT, () => {\n  // eslint-disable-next-line no-console\n  console.log(\\`[insights] \\${ FILE } on :\\${ PORT }\\`);\n});\n`;\n",
    "pkg/dev-extension/models/configmap.js": "import ConfigMap from '@shell/models/configmap';\n\n// Extend the shell ConfigMap model rather than replace it: extension models override by key,\n// so a bare class here would drop keysDisplay / fullDetailPageOverride. The `doof` getter backs\n// the hardcoded 'Floof' column, which references it by value path ('doof').\nexport default class DevConfigMap extends ConfigMap {\n  get doof() {\n    return 'doof';\n  }\n}\n",
    "pkg/dev-extension/models/secret.js": "import Secret from '@shell/models/secret';\n\n/**\n * DevExtension's override of the shell's Secret model.\n *\n * `importTypes()` registers everything under `models/` by filename, and an extension's model\n * wins over the shell's of the same name - so this class is what every `secret` resource in\n * the dashboard is instantiated as while the dev loop is on.\n *\n * Right now it is a pure clone: it extends the shell's model and changes nothing, so\n * behaviour is identical and this is only a seam. Add overrides here - a getter, a different\n * `details`, an extra action - and they take effect on the running instance without touching\n * the shell's own copy.\n *\n * Overriding rather than editing `@rancher/shell/models/secret.js` in place matters: the\n * shell copy is a node_modules file, so an edit there is invisible to anyone reading this\n * repo and is lost the moment the pod's tree is rebuilt from the seed.\n */\nexport default class DevSecret extends Secret {}\n",
    "pkg/dev-extension/package.json": "{\n  \"name\": \"dev-extension\",\n  \"description\": \"dev-extension plugin\",\n  \"version\": \"0.1.0\",\n  \"private\": false,\n  \"rancher\": {\n    \"annotations\": {\n      \"catalog.cattle.io/rancher-version\": \">= 2.10.0\",\n      \"catalog.cattle.io/ui-extensions-version\": \">= 3.0.0 < 4.0.0\"\n    }\n  },\n  \"scripts\": {},\n  \"engines\": {\n    \"node\": \">=24\"\n  },\n  \"devDependencies\": {\n    \"@vue/cli-plugin-babel\": \"5.0.9\",\n    \"@vue/cli-service\": \"5.0.8\",\n    \"@vue/cli-plugin-typescript\": \"5.0.9\"\n  },\n  \"browserslist\": [\n    \"> 1%\",\n    \"last 2 versions\",\n    \"not dead\"\n  ]\n}",
    "pkg/dev-extension/pages/CreateWorkspace.vue": "<script>\n// Create a workspace: a name and a template, which is exactly what the harness asks for.\n//\n// Not CruResource, which is the shell's form chrome for editing one Steve resource: a\n// workspace is three of them created together and there is no model to hand it. The inputs,\n// the banner and the buttons are still the shell's.\nimport AsyncButton from '@shell/components/AsyncButton';\nimport LabeledSelect from '@shell/components/form/LabeledSelect';\nimport { LabeledInput } from '@components/Form/LabeledInput';\nimport { Banner } from '@components/Banner';\nimport { RcButton } from '@components/RcButton';\nimport {\n  createWorkspace, workspaceNameError, workspaceNamespace, listClusters, readableBytes\n} from '../api';\nimport { TEMPLATES, templateById } from '../templates';\nimport {\n  DEV_PRODUCT, BLANK_CLUSTER, WORKSPACES_ROUTE, WORKSPACE_ROUTE\n} from '../config/constants';\n\nexport default {\n  name: 'DevCreateWorkspace',\n\n  components: {\n    AsyncButton, LabeledSelect, LabeledInput, Banner, RcButton\n  },\n\n  async fetch() {\n    this.clusters = await listClusters().catch(() => []);\n\n    // The one Rancher itself runs in, where a workspace has always gone, unless it is not on the\n    // list: a person with access to one downstream cluster and not to local should not have a\n    // form that opens on a cluster they cannot use.\n    // The sidebar links here with a cluster already chosen, the way the Templates page links\n    // here with a template. An unknown one falls back rather than leaving the form pointed at a\n    // cluster that is not on the list.\n    const asked = this.$route.query.cluster;\n    const known = (id) => this.clusters.some((entry) => entry.id === id) && id;\n\n    this.cluster = known(asked) || known('local') || this.clusters[0]?.id || 'local';\n  },\n\n  data() {\n    // The Templates page links here with a template already chosen; an unknown one in the\n    // query falls back rather than leaving the select empty and the form unsubmittable.\n    const asked = this.$route.query.template;\n\n    return {\n      name:     '',\n      // The clusters a workspace could be hosted on, and the one it will be.\n      clusters: [],\n      cluster:  'local',\n      template: templateById(asked)?.id || TEMPLATES[0].id,\n      error:    '',\n      // The name is only complained about once it has been typed in and left alone, so the\n      // form does not tell someone their first keystroke is invalid.\n      touched:  false,\n      options:  TEMPLATES.map((template) => ({ label: template.label, value: template.id })),\n      cancelTo: { name: WORKSPACES_ROUTE, params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER } },\n    };\n  },\n\n  computed: {\n    /**\n     * The clusters, each with what is left on it, which is what the select shows.\n     *\n     * MEM and DSK rather than the words: the label sits in a select a third of a form wide, and\n     * a cluster whose numbers are truncated is a cluster you cannot choose between.\n     */\n    clusterOptions() {\n      return this.clusters.map((entry) => ({\n        value: entry.id,\n        label: `${ entry.name } (MEM ${ readableBytes(entry.memoryFree) }, DSK ${ readableBytes(entry.diskFree) })`,\n      }));\n    },\n\n    nameError() {\n      return workspaceNameError(this.name);\n    },\n\n    shownNameError() {\n      return this.touched ? this.nameError : '';\n    },\n\n    selected() {\n      return templateById(this.template);\n    },\n\n    namespace() {\n      return this.nameError ? '' : workspaceNamespace(this.name);\n    },\n  },\n\n  watch: {\n    // The error is about the name that was submitted, so editing the name is what ends it.\n    // Left standing it would go on hiding the banner that says what the new name would make,\n    // until the next press of Create.\n    name() {\n      this.error = '';\n    },\n  },\n\n  methods: {\n    async create(done) {\n      this.touched = true;\n      this.error = '';\n\n      if (this.nameError) {\n        done(false);\n\n        return;\n      }\n\n      try {\n        await createWorkspace(this.name, this.template, this.cluster);\n        // Straight to the workspace rather than back to the list: the thing worth watching\n        // next is the pod coming up, and that is on the detail page.\n        this.$router.push({\n          name:   WORKSPACE_ROUTE,\n          params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER, workspace: this.name },\n        });\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n  },\n};\n</script>\n\n<template>\n  <div class=\"dev-create\">\n    <header>\n      <h1>Create Workspace</h1>\n    </header>\n\n    <Banner\n      v-if=\"error\"\n      color=\"error\"\n      :label=\"error\"\n    />\n\n    <div class=\"dev-create__form\">\n      <LabeledInput\n        v-model:value=\"name\"\n        label=\"Workspace name\"\n        :required=\"true\"\n        placeholder=\"my-workspace\"\n        @blur=\"touched = true\"\n      />\n      <LabeledSelect\n        v-model:value=\"template\"\n        label=\"Template\"\n        :options=\"options\"\n        :clearable=\"false\"\n      />\n      <!--\n        Which cluster hosts it. The free memory and disk are beside each name because that is the\n        question somebody is actually answering: not which cluster, but which one has room for a\n        checkout, an install and a compile.\n      -->\n      <LabeledSelect\n        v-model:value=\"cluster\"\n        label=\"Cluster\"\n        :options=\"clusterOptions\"\n        option-label=\"label\"\n        option-key=\"value\"\n        :reduce=\"(entry) => entry.value\"\n        :clearable=\"false\"\n      />\n    </div>\n\n    <Banner\n      v-if=\"shownNameError\"\n      color=\"error\"\n      :label=\"shownNameError\"\n    />\n    <!--\n      Not while a create has failed. This banner says what the name would make and the error\n      above says why it did not, so on a name that is taken the page reads \"a workspace called\n      delta already exists\" and \"creates the namespace dev-delta\" at the same time.\n    -->\n    <Banner\n      v-else-if=\"namespace && !error\"\n      color=\"info\"\n      :label=\"`Creates the namespace ${ namespace } on ${ cluster }, running ${ selected.image }.`\"\n    />\n\n\n    <div class=\"dev-create__actions\">\n      <RcButton\n        variant=\"secondary\"\n        :to=\"cancelTo\"\n      >\n        Cancel\n      </RcButton>\n      <AsyncButton\n        mode=\"create\"\n        :disabled=\"!name\"\n        @click=\"create\"\n      />\n    </div>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-create {\n    // The product's pages have no padding of their own: the shell's blank template hands the\n    // router-view the whole pane so that a terminal and a browser frame can fill it. A form is\n    // not one of those, so it puts its own back, the same 20px the other pages use.\n    overflow-y: auto;\n    padding:    var(--dev-space-5);\n    max-width:  760px;\n\n    header {\n      display:       block;\n      margin-bottom: var(--dev-space-5);\n\n      h1 {\n        margin-bottom: 0;\n      }\n\n      .subheader {\n        margin: var(--dev-space-2) 0 0 0;\n        color:  var(--muted);\n      }\n    }\n\n    // Three across on a wide window and one on a narrow one, rather than a fixed pair: the\n    // cluster's label carries two numbers and does not fit in half of what the name gets.\n    &__form {\n      display:               grid;\n      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n      gap:                   var(--dev-space-5);\n      margin-bottom:         var(--dev-space-5);\n    }\n\n    &__description {\n      max-width: 80ch;\n      color:     var(--muted);\n    }\n\n    &__actions {\n      display:         flex;\n      gap:             var(--dev-space-4);\n      justify-content: flex-end;\n      margin-top:      var(--dev-space-5);\n    }\n  }\n</style>\n",
    "pkg/dev-extension/pages/DevHome.vue": "<script>\nexport default {\n  name: 'DevHome',\n\n  data() {\n    return {\n      // Edit this string and it should change in the running Rancher without a reload.\n      headline: 'DevExtension is live',\n      loadedAt: new Date().toLocaleTimeString()\n    };\n  }\n};\n</script>\n\n<template>\n  <div class=\"dev-home\">\n    <h1>{{ headline }}</h1>\n    <p class=\"subtitle\">\n      This page is served by the DevExtension dev server, through the k8s proxy,\n      into the Rancher instance you are looking at.\n    </p>\n    <div class=\"marker\">\n      component first rendered at {{ loadedAt }}\n    </div>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-home {\n    padding: 20px;\n\n    h1 {\n      color: var(--primary);\n    }\n\n    .subtitle {\n      max-width: 60ch;\n      margin-bottom: 20px;\n    }\n\n    .marker {\n      display: inline-block;\n      padding: 8px 12px;\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      font-family: monospace;\n    }\n  }\n</style>\n",
    "pkg/dev-extension/pages/DevShell.vue": "<script>\n// The Dev product's own page template: the sidebar, and whatever page is open beside it.\n//\n// A template of this product's own rather than one of the shell's, because none of the shell's\n// fits. `default` renders Rancher's own side nav, which is the thing being replaced, and that\n// nav cannot draw a workspace row (see components/DevSidebar.vue). `plain` has no side nav but\n// wraps its page in an IndentedPanel, which is 90% wide and centred, and the two panes this\n// product is mostly used through are a terminal and an iframe that want the window.\n//\n// What it is not is a new layout. It is the shell's own: the same `dashboard-root` and\n// `dashboard-content` grid every Rancher page is laid out by, with the sidebar in the grid's\n// `nav` area, the page in `main`, and the terminal drawer in `wm`. So the header height, the\n// nav width, the drawer's resizing and the offset for the app bar are Rancher's numbers rather\n// than numbers picked here, and they follow it when it changes.\n//\n// What it costs against `default`, since it is a trade rather than a detail: Rancher's side nav\n// is gone, which is the point, and Header runs in `simple` mode, which drops the product title\n// block at the top left. The product switcher, the notifications, the user menu and this\n// extension's own Dev button are all in the part of the header that stays.\nimport { mapGetters } from 'vuex';\nimport Header from '@shell/components/nav/Header';\nimport WindowManager from '@shell/components/nav/WindowManager';\nimport ActionMenu from '@shell/components/ActionMenu';\nimport PromptRemove from '@shell/components/PromptRemove';\nimport ModalManager from '@shell/components/ModalManager';\nimport DevSidebar from '../components/DevSidebar.vue';\n\nexport default {\n  name: 'DevShell',\n\n  components: {\n    Header, WindowManager, ActionMenu, PromptRemove, ModalManager, DevSidebar\n  },\n\n  computed: {\n    // The shell's own app bar is fixed to the left edge and is not part of the grid, so the\n    // grid is padded out of its way. Same getter, same class, same width as every other page.\n    ...mapGetters(['showTopLevelMenu']),\n  },\n};\n</script>\n\n<template>\n  <div class=\"dashboard-root\">\n    <div\n      class=\"dashboard-content\"\n      :class=\"{ 'dashboard-padding-left': showTopLevelMenu }\"\n    >\n      <Header :simple=\"true\" />\n      <DevSidebar class=\"default-side-nav\" />\n      <main class=\"main-layout\">\n        <router-view />\n      </main>\n      <!--\n        The terminal drawer. `default` rather than a layout of this template's own, because a\n        tab declares which layouts it may appear in and every tab this product opens claims all\n        of them (see terminals.ts).\n      -->\n      <WindowManager layout=\"default\" />\n      <ActionMenu />\n      <PromptRemove />\n      <ModalManager />\n    </div>\n  </div>\n</template>\n",
    "pkg/dev-extension/pages/Floof.vue": "<script>\nimport Loading from '@shell/components/Loading';\nimport ResourceTable from '@shell/components/ResourceTable';\nimport { CONFIG_MAP } from '@shell/config/types';\n\n/**\n * An extension page inside Rancher's own Cluster Explorer.\n *\n * Two things make it a real explorer page rather than a page that merely looks like one:\n * the route is registered under the explorer's `c-cluster-` parent so the cluster nav and\n * switcher stay in place, and the rows come from the Steve `cluster` store, so ResourceTable\n * gets the same schema-driven columns, sorting, grouping and live updates it gives any\n * built-in list.\n */\nexport default {\n  // Two words to satisfy vue/multi-word-component-names, which exists so a component can\n  // never collide with a current or future HTML element. The page is still \"Floof\".\n  name: 'FloofPage',\n\n  components: { Loading, ResourceTable },\n\n  async fetch() {\n    // The schema comes back with the resource, and ResourceTable needs it to build columns -\n    // without it the table renders but has nothing to put in the header row.\n    this.rows = await this.$store.dispatch('cluster/findAll', { type: CONFIG_MAP });\n  },\n\n  data() {\n    return { rows: [] };\n  },\n\n  computed: {\n    schema() {\n      return this.$store.getters['cluster/schemaFor'](CONFIG_MAP);\n    }\n  }\n};\n</script>\n\n<template>\n  <Loading v-if=\"$fetchState.pending\" />\n  <div\n    v-else\n    class=\"floof\"\n  >\n    <header>\n      <h1>Floof</h1>\n      <p class=\"subheader\">\n        doof\n      </p>\n    </header>\n\n    <ResourceTable\n      :schema=\"schema\"\n      :rows=\"rows\"\n      :headers=\"schema ? null : []\"\n    />\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .floof {\n    header {\n      // The shell styles `header` as a flex row (it is the masthead pattern on every list\n      // page), which puts the subheader out to the right of the title instead of under it.\n      // Overridden rather than renamed so the element stays semantically the page header.\n      display:        block;\n      margin-bottom:  20px;\n\n      h1 {\n        margin-bottom: 0;\n      }\n\n      .subheader {\n        margin:  0;\n        opacity: 0.7;\n      }\n    }\n  }\n</style>\n",
    "pkg/dev-extension/pages/Insights.vue": "<script>\n// Insights: what this person's agents have recorded, and a box to ask about it.\n//\n// It is one SQLite database per person rather than one per workspace, because the question it\n// answers spans them: what have my agents been running into. It lives in dev-system beside the\n// secret store, is created the first time this page is opened, and is written to over HTTP by\n// anything in a workspace - `INSIGHTS_URL` is set on every workspace's pod, which is the same\n// name the harness's own agents post to.\n//\n// Schema on write, so there is nothing to declare. An agent that posts a JSON object to\n// `/api/insights/missing-tool` creates the table and the columns it implies, which is what lets a\n// shell script in a conversation record something nobody planned for. See insights-server.ts.\n//\n// The query box is SELECT only, and that is enforced in the pod rather than here: a page can be\n// edited from the console, and the thing holding the database is the only place a rule about it\n// can actually hold.\nimport SortableTable from '@shell/components/SortableTable';\nimport { Banner } from '@components/Banner';\nimport { RcButton } from '@components/RcButton';\nimport {\n  ensureInsights, insightsTables, insightsQuery, insightsServiceUrl\n} from '../api';\n\n/** How long to wait for a database that has just been created to start answering. */\nconst READY_TRIES = 20;\nconst READY_MS = 3000;\n\nexport default {\n  name: 'DevInsights',\n\n  components: { SortableTable, Banner, RcButton },\n\n  async fetch() {\n    await this.start();\n  },\n\n  data() {\n    return {\n      tables:  [],\n      table:   '',\n      sql:     '',\n      columns: [],\n      rows:    [],\n      error:   '',\n      /** Where a workspace posts to, which is the one thing this page tells rather than asks. */\n      address: '',\n      /** True while the database is being created, which is a pull and a start. */\n      starting: false,\n      running:  false,\n    };\n  },\n\n  computed: {\n    /**\n     * The table's columns, as SortableTable wants them.\n     *\n     * Built from the result rather than declared, because the whole point of the page is that the\n     * shape is whatever was asked for. Everything is a string by the time it is here (see the\n     * server: only the id is not TEXT), so there is nothing to format.\n     */\n    headers() {\n      return this.columns.map((name) => ({\n        name, label: name, value: name, sort: [name],\n      }));\n    },\n  },\n\n  beforeUnmount() {\n    this.stopped = true;\n  },\n\n  methods: {\n    /**\n     * Make sure there is a database, then read what is in it.\n     *\n     * The first visit creates a Deployment and waits for an image pull, so this polls rather than\n     * asking once and reporting that nothing is answering. Later visits find it running and the\n     * first ask succeeds.\n     */\n    async start() {\n      this.error = '';\n      this.address = await insightsServiceUrl().catch(() => '');\n\n      await ensureInsights().catch(() => {});\n\n      for (let attempt = 0; attempt < READY_TRIES && !this.stopped; attempt++) {\n        try {\n          this.tables = await insightsTables();\n          this.running = true;\n          this.starting = false;\n\n          if (this.tables.length) {\n            await this.open(this.tables[0].name);\n          }\n\n          return;\n        } catch (e) {\n          this.starting = true;\n          this.error = e.message || String(e);\n          await new Promise((resolve) => setTimeout(resolve, READY_MS));\n        }\n      }\n\n      this.starting = false;\n    },\n\n    /** A tab: the table's own rows, most recent first, which is the order they are written in. */\n    open(name) {\n      this.table = name;\n      this.sql = `SELECT * FROM ${ name } ORDER BY id DESC LIMIT 200`;\n\n      return this.run();\n    },\n\n    async run() {\n      this.error = '';\n\n      try {\n        const result = await insightsQuery(this.sql);\n\n        this.columns = result.columns;\n        this.rows = (result.rows || []).map((row, i) => ({ ...row, _key: row.id ?? i }));\n\n        // The counts move as rows are added, and running a query is the moment this page is\n        // being looked at, so it is the moment to ask again.\n        this.tables = await insightsTables().catch(() => this.tables);\n      } catch (e) {\n        this.columns = [];\n        this.rows = [];\n        this.error = e.message || String(e);\n      }\n    },\n  },\n};\n</script>\n\n<template>\n  <div class=\"dev-insights\">\n    <header>\n      <h1>Insights</h1>\n      <p class=\"subheader\">\n        What your agents have recorded, across every workspace you have.\n      </p>\n      <RcButton\n        variant=\"tertiary\"\n        size=\"small\"\n        left-icon=\"refresh\"\n        @click=\"run\"\n      >\n        Run\n      </RcButton>\n    </header>\n\n    <Banner\n      v-if=\"starting\"\n      color=\"info\"\n      label=\"Starting the insights database. The first time is an image pull, so it is a minute or two.\"\n    />\n    <Banner\n      v-else-if=\"error\"\n      color=\"warning\"\n      :label=\"error\"\n    />\n\n    <label class=\"dev-insights__label\">SQL query</label>\n    <textarea\n      v-model=\"sql\"\n      class=\"dev-insights__sql\"\n      rows=\"3\"\n      spellcheck=\"false\"\n      @keydown.ctrl.enter=\"run\"\n      @keydown.meta.enter=\"run\"\n    />\n\n    <!--\n      A tab per table, with its row count, which is the harness's own shape. They come from the\n      database rather than from a list here, because nothing declares them: a table exists because\n      something posted to it.\n    -->\n    <div class=\"dev-insights__tables\">\n      <button\n        v-for=\"entry in tables\"\n        :key=\"entry.name\"\n        type=\"button\"\n        class=\"dev-insights__table\"\n        :class=\"{ 'dev-insights__table--current': entry.name === table }\"\n        @click=\"open(entry.name)\"\n      >\n        {{ entry.name }}\n        <span class=\"dev-insights__rows\">{{ entry.rows }}</span>\n      </button>\n      <span\n        v-if=\"running && !tables.length\"\n        class=\"dev-insights__empty\"\n      >\n        Nothing has been recorded yet.\n      </span>\n    </div>\n\n    <SortableTable\n      v-if=\"columns.length\"\n      :headers=\"headers\"\n      :rows=\"rows\"\n      key-field=\"_key\"\n      :table-actions=\"false\"\n      :row-actions=\"false\"\n      :search=\"false\"\n      :rows-per-page=\"50\"\n    />\n    <p\n      v-else-if=\"running && !error\"\n      class=\"dev-insights__empty\"\n    >\n      That query returned no rows.\n    </p>\n\n    <!--\n      The address, because the page is only half of this: the other half is an agent posting to\n      it, and an agent cannot be told where to post from a page it never sees. It is on every\n      workspace's pod as INSIGHTS_URL, so this is the copy for a person writing the command.\n    -->\n    <p\n      v-if=\"address\"\n      class=\"dev-insights__note\"\n    >\n      Anything in a workspace can record something here, and every workspace has this address as\n      <b>INSIGHTS_URL</b>:\n      <code>curl -s -X POST $INSIGHTS_URL/api/insights/missing-tool -H 'content-type: application/json' -d '{\"tool\":\"jq\",\"project\":\"expo\"}'</code>\n      The table and its columns are made by the first row that needs them, so there is nothing to\n      declare first. Reading is SELECT only.\n    </p>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-insights {\n    overflow-y: auto;\n    padding:    var(--dev-space-5);\n\n    header {\n      display:       flex;\n      align-items:   center;\n      gap:           var(--dev-space-4);\n      margin-bottom: var(--dev-space-5);\n\n      h1 {\n        margin-bottom: 0;\n      }\n\n      .subheader {\n        flex:   1 1 auto;\n        margin: 0;\n        color:  var(--muted);\n      }\n    }\n\n    &__label {\n      display:        block;\n      margin-bottom:  var(--dev-space-2);\n      color:          var(--muted);\n      font-size:      12px;\n      letter-spacing: 0.05em;\n      text-transform: uppercase;\n    }\n\n    // Monospace and full width: what goes in here is SQL, and it wraps rather than scrolling\n    // sideways because a query is read as a whole.\n    &__sql {\n      display:       block;\n      width:         100%;\n      padding:       var(--dev-space-3) var(--dev-space-4);\n      border:        1px solid var(--border);\n      border-radius: var(--border-radius);\n      background:    var(--body-bg);\n      color:         var(--body-text);\n      font-family:   monospace;\n      font-size:     13px;\n      resize:        vertical;\n    }\n\n    &__tables {\n      display:   flex;\n      flex-wrap: wrap;\n      gap:       var(--dev-space-3);\n      margin:    var(--dev-space-4) 0;\n    }\n\n    // A tab, not a button: quiet until it is the current one, which is the only state worth\n    // drawing attention to.\n    &__table {\n      display:       flex;\n      align-items:   center;\n      gap:           var(--dev-space-3);\n      min-height:    0;\n      padding:       var(--dev-space-2) var(--dev-space-4);\n      border:        1px solid var(--border);\n      border-radius: var(--border-radius);\n      background:    transparent;\n      color:         var(--body-text);\n      font-family:   monospace;\n      font-size:     12px;\n      cursor:        pointer;\n\n      &:hover {\n        background: var(--nav-hover, var(--accent-btn));\n      }\n\n      &--current {\n        border-color: var(--primary);\n        font-weight:  600;\n      }\n    }\n\n    &__rows {\n      color:     var(--muted);\n      font-size: 11px;\n    }\n\n    &__empty {\n      color:     var(--muted);\n      font-size: 12px;\n    }\n\n    &__note {\n      max-width:  100ch;\n      margin-top: var(--dev-space-5);\n      color:      var(--muted);\n      font-size:  12px;\n\n      code {\n        display:     block;\n        overflow-x:  auto;\n        margin:      var(--dev-space-3) 0;\n        padding:     var(--dev-space-3) var(--dev-space-4);\n        border:      1px solid var(--border);\n        border-radius: var(--border-radius);\n        font-size:   11px;\n        white-space: pre;\n      }\n    }\n  }\n</style>\n",
    "pkg/dev-extension/pages/MyWork.vue": "<script>\n// My Work: the harness's landing page, and the first thing a person looks for.\n//\n// Two lists, in the order the harness has them: what is waiting on you, then what you wrote.\n// Both come from one GraphQL request made by this page (see github.ts) rather than from a pod,\n// so the token is only ever in the browser of the person it belongs to.\n//\n// The token comes from the same secret store Settings writes, which is per-user: two people\n// looking at this page are looking at their own work, without either of them configuring\n// anything here.\nimport SortableTable from '@shell/components/SortableTable';\nimport { Banner } from '@components/Banner';\nimport { RcButton } from '@components/RcButton';\nimport AsyncButton from '@shell/components/AsyncButton';\nimport { myWork, rerunFailed, dependabotAlerts } from '../github';\nimport {\n  listAllWorkspaces, createWorkspace, queueConversation, listPrompts, getWorkspace\n} from '../api';\nimport { TEMPLATES } from '../templates';\nimport { fillPrompt } from '../prompts';\nimport {\n  DEV_PRODUCT, BLANK_CLUSTER, SETTINGS_ROUTE, WORKSPACE_ROUTE, CREATE_ROUTE\n} from '../config/constants';\n\n/** Columns shared by both tables, since the two differ only at their right-hand end. */\nfunction columns(extra) {\n  return [\n    {\n      name: 'state', label: 'State', value: 'draft', width: 90\n    },\n    {\n      name: 'approved', label: 'Approved', value: 'approved', width: 90\n    },\n    {\n      name: 'pr', label: 'PR', value: 'number', sort: ['number'], width: 90\n    },\n    // Which repository, because a PR number on its own does not say: these lists span every\n    // repository a person touches, and `#2` and `#18777` are both perfectly ordinary.\n    {\n      name: 'repo', label: 'Repo', value: 'repo', sort: ['repo'], width: 130\n    },\n    {\n      name: 'issue', label: 'Issue', value: 'issue.number', width: 90\n    },\n    { name: 'title', label: 'Title', value: 'title' },\n    {\n      name: 'ci', label: 'CI', value: 'checks.state', width: 190\n    },\n    ...extra,\n    // The workspace for this pull request, which is the harness's Project column under the name\n    // this product uses for the same thing.\n    {\n      name: 'workspace', label: 'Workspace', value: 'key', width: 130\n    },\n    {\n      name: 'actions', label: 'Actions', align: 'right', width: 100\n    },\n  ];\n}\n\nexport default {\n  name: 'DevMyWork',\n\n  components: {\n    SortableTable, Banner, RcButton, AsyncButton\n  },\n\n  async fetch() {\n    await this.refresh();\n  },\n\n  data() {\n    return {\n      work:       null,\n      error:      '',\n      // The workspaces that exist, so a row can say whether it already has one. Names only:\n      // this page is about pull requests and the sidebar is about workspaces.\n      workspaces: [],\n      // This person's own prompts, which is what a queued conversation opens on.\n      prompts:    [],\n      // The repository's open Dependabot advisories, and why they could not be read when they\n      // could not be. A token without the security tab is an ordinary thing, not a page error.\n      alerts:     [],\n      alertError: '',\n      issueHeaders: [\n        {\n          name: 'number', label: 'Issue', value: 'number', width: 90\n        },\n        { name: 'title', label: 'Title', value: 'title' },\n        {\n          name: 'repo', label: 'Repo', value: 'repo', sort: ['repo'], width: 130\n        },\n        // What the harness calls Area: the issue's own labels, which is how this team says which\n        // part of the product something is about.\n        {\n          name: 'area', label: 'Area', value: 'labels', width: 220\n        },\n        {\n          name: 'age', label: 'Age', value: 'createdAt', sort: ['createdAt'], width: 90\n        },\n        {\n          name: 'workspace', label: 'Workspace', value: 'key', width: 130\n        },\n        {\n          name: 'actions', label: 'Actions', align: 'right', width: 110\n        },\n      ],\n      alertHeaders: [\n        {\n          name: 'severity', label: 'Severity', value: 'severity', sort: ['severity'], width: 100\n        },\n        { name: 'advisory', label: 'Advisory', value: 'summary' },\n        {\n          name: 'package', label: 'Package', value: 'packages', width: 160\n        },\n        {\n          name: 'alerts', label: 'Alerts', value: 'alerts', width: 120\n        },\n        {\n          name: 'fix', label: 'Fix', value: 'patched', width: 140\n        },\n        {\n          name: 'actions', label: 'Action', align: 'right', width: 110\n        },\n      ],\n      settingsTo: { name: SETTINGS_ROUTE, params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER } },\n      // The two tables' own last columns: when you last reviewed something that is waiting on\n      // you, and when anyone last said anything on something you wrote.\n      reviewHeaders: columns([\n        {\n          name: 'reviewed', label: 'My last review', value: 'reviewedAt', width: 130\n        },\n        {\n          name: 'updated', label: 'Updated', value: 'updatedAt', sort: ['updatedAt:desc'], width: 110\n        },\n      ]),\n      mineHeaders: columns([\n        {\n          name: 'updated', label: 'Last update', value: 'updatedAt', sort: ['updatedAt:desc'], width: 110\n        },\n        {\n          name: 'commented', label: 'Last comment', value: 'commentedAt', width: 120\n        },\n      ]),\n    };\n  },\n\n  computed: {\n    /** The repository this product's workspaces work on, from the template that clones it. */\n    repo() {\n      return TEMPLATES.find((template) => !!template.repo)?.repo || '';\n    },\n\n    /**\n     * What is waiting on you, most urgent first.\n     *\n     * The default sort was \"updated\", which is activity rather than need: a pull request somebody\n     * pushed to a minute ago is at the top whether or not it wants anything from you. This orders\n     * by what a reviewer actually decides between:\n     *\n     *   1. never reviewed, because it is the only state where nothing has happened at all;\n     *   2. not approved before approved, since an approved one is off your desk;\n     *   3. green CI before red, because a review of a branch that does not build is a review that\n     *      will be asked for again;\n     *   4. oldest first inside all of that, so the one that has been waiting longest wins.\n     */\n    reviewing() {\n      return [...(this.work?.reviewing || [])].sort((a, b) => (\n        Number(!!a.reviewedAt) - Number(!!b.reviewedAt) ||\n        Number(a.approved) - Number(b.approved) ||\n        Number(!!a.checks?.failing) - Number(!!b.checks?.failing) ||\n        Date.parse(a.updatedAt || 0) - Date.parse(b.updatedAt || 0)\n      ));\n    },\n\n    /**\n     * Your own, most urgent first.\n     *\n     * The other way round from the list above, because what these want from you is work rather\n     * than judgement: something red is something to fix, and something nobody has commented on\n     * is something to chase. Approved and green is the bottom of the list, which is where a pull\n     * request that only needs merging belongs.\n     */\n    mine() {\n      return [...(this.work?.mine || [])].sort((a, b) => (\n        Number(!!b.checks?.failing) - Number(!!a.checks?.failing) ||\n        Number(a.approved) - Number(b.approved) ||\n        Number(a.draft) - Number(b.draft) ||\n        Date.parse(a.updatedAt || 0) - Date.parse(b.updatedAt || 0)\n      ));\n    },\n\n    /**\n     * The repositories the two lists span, for the subtitle.\n     *\n     * Capped, because this is a line under a heading rather than a list: someone who reviews\n     * widely has a dozen of them and the page's own title ends up on the second line.\n     */\n    repos() {\n      const all = [...(this.work?.reviewing || []), ...(this.work?.mine || [])].map((pr) => pr.repo);\n      const unique = [...new Set(all)];\n      const shown = unique.slice(0, 3).join(', ');\n\n      return unique.length > 3 ? `${ shown } and ${ unique.length - 3 } more` : shown;\n    },\n  },\n\n  methods: {\n    async refresh() {\n      this.error = '';\n\n      try {\n        const [work, workspaces, prompts] = await Promise.all([\n          myWork(),\n          listAllWorkspaces().catch(() => []),\n          listPrompts().catch(() => []),\n        ]);\n\n        this.work = work;\n        this.workspaces = workspaces.map((workspace) => workspace.name);\n        this.prompts = prompts;\n\n        // Separately, and allowed to fail on its own: the alerts belong to a repository and need\n        // a permission the rest of this page does not, so a token without it should cost that\n        // section and nothing else.\n        this.alertError = '';\n\n        try {\n          this.alerts = await dependabotAlerts(this.repo);\n        } catch (e) {\n          this.alerts = [];\n          this.alertError = e.message || String(e);\n        }\n      } catch (e) {\n        this.work = null;\n        this.error = e.message || String(e);\n      }\n    },\n\n    /**\n     * The workspace a pull request would have, by name.\n     *\n     * `issue-18536` is what the harness calls the project for issue 18536, and the workspace\n     * name rules here are the same shape (a DNS label), so the same name works. A PR that closes\n     * no issue falls back to its own number, which is the only other stable thing about it.\n     */\n    workspaceName(pr) {\n      return pr.issue ? `issue-${ pr.issue.number }` : `pr-${ pr.number }`;\n    },\n\n    /** Where its workspace is, when it has one, and where one would be made when it does not. */\n    workspaceTo(pr) {\n      const name = this.workspaceName(pr);\n\n      if (this.workspaces.includes(name)) {\n        return {\n          name:   WORKSPACE_ROUTE,\n          params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER, workspace: name },\n        };\n      }\n\n      return {\n        name:   CREATE_ROUTE,\n        params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER },\n        query:  { template: 'rancher', name },\n      };\n    },\n\n    hasWorkspace(pr) {\n      return this.workspaces.includes(this.workspaceName(pr));\n    },\n\n    /** The same two, for an issue, whose workspace is named for the issue rather than the PR. */\n    hasIssueWorkspace(issue) {\n      return this.workspaces.includes(`issue-${ issue.number }`);\n    },\n\n    issueWorkspaceTo(issue) {\n      const name = `issue-${ issue.number }`;\n\n      if (this.workspaces.includes(name)) {\n        return {\n          name:   WORKSPACE_ROUTE,\n          params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER, workspace: name },\n        };\n      }\n\n      return {\n        name:   CREATE_ROUTE,\n        params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER },\n        query:  { template: 'rancher', name },\n      };\n    },\n\n    /**\n     * Review: make the workspace for this pull request, and open a conversation about it.\n     *\n     * Two halves, and the second is the point. A workspace with a checkout in it is a place to\n     * work; a workspace with a conversation already asking about the right pull request is the\n     * thing this page exists to save. The prompt is this person's own (see prompts.ts), and it\n     * waits in the pod until the pane opens, so this does not have to wait for a workspace that\n     * is still cloning.\n     *\n     * It ends on the workspace's Conversations tab, because that is where what it just queued\n     * will appear.\n     */\n    async review(pr, done) {\n      const prompt = this.prompts.find((entry) => entry.id === 'review-pr');\n\n      return this.startWork(done, this.workspaceName(pr), prompt, {\n        repo:  pr.repo,\n        pr:    String(pr.number),\n        issue: pr.issue ? String(pr.issue.number) : '',\n        title: pr.title,\n        url:   pr.url,\n      });\n    },\n\n    /**\n     * Wait for the pod, then write the prompt into it.\n     *\n     * A workspace that has just been created has no pod for a few seconds, and queueConversation\n     * needs one to write a file. This is the only waiting the action does: everything after it\n     * happens in the workspace, in its own time.\n     */\n    async queueWhenReady(name, text) {\n      for (let attempt = 0; attempt < 20; attempt++) {\n        const workspace = await getWorkspace(name).catch(() => null);\n\n        if (workspace?.replicas) {\n          try {\n            await queueConversation(name, 1, text);\n\n            return;\n          } catch { /* no pod yet, which is what the next attempt is for */ }\n        }\n\n        await new Promise((resolve) => setTimeout(resolve, 3000));\n      }\n\n      throw new Error('The workspace did not start in time, so nothing was queued in it.');\n    },\n\n    /**\n     * Start fix on an issue: the workspace for it, and a conversation already about it.\n     *\n     * The same two steps Review takes on a pull request, with the other prompt. The workspace is\n     * named for the issue, which is what the harness calls the project for one, so pressing this\n     * twice lands in the same workspace rather than making a second.\n     */\n    async startFix(issue, done) {\n      const prompt = this.prompts.find((entry) => entry.id === 'fix-issue');\n\n      return this.startWork(done, `issue-${ issue.number }`, prompt, {\n        repo:  issue.repo,\n        issue: String(issue.number),\n        title: issue.title,\n        url:   issue.url,\n        pr:    '',\n      });\n    },\n\n    /**\n     * Start fix on a Dependabot advisory.\n     *\n     * Named for the advisory rather than the package, because one advisory is one piece of work\n     * however many packages and files it touches. GHSA ids are lowercase-safe and already look\n     * like a name.\n     */\n    async startAlertFix(alert, done) {\n      const prompt = this.prompts.find((entry) => entry.id === 'fix-dependabot');\n\n      return this.startWork(done, alert.ghsa.toLowerCase(), prompt, {\n        repo:    this.repo,\n        ghsa:    alert.ghsa,\n        cve:     alert.cve || 'no CVE',\n        title:   alert.summary,\n        package: alert.packages.join(', '),\n        files:   String(alert.files),\n        fix:     alert.patched || 'not released yet',\n        url:     alert.url,\n      });\n    },\n\n    /**\n     * The two steps every one of these actions is: make the workspace, queue the conversation.\n     *\n     * One function because the difference between fixing an issue, reviewing a pull request and\n     * clearing an advisory is which prompt and what is substituted into it. Everything else -\n     * creating the workspace if it is not there, waiting for its pod, going to it - is the same.\n     */\n    async startWork(done, name, prompt, values) {\n      this.error = '';\n\n      try {\n        if (!this.workspaces.includes(name)) {\n          await createWorkspace(name, 'rancher');\n          this.workspaces = [...this.workspaces, name];\n        }\n\n        if (prompt) {\n          await this.queueWhenReady(name, fillPrompt(prompt.text, values));\n        }\n\n        done(true);\n        this.$router.push({\n          name:   WORKSPACE_ROUTE,\n          params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER, workspace: name },\n          hash:   '#conversations',\n        });\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /** How severe, in the one word GitHub uses, coloured the way the rest of the page is. */\n    severityTone(severity) {\n      return {\n        critical: 'error', high: 'error', medium: 'warning', low: 'muted'\n      }[severity] || 'muted';\n    },\n\n    /**\n     * Run the failed jobs again, on every workflow that has one.\n     *\n     * The rows are not refreshed afterwards, deliberately: GitHub takes a moment to move a rerun\n     * job out of its failed state, and a table that redrew immediately would show the same red\n     * counts and read as a button that did nothing. The next Refresh shows it.\n     */\n    async rerun(pr, done) {\n      this.error = '';\n\n      try {\n        await Promise.all(pr.runs.map((run) => rerunFailed(pr.repo, run)));\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /**\n     * How long ago, in the one unit that is worth reading at a glance.\n     *\n     * The harness writes these as `5m ago`, `48d ago`, `2mo ago`, and that is the whole format:\n     * a pull request nobody has touched for two months and one touched for forty-eight days are\n     * different in a way that a date does not show and this does.\n     */\n    ago(when) {\n      if (!when) {\n        return 'never';\n      }\n\n      const minutes = Math.max(0, Math.round((Date.now() - Date.parse(when)) / 60000));\n\n      if (minutes < 60) {\n        return `${ minutes }m ago`;\n      }\n\n      if (minutes < 60 * 24) {\n        return `${ Math.round(minutes / 60) }h ago`;\n      }\n\n      const days = Math.round(minutes / (60 * 24));\n\n      return days < 60 ? `${ days }d ago` : `${ Math.round(days / 30) }mo ago`;\n    },\n\n    /**\n     * What the CI cell says, as the harness says it: the counts that are the reason it is not a\n     * tick, both of them, rather than whichever is worse.\n     *\n     * Nine pending and four failing are two different things to know and they are true at the\n     * same time. The version that showed one number showed the failures and hid the fact that\n     * half the run had not finished, which is the difference between \"this is broken\" and \"this\n     * is broken so far\".\n     */\n    badges(checks) {\n      if (!checks || !checks.total) {\n        return [];\n      }\n\n      const out = [];\n\n      if (checks.pending) {\n        out.push({ label: `${ checks.pending } pending`, tone: 'warning' });\n      }\n\n      if (checks.failing) {\n        out.push({ label: `${ checks.failing } failing`, tone: 'error' });\n      }\n\n      return out.length ? out : [{ label: '✓', tone: checks.state === 'SUCCESS' ? 'success' : 'muted' }];\n    },\n  },\n};\n</script>\n\n<template>\n  <div class=\"dev-my-work\">\n    <header>\n      <h1>My Work</h1>\n      <p class=\"subheader\">\n        <span v-if=\"work\">@{{ work.login }}<span v-if=\"repos\"> &middot; {{ repos }}</span></span>\n        <span v-else>What you wrote and what is waiting on you, from GitHub.</span>\n      </p>\n      <RcButton\n        variant=\"tertiary\"\n        size=\"small\"\n        left-icon=\"refresh\"\n        @click=\"refresh\"\n      >\n        Refresh\n      </RcButton>\n    </header>\n\n    <!--\n      A token that is missing and a token that is refused are different problems with the same\n      shape, so the message says which and the button goes where either is fixed.\n    -->\n    <Banner\n      v-if=\"error\"\n      color=\"warning\"\n    >\n      <div class=\"dev-my-work__error\">\n        <span>{{ error }}</span>\n        <RcButton\n          variant=\"secondary\"\n          size=\"small\"\n          :to=\"settingsTo\"\n        >\n          Go to Settings\n        </RcButton>\n      </div>\n    </Banner>\n\n    <template v-if=\"work\">\n      <h3>PRs with me as a reviewer <span class=\"dev-my-work__count\">{{ reviewing.length }}</span></h3>\n      <SortableTable\n        :headers=\"reviewHeaders\"\n        :rows=\"reviewing\"\n        key-field=\"key\"\n        :table-actions=\"false\"\n        :row-actions=\"false\"\n        :search=\"false\"\n        :paging=\"true\"\n        :rows-per-page=\"5\"\n      >\n        <template #cell:state=\"{ row }\">\n          <span :class=\"row.draft ? 'text-muted' : 'text-success'\">{{ row.draft ? 'Draft' : 'Open' }}</span>\n        </template>\n        <template #cell:approved=\"{ row }\">\n          <span :class=\"row.approved ? 'text-success' : 'text-muted'\">{{ row.approved ? '✓' : '' }}</span>\n        </template>\n        <template #cell:pr=\"{ row }\">\n          <a\n            :href=\"row.url\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >#{{ row.number }}</a>\n        </template>\n        <template #cell:repo=\"{ row }\">\n          <span class=\"dev-my-work__repo\">{{ row.repo }}</span>\n        </template>\n        <template #cell:issue=\"{ row }\">\n          <a\n            v-if=\"row.issue\"\n            :href=\"row.issue.url\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >#{{ row.issue.number }}</a>\n          <span\n            v-else\n            class=\"text-muted\"\n          >&ndash;</span>\n        </template>\n        <template #cell:ci=\"{ row }\">\n          <div class=\"dev-my-work__ci\">\n            <span\n              v-for=\"badge in badges(row.checks)\"\n              :key=\"badge.label\"\n              class=\"dev-my-work__badge\"\n              :class=\"`dev-my-work__badge--${ badge.tone }`\"\n            >{{ badge.label }}</span>\n            <!--\n              Only where there is something to rerun. It reruns the failed jobs of every workflow\n              that has one, which is usually a single run: see rerunFailed.\n            -->\n            <AsyncButton\n              v-if=\"row.runs.length\"\n              mode=\"apply\"\n              action-label=\"Rerun\"\n              waiting-label=\"Asking\"\n              success-label=\"Asked\"\n              size=\"sm\"\n              @click=\"(done) => rerun(row, done)\"\n            />\n          </div>\n        </template>\n        <!--\n          The workspace for this pull request. One that exists is a link to it; one that does not\n          is a link to the create page with the name already filled in, which is the harness's\n          \"Start project\" under the word this product uses.\n        -->\n        <template #cell:workspace=\"{ row }\">\n          <RcButton\n            variant=\"tertiary\"\n            size=\"small\"\n            :to=\"workspaceTo(row)\"\n          >\n            {{ hasWorkspace(row) ? 'Workspace' : 'Start workspace' }}\n          </RcButton>\n        </template>\n        <template #cell:actions=\"{ row }\">\n          <AsyncButton\n            mode=\"apply\"\n            action-label=\"Review\"\n            waiting-label=\"Opening\"\n            success-label=\"Opened\"\n            size=\"sm\"\n            @click=\"(done) => review(row, done)\"\n          />\n        </template>\n        <template #cell:reviewed=\"{ row }\">\n          <span :class=\"row.reviewedAt ? '' : 'text-muted'\">{{ ago(row.reviewedAt) }}</span>\n        </template>\n        <template #cell:updated=\"{ row }\">\n          {{ ago(row.updatedAt) }}\n        </template>\n      </SortableTable>\n\n      <h3>My PRs <span class=\"dev-my-work__count\">{{ mine.length }}</span></h3>\n      <SortableTable\n        :headers=\"mineHeaders\"\n        :rows=\"mine\"\n        key-field=\"key\"\n        :table-actions=\"false\"\n        :row-actions=\"false\"\n        :search=\"false\"\n        :paging=\"true\"\n        :rows-per-page=\"5\"\n      >\n        <template #cell:state=\"{ row }\">\n          <span :class=\"row.draft ? 'text-muted' : 'text-success'\">{{ row.draft ? 'Draft' : 'Open' }}</span>\n        </template>\n        <template #cell:approved=\"{ row }\">\n          <span :class=\"row.approved ? 'text-success' : 'text-muted'\">{{ row.approved ? '✓' : '' }}</span>\n        </template>\n        <template #cell:pr=\"{ row }\">\n          <a\n            :href=\"row.url\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >#{{ row.number }}</a>\n        </template>\n        <template #cell:repo=\"{ row }\">\n          <span class=\"dev-my-work__repo\">{{ row.repo }}</span>\n        </template>\n        <template #cell:issue=\"{ row }\">\n          <a\n            v-if=\"row.issue\"\n            :href=\"row.issue.url\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >#{{ row.issue.number }}</a>\n          <span\n            v-else\n            class=\"text-muted\"\n          >&ndash;</span>\n        </template>\n        <template #cell:ci=\"{ row }\">\n          <div class=\"dev-my-work__ci\">\n            <span\n              v-for=\"badge in badges(row.checks)\"\n              :key=\"badge.label\"\n              class=\"dev-my-work__badge\"\n              :class=\"`dev-my-work__badge--${ badge.tone }`\"\n            >{{ badge.label }}</span>\n            <!--\n              Only where there is something to rerun. It reruns the failed jobs of every workflow\n              that has one, which is usually a single run: see rerunFailed.\n            -->\n            <AsyncButton\n              v-if=\"row.runs.length\"\n              mode=\"apply\"\n              action-label=\"Rerun\"\n              waiting-label=\"Asking\"\n              success-label=\"Asked\"\n              size=\"sm\"\n              @click=\"(done) => rerun(row, done)\"\n            />\n          </div>\n        </template>\n        <template #cell:updated=\"{ row }\">\n          {{ ago(row.updatedAt) }}\n        </template>\n        <!--\n          The workspace for this pull request. One that exists is a link to it; one that does not\n          is a link to the create page with the name already filled in, which is the harness's\n          \"Start project\" under the word this product uses.\n        -->\n        <template #cell:workspace=\"{ row }\">\n          <RcButton\n            variant=\"tertiary\"\n            size=\"small\"\n            :to=\"workspaceTo(row)\"\n          >\n            {{ hasWorkspace(row) ? 'Workspace' : 'Start workspace' }}\n          </RcButton>\n        </template>\n        <!--\n          Nothing to do to your own pull request from here that GitHub does not do better, and the\n          harness's own row says the same by leaving it empty.\n        -->\n        <template #cell:actions>\n          <span class=\"text-muted\">&ndash;</span>\n        </template>\n        <template #cell:commented=\"{ row }\">\n          <span :class=\"row.commentedAt ? '' : 'text-muted'\">{{ ago(row.commentedAt) }}</span>\n        </template>\n      </SortableTable>\n      <h3>Issues assigned to me <span class=\"dev-my-work__count\">{{ work.issues.length }}</span></h3>\n      <SortableTable\n        :headers=\"issueHeaders\"\n        :rows=\"work.issues\"\n        key-field=\"key\"\n        default-sort-by=\"age\"\n        :table-actions=\"false\"\n        :row-actions=\"false\"\n        :search=\"false\"\n        :paging=\"true\"\n        :rows-per-page=\"5\"\n      >\n        <template #cell:number=\"{ row }\">\n          <a\n            :href=\"row.url\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >#{{ row.number }}</a>\n        </template>\n        <template #cell:repo=\"{ row }\">\n          <span class=\"dev-my-work__repo\">{{ row.repo }}</span>\n        </template>\n        <!-- The labels, as the chips the harness draws them as. -->\n        <template #cell:area=\"{ row }\">\n          <span\n            v-for=\"label in row.labels\"\n            :key=\"label\"\n            class=\"dev-my-work__area\"\n          >{{ label }}</span>\n        </template>\n        <template #cell:age=\"{ row }\">\n          {{ ago(row.createdAt) }}\n        </template>\n        <template #cell:workspace=\"{ row }\">\n          <RcButton\n            variant=\"tertiary\"\n            size=\"small\"\n            :to=\"issueWorkspaceTo(row)\"\n          >\n            {{ hasIssueWorkspace(row) ? 'Workspace' : 'Start workspace' }}\n          </RcButton>\n        </template>\n        <template #cell:actions=\"{ row }\">\n          <AsyncButton\n            mode=\"apply\"\n            action-label=\"Start fix\"\n            waiting-label=\"Opening\"\n            success-label=\"Opened\"\n            size=\"sm\"\n            @click=\"(done) => startFix(row, done)\"\n          />\n        </template>\n      </SortableTable>\n\n      <h3>\n        Dependabot alerts <span class=\"dev-my-work__count\">{{ alerts.length }}</span>\n        <a\n          v-if=\"repo\"\n          class=\"dev-my-work__link\"\n          :href=\"`https://github.com/${ repo }/security/dependabot`\"\n          target=\"_blank\"\n          rel=\"noopener noreferrer\"\n        >on GitHub</a>\n      </h3>\n      <!--\n        One row per advisory rather than per alert: GitHub raises one alert per package per\n        manifest, so a transitive dependency in three lockfiles is three alerts about one thing to\n        do. The count says how many, and how many files they are in.\n      -->\n      <Banner\n        v-if=\"alertError\"\n        color=\"info\"\n        :label=\"alertError\"\n      />\n      <SortableTable\n        v-else\n        :headers=\"alertHeaders\"\n        :rows=\"alerts\"\n        key-field=\"key\"\n        default-sort-by=\"severity\"\n        :table-actions=\"false\"\n        :row-actions=\"false\"\n        :search=\"false\"\n        :paging=\"true\"\n        :rows-per-page=\"5\"\n      >\n        <template #cell:severity=\"{ row }\">\n          <span\n            class=\"dev-my-work__badge\"\n            :class=\"`dev-my-work__badge--${ severityTone(row.severity) }`\"\n          >{{ row.severity }}</span>\n        </template>\n        <template #cell:advisory=\"{ row }\">\n          <a\n            :href=\"row.url\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n          >{{ row.summary }}</a>\n          <span class=\"dev-my-work__ids\">{{ row.ghsa }}<template v-if=\"row.cve\"> &middot; {{ row.cve }}</template></span>\n        </template>\n        <template #cell:package=\"{ row }\">\n          <span class=\"dev-my-work__repo\">{{ row.packages.join(', ') }}</span>\n        </template>\n        <template #cell:alerts=\"{ row }\">\n          {{ row.alerts }} in {{ row.files }} file{{ row.files === 1 ? '' : 's' }}\n        </template>\n        <template #cell:fix=\"{ row }\">\n          <span :class=\"row.patched ? '' : 'text-muted'\">{{ row.patched || 'no patch yet' }}</span>\n        </template>\n        <template #cell:actions=\"{ row }\">\n          <AsyncButton\n            mode=\"apply\"\n            action-label=\"Start fix\"\n            waiting-label=\"Opening\"\n            success-label=\"Opened\"\n            size=\"sm\"\n            @click=\"(done) => startAlertFix(row, done)\"\n          />\n        </template>\n      </SortableTable>\n    </template>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-my-work {\n    overflow-y: auto;\n    padding:    var(--dev-space-5);\n\n    header {\n      display:       flex;\n      align-items:   center;\n      gap:           var(--dev-space-4);\n      margin-bottom: var(--dev-space-5);\n\n      h1 {\n        margin-bottom: 0;\n      }\n\n      .subheader {\n        flex:      1 1 auto;\n        margin:    0;\n        color:     var(--muted);\n      }\n    }\n\n    h3 {\n      margin: var(--dev-space-5) 0 var(--dev-space-3) 0;\n    }\n\n    // The row count beside a heading, which is the harness's, and quiet because it is a count\n    // rather than part of the heading.\n    &__count {\n      margin-left: var(--dev-space-3);\n      color:       var(--muted);\n      font-size:   12px;\n      font-weight: 400;\n    }\n\n    // The owner is the same for nearly every row, so it is there to be read when it differs\n    // rather than to be read every time.\n    &__repo {\n      color:     var(--muted);\n      font-size: 12px;\n    }\n\n    &__ci {\n      display:     flex;\n      align-items: center;\n      gap:         var(--dev-space-3);\n    }\n\n    // The harness's own pill, in Rancher's colours. Not BadgeState, which takes a Rancher state\n    // name and would have to be told that \"4 failing\" is one.\n    &__badge {\n      padding:       1px var(--dev-space-3);\n      border-radius: 10px;\n      font-size:     11px;\n      white-space:   nowrap;\n\n      &--warning {\n        background: var(--warning-banner-bg, var(--warning));\n        color:      var(--warning);\n      }\n\n      &--error {\n        background: var(--error-banner-bg, var(--error));\n        color:      var(--error);\n      }\n\n      &--success,\n      &--muted {\n        color: var(--success);\n      }\n\n      &--muted {\n        color: var(--muted);\n      }\n    }\n\n    // A label, as a chip. Several to a cell and they wrap, because an issue can carry four.\n    &__area {\n      display:       inline-block;\n      margin:        1px var(--dev-space-2) 1px 0;\n      padding:       1px var(--dev-space-3);\n      border:        1px solid var(--border);\n      border-radius: 10px;\n      color:         var(--muted);\n      font-size:     11px;\n      white-space:   nowrap;\n    }\n\n    // The advisory's identifiers, under its own title, where the harness has them.\n    &__ids {\n      display:     block;\n      color:       var(--muted);\n      font-family: monospace;\n      font-size:   11px;\n    }\n\n    &__link {\n      margin-left: var(--dev-space-3);\n      font-size:   12px;\n      font-weight: 400;\n    }\n\n    &__error {\n      display:     flex;\n      align-items: center;\n      gap:         var(--dev-space-4);\n    }\n  }\n</style>\n",
    "pkg/dev-extension/pages/Settings.vue": "<script>\n// Settings: the one place a secret is set, generated from what declared it.\n//\n// Nothing here is written per key. The fields come from the declarations in templates.ts, global\n// ones first and then one section per template, so adding a secret is a data change in the same\n// way adding a template is. That is also what keeps this page and the sidecar cards agreeing\n// about which keys exist.\n//\n// Three rules the store's shape imposes on this page:\n//\n//   - a stored value is never rendered back into its field. The field shows whether the key is\n//     set and offers to replace or clear it, so a page someone left open cannot leak a token to\n//     whoever walks past.\n//   - saving writes only the fields that were touched, so opening this page and pressing Save\n//     cannot blank a key nobody could see.\n//   - a generated secret is different in kind, and this is the deliberate exception to the rule\n//     above rather than an oversight in it. The rule exists so that a value someone entrusted to\n//     this page cannot be read back out of it; a value the product invented was never anyone's\n//     secret, and a password you cannot read is a password you cannot log in with. So: never\n//     render back what a person typed, always allow reading what the product generated. Those\n//     fields say they are generated rather than pretending someone chose them.\n//\n// The claude login is on this page too, as an identity rather than a secret: who it is and\n// whether it is still valid, never the token.\nimport Loading from '@shell/components/Loading';\nimport AsyncButton from '@shell/components/AsyncButton';\nimport { Banner } from '@components/Banner';\nimport { RcButton } from '@components/RcButton';\nimport { LabeledInput } from '@components/Form/LabeledInput';\nimport BrandImage from '@shell/components/BrandImage';\nimport {\n  setSecretKeys, saveSecrets, secretValue, migrateGithubToken, templateSecretKey,\n  listPrompts, savePrompts as writePrompts\n} from '../api';\nimport { TEMPLATES, GLOBAL_SECRETS } from '../templates';\n\nexport default {\n  name: 'DevSettings',\n\n  components: {\n    Loading, AsyncButton, Banner, RcButton, LabeledInput, BrandImage\n  },\n\n  async fetch() {\n    // The one-off `github-token` Secret is folded into the store here, on the page that owns the\n    // store, and deleted. It is idempotent and does nothing on a cluster that never had one.\n    await migrateGithubToken().catch(() => {});\n    await this.refresh();\n  },\n\n  data() {\n    return {\n      keys:     [],\n      // The prompts a queued conversation opens on, and the edits made to them. Separate from\n      // the secret edits because these are read back after they are saved, and a secret is not.\n      prompts:      [],\n      promptEdits:  {},\n      // The sections whose fields are showing. A card opens on its summary line, because what a\n      // person comes here to know first is whether a template is configured at all.\n      open:         {},\n      // Written here rather than in the template: a moustache cannot contain the braces it is\n      // made of, and escaping them in the markup is less readable than one string.\n      placeholders: '{{repo}} {{pr}} {{issue}} {{title}} {{url}}',\n      // Key to the string typed into its field. A key that is not in here was not touched, and\n      // is not written on Save. An empty field is never in here: clearing is what Clear is for.\n      edits:    {},\n      // Key to the value of a generated secret, once Show has been pressed for it.\n      revealed: {},\n      error:    '',\n      saved:    false,\n    };\n  },\n\n  computed: {\n    /**\n     * The sections, in the order the spec asks for them: global first, then one per template.\n     *\n     * A template with no declared secrets still gets a section, saying so, for the same reason\n     * the sidebar shows a template with no workspaces: the set of templates is the map of what\n     * this product can do, and a gap in it reads as something being broken.\n     */\n    sections() {\n      return [\n        {\n          id:      'global',\n          title:   'Global',\n          help:    'Secrets that belong to the product rather than to any one template.',\n          secrets: GLOBAL_SECRETS.map((secret) => this.field(secret, secret.key)),\n        },\n        ...TEMPLATES.map((template) => ({\n          id:      template.id,\n          title:   template.label,\n          // The card's own identity, so a template reads as the thing it is rather than as a\n          // heading over some fields. The harness's settings card does the same: a mark, a name,\n          // a line about what it is, and the identifier under it.\n          icon:    template.icon,\n          logo:    template.logo,\n          // A short line rather than the description's first sentence, which is a paragraph in\n          // its own right: this is the line under a name on a card, and it has one line of room.\n          subtitle: `${ template.label } dev environment`,\n          meta:    template.id,\n          help:    `Stored under the ${ template.id }. prefix, so two templates can each have a key of the same name.`,\n          secrets: (template.secrets || []).map((secret) => this.field(secret, templateSecretKey(template.id, secret.key))),\n        })),\n      ];\n    },\n\n    /** What Save will write: the fields that were typed into, and the keys Clear was pressed on. */\n    writes() {\n      return { ...this.edits };\n    },\n\n  },\n\n  methods: {\n    /** How many of a section's keys have a value, which is the card's summary line. */\n    configured(section) {\n      return section.secrets.filter((secret) => secret.set).length;\n    },\n\n    toggle(section) {\n      this.open = { ...this.open, [section.id]: !this.open[section.id] };\n    },\n\n    /** What is in a prompt's box: the edit if there is one, and what is stored otherwise. */\n    promptText(prompt) {\n      return this.promptEdits[prompt.id] ?? prompt.text;\n    },\n\n    /** Whether anything has actually been typed, which is what Save is enabled by. */\n    promptsChanged() {\n      return this.prompts.some((prompt) => this.promptText(prompt) !== prompt.text);\n    },\n\n    /**\n     * Save the prompts that changed, and nothing else.\n     *\n     * The same rule the secrets above follow: a field nobody touched is not written, so two\n     * people saving different things do not overwrite each other's untouched ones.\n     */\n    async savePrompts(done) {\n      const changed = Object.fromEntries(this.prompts\n        .filter((prompt) => this.promptText(prompt) !== prompt.text)\n        .map((prompt) => [prompt.id, this.promptText(prompt)]));\n\n      try {\n        await writePrompts(changed);\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n\n    /** One declaration, joined to whether the cluster has it. */\n    field(secret, key) {\n      return {\n        ...secret,\n        storeKey: key,\n        set:      this.keys.includes(key),\n      };\n    },\n\n    async refresh() {\n      const [keys, prompts] = await Promise.all([\n        setSecretKeys().catch(() => []),\n        listPrompts().catch(() => []),\n      ]);\n\n      this.prompts = prompts;\n      this.promptEdits = {};\n\n      this.keys = keys;\n    },\n\n    placeholder(secret) {\n      if (secret.set) {\n        return 'Set. Type to replace it.';\n      }\n\n      return secret.generated ? 'Generated when it is first needed' : 'Not set';\n    },\n\n    /**\n     * What is in the box: what was typed, or the revealed value, or nothing.\n     *\n     * A secret that has not been revealed shows its placeholder rather than a row of dots for a\n     * value the page does not have. Typing wins over both, because it is what will be saved.\n     */\n    fieldValue(secret) {\n      return this.edits[secret.storeKey] ?? this.revealed[secret.storeKey] ?? '';\n    },\n\n    async toggleReveal(secret) {\n      if (this.revealed[secret.storeKey]) {\n        this.hide(secret);\n\n        return;\n      }\n\n      try {\n        this.revealed = { ...this.revealed, [secret.storeKey]: await secretValue(secret.storeKey) };\n      } catch (e) {\n        this.error = e.message || String(e);\n      }\n    },\n\n    hide(secret) {\n      const revealed = { ...this.revealed };\n\n      delete revealed[secret.storeKey];\n      this.revealed = revealed;\n    },\n\n    /**\n     * Something was typed.\n     *\n     * An empty field is never a change, whatever it was a moment ago. Typing a character into a\n     * field whose key is set and deleting it again used to leave an empty edit behind, and an\n     * empty value is a deliberate clear, so one stray keystroke and a Save destroyed a token\n     * nobody could see. Clearing has a button of its own; the field only ever sets a value.\n     */\n    edit(secret, value) {\n      const edits = { ...this.edits };\n\n      if (value === '') {\n        delete edits[secret.storeKey];\n      } else {\n        edits[secret.storeKey] = value;\n      }\n\n      this.edits = edits;\n    },\n\n    /** An explicit clear, which is the only thing that writes an empty value. */\n\n    /** Whether anything in one card was typed into, which is what its Save asks. */\n    changedIn(section) {\n      return section.secrets.some((secret) => secret.storeKey in this.edits);\n    },\n\n    /**\n     * Save one card's keys, and only that card's.\n     *\n     * Each card has its own button, inside its own accordion, because that is where the fields\n     * are: a single Save at the foot of the page is a button a long way from what it acts on, and\n     * one that quietly writes the other cards' edits too. The store is still one Secret, so this\n     * is a narrower write rather than a different one.\n     */\n    async save(section, done) {\n      this.error = '';\n      this.saved = false;\n\n      const keys = section.secrets.map((secret) => secret.storeKey);\n      const writes = Object.fromEntries(Object.entries(this.writes).filter(([key]) => keys.includes(key)));\n\n      try {\n        await saveSecrets(writes);\n\n        // Only this card's, so an edit sitting in another card is not lost by saving this one.\n        this.edits = Object.fromEntries(Object.entries(this.edits).filter(([key]) => !keys.includes(key)));\n        this.revealed = {};\n        await this.refresh();\n        this.saved = true;\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      }\n    },\n  },\n};\n</script>\n\n<template>\n  <Loading v-if=\"$fetchState.pending\" />\n  <div\n    v-else\n    class=\"dev-settings\"\n  >\n    <header>\n      <h1>Settings</h1>\n      <p class=\"subheader\">\n        Every secret this product uses, in one Kubernetes Secret of your own in the dev-system\n        namespace. A value is never shown again after it is saved, and saving writes only the\n        fields you changed.\n      </p>\n    </header>\n\n    <Banner\n      v-if=\"error\"\n      color=\"error\"\n      :label=\"error\"\n    />\n    <Banner\n      v-else-if=\"saved\"\n      color=\"success\"\n      label=\"Saved.\"\n    />\n\n    <!--\n      A card per template, the shape the harness's own settings page has: the template's mark and\n      name, one line about what it is, and a summary of how many of its keys are set that opens\n      the fields when you press it. A page of forty fields is one nobody reads; a page of three\n      cards saying \"5 keys configured\" is one that answers the usual question without being\n      opened at all.\n    -->\n    <section\n      v-for=\"section in sections\"\n      :key=\"section.id\"\n      class=\"dev-settings__card\"\n    >\n      <div class=\"dev-settings__card-head\">\n        <BrandImage\n          v-if=\"section.logo\"\n          class=\"dev-settings__card-icon\"\n          :file-name=\"section.logo\"\n        />\n        <i\n          v-else\n          class=\"dev-settings__card-icon icon\"\n          :class=\"section.icon || 'icon-gear'\"\n        />\n        <div class=\"dev-settings__card-title\">\n          <h3>{{ section.title }}</h3>\n          <p v-if=\"section.subtitle\">\n            {{ section.subtitle }}\n          </p>\n          <p\n            v-if=\"section.meta\"\n            class=\"dev-settings__card-meta\"\n          >\n            {{ section.meta }} &middot; {{ section.secrets.length }} keys\n          </p>\n        </div>\n      </div>\n\n      <button\n        type=\"button\"\n        class=\"dev-settings__summary\"\n        @click=\"toggle(section)\"\n      >\n        <i\n          class=\"icon\"\n          :class=\"open[section.id] ? 'icon-chevron-down' : 'icon-chevron-right'\"\n        />\n        {{ configured(section) }} of {{ section.secrets.length }} keys configured\n      </button>\n\n      <template v-if=\"open[section.id]\">\n        <p class=\"subheader\">\n          {{ section.help }}\n        </p>\n\n        <p\n          v-if=\"!section.secrets.length\"\n          class=\"dev-settings__none\"\n        >\n          This template declares no secrets.\n        </p>\n\n        <div\n        v-for=\"secret in section.secrets\"\n        :key=\"secret.storeKey\"\n        class=\"dev-settings__field\"\n      >\n        <!--\n          Bound through a handler rather than with v-model, so a key is in `edits` only because\n          something was typed into it. With v-model an input that emitted once on mount would put\n          every key in there as an empty string, and an empty string is a deliberate clear.\n        -->\n        <!--\n          The value lives in the box, revealed or not, which is where Rancher puts a password:\n          its own Password component is a LabeledInput whose type flips between password and text\n          from a link in the suffix slot, and this is that arrangement with one difference. The\n          value of a generated secret is not in the page until Show is pressed, because it is\n          fetched then; a typed one is never offered back at all.\n        -->\n        <LabeledInput\n          :type=\"revealed[secret.storeKey] ? 'text' : 'password'\"\n          :value=\"fieldValue(secret)\"\n          :label=\"secret.label\"\n          :placeholder=\"placeholder(secret)\"\n          @update:value=\"(value) => edit(secret, value)\"\n        >\n          <template\n            v-if=\"secret.generated && secret.set\"\n            #suffix\n          >\n            <div class=\"addon\">\n              <a\n                href=\"#\"\n                @click.prevent.stop=\"toggleReveal(secret)\"\n              >{{ revealed[secret.storeKey] ? 'Hide' : 'Show' }}</a>\n            </div>\n          </template>\n        </LabeledInput>\n        <!--\n          The help is a paragraph rather than LabeledInput's `sub-label`, because that slot is\n          `position: absolute; top: 100%` with pointer events, so it hangs over whatever follows\n          the field. Here that is the row of controls, and Clear and Show were unclickable behind\n          it. In flow it takes its own height and nothing sits underneath anything.\n        -->\n        <p class=\"dev-settings__help\">\n          {{ secret.help }}\n        </p>\n        <div class=\"dev-settings__row\">\n          <span class=\"dev-settings__key\">{{ secret.storeKey }}</span>\n          <span\n            class=\"dev-settings__state\"\n            :class=\"{ 'dev-settings__state--set': secret.set }\"\n          >{{ secret.set ? 'Set' : 'Not set' }}</span>\n          <span\n            v-if=\"secret.required && !secret.set\"\n            class=\"dev-settings__pending\"\n          >Required</span>\n          <span\n            v-if=\"secret.generated\"\n            class=\"dev-settings__state\"\n          >Generated</span>\n          </div>\n        </div>\n\n        <div class=\"dev-settings__actions\">\n          <AsyncButton\n            mode=\"apply\"\n            action-label=\"Save keys\"\n            :disabled=\"!changedIn(section)\"\n            @click=\"(done) => save(section, done)\"\n          />\n        </div>\n      </template>\n    </section>\n\n    <!--\n      The prompts a queued conversation opens on. They are per person and they are text, so they\n      are edited here rather than declared: see prompts.ts, which holds the defaults and what a\n      placeholder in one can stand for.\n    -->\n    <section class=\"dev-settings__card\">\n      <div class=\"dev-settings__card-head\">\n        <i class=\"dev-settings__card-icon icon icon-comment\" />\n        <div class=\"dev-settings__card-title\">\n          <h3>Conversation prompts</h3>\n          <p>What a conversation queued from My Work opens on.</p>\n          <p class=\"dev-settings__card-meta\">\n            {{ prompts.length }} prompts &middot; yours alone\n          </p>\n        </div>\n      </div>\n\n      <div\n        v-for=\"prompt in prompts\"\n        :key=\"prompt.id\"\n        class=\"dev-settings__field\"\n      >\n        <label class=\"dev-settings__prompt-label\">{{ prompt.label }}</label>\n        <p class=\"dev-settings__help\">\n          {{ prompt.help }}\n        </p>\n        <textarea\n          class=\"dev-settings__prompt\"\n          rows=\"6\"\n          spellcheck=\"false\"\n          :value=\"promptText(prompt)\"\n          @input=\"(event) => promptEdits = { ...promptEdits, [prompt.id]: event.target.value }\"\n        />\n      </div>\n\n      <p class=\"dev-settings__help\">\n        <code>{{ placeholders }}</code> are filled in from the row the action was pressed on.\n        Anything else is left as it is written.\n      </p>\n\n      <div class=\"dev-settings__actions\">\n        <AsyncButton\n          mode=\"apply\"\n          action-label=\"Save prompts\"\n          :disabled=\"!promptsChanged()\"\n          @click=\"savePrompts\"\n        />\n      </div>\n    </section>\n\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-settings {\n    padding:   var(--dev-space-5);\n    overflow-y: auto;\n\n    header {\n      margin-bottom: var(--dev-space-5);\n\n      h1 {\n        margin-bottom: 0;\n      }\n    }\n\n    .subheader {\n      max-width: 90ch;\n      margin:    var(--dev-space-2) 0 var(--dev-space-4) 0;\n      color:     var(--muted);\n    }\n\n    &__section {\n      margin-top: var(--dev-space-6);\n      max-width:  90ch;\n    }\n\n    &__field {\n      margin-top: var(--dev-space-5);\n    }\n\n    // The key, its state and its controls on one line under the field, so the field itself is\n    // just a field and everything about it is in one place.\n    &__row {\n      display:     flex;\n      align-items: center;\n      gap:         var(--dev-space-4);\n      margin-top:  var(--dev-space-2);\n      font-size:   12px;\n    }\n\n    &__help {\n      margin:    var(--dev-space-2) 0 0 0;\n      color:     var(--muted);\n      font-size: 12px;\n    }\n\n    &__key {\n      color:       var(--muted);\n      font-family: monospace;\n    }\n\n    &__state {\n      color: var(--muted);\n\n      &--set {\n        color: var(--success);\n      }\n    }\n\n\n    &__pending {\n      color: var(--warning);\n    }\n\n    &__none {\n      color: var(--muted);\n    }\n\n    // The card, which is the harness's: a mark, a name, a line, and a summary that opens it.\n    &__card {\n      max-width:     720px;\n      margin-bottom: var(--dev-space-5);\n      padding:       var(--dev-space-5);\n      border:        1px solid var(--border);\n      border-radius: var(--border-radius);\n    }\n\n    &__card-head {\n      display:     flex;\n      gap:         var(--dev-space-4);\n      align-items: flex-start;\n    }\n\n    &__card-icon {\n      flex:      0 0 32px;\n      width:     32px;\n      height:    32px;\n      color:     var(--primary);\n      font-size: 28px;\n    }\n\n    &__card-title {\n      flex:      1 1 auto;\n      min-width: 0;\n\n      h3 {\n        margin: 0;\n      }\n\n      p {\n        margin: var(--dev-space-1) 0 0 0;\n        color:  var(--muted);\n      }\n    }\n\n    &__card-meta {\n      font-family: monospace;\n      font-size:   12px;\n    }\n\n    // The summary line, which is a control rather than a heading: pressing it is what shows the\n    // fields, and it says what someone came to find out before they press anything.\n    &__summary {\n      display:       flex;\n      align-items:   center;\n      gap:           var(--dev-space-3);\n      width:         100%;\n      min-height:    0;\n      margin:        var(--dev-space-4) 0 0 0;\n      padding:       var(--dev-space-3) var(--dev-space-4);\n      border:        1px solid var(--border);\n      border-radius: var(--border-radius);\n      background:    transparent;\n      color:         var(--body-text);\n      font:          inherit;\n      text-align:    left;\n      cursor:        pointer;\n\n      &:hover {\n        background: var(--nav-hover, var(--accent-btn));\n      }\n    }\n\n    &__prompt-label {\n      display:     block;\n      margin-top:  var(--dev-space-4);\n      font-weight: 600;\n    }\n\n    &__prompt {\n      display:       block;\n      width:         100%;\n      padding:       var(--dev-space-3) var(--dev-space-4);\n      border:        1px solid var(--border);\n      border-radius: var(--border-radius);\n      background:    var(--body-bg);\n      color:         var(--body-text);\n      font-family:   monospace;\n      font-size:     12px;\n      resize:        vertical;\n    }\n\n    &__actions {\n      display:    flex;\n      margin-top: var(--dev-space-5);\n    }\n  }\n</style>\n",
    "pkg/dev-extension/pages/Templates.vue": "<script>\n// The templates a workspace can be made from.\n//\n// A read-only page, because a template is code here rather than data in the cluster (see\n// templates.ts for why). It exists so the choice on the create form is explainable without\n// reading the source, and so the create form's dropdown can stay a dropdown.\nimport SortableTable from '@shell/components/SortableTable';\nimport { RcButton } from '@components/RcButton';\nimport { TEMPLATES } from '../templates';\nimport { DEV_PRODUCT, BLANK_CLUSTER, CREATE_ROUTE } from '../config/constants';\n\nexport default {\n  name: 'DevTemplates',\n\n  components: { SortableTable, RcButton },\n\n  data() {\n    return {\n      rows:    TEMPLATES,\n      headers: [\n        {\n          name: 'label', label: 'Template', value: 'label', sort: ['label']\n        },\n        {\n          name: 'image', label: 'Image', value: 'image', sort: ['image']\n        },\n        {\n          name: 'port', label: 'Port', value: 'port', sort: ['port'], width: 80\n        },\n        // What the workspace's Conversations tab will actually be. Every template says\n        // 'shell' today, and the column exists so that is visible when choosing rather than\n        // when opening the tab.\n        {\n          name:  'conversations',\n          label: 'Conversations',\n          value: 'conversations',\n          sort:  ['conversations'],\n          width: 130\n        },\n        {\n          name: 'description', label: 'Description', value: 'description'\n        },\n        {\n          name: 'actions', label: '', align: 'right', width: 120\n        },\n      ],\n    };\n  },\n\n  methods: {\n    // The create form reads this back out of the query, so picking a template here lands on a\n    // form that is already filled in rather than one that has to be filled in again.\n    createTo(template) {\n      return {\n        name:   CREATE_ROUTE,\n        params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER },\n        query:  { template: template.id },\n      };\n    },\n  },\n};\n</script>\n\n<template>\n  <div class=\"dev-templates\">\n    <header>\n      <h1>Templates</h1>\n      <p class=\"subheader\">\n        What a workspace's pod runs. The harness clones a repo and installs; here the same\n        decision is which container image a workspace gets.\n      </p>\n    </header>\n\n    <SortableTable\n      :headers=\"headers\"\n      :rows=\"rows\"\n      key-field=\"id\"\n      default-sort-by=\"label\"\n      :table-actions=\"false\"\n      :row-actions=\"false\"\n      :search=\"false\"\n      :paging=\"false\"\n    >\n      <template #cell:conversations=\"{ row }\">\n        <span :class=\"row.conversations === 'claude' ? '' : 'text-muted'\">\n          {{ row.conversations === 'claude' ? 'Claude' : 'Shell only' }}\n        </span>\n      </template>\n\n      <template #cell:actions=\"{ row }\">\n        <RcButton\n          variant=\"tertiary\"\n          size=\"small\"\n          left-icon=\"plus\"\n          :to=\"createTo(row)\"\n        >\n          Create\n        </RcButton>\n      </template>\n    </SortableTable>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-templates {\n    header {\n      display:       block;\n      margin-bottom: var(--dev-space-5);\n\n      h1 {\n        margin-bottom: 0;\n      }\n\n      .subheader {\n        max-width: 80ch;\n        margin:    var(--dev-space-2) 0 0 0;\n        color:     var(--muted);\n      }\n    }\n  }\n</style>\n",
    "pkg/dev-extension/pages/WorkspaceDetail.vue": "<script>\n// One workspace, opened: the same running thing seen three ways, and nothing above them.\n//\n// There is no masthead. The workspace's name and state are on the sidebar row you opened it\n// from, which is on screen from every page rather than only this one, so repeating them here\n// would cost the panes a strip of height to say something already said. What is left of the\n// page's chrome is the tab strip, with Start and Stop at its right-hand end, because those are\n// the two things worth doing from any tab. Delete is on the sidebar row and on the Workspaces\n// list, both of which ask first, which is enough places for it.\n//\n// The tab is the hash, `#conversations`, and not a path segment the way the harness's\n// `/:projectId/conversations` is. That is a deliberate divergence, and it is not a matter of\n// taste:\n//\n//   - the shell renders its router-view with `:key=\"$route.path\"` (components/templates/\n//     blank.vue), so a tab in the path is a different component instance, and every tab click\n//     destroys and rebuilds this page;\n//   - the apiserver does not reap an exec'd process when its WebSocket closes, so each of those\n//     rebuilds leaves the previous tab's shell running in the workspace's pod. A tab bar that\n//     accumulates processes in the thing it is a view of is not a tab bar.\n//\n// The hash keeps the property the layout actually needs, which is that a tab is addressable and\n// therefore shareable, and it is what Rancher's own detail pages use.\nimport Loading from '@shell/components/Loading';\nimport Tabbed from '@shell/components/Tabbed';\nimport Tab from '@shell/components/Tabbed/Tab';\nimport { Banner } from '@components/Banner';\nimport Row from '../design/Row.vue';\nimport { RcButton } from '@components/RcButton';\nimport WorkspaceConversations from '../components/WorkspaceConversations.vue';\nimport WorkspaceBrowser from '../components/WorkspaceBrowser.vue';\nimport WorkspacePorts from '../components/WorkspacePorts.vue';\nimport WorkspaceSidecars from '../components/WorkspaceSidecars.vue';\nimport {\n  getWorkspace, listAllWorkspaces, setWorkspaceRunning, workspacePod, workspaceLogTail,\n  sidecarReady, workspaceServing, setCluster\n} from '../api';\nimport { templateById, templateBrowser } from '../templates';\nimport { rememberWorkspace, rememberTab, lastTab } from '../recent';\nimport {\n  DEV_PRODUCT, BLANK_CLUSTER, WORKSPACES_ROUTE, WORKSPACE_TABS, DEFAULT_WORKSPACE_TAB\n} from '../config/constants';\n\nconst REFRESH_MS = 5000;\n\nexport default {\n  name: 'DevWorkspaceDetail',\n\n  components: {\n    Loading, Tabbed, Tab, Banner, RcButton, Row,\n    WorkspaceConversations, WorkspaceBrowser, WorkspacePorts, WorkspaceSidecars\n  },\n\n  async fetch() {\n    await this.refresh();\n  },\n\n  data() {\n    return {\n      workspace:    null,\n      pod:          '',\n      // The last line the container printed, while it is still starting. See refresh.\n      logTail:      '',\n      error:        '',\n      busy:         false,\n      refreshTimer: null,\n      // Which tabs have been opened. Tab content is mounted on first activation and left\n      // mounted afterwards: Tabbed hides an inactive tab with v-show rather than unmounting it,\n      // so a terminal survives a trip to another tab, but a tab nobody opened should not have\n      // opened a shell in the pod or framed the workspace's server to begin with.\n      seen:         {},\n      // Whether there is anything to frame, which is whether the Browser tab exists at all. See\n      // refresh: it is a question about the browser sidecar, not about the workspace.\n      framable:     false,\n      /** The tab Tabbed is actually showing, which is what an unusable hash is corrected to. */\n      active:       DEFAULT_WORKSPACE_TAB,\n      listTo:       { name: WORKSPACES_ROUTE, params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER } },\n    };\n  },\n\n  computed: {\n    name() {\n      return this.$route.params.workspace;\n    },\n\n    /**\n     * The tabs this workspace actually has, which is not always all of them: Browser is there\n     * only while there is something in it. Everything that reads a tab name out of the address\n     * validates against this rather than the full list.\n     */\n    tabs() {\n      return WORKSPACE_TABS.filter((name) => name !== 'browser' || this.framable);\n    },\n\n    /**\n     * The tab the address names, or the default when it names none or names one that is not\n     * there. Read here as well as by Tabbed, because it decides which tab's content is mounted\n     * on the way up, before Tabbed has said anything.\n     */\n    tab() {\n      const tab = this.$route.hash.replace('#', '');\n\n      if (this.tabs.includes(tab)) {\n        return tab;\n      }\n\n      // No tab in the address, or one this workspace does not have: the one you were last on,\n      // which is what makes switching between two workspaces keep the same view of both. See\n      // recent.ts. The default is only reached on a browser that remembers nothing.\n      const remembered = lastTab();\n\n      return this.tabs.includes(remembered) ? remembered : DEFAULT_WORKSPACE_TAB;\n    },\n\n    /** True while there is no pod to frame or talk to, which is what the tabs have to say. */\n    starting() {\n      return !!this.workspace && this.workspace.state !== 'running' && this.workspace.state !== 'stopped';\n    },\n\n    stopped() {\n      return this.workspace?.state === 'stopped';\n    },\n\n  },\n\n  watch: {\n    /**\n     * Keep the address describing the tab that is actually showing.\n     *\n     * Tabbed's `select()` returns without doing anything when the hash names a tab it does not\n     * have, so editing `#sidecars` to `#overview` in the address bar leaves Sidecars on screen\n     * with `#overview` in the URL, and copying that address shares the wrong tab. A cold load is\n     * already right, because Tabbed replaces the hash itself when it falls back to the default;\n     * this is the same correction for the case where the document does not reload.\n     */\n    '$route.hash'(hash) {\n      const wanted = hash.replace('#', '');\n\n      if (wanted && !this.tabs.includes(wanted)) {\n        this.$router.replace({ ...this.$route, hash: `#${ this.active }` });\n      }\n    },\n  },\n\n  mounted() {\n    rememberWorkspace(this.name);\n    this.seen[this.tab] = true;\n    this.refreshTimer = setInterval(() => this.refresh(), REFRESH_MS);\n  },\n\n  beforeUnmount() {\n    clearInterval(this.refreshTimer);\n  },\n\n  methods: {\n    /**\n     * A tab became the active one. Recorded so its content is mounted from here on, and\n     * remembered so the next workspace opens on it.\n     */\n    onTabChanged({ tab }) {\n      this.seen[tab.name] = true;\n      this.active = tab.name;\n      rememberTab(tab.name);\n    },\n\n    async refresh() {\n      this.workspace = await getWorkspace(this.name);\n\n      // Point everything that follows at the cluster this workspace is actually on. It is set\n      // here rather than by the router because a page is about one workspace and every request\n      // it makes is about that workspace's cluster: see setCluster.\n      if (this.workspace?.cluster) {\n        setCluster(this.workspace.cluster);\n      }\n\n      if (!this.workspace) {\n        // Nothing left to poll for. The page is now a banner saying the workspace is gone, and\n        // asking again every five seconds would only repeat the 404 that proved it.\n        clearInterval(this.refreshTimer);\n\n        return;\n      }\n\n      // The sidebar is the workspace list, and this page is where someone watching one would\n      // notice a change, so its poll keeps that list fresh too.\n      listAllWorkspaces().catch(() => {});\n\n      // Only ask for the pod when there could be one: a stopped workspace has none.\n      this.pod = this.workspace.replicas > 0 ? await workspacePod(this.name) || '' : '';\n      // The log's last line, only while the workspace is still coming up. It is the difference\n      // between \"Starting up\" and knowing it is four minutes into an install, and once the\n      // workspace is running it is the terminal's job rather than this page's.\n      this.logTail = this.starting && this.pod ? await workspaceLogTail(this.name, this.pod) : '';\n\n      this.framable = await this.canFrame();\n    },\n\n    /**\n     * Whether the Browser tab has anything in it, which is what decides the tab is there.\n     *\n     * Two different questions, because the two kinds of template frame two different things. A\n     * template with a browser sidecar is asking about the sidecar and not about the workspace:\n     * the browser is worth looking at whatever the workspace is doing, since a workspace that is\n     * still compiling is a page in it that says so.\n     */\n    async canFrame() {\n      const template = templateById(this.workspace?.template);\n\n      if (!template || this.stopped) {\n        return false;\n      }\n\n      const browser = templateBrowser(template);\n\n      if (browser) {\n        return sidecarReady(this.name, browser).catch(() => false);\n      }\n\n      return workspaceServing(this.name, template.port, template.scheme).catch(() => false);\n    },\n\n    async run(action, done) {\n      this.error = '';\n      this.busy = true;\n\n      try {\n        await action();\n        await this.refresh();\n        done(true);\n      } catch (e) {\n        this.error = e.message || String(e);\n        done(false);\n      } finally {\n        this.busy = false;\n      }\n    },\n\n    /**\n     * The one way to start a workspace from this page.\n     *\n     * Start and Stop used to sit on the tab strip, on the argument that they were reachable\n     * from every tab and cost no height; what they actually did was put a button beside four\n     * tab labels that is not a tab. The list is where a workspace is started and stopped, and\n     * the banner that replaces the tabs while it is stopped offers it here.\n     */\n    startFromTab() {\n      return this.run(() => setWorkspaceRunning(this.name, true), () => {});\n    },\n  },\n};\n</script>\n\n<template>\n  <Loading v-if=\"$fetchState.pending\" />\n  <div\n    v-else-if=\"!workspace\"\n    class=\"dev-workspace dev-workspace--message\"\n  >\n    <Banner\n      color=\"warning\"\n      :label=\"`There is no workspace called ${ name }. It may have been deleted.`\"\n    />\n    <RcButton\n      variant=\"secondary\"\n      :to=\"listTo\"\n    >\n      Back to workspaces\n    </RcButton>\n  </div>\n  <div\n    v-else\n    class=\"dev-workspace\"\n  >\n    <Banner\n      v-if=\"error\"\n      color=\"error\"\n      :label=\"error\"\n    />\n\n    <!--\n      A stopped workspace is a banner and nothing else.\n\n      The tabs used to stay, with this same banner inside the Conversations one. Every one of\n      them was empty in a different way: no conversations to talk to, no ports being listened\n      on, no sidecars running, and a browser that is not there. Four tabs whose only content is\n      four ways of saying the workspace is stopped is worse than one sentence and the button\n      that fixes it.\n    -->\n    <Banner\n      v-if=\"stopped\"\n      color=\"info\"\n    >\n      <Row gap=\"4\">\n        <span>This workspace is stopped, so there is nothing to talk to.</span>\n        <RcButton\n          variant=\"secondary\"\n          size=\"small\"\n          :disabled=\"busy\"\n          @click=\"startFromTab\"\n        >\n          Start it\n        </RcButton>\n      </Row>\n    </Banner>\n\n    <Tabbed\n      v-else\n      class=\"dev-workspace__tabs\"\n      :default-tab=\"tab\"\n      @changed=\"onTabChanged\"\n    >\n      <Tab\n        name=\"conversations\"\n        label=\"Conversations\"\n        :weight=\"3\"\n      >\n        <WorkspaceConversations\n          v-if=\"seen.conversations\"\n          :workspace=\"workspace\"\n          :log-tail=\"logTail\"\n        />\n      </Tab>\n\n      <!--\n        Only while there is a browser to frame. Absent rather than dim, because a Browser tab\n        with nothing in it could only explain itself by talking about a sidecar that is started\n        on the Sidecars tab, and a tab whose content is a pointer to another tab is not content.\n      -->\n      <Tab\n        v-if=\"framable\"\n        name=\"browser\"\n        label=\"Browser\"\n        :weight=\"2\"\n      >\n        <WorkspaceBrowser\n          v-if=\"seen.browser\"\n          :workspace=\"workspace\"\n        />\n      </Tab>\n\n      <Tab\n        name=\"ports\"\n        label=\"Ports\"\n        :weight=\"1\"\n      >\n        <WorkspacePorts\n          v-if=\"seen.ports\"\n          :workspace=\"workspace\"\n        />\n      </Tab>\n\n      <Tab\n        name=\"sidecars\"\n        label=\"Sidecars\"\n        :weight=\"0\"\n      >\n        <WorkspaceSidecars\n          v-if=\"seen.sidecars\"\n          :workspace=\"workspace\"\n        />\n      </Tab>\n    </Tabbed>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-workspace {\n    display:        flex;\n    flex-direction: column;\n    // The page is the whole area now that nothing sits above the tabs, and the panes inside it\n    // are a terminal and an iframe, both of which size themselves from their container.\n    height:         100%;\n    min-height:     0;\n\n    &--message {\n      padding: var(--dev-space-5);\n    }\n\n    // The sentence and the button on one line, since the button is what the sentence is about.\n    &__tabs {\n      display:        flex;\n      flex-direction: column;\n      flex:           1 1 auto;\n      min-height:     0;\n      // Tabbed's own class sets `min-width: fit-content`, so without the max the strip grows to\n      // whatever the widest pane wants and takes the page with it.\n      max-width:      100%;\n      // And the flex minimum, which max-width alone does not beat: a flex child's minimum is its\n      // content, so the strip stayed wider than the page and put a horizontal scrollbar under\n      // every tab. Both are needed, which is why the max on its own looked like it worked.\n      min-width:      0;\n\n      // The tab strip is the top edge of the page, so it keeps the shell's border between it\n      // and the content but not the outer frame it would have inside a card.\n      :deep(> .tabs) {\n        border-top:  0;\n        border-left: 0;\n        border-right: 0;\n      }\n\n      // The content is everything below the strip. No padding of its own: a terminal and an\n      // iframe are the two things on it, and both want the whole area.\n      :deep(> .tab-container) {\n        display:        flex;\n        flex-direction: column;\n        flex:           1 1 auto;\n        min-height:     0;\n        padding:        0;\n        border:         0;\n\n        > section {\n          display:        flex;\n          flex-direction: column;\n          flex:           1 1 auto;\n          min-height:     0;\n          // And min-width, for the same reason and the one that is easier to forget: a flex\n          // child's minimum is its content by default, so a pane refuses to be narrower than\n          // what is in it and the page grows a horizontal scrollbar instead of the pane\n          // wrapping. It is what put one under the Sidecars tab.\n          min-width:      0;\n        }\n      }\n    }\n\n  }\n</style>\n",
    "pkg/dev-extension/pages/Workspaces.vue": "<script>\n// The workspaces list: the harness's home page, on Kubernetes.\n//\n// The rows are plain objects rather than Steve models, so this is SortableTable directly\n// instead of ResourceTable: there is no single schema behind a workspace (it is a namespace\n// joined to a Deployment) and nothing for ResourceTable's schema-driven columns to read.\n// Everything else about the table is the shell's, including the state badge and the live age.\nimport SortableTable from '@shell/components/SortableTable';\nimport Loading from '@shell/components/Loading';\nimport { Banner } from '@components/Banner';\nimport { RcButton } from '@components/RcButton';\nimport ConfirmDeleteWorkspace from '../components/ConfirmDeleteWorkspace.vue';\nimport { listAllWorkspaces, setWorkspaceRunning } from '../api';\nimport { lastWorkspace, lastTab } from '../recent';\nimport {\n  DEV_PRODUCT, BLANK_CLUSTER, WORKSPACE_ROUTE, CREATE_ROUTE, DEFAULT_WORKSPACE_TAB\n} from '../config/constants';\n\n// How often the list re-reads the cluster. Workspaces change state without anything on this\n// page doing it (a pull finishes, a pod crashes), and Steve's websocket only carries\n// resources the store is watching, which these are not.\nconst REFRESH_MS = 5000;\n\nexport default {\n  name: 'DevWorkspaces',\n\n  components: {\n    SortableTable, Loading, Banner, RcButton, ConfirmDeleteWorkspace\n  },\n\n  async fetch() {\n    this.rows = await listAllWorkspaces();\n\n    // Straight through to a workspace. This page is the product's landing route, so pressing Dev\n    // in Rancher's rail arrives here, and what somebody wants on arriving is a workspace rather\n    // than a list of them: the one they were in, or failing that the first one there is.\n    //\n    // Which leaves this list on screen in exactly one case, which is the one it is useful in:\n    // there are no workspaces yet, and what it shows is how to make one.\n    //\n    // `replace` rather than `push`, so Back goes where it went before rather than bouncing off\n    // this page and being redirected again.\n    // Unless it was asked for. The redirect makes the landing route useful and would otherwise\n    // make this page unreachable, and it is the only place a workspace can be stopped: a\n    // crash-looping one is exactly when somebody needs it. The sidebar's template heading links\n    // here with this, which is the way back in.\n    const asked = this.$route.query.all !== undefined;\n    const last = lastWorkspace();\n    const going = asked ? null : (this.rows.find((row) => row.name === last) || this.rows[0]);\n\n    if (going) {\n      this.$router.replace({\n        name:   WORKSPACE_ROUTE,\n        params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER, workspace: going.name },\n        hash:   `#${ lastTab() || DEFAULT_WORKSPACE_TAB }`,\n      });\n    }\n  },\n\n  data() {\n    return {\n      rows:         [],\n      error:        '',\n      // The workspace a delete has been asked for, and is waiting on a confirmation for.\n      deleting:     null,\n      // Names with a start or stop in flight, so their buttons cannot be pressed twice\n      // before the list has caught up with the first press.\n      busy:         [],\n      refreshTimer: null,\n      createTo:     { name: CREATE_ROUTE, params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER } },\n      headers:      [\n        {\n          name:          'state',\n          label:         'State',\n          value:         'state',\n          sort:          ['state', 'name'],\n          formatter:     'BadgeStateFormatter',\n          // `arbitrary` is what lets the formatter colour a bare string; without it it wants\n          // a Steve model with a stateBackground of its own.\n          formatterOpts: { arbitrary: true },\n          width:         120,\n        },\n        {\n          name: 'name', label: 'Name', value: 'name', sort: ['name']\n        },\n        {\n          name: 'template', label: 'Template', value: 'templateLabel', sort: ['templateLabel', 'name']\n        },\n        {\n          name: 'namespace', label: 'Namespace', value: 'namespace', sort: ['namespace']\n        },\n        {\n          name:      'age',\n          label:     'Age',\n          value:     'createdAt',\n          sort:      ['createdAt:desc'],\n          formatter: 'LiveDate',\n          width:     100,\n        },\n        {\n          name: 'actions', label: '', align: 'right', width: 230\n        },\n      ],\n    };\n  },\n\n  mounted() {\n    this.refreshTimer = setInterval(() => this.refresh(), REFRESH_MS);\n  },\n\n  beforeUnmount() {\n    clearInterval(this.refreshTimer);\n  },\n\n  methods: {\n    workspaceTo(workspace) {\n      return {\n        name:   WORKSPACE_ROUTE,\n        params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER, workspace: workspace.name },\n      };\n    },\n\n    // The poll, deliberately quieter than $fetch: a failure here is usually a request that\n    // raced a page change, and replacing the table with an error because one poll missed\n    // would be worse than showing the previous rows for another five seconds.\n    async refresh() {\n      try {\n        this.rows = await listAllWorkspaces();\n      } catch { /* the next poll will say if it is more than a blip */ }\n    },\n\n    isBusy(workspace) {\n      return this.busy.includes(workspace.name);\n    },\n\n    async run(workspace, action) {\n      this.error = '';\n      this.busy = [...this.busy, workspace.name];\n\n      try {\n        await action();\n        await this.refresh();\n      } catch (e) {\n        this.error = e.message || String(e);\n      } finally {\n        this.busy = this.busy.filter((name) => name !== workspace.name);\n      }\n    },\n\n    start(workspace) {\n      return this.run(workspace, () => setWorkspaceRunning(workspace.name, true));\n    },\n\n    stop(workspace) {\n      return this.run(workspace, () => setWorkspaceRunning(workspace.name, false));\n    },\n\n    // Deleting a workspace deletes its namespace, which is not something to do on a stray\n    // click, so it is asked about by name first.\n    confirmDelete(workspace) {\n      this.error = '';\n      this.deleting = workspace;\n    },\n\n    onDeleted() {\n      this.deleting = null;\n      this.refresh();\n    },\n\n    onDeleteError(message) {\n      this.deleting = null;\n      this.error = message;\n    },\n  },\n};\n</script>\n\n<template>\n  <Loading v-if=\"$fetchState.pending\" />\n  <div\n    v-else\n    class=\"dev-workspaces\"\n  >\n    <header>\n      <div>\n        <h1>Workspaces</h1>\n        <p class=\"subheader\">\n          Every workspace is a namespace with a Deployment and a Service in it. Starting and\n          stopping scales that Deployment; deleting removes the namespace.\n        </p>\n      </div>\n      <RcButton\n        variant=\"primary\"\n        :to=\"createTo\"\n      >\n        Create\n      </RcButton>\n    </header>\n\n    <Banner\n      v-if=\"$fetchState.error\"\n      color=\"error\"\n      :label=\"`Could not list workspaces: ${ $fetchState.error }`\"\n    />\n    <Banner\n      v-else-if=\"error\"\n      color=\"error\"\n      :label=\"error\"\n    />\n\n    <SortableTable\n      :headers=\"headers\"\n      :rows=\"rows\"\n      key-field=\"name\"\n      default-sort-by=\"name\"\n      :table-actions=\"false\"\n      :row-actions=\"false\"\n      :paging=\"true\"\n    >\n      <template #cell:name=\"{ row }\">\n        <router-link :to=\"workspaceTo(row)\">\n          {{ row.name }}\n        </router-link>\n      </template>\n\n      <template #cell:actions=\"{ row }\">\n        <div class=\"dev-workspaces__actions\">\n          <RcButton\n            v-if=\"row.state === 'stopped'\"\n            variant=\"tertiary\"\n            size=\"small\"\n            left-icon=\"play\"\n            :disabled=\"isBusy(row)\"\n            @click=\"start(row)\"\n          >\n            Start\n          </RcButton>\n          <RcButton\n            v-else\n            variant=\"tertiary\"\n            size=\"small\"\n            left-icon=\"pause\"\n            :disabled=\"isBusy(row) || row.state === 'removing'\"\n            @click=\"stop(row)\"\n          >\n            Stop\n          </RcButton>\n          <RcButton\n            variant=\"tertiary\"\n            size=\"small\"\n            left-icon=\"terminal\"\n            :to=\"workspaceTo(row)\"\n          >\n            Open\n          </RcButton>\n          <RcButton\n            variant=\"tertiary\"\n            size=\"small\"\n            left-icon=\"trash\"\n            :disabled=\"row.state === 'removing'\"\n            @click=\"confirmDelete(row)\"\n          >\n            Delete\n          </RcButton>\n        </div>\n      </template>\n\n      <template #no-rows>\n        <tr>\n          <td :colspan=\"headers.length\">\n            <span class=\"text-muted\">There are no workspaces yet. Create one to get started.</span>\n          </td>\n        </tr>\n      </template>\n    </SortableTable>\n\n    <ConfirmDeleteWorkspace\n      v-if=\"deleting\"\n      :workspace=\"deleting\"\n      @close=\"deleting = null\"\n      @deleted=\"onDeleted\"\n      @error=\"onDeleteError\"\n    />\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n  .dev-workspaces {\n    header {\n      display:        flex;\n      align-items:    flex-start;\n      gap:            var(--dev-space-5);\n      margin-bottom:  var(--dev-space-5);\n\n      h1 {\n        margin-bottom: 0;\n      }\n\n      .subheader {\n        max-width: 80ch;\n        margin:    var(--dev-space-2) 0 0 0;\n        color:     var(--muted);\n      }\n\n      // Push the create button to the far edge, where every other Rancher list page has it.\n      > :last-child {\n        margin-left: auto;\n      }\n    }\n\n    &__actions {\n      display:         flex;\n      gap:             var(--dev-space-3);\n      justify-content: flex-end;\n    }\n  }\n</style>\n",
    "pkg/dev-extension/product.ts": "import { IPlugin } from '@shell/core/types';\nimport { ensureDevRbac, ensureWorkspaceApi } from './api';\nimport {\n  PRODUCT_NAME, CUSTOM_PAGE_NAME, BLANK_CLUSTER, HOME_ROUTE,\n  EXPLORER_PRODUCT, FLOOF_PAGE, FLOOF_ROUTE,\n  DEV_PRODUCT, WORKSPACES_ROUTE\n} from './config/constants';\n\n// `store` is the raw Vuex store the extension manager hands to every product init, and\n// $plugin.DSL takes it as `any`. There is no narrower type to reach for.\n// eslint-disable-next-line @typescript-eslint/no-explicit-any\nexport function init($plugin: IPlugin, store: any) {\n  const { product, basicType, virtualType } = $plugin.DSL(store, PRODUCT_NAME);\n\n  // `public` is what makes the product visible without a session, and the shell honours it at\n  // runtime, but TypeMapProduct does not declare it. The dev build only warns; the production\n  // build that `hmr: off` mode needs treats it as an error, so the literal is widened here.\n  const productOpts: Record<string, unknown> = {\n    icon:                'flask',\n    public:              true,\n    inStore:             'management',\n    weight:              100,\n    showClusterSwitcher: false,\n    to:                  {\n      name:   HOME_ROUTE,\n      params: { product: PRODUCT_NAME, cluster: BLANK_CLUSTER }\n    }\n  };\n\n  product(productOpts);\n\n  virtualType({\n    name:  CUSTOM_PAGE_NAME,\n    label: 'Live Reload Demo',\n    route: {\n      name:   HOME_ROUTE,\n      params: { product: PRODUCT_NAME, cluster: BLANK_CLUSTER }\n    },\n    weight: 100\n  });\n\n  basicType([CUSTOM_PAGE_NAME]);\n\n  // Floof goes into Rancher's Cluster Explorer, not into this product.\n  //\n  // A second DSL() call scoped to 'explorer' is how an extension adds to a product it does\n  // not own - the same virtualType/basicType calls, aimed at someone else's nav. `group:\n  // 'Root'` puts it at the top level alongside Cluster and Workloads rather than inside a\n  // resource group, matching how the shell registers its own non-resource pages.\n  const explorer = $plugin.DSL(store, EXPLORER_PRODUCT);\n\n  // `group`, `icon` and `exact` are all honoured by the nav at runtime and are what the shell's\n  // own pages set, but ConfigureVirtualTypeOptions declares none of them. Spread rather than\n  // written into the literal, because an excess property is an error where a spread of one is\n  // not, and the production build that `hmr: off` needs treats it as an error. Same reason as\n  // `public` above.\n  const navOnly = { group: 'Root', icon: 'folder', exact: true } as Record<string, unknown>;\n\n  explorer.virtualType({\n    name:       FLOOF_PAGE,\n    label:      'Floof',\n    namespaced: false,\n    weight:     99,\n    route:      { name: FLOOF_ROUTE },\n    ...navOnly\n  });\n\n  explorer.basicType([FLOOF_PAGE], 'Root');\n\n  devProduct($plugin, store);\n}\n\n/**\n * The Dev product: the Claude Harness on Kubernetes.\n *\n * A second `product()` from a second DSL() call, which is how one extension registers two\n * unrelated products. It owns no cluster, so it takes BLANK_CLUSTER and hides the cluster\n * switcher, exactly as the demo product above does.\n *\n * It registers no nav entries, because it does not use Rancher's nav: its pages are children of\n * a page template of their own which draws the sidebar (see routing/index.ts). The `product()`\n * call still matters, since that is what puts Dev in the product switcher and tells the header\n * whose page this is.\n */\n// eslint-disable-next-line @typescript-eslint/no-explicit-any\nfunction devProduct($plugin: IPlugin, store: any) {\n  const { product, basicType, virtualType } = $plugin.DSL(store, DEV_PRODUCT);\n\n  // See the note above productOpts: `public` is honoured at runtime but not declared on\n  // TypeMapProduct, so the literal is widened for the production build's sake.\n  const devOpts: Record<string, unknown> = {\n    icon:                'terminal',\n    public:              true,\n    inStore:             'management',\n    weight:              99,\n    showClusterSwitcher: false,\n    to:                  {\n      name:   WORKSPACES_ROUTE,\n      params: { product: DEV_PRODUCT, cluster: BLANK_CLUSTER }\n    }\n  };\n\n  product(devOpts);\n\n  // No virtualTypes and no basicTypes for this product: its navigation is its own sidebar\n  // (see components/DevSidebar.vue and pages/DevShell.vue), and registering entries that\n  // nothing renders would leave two descriptions of the same list.\n\n  // The identities the terminals run as, and the namespace holding the credentials they share.\n  // Create-if-missing, so a cluster that already has them keeps what it has, and quiet, for the\n  // same reason the fetch above is: this runs for every user on every load.\n  ensureDevRbac().catch(() => {});\n\n  // The workspace API, for everything that is not a person: an action with no browser and no\n  // Rancher session can still ask for a workspace. Same rule as above - create if missing, quiet\n  // if the person looking cannot create any of it. See ensureWorkspaceApi.\n  ensureWorkspaceApi().catch(() => {});\n}\n",
    "pkg/dev-extension/prompts.ts": "/**\n * The prompts a queued conversation opens with, which belong to the person rather than to the\n * product.\n *\n * An action on My Work does two things: it makes the workspace for a pull request, and it starts\n * a conversation in it that is already about that pull request. The second half is a prompt, and\n * a prompt is exactly the kind of thing one person wants worded differently from the next, so\n * these are defaults rather than rules: they are copied into a per-user ConfigMap the first time\n * Settings is opened, and everything after that reads what is in there.\n *\n * That is the same arrangement the harness has for its shared skills, where the text an agent\n * runs on is browsable and editable rather than compiled in.\n *\n * The placeholders are the ones an action can actually fill in. They are deliberately few: a\n * prompt that needs a dozen substitutions is a program, and this is a sentence.\n *\n *   {{repo}}   rancher/dashboard\n *   {{pr}}     18536\n *   {{issue}}  18500, or an empty string when the pull request closes none\n *   {{title}}  the pull request's title\n *   {{url}}    the pull request's address\n */\nexport interface DevPrompt {\n  id: string;\n  label: string;\n  /** What the action is for, shown under the field in Settings. */\n  help: string;\n  text: string;\n}\n\nexport const DEFAULT_PROMPTS: DevPrompt[] = [\n  {\n    id:    'review-pr',\n    label: 'Review a pull request',\n    help:  'Queued by Review on My Work. The workspace is made for the pull request first, so the conversation opens in a checkout of it.',\n    text:  [\n      'Review {{url}} ({{repo}}#{{pr}}): \"{{title}}\".',\n      '',\n      'This is a placeholder prompt. Edit it in Settings to say what a review should actually do.',\n      'Read the diff, then leave your findings as pending inline comments rather than submitting.',\n    ].join('\\n'),\n  },\n  {\n    id:    'fix-issue',\n    label: 'Fix an issue',\n    help:  'Queued when a workspace is started for an issue rather than for a pull request.',\n    text:  [\n      'Fix issue #{{issue}} in {{repo}}.',\n      '',\n      'This is a placeholder prompt. Edit it in Settings to say what fixing an issue should involve:',\n      'reproducing it first, what counts as verified, and whether to open a pull request at the end.',\n    ].join('\\n'),\n  },\n  {\n    id:    'fix-dependabot',\n    label: 'Fix a Dependabot alert',\n    help:  'Queued by Start fix on a Dependabot alert. One advisory can raise several alerts, so the prompt is about the advisory rather than about one of them.',\n    text:  [\n      'Resolve the Dependabot advisory {{ghsa}} ({{cve}}) in {{repo}}: \"{{title}}\".',\n      '',\n      'It affects {{package}}, across {{files}} file(s). The fix is {{fix}}.',\n      '',\n      'This is a placeholder prompt. Edit it in Settings to say what resolving one should involve:',\n      'whether to bump a direct dependency or a resolution, and what to check before opening a PR.',\n    ].join('\\n'),\n  },\n];\n\n/** Fill a prompt in. An unknown placeholder is left alone rather than replaced with 'undefined'. */\nexport function fillPrompt(text: string, values: Record<string, string>): string {\n  return text.replace(/{{(\\w+)}}/g, (whole, key) => (key in values ? values[key] : whole));\n}\n",
    "pkg/dev-extension/rancher-sidecar.ts": "/**\n * A real Rancher for a workspace, as `deploy/closet/templates/rancher.yaml` already does it.\n *\n * The obvious approach does not work and it is worth writing down why, because it is the reason\n * everything below is shaped the way it is. `rancher/rancher` is the docker-style image with an\n * embedded k3s in it, and a pod running it fights the host cluster over cgroups: here a\n * privileged pod gets the node's own cgroup root rather than a namespace of its own, so its\n * kubelet is killed within seconds. That is what a previous pass investigated and concluded was\n * impossible, and it is not what this does.\n *\n * What this does instead is the topology Rancher actually supports. A manager pod helm-installs a\n * **vcluster** (a k3s control plane of its own, whose workloads are synced back to this cluster as\n * ordinary pods), then helm-installs cert-manager and rancher-latest *inside* that vcluster, which\n * is a completely ordinary Rancher installation on a completely ordinary cluster. The vcluster\n * replicates the rancher Service back out to this namespace, and the manager relays :443 to it, so\n * the sidecar's own Service points at the manager pod and everything downstream of it is unchanged.\n *\n * Every value here is the chart's rather than a fresh opinion: the vcluster version, the k8s\n * version kept below the rancher chart's ceiling, the hostPath data volume (this cluster has no\n * StorageClass, so a PVC would never bind), the watchdog, the order of the installs, their\n * timeouts, and the `role: relay` label that keeps the manager pod distinguishable from the\n * rancher pod the vcluster syncs into the same namespace with an `app: rancher` label of its own.\n *\n * The one thing added to the chart's script is the bootstrap, and there is a note on it below.\n */\n\n/**\n * Where the vcluster's control plane keeps its data.\n *\n * Its own base rather than the workspace's, for two reasons: the workspace's directory is mounted\n * into the workspace container as `/workspace`, so a vcluster's etcd would appear inside somebody's\n * checkout, and a hostPath outlives the namespace that used it, so having one place to clean up is\n * worth more than having it next to the thing that made it.\n */\nexport const SIDECAR_HOST_PATH = '/var/lib/rancher/dev-sidecars';\n\n/**\n * The vcluster's own values, from the chart.\n *\n * `volumeClaim.enabled: false` plus a hostPath dataVolume is how the chart handles a cluster with\n * no StorageClass, which is this one: a PVC would sit Pending for ever and the control plane would\n * never start.\n *\n * `replicateServices.toHost` is what makes the rest possible. The rancher Service inside the\n * vcluster is copied out into this namespace as `rancher-vc`, and that is what the relay dials.\n *\n * `replicateServices.fromHost` is the obvious way to give Rancher an address for the auth sidecars,\n * and it is not used here. It was tried and it cannot work with this manager. The keycloak and\n * openldap sidecars are ordinary Deployments in this namespace, so a pod inside the vcluster cannot\n * resolve them: the vcluster's CoreDNS is authoritative for `*.svc.cluster.local` and has never\n * heard of them. But adding a `fromHost` entry makes the chart render a **ClusterRole** and a\n * ClusterRoleBinding (services and endpoints, get/watch/list, cluster-wide), because the chart\n * cannot know that the source namespace is the vcluster's own. Measured with `helm template`: no\n * ClusterRole without the entry, two with it. The manager's Role is deliberately namespaced, so the\n * upgrade fails at the point helm reads that object:\n *\n *   Error: UPGRADE FAILED: could not get information about the resource ClusterRole\n *   \"vc-vc-v-dev-demo\": clusterroles.rbac.authorization.k8s.io is forbidden\n *\n * Widening the manager to create ClusterRoles is not a smaller problem than the one being solved:\n * a namespaced account that can write cluster-scoped RBAC is a cluster-admin account with extra\n * steps. So the address Rancher is given is the host Service's ClusterIP instead, which needs no\n * DNS and no rights at all: a vcluster's pods are ordinary pods on this node, so kube-proxy routes\n * them to a host ClusterIP like anything else. Proven from the rancher pod inside the vcluster:\n * a connection to the openldap Service's ClusterIP on 389 is accepted (curl exit 52, an answer that\n * is not HTTP) while an unused port on the same address times out (exit 28). See AUTH_SCRIPT.\n */\nexport const VCLUSTER_VALUES = `controlPlane:\n  distro:\n    k8s:\n      enabled: true\n      # Kept below the rancher chart's kubeVersion ceiling\n      version: v1.34.1\n  statefulSet:\n    persistence:\n      volumeClaim:\n        enabled: false\n      dataVolume:\n        - name: data\n          hostPath:\n            path: {{dataPath}}\n            type: DirectoryOrCreate\nnetworking:\n  replicateServices:\n    toHost:\n      - from: cattle-system/rancher\n        to: rancher-vc\n`;\n\n/**\n * What the manager pod runs, start to finish. The chart's `manage.sh`, plus a bootstrap.\n *\n * The ordering and the waits are the chart's and are not rearranged. They exist because someone\n * hit the race they prevent:\n *\n *   - the watchdog goes first, before any install. A rollout's old pod runs the preStop pause at\n *     any moment, and it would otherwise scale the vcluster to nothing in the middle of this pod's\n *     install. It keeps the vcluster up for as long as this manager lives, so a real stop (which\n *     removes the manager) still pauses it.\n *   - `--wait` on the vcluster install, then a wait for the `vc-vc` Secret, then a wait for the\n *     API inside it to answer. The Secret carries the kubeconfig and appears after the install\n *     reports success; the API answers some time after that.\n *   - cert-manager before rancher, with its CRDs, because the rancher chart's issuer needs them.\n *\n * The kubeconfig rewrite is the chart's too: the config in the Secret points at localhost:8443,\n * which is right inside the control plane's pod and wrong everywhere else, and its CA is for a\n * name this pod does not dial.\n */\nexport const MANAGE_SCRIPT = `#!/bin/sh\nset -x\n# openldap-clients is for auth.sh: seeding a directory needs an LDAP client, and this pod is the\n# only one that can reach OpenLDAP and hold the admin password at the same time.\napk add --no-cache socat curl openldap-clients || true\n\n# Nothing is installed without a password to install it with.\n#\n# The reference to it is optional, so an absent or cleared key arrives as an empty variable rather\n# than a failure to start. Rancher would then be installed with an empty bootstrapPassword, which\n# makes it generate one of its own, and everything downstream would be trying to log in with a\n# password that Rancher has never heard of. Refusing here is the difference between a sidecar that\n# says what is wrong and a Rancher nobody can get into.\nif [ -z \"$CATTLE_BOOTSTRAP_PASSWORD\" ]; then\n  echo \"refusing to install: RANCHER_BOOTSTRAP_PASSWORD is not set in the secret store\"\n  echo \"set it in Settings, then start this sidecar again\"\n  exit 1\nfi\n\n# Watchdog (started first): a rollout's old pod runs the preStop pause and can race this pod's\n# install at any phase. Keep the vcluster scaled up while this manager lives; a real stop removes\n# the manager, so the pause sticks.\n( while true; do kubectl -n \"$NS\" scale deploy vc --replicas=1 >/dev/null 2>&1 || true; sleep 30; done ) &\n\nhelm repo add loft https://charts.loft.sh\nhelm repo add jetstack https://charts.jetstack.io\nhelm repo add rancher-latest https://releases.rancher.com/server-charts/latest\nhelm repo update\n\nhelm upgrade --install vc loft/vcluster -n \"$NS\" \\\\\n  --version \"$VCLUSTER_VERSION\" -f /scripts/vcluster-values.yaml \\\\\n  --wait --timeout 10m\n\nuntil kubectl -n \"$NS\" get secret vc-vc; do sleep 5; done\nkubectl -n \"$NS\" get secret vc-vc -o jsonpath='{.data.config}' | base64 -d \\\\\n  | sed -e \"s|server: https://localhost:8443|server: https://vc.$NS.svc:443|\" \\\\\n        -e \"s|certificate-authority-data:.*|insecure-skip-tls-verify: true|\" > /tmp/kc\nexport KUBECONFIG=/tmp/kc\nuntil kubectl get ns default; do sleep 5; done\n\nhelm upgrade --install cert-manager jetstack/cert-manager \\\\\n  -n cert-manager --create-namespace \\\\\n  --set crds.enabled=true --wait --timeout 10m\n\n# The password goes in through a file rather than on the command line, and the file is written\n# with tracing off. set -x is what makes this script readable while it runs, and it also prints\n# every argument of every command, so the chart's --set bootstrapPassword=... puts the generated\n# password into kubectl logs, readable by anything with pod/log in this namespace, and onto the\n# sidecar card, which shows the last line while a sidecar is starting. The secretKeyRef keeps it\n# out of the pod spec; this is the other half of the same promise.\nset +x\nprintf 'bootstrapPassword: %s\\\\n' \"$CATTLE_BOOTSTRAP_PASSWORD\" > /tmp/rancher-values.yaml\nchmod 600 /tmp/rancher-values.yaml\nset -x\n\n# The two things the card's gear sets, and the only reason this is built up rather than written\n# out: an empty RANCHER_TAG has to mean \"whatever the chart installs\" rather than an image tag of\n# the empty string, which is a pod that cannot pull.\nEXTRA=\"\"\n\nif [ -n \"$RANCHER_TAG\" ]; then\n  EXTRA=\"$EXTRA --set rancherImageTag=$RANCHER_TAG\"\nfi\n\n# Prime is a UI brand, set as an environment variable on the Rancher container. The chart's own\n# way to pass one through is extraEnv, which is a list, so it is indexed.\nif [ -n \"$RANCHER_PRIME\" ]; then\n  EXTRA=\"$EXTRA --set extraEnv[0].name=CATTLE_BASE_UI_BRAND --set extraEnv[0].value=suse\"\nfi\n\nhelm upgrade --install rancher rancher-latest/rancher \\\\\n  -n cattle-system --create-namespace \\\\\n  --set hostname=\"$RANCHER_HOSTNAME\" --set replicas=1 \\\\\n  $EXTRA \\\\\n  -f /tmp/rancher-values.yaml \\\\\n  --wait --timeout 20m\n\nunset KUBECONFIG\n\n# The relay, before the bootstrap rather than after it. The bootstrap talks to Rancher through\n# this pod's own network either way, but starting the listener first is what lets the readiness\n# probe pass and the card say Running while the bootstrap finishes, instead of holding the whole\n# sidecar in Starting for the sake of three settings.\nsocat TCP-LISTEN:443,fork,reuseaddr \"TCP:rancher-vc.$NS.svc:443\" &\n\n# ---- bootstrap: a Rancher you log into, not a setup wizard ----\n#\n# The steps are the closet api's (see the closet project's CLAUDE.md): wait for the API, log in with the\n# generated bootstrap password, turn off the first-login wizard, set the server URL and put the\n# agent TLS mode on the system store. It runs here rather than anywhere else because this is the\n# only place that already holds the password, by secretKeyRef, and never renders it; and because\n# it is idempotent, so the manager restarting re-applies it exactly as the closet's \"once per\n# container\" does.\nRURL=\"https://rancher-vc.$NS.svc\"\n\nuntil curl -sk -o /dev/null --max-time 10 \"$RURL/ping\"; do sleep 5; done\n\n# Tracing off for the rest of it. Every command from here carries either the password or the\n# session token it returns, and neither belongs in a log.\nset +x\n\n# Writes the body to /tmp/login.json and prints the status, because the two failures need\n# different answers and the body alone cannot tell them apart.\nlogin() {\n  curl -sk --max-time 20 -o /tmp/login.json -w '%{http_code}' \\\\\n    -X POST \"$RURL/v3-public/localProviders/local?action=login\" \\\\\n    -H 'content-type: application/json' \\\\\n    -d \"{\\\\\"username\\\\\":\\\\\"admin\\\\\",\\\\\"password\\\\\":\\\\\"$1\\\\\"}\"\n}\n\ntoken_from_login() {\n  tr ',' '\\\\n' < /tmp/login.json | sed -n 's/.*\"token\":\"\\\\([^\"]*\\\\)\".*/\\\\1/p' | head -1\n}\n\nTOKEN=\"\"\ni=0\nwhile [ $i -lt 60 ]; do\n  CODE=$(login \"$CATTLE_BOOTSTRAP_PASSWORD\")\n\n  if [ \"$CODE\" = \"200\" ] || [ \"$CODE\" = \"201\" ]; then\n    TOKEN=$(token_from_login)\n    break\n  fi\n\n  # 401 is Rancher answering, and answering that this password is not its password. Waiting does\n  # not change that, so the loop stops and the reset below runs. Retrying it to the end of the\n  # count is how a rotated password turned into twenty-five minutes of a sidecar that looked fine\n  # and was not: the retries are for a Rancher that is still starting, which is a refused\n  # connection or a 5xx, not a considered no.\n  if [ \"$CODE\" = \"401\" ]; then\n    break\n  fi\n\n  sleep 5\n  i=$((i + 1))\ndone\n\n# The password in the store is only the password Rancher has if this Rancher was installed with\n# it. The bootstrapPassword value applies at install and never again, so a Rancher that exists\n# keeps whatever it was given the first time: rotate the key in the store and every login here\n# fails, silently, and the value Settings shows is one nothing accepts.\n#\n# So when the login fails against a Rancher that is answering, the password is reset to the store's\n# rather than left disagreeing with it. reset-password is Rancher's own recovery path and prints\n# a working password; that is used once, to set ours, and never stored anywhere.\n# Only on a considered 401, and only when there is a password to put back.\n#\n# reset-password changes the admin password to a fresh random string as a side effect of being\n# run. If that string is then not set to anything, it exists in one shell variable in one\n# container and nowhere else: not echoed, not written back, kept out of the trace by set +x. The\n# version gated on an empty token reached that from three directions - a cleared key, a 200 with\n# an unexpected body, and the loop simply running out - and each of them ended with a Rancher\n# whose password nobody had.\nif [ -z \"$TOKEN\" ] && [ \"$CODE\" = \"401\" ]; then\n  echo \"admin login failed; resetting the password to the one in the store\"\n  RESET=$(kubectl --kubeconfig /tmp/kc -n cattle-system exec deploy/rancher -- reset-password 2>/dev/null | tail -1 | tr -d '[:space:]')\n\n  if [ -n \"$RESET\" ]; then\n    login \"$RESET\" > /dev/null\n    TEMP=$(token_from_login)\n    USERID=$(curl -sk --max-time 20 -H \"Authorization: Bearer $TEMP\" \"$RURL/v3/users?me=true\" \\\\\n      | tr ',' '\\\\n' | sed -n 's/.*\"id\":\"\\\\(user-[^\"]*\\\\)\".*/\\\\1/p' | head -1)\n\n    if [ -n \"$TEMP\" ] && [ -n \"$USERID\" ]; then\n      # setpassword on the user, not changepassword. changepassword exists here only as a\n      # collection action and answers 422 InvalidAction on a user id; setpassword is the one that\n      # takes a user, and it also clears the mustChangePassword flag reset-password sets, which\n      # would otherwise stop the next login at a change-your-password screen.\n      SET=$(curl -sk --max-time 20 -X POST \"$RURL/v3/users/$USERID?action=setpassword\" \\\\\n        -H \"Authorization: Bearer $TEMP\" -H 'content-type: application/json' \\\\\n        -d \"{\\\\\"newPassword\\\\\":\\\\\"$CATTLE_BOOTSTRAP_PASSWORD\\\\\"}\" \\\\\n        -o /dev/null -w '%{http_code}')\n      echo \"password reset $SET\"\n\n      # Read, not merely printed. A status that only ever went into curl's -w was a status nothing\n      # acted on, so a rejected setpassword looked exactly like a successful one and the admin\n      # password stayed at the value reset-password had just invented.\n      case \"$SET\" in\n        2*)\n          CODE=$(login \"$CATTLE_BOOTSTRAP_PASSWORD\")\n\n          if [ \"$CODE\" = \"200\" ] || [ \"$CODE\" = \"201\" ]; then\n            TOKEN=$(token_from_login)\n          fi\n          ;;\n        *)\n          echo \"SETTING THE ADMIN PASSWORD FAILED ($SET).\"\n          echo \"This Rancher's admin password was changed by reset-password and is not the one in\"\n          echo \"the secret store. To get back in, run reset-password again and use what it prints:\"\n          echo \"  kubectl -n cattle-system exec deploy/rancher -- reset-password\"\n          ;;\n      esac\n    fi\n  fi\nfi\n\nif [ -n \"$TOKEN\" ]; then\n  for pair in \"first-login=false\" \"server-url=$RURL\" \"agent-tls-mode=system-store\"; do\n    name=\\${pair%%=*}\n    value=\\${pair#*=}\n    curl -sk --max-time 20 -X PUT \"$RURL/v3/settings/$name\" \\\\\n      -H \"Authorization: Bearer $TOKEN\" -H 'content-type: application/json' \\\\\n      -d \"{\\\\\"name\\\\\":\\\\\"$name\\\\\",\\\\\"value\\\\\":\\\\\"$value\\\\\"}\" \\\\\n      -o /dev/null -w \"bootstrap $name %{http_code}\\\\n\"\n  done\n  # The cloud credentials this person has set, put into this Rancher so a cluster can be\n  # provisioned without typing them in again. The closet does the same at start, and for the same\n  # reason: they are the workspace's own copy of a credential that already exists, not a new one.\n  #\n  # Only where both halves of a credential are set. A cloud credential with one of its two keys\n  # is one Rancher accepts and every provisioning attempt then fails on, which is worse than not\n  # having it: the failure arrives minutes later and names something else.\n  if [ -n \"$AWS_ACCESS_KEY\" ] && [ -n \"$AWS_SECRET_KEY\" ]; then\n    # The name is fixed, so this is the same credential on every restart rather than a new one\n    # each time. Rancher generates the id, so an existing one is found by name and left alone.\n    if curl -sk --max-time 20 -H \"Authorization: Bearer $TOKEN\" \"$RURL/v3/cloudcredentials\" \\\n      | grep -q '\"name\":\"aws\"'; then\n      echo \"bootstrap aws credential already there\"\n    else\n      set +x\n      cat > /tmp/aws-cred.json <<JSON\n{\"type\":\"provisioning.cattle.io/cloud-credential\",\"name\":\"aws\",\n \"description\":\"From the workspace's own settings\",\n \"amazonec2credentialConfig\":{\"accessKey\":\"$AWS_ACCESS_KEY\",\"secretKey\":\"$AWS_SECRET_KEY\",\"defaultRegion\":\"\\${AWS_DEFAULT_REGION:-us-west-2}\"}}\nJSON\n      chmod 600 /tmp/aws-cred.json\n      set -x\n\n      curl -sk --max-time 20 -X POST \"$RURL/v3/cloudcredentials\" \\\n        -H \"Authorization: Bearer $TOKEN\" -H 'content-type: application/json' \\\n        -d @/tmp/aws-cred.json -o /dev/null -w \"bootstrap aws credential %{http_code}\\n\"\n\n      rm -f /tmp/aws-cred.json\n    fi\n  fi\n\n  echo \"bootstrap done\"\nelse\n  echo \"bootstrap skipped: could not log in as admin\"\nfi\n\n# The auth provider the workspace asked for, applied and then kept applied. Separate script and a\n# loop of its own, because it answers to a ConfigMap somebody edits while this pod runs, where\n# everything above happens once and is finished.\nsh /scripts/auth.sh &\n\nwait\n`;\n\n/**\n * The reconciler behind the Sidecars tab's auth row.\n *\n * The shape is the closet's, moved from its api container to here: one provider at a time, applying\n * one disables the others, and the switch is a stored choice rather than a call, so a Rancher that\n * is reinstalled comes back with the same provider. What has changed is where the choice lives. The\n * closet keeps it in `.env` beside a docker socket; there is no such place here, so it is a\n * ConfigMap in the workspace's namespace, which the tab can write and this can read.\n *\n * It runs in the manager and not in the browser, and that is not a preference. Every call below\n * needs an admin token for a Rancher that answers only inside this namespace. The browser reaches\n * that Rancher through the apiserver's service proxy, and its Authorization header belongs to the\n * Rancher this product is served from: there is no second one to send. The manager already holds\n * the password by secretKeyRef, already reaches Keycloak's admin API and OpenLDAP's port, and is\n * already where the first bootstrap happens.\n *\n * Status goes back into the same ConfigMap, so the card can say what happened without holding a\n * token either.\n */\nexport const AUTH_SCRIPT = `#!/bin/sh\n# Tracing off for all of it: every call carries a password or a token.\nCM=dev-auth\nRURL=\"https://rancher-vc.$NS.svc\"\n\n# Two addresses for each provider, and they are not interchangeable.\n#\n#   *_SEED is how this pod reaches it: an ordinary Service name in this namespace, used to create a\n#   realm or a directory entry.\n#   what Rancher is given is different, because Rancher runs inside the vcluster and its DNS is not\n#   this cluster's. For LDAP that is the host Service's ClusterIP, looked up below (see\n#   VCLUSTER_VALUES for why it is not a replicated Service). For OIDC it is the node's address,\n#   because the browser is part of that exchange and the node is the only address both can use.\nKC_SEED=\"http://$NS-keycloak.$NS.svc:8080\"\nLDAP_SEED=\"$NS-openldap.$NS.svc\"\nLDAP_BASE=\"dc=dev,dc=local\"\nLDAP_ADMIN=\"cn=admin,dc=dev,dc=local\"\n\nnow() { date -u +%Y-%m-%dT%H:%M:%SZ; }\n\n# Status back to the object the request came from, so the card reads the outcome from the same\n# place it wrote the request. Message stays plain text: it goes through a JSON merge patch.\nsay() {\n  kubectl -n \"$NS\" patch cm \"$CM\" --type merge \\\\\n    -p \"{\\\\\"data\\\\\":{\\\\\"applied\\\\\":\\\\\"$1\\\\\",\\\\\"message\\\\\":\\\\\"$2\\\\\",\\\\\"at\\\\\":\\\\\"$(now)\\\\\"}}\" >/dev/null 2>&1\n  echo \"auth: [$1] $2\"\n}\n\nadmin_token() {\n  curl -sk --max-time 20 -o /tmp/auth-login.json \\\\\n    -X POST \"$RURL/v3-public/localProviders/local?action=login\" \\\\\n    -H 'content-type: application/json' \\\\\n    -d \"{\\\\\"username\\\\\":\\\\\"admin\\\\\",\\\\\"password\\\\\":\\\\\"$CATTLE_BOOTSTRAP_PASSWORD\\\\\"}\" >/dev/null 2>&1\n  tr ',' '\\\\n' < /tmp/auth-login.json | sed -n 's/.*\"token\":\"\\\\([^\"]*\\\\)\".*/\\\\1/p' | head -1\n}\n\n# Rancher enables one provider at a time, so applying one is also disabling the other. Reading\n# first, because disable on an already-disabled provider is an error rather than a no-op.\ndisable_provider() {\n  if curl -sk --max-time 20 -H \"Authorization: Bearer $TOKEN\" \"$RURL/v3/$1/$2\" | grep -q '\"enabled\":true'; then\n    curl -sk --max-time 20 -o /dev/null -X POST -H \"Authorization: Bearer $TOKEN\" \"$RURL/v3/$1/$2?action=disable\"\n    echo \"auth: disabled $2\"\n  fi\n}\n\n# ---- openldap ----\n#\n# The directory is empty when it starts, so there is nobody to sign in as until this runs. The\n# closet's api does exactly this with the same ldap tools. -c so that an entry that is already\n# there does not stop the next one, and ldappasswd afterwards so the entry always carries the\n# password that is in the store rather than the one it was created with.\nseed_ldap() {\n  cat > /tmp/seed.ldif <<LDIF\ndn: ou=users,$LDAP_BASE\nobjectClass: organizationalUnit\nou: users\n\ndn: uid=user1,ou=users,$LDAP_BASE\nobjectClass: inetOrgPerson\ncn: user1\nsn: One\nuid: user1\nuserPassword: $AUTH_USER_PASSWORD\nLDIF\n  chmod 600 /tmp/seed.ldif\n  ldapadd -c -x -H \"ldap://$LDAP_SEED:389\" -D \"$LDAP_ADMIN\" -w \"$OPENLDAP_ADMIN_PASSWORD\" \\\\\n    -f /tmp/seed.ldif >/dev/null 2>&1\n  rm -f /tmp/seed.ldif\n  ldappasswd -x -H \"ldap://$LDAP_SEED:389\" -D \"$LDAP_ADMIN\" -w \"$OPENLDAP_ADMIN_PASSWORD\" \\\\\n    -s \"$AUTH_USER_PASSWORD\" \"uid=user1,ou=users,$LDAP_BASE\" >/dev/null 2>&1\n  # What decides is whether the entry is there, not what ldapadd returned: the usual outcome is a\n  # non-zero exit because one of the two entries already existed.\n  ldapsearch -x -H \"ldap://$LDAP_SEED:389\" -D \"$LDAP_ADMIN\" -w \"$OPENLDAP_ADMIN_PASSWORD\" \\\\\n    -b \"ou=users,$LDAP_BASE\" \"(uid=user1)\" 2>/dev/null | grep -q '^uid: user1'\n}\n\napply_openldap() {\n  if [ -z \"$OPENLDAP_ADMIN_PASSWORD\" ] || [ -z \"$AUTH_USER_PASSWORD\" ]; then\n    say \"\" \"openldap: its passwords are not in the secret store\"\n    return 1\n  fi\n\n  if ! seed_ldap; then\n    say \"\" \"openldap: could not create uid=user1 in the directory\"\n    return 1\n  fi\n\n  # The address Rancher gets. Read now rather than held anywhere, because a Service that is deleted\n  # and recreated has a different one and this is the moment it matters.\n  LDAP_FOR_RANCHER=$(kubectl -n \"$NS\" get svc \"$NS-openldap\" -o jsonpath='{.spec.clusterIP}' 2>/dev/null)\n\n  if [ -z \"$LDAP_FOR_RANCHER\" ]; then\n    say \"\" \"openldap: it has no Service, so Rancher has no address for it\"\n    return 1\n  fi\n\n  cat > /tmp/ldap.json <<JSON\n{\"type\":\"openLdapConfig\",\"id\":\"openldap\",\"enabled\":true,\"accessMode\":\"unrestricted\",\n\"servers\":[\"$LDAP_FOR_RANCHER\"],\"port\":389,\"tls\":false,\"starttls\":false,\n\"serviceAccountDistinguishedName\":\"$LDAP_ADMIN\",\"serviceAccountPassword\":\"$OPENLDAP_ADMIN_PASSWORD\",\n\"userSearchBase\":\"ou=users,$LDAP_BASE\",\"userObjectClass\":\"inetOrgPerson\",\"userLoginAttribute\":\"uid\",\n\"userNameAttribute\":\"cn\",\"userMemberAttribute\":\"memberOf\",\"userSearchAttribute\":\"uid|sn|givenName\",\n\"groupSearchBase\":\"ou=users,$LDAP_BASE\",\"groupObjectClass\":\"groupOfNames\",\"groupNameAttribute\":\"cn\",\n\"groupMemberMappingAttribute\":\"member\",\"groupMemberUserAttribute\":\"entryDN\",\"groupDNAttribute\":\"entryDN\",\n\"groupSearchAttribute\":\"cn\",\"disabledStatusBitmask\":0,\"nestedGroupMembershipEnabled\":false,\n\"connectionTimeout\":5000}\nJSON\n  chmod 600 /tmp/ldap.json\n  CODE=$(curl -sk --max-time 60 -o /tmp/ldap-put.json -w '%{http_code}' \\\\\n    -X PUT \"$RURL/v3/openLdapConfigs/openldap\" \\\\\n    -H \"Authorization: Bearer $TOKEN\" -H 'content-type: application/json' -d @/tmp/ldap.json)\n  rm -f /tmp/ldap.json\n\n  case \"$CODE\" in\n    2*) ;;\n    *) say \"\" \"openldap: this Rancher would not take the config (HTTP $CODE)\"; return 1 ;;\n  esac\n\n  # The PUT succeeding only means Rancher stored it. A login as user1 is the thing that proves\n  # Rancher can bind, search and authenticate, which is what the person pressing Apply is asking.\n  curl -sk --max-time 30 -o /tmp/ldap-user.json \\\\\n    -X POST \"$RURL/v3-public/openLdapProviders/openldap?action=login\" \\\\\n    -H 'content-type: application/json' \\\\\n    -d \"{\\\\\"username\\\\\":\\\\\"user1\\\\\",\\\\\"password\\\\\":\\\\\"$AUTH_USER_PASSWORD\\\\\",\\\\\"responseType\\\\\":\\\\\"token\\\\\"}\" >/dev/null 2>&1\n\n  if ! grep -q '\"token\"' /tmp/ldap-user.json; then\n    say \"\" \"openldap: enabled, but signing in as user1 did not work\"\n    return 1\n  fi\n\n  say \"openldap\" \"Rancher is using OpenLDAP. Sign in as user1.\"\n}\n\n# ---- keycloak (OIDC) ----\n#\n# The browser takes part in this one, so the issuer has to be an address the browser can reach and\n# the same address Rancher fetches the discovery document from. Inside a vcluster there is exactly\n# one such address, the node's, which is why the keycloak sidecar declares a node port.\napply_keycloak() {\n  if [ -z \"$KEYCLOAK_ADMIN_PASSWORD\" ] || [ -z \"$KEYCLOAK_CLIENT_SECRET\" ] || [ -z \"$AUTH_USER_PASSWORD\" ]; then\n    say \"\" \"keycloak: its secrets are not in the secret store\"\n    return 1\n  fi\n\n  KCPORT=$(kubectl -n \"$NS\" get svc \"$NS-keycloak\" -o jsonpath='{.spec.ports[0].nodePort}' 2>/dev/null)\n  WSPORT=$(kubectl -n \"$NS\" get svc \"$NS\" -o jsonpath='{.spec.ports[0].nodePort}' 2>/dev/null)\n\n  if [ -z \"$KCPORT\" ] || [ -z \"$NODE_IP\" ]; then\n    say \"\" \"keycloak: it has no node port, so no address a browser and Rancher can share\"\n    return 1\n  fi\n\n  if [ -z \"$WSPORT\" ]; then\n    say \"\" \"keycloak: this workspace has no node port to be sent back to after signing in\"\n    return 1\n  fi\n\n  ISSUER=\"http://$NODE_IP:$KCPORT/realms/rancher\"\n  RETURN_URL=\"https://$NODE_IP:$WSPORT/verify-auth\"\n\n  KT=$(curl -s --max-time 20 \"$KC_SEED/realms/master/protocol/openid-connect/token\" \\\\\n    -d client_id=admin-cli -d username=admin -d grant_type=password \\\\\n    --data-urlencode \"password=$KEYCLOAK_ADMIN_PASSWORD\" \\\\\n    | tr ',' '\\\\n' | sed -n 's/.*\"access_token\":\"\\\\([^\"]*\\\\)\".*/\\\\1/p' | head -1)\n\n  if [ -z \"$KT\" ]; then\n    say \"\" \"keycloak: could not log in to its admin API as admin\"\n    return 1\n  fi\n\n  # Realm, client and user, each create-if-missing and then updated, so a second Apply repairs a\n  # realm somebody has edited rather than failing on the 409.\n  curl -s -o /dev/null -X POST \"$KC_SEED/admin/realms\" -H \"Authorization: Bearer $KT\" \\\\\n    -H 'content-type: application/json' \\\\\n    -d '{\"realm\":\"rancher\",\"enabled\":true,\"sslRequired\":\"none\"}'\n\n  printf '{\"clientId\":\"rancher\",\"enabled\":true,\"protocol\":\"openid-connect\",\"publicClient\":false,\"standardFlowEnabled\":true,\"directAccessGrantsEnabled\":true,\"secret\":\"%s\",\"redirectUris\":[\"%s\",\"*\"],\"webOrigins\":[\"*\"]}' \\\\\n    \"$KEYCLOAK_CLIENT_SECRET\" \"$RETURN_URL\" > /tmp/kc-client.json\n  chmod 600 /tmp/kc-client.json\n  CODE=$(curl -s -o /dev/null -w '%{http_code}' -X POST \"$KC_SEED/admin/realms/rancher/clients\" \\\\\n    -H \"Authorization: Bearer $KT\" -H 'content-type: application/json' -d @/tmp/kc-client.json)\n\n  if [ \"$CODE\" = \"409\" ]; then\n    CID=$(curl -s -H \"Authorization: Bearer $KT\" \"$KC_SEED/admin/realms/rancher/clients?clientId=rancher\" \\\\\n      | tr ',' '\\\\n' | sed -n 's/.*\"id\":\"\\\\([^\"]*\\\\)\".*/\\\\1/p' | head -1)\n    curl -s -o /dev/null -X PUT \"$KC_SEED/admin/realms/rancher/clients/$CID\" \\\\\n      -H \"Authorization: Bearer $KT\" -H 'content-type: application/json' -d @/tmp/kc-client.json\n  fi\n  rm -f /tmp/kc-client.json\n\n  printf '{\"username\":\"user1\",\"enabled\":true,\"email\":\"user1@dev.local\",\"emailVerified\":true,\"firstName\":\"User\",\"lastName\":\"One\",\"credentials\":[{\"type\":\"password\",\"value\":\"%s\",\"temporary\":false}]}' \\\\\n    \"$AUTH_USER_PASSWORD\" > /tmp/kc-user.json\n  chmod 600 /tmp/kc-user.json\n  CODE=$(curl -s -o /dev/null -w '%{http_code}' -X POST \"$KC_SEED/admin/realms/rancher/users\" \\\\\n    -H \"Authorization: Bearer $KT\" -H 'content-type: application/json' -d @/tmp/kc-user.json)\n\n  if [ \"$CODE\" = \"409\" ]; then\n    UID1=$(curl -s -H \"Authorization: Bearer $KT\" \"$KC_SEED/admin/realms/rancher/users?username=user1\" \\\\\n      | tr ',' '\\\\n' | sed -n 's/.*\"id\":\"\\\\([^\"]*\\\\)\".*/\\\\1/p' | head -1)\n    printf '{\"type\":\"password\",\"value\":\"%s\",\"temporary\":false}' \"$AUTH_USER_PASSWORD\" > /tmp/kc-pw.json\n    chmod 600 /tmp/kc-pw.json\n    curl -s -o /dev/null -X PUT \"$KC_SEED/admin/realms/rancher/users/$UID1/reset-password\" \\\\\n      -H \"Authorization: Bearer $KT\" -H 'content-type: application/json' -d @/tmp/kc-pw.json\n    rm -f /tmp/kc-pw.json\n  fi\n  rm -f /tmp/kc-user.json\n\n  # Rancher validates this one itself: it fetches the discovery document from the issuer as it\n  # stores the config, so a non-2xx here is Rancher saying it could not reach Keycloak.\n  printf '{\"type\":\"keyCloakOIDCConfig\",\"id\":\"keycloakoidc\",\"enabled\":true,\"accessMode\":\"unrestricted\",\"clientId\":\"rancher\",\"clientSecret\":\"%s\",\"issuer\":\"%s\",\"authEndpoint\":\"%s/protocol/openid-connect/auth\",\"rancherUrl\":\"%s\",\"scope\":\"openid profile email\"}' \\\\\n    \"$KEYCLOAK_CLIENT_SECRET\" \"$ISSUER\" \"$ISSUER\" \"$RETURN_URL\" > /tmp/kc-oidc.json\n  chmod 600 /tmp/kc-oidc.json\n  CODE=$(curl -sk --max-time 60 -o /tmp/kc-oidc-put.json -w '%{http_code}' \\\\\n    -X PUT \"$RURL/v3/keyCloakOIDCConfigs/keycloakoidc\" \\\\\n    -H \"Authorization: Bearer $TOKEN\" -H 'content-type: application/json' -d @/tmp/kc-oidc.json)\n  rm -f /tmp/kc-oidc.json\n\n  case \"$CODE\" in\n    2*) say \"keycloak-oidc\" \"Rancher is using Keycloak OIDC at $ISSUER. Sign in as user1.\" ;;\n    *) say \"\" \"keycloak: this Rancher would not take the OIDC config (HTTP $CODE)\"; return 1 ;;\n  esac\n}\n\n# The ConfigMap is created here rather than only by the tab, so that a workspace whose auth has\n# never been touched still has somewhere for this to report to.\nkubectl -n \"$NS\" get cm \"$CM\" >/dev/null 2>&1 || \\\\\n  kubectl -n \"$NS\" create cm \"$CM\" --from-literal=provider= >/dev/null 2>&1\n\n# A sentinel that no provider can equal, so the first pass always applies whatever is asked for,\n# including nothing. A failed apply leaves it alone, which is what makes this retry.\nLAST=__unread__\n\nwhile true; do\n  WANT=$(kubectl -n \"$NS\" get cm \"$CM\" -o jsonpath='{.data.provider}' 2>/dev/null)\n\n  if [ \"$WANT\" != \"$LAST\" ]; then\n    TOKEN=$(admin_token)\n\n    if [ -z \"$TOKEN\" ]; then\n      say \"\" \"cannot sign in to this workspace's Rancher as admin\"\n    else\n      case \"$WANT\" in\n        openldap)\n          disable_provider keyCloakOIDCConfigs keycloakoidc\n          apply_openldap && LAST=\"$WANT\"\n          ;;\n        keycloak-oidc)\n          disable_provider openLdapConfigs openldap\n          apply_keycloak && LAST=\"$WANT\"\n          ;;\n        '')\n          disable_provider keyCloakOIDCConfigs keycloakoidc\n          disable_provider openLdapConfigs openldap\n          say \"\" \"local users only\"\n          LAST=\"$WANT\"\n          ;;\n        *)\n          say \"\" \"no idea what provider [$WANT] is\"\n          LAST=\"$WANT\"\n          ;;\n      esac\n    fi\n  fi\n\n  sleep 20\ndone\n`;\n\n/**\n * What a stop has to do, beyond scaling this pod to nothing.\n *\n * The vcluster is a StatefulSet and a Deployment of its own, installed by helm from inside this\n * pod, so nothing about scaling the manager touches them. Without this, Stop would leave a k3s\n * control plane and a whole Rancher running in the namespace with no card admitting to it.\n */\nexport const PAUSE_SCRIPT = `#!/bin/sh\nkubectl -n \"$NS\" scale deploy vc --replicas=0 2>/dev/null\nkubectl -n \"$NS\" scale sts vc --replicas=0 2>/dev/null\nkubectl -n \"$NS\" delete pods -l vcluster.loft.sh/managed-by=vc --wait=false\n`;\n\n/**\n * The chart's vcluster chart version, and the rights its manager needs.\n *\n * The rules are the chart's `rancher-manager` Role verbatim: namespaced, but everything within the\n * namespace including RBAC, because a helm install of vcluster creates a ServiceAccount, a Role\n * and a RoleBinding of its own. Kubernetes' aggregated `edit` role, which is what an ordinary\n * workspace pod gets, deliberately excludes RBAC, so a manager running as that account fails\n * part-way through the install with a message about roles.\n */\nexport const VCLUSTER_VERSION = '0.36.0';\n\nexport const MANAGER_RULES = [{\n  apiGroups: [\n    '', 'apps', 'batch', 'networking.k8s.io', 'rbac.authorization.k8s.io',\n    'policy', 'coordination.k8s.io', 'events.k8s.io', 'discovery.k8s.io',\n  ],\n  resources: ['*'],\n  verbs:     ['*'],\n}];\n",
    "pkg/dev-extension/recent.ts": "/**\n * Where you were last, so that coming back lands there.\n *\n * Two things, and they are the same idea one level apart: which workspace you had open, and\n * which of its tabs. Pressing Dev in Rancher's rail takes you back to the workspace you were in\n * rather than to a list you then have to click through, and switching from one workspace to\n * another keeps the tab you were on, because somebody moving between two workspaces is usually\n * looking at the same thing in both.\n *\n * localStorage rather than the shell's preferences store, which is a Kubernetes resource per\n * user: this is where a browser tab was a moment ago, it is worth nothing to anybody else, and\n * writing it through the apiserver on every navigation would be a request per click for it.\n *\n * Every read is guarded. A browser with storage disabled is one where this does nothing and the\n * product opens on its list, which is exactly what it did before any of this existed.\n */\nconst WORKSPACE_KEY = 'dev-extension.last-workspace';\nconst TAB_KEY = 'dev-extension.last-tab';\n\nfunction read(key: string): string {\n  try {\n    return window.localStorage.getItem(key) || '';\n  } catch {\n    return '';\n  }\n}\n\nfunction write(key: string, value: string): void {\n  try {\n    window.localStorage.setItem(key, value);\n  } catch { /* a browser that will not store this is one that opens on the list */ }\n}\n\n/** The workspace last opened, which may since have been deleted. Callers check. */\nexport function lastWorkspace(): string {\n  return read(WORKSPACE_KEY);\n}\n\nexport function rememberWorkspace(name: string): void {\n  write(WORKSPACE_KEY, name);\n}\n\n/**\n * The tab last looked at, across workspaces rather than per workspace.\n *\n * Per workspace was the other option and it is worse: the reason to keep a tab at all is that\n * somebody comparing two workspaces wants the same view of both, and a remembered-per-workspace\n * tab is exactly what defeats that.\n */\nexport function lastTab(): string {\n  return read(TAB_KEY);\n}\n\nexport function rememberTab(tab: string): void {\n  write(TAB_KEY, tab);\n}\n",
    "pkg/dev-extension/routing/index.ts": "import { RouteRecordRaw } from 'vue-router';\nimport { PluginRouteRecordRaw } from '@shell/core/types';\nimport {\n  PRODUCT_NAME, CUSTOM_PAGE_NAME, BLANK_CLUSTER, HOME_ROUTE,\n  EXPLORER_PRODUCT, FLOOF_PAGE, FLOOF_ROUTE,\n  DEV_PRODUCT, WORKSPACES_PAGE, CREATE_PAGE, MY_WORK_PAGE, INSIGHTS_PAGE, SETTINGS_PAGE,\n  DEV_SHELL_ROUTE, WORKSPACES_ROUTE, WORKSPACE_ROUTE, CREATE_ROUTE,\n  MY_WORK_ROUTE, INSIGHTS_ROUTE, SETTINGS_ROUTE\n} from '../config/constants';\nimport DevHome from '../pages/DevHome.vue';\nimport Floof from '../pages/Floof.vue';\nimport DevShell from '../pages/DevShell.vue';\nimport Workspaces from '../pages/Workspaces.vue';\nimport CreateWorkspace from '../pages/CreateWorkspace.vue';\nimport WorkspaceDetail from '../pages/WorkspaceDetail.vue';\nimport MyWork from '../pages/MyWork.vue';\nimport Insights from '../pages/Insights.vue';\nimport Settings from '../pages/Settings.vue';\n\n/**\n * This extension's own product page. Top-level products need the `/{product}/c/:cluster/`\n * shape and the BLANK_CLUSTER param, since they have no cluster of their own.\n */\nconst ownRoutes: RouteRecordRaw[] = [\n  {\n    name:      HOME_ROUTE,\n    path:      `/${ PRODUCT_NAME }/c/:cluster/${ CUSTOM_PAGE_NAME }`,\n    component: DevHome,\n    meta:      {\n      product: PRODUCT_NAME,\n      cluster: BLANK_CLUSTER\n    }\n  }\n];\n\n/**\n * Floof, which belongs to Rancher's Cluster Explorer rather than to this extension.\n *\n * `parent: 'default'` is what makes it an explorer page rather than a bare page at an\n * explorer-shaped URL. The shell's own cluster pages are children of the `default` template\n * route (shell/config/router/routes.js), which is what supplies the side nav, the cluster\n * switcher and the header. Registered at the top level instead, the component renders alone\n * on a blank page - the usual symptom of getting this wrong.\n *\n * `meta.product` is equally load-bearing: it tells the shell which product's nav to show and\n * which entry to highlight. Without it the page renders inside the explorer but the nav does\n * not know Floof is the current page.\n */\nconst explorerRoutes: PluginRouteRecordRaw[] = [\n  {\n    parent: 'default',\n    route:  {\n      name:      FLOOF_ROUTE,\n      path:      `/c/:cluster/${ EXPLORER_PRODUCT }/${ FLOOF_PAGE }`,\n      component: Floof,\n      meta:      { product: EXPLORER_PRODUCT }\n    }\n  }\n];\n\nconst devMeta = { product: DEV_PRODUCT, cluster: BLANK_CLUSTER };\n\n/**\n * The Dev product's pages, inside a page template of this product's own.\n *\n * `parent: 'blank'` is the shell's barest template, a `<main>` around a router-view, and it is\n * chosen for what it does not bring. The usual parent, `default`, renders Rancher's product\n * nav, which is the thing pages/DevShell.vue replaces; `plain` has no nav but wraps the page in\n * an IndentedPanel that is 90% wide and centred, and the two panes this product is mostly used\n * through are a terminal and an iframe that want the window. So DevShell supplies the header,\n * the sidebar and the terminal drawer itself, out of the shell's own components.\n *\n * What that costs, since it is a trade rather than a detail: Rancher's side nav is gone (that\n * is the point), and Header runs in `simple` mode, which drops the product title block at the\n * top left. The product switcher, the notifications, the user menu and this extension's own Dev\n * button are all in the part of the header that stays.\n *\n * Every page below is a child, so they share one sidebar rather than each drawing their own,\n * and their names are unchanged, so every link written against them still resolves.\n *\n * The create page is a sibling of the list rather than a child of it. Nested under\n * `workspaces/`, `create` would also match the detail route's `:workspace` param, and which of\n * the two won would come down to registration order.\n */\nconst devRoutes: PluginRouteRecordRaw[] = [\n  {\n    parent: 'blank',\n    route:  {\n      name:      DEV_SHELL_ROUTE,\n      path:      `/${ DEV_PRODUCT }/c/:cluster`,\n      component: DevShell,\n      meta:      devMeta,\n      children:  [\n        {\n          name: WORKSPACES_ROUTE, path: WORKSPACES_PAGE, component: Workspaces, meta: devMeta\n        },\n        {\n          name: CREATE_ROUTE, path: CREATE_PAGE, component: CreateWorkspace, meta: devMeta\n        },\n        {\n          // The tab is the hash rather than a path segment. pages/WorkspaceDetail.vue says why.\n          name:      WORKSPACE_ROUTE,\n          path:      `${ WORKSPACES_PAGE }/:workspace`,\n          component: WorkspaceDetail,\n          meta:      devMeta\n        },\n        // There is no terminal page. The terminal is the drawer along the bottom, opened\n        // from the sidebar's terminal icon, and it stays there while you work on whatever\n        // else is on screen. A page whose content was a sentence about another part of the\n        // screen is the thing that was wrong with having one.\n        {\n          name: MY_WORK_ROUTE, path: MY_WORK_PAGE, component: MyWork, meta: devMeta\n        },\n        {\n          name: INSIGHTS_ROUTE, path: INSIGHTS_PAGE, component: Insights, meta: devMeta\n        },\n        {\n          name: SETTINGS_ROUTE, path: SETTINGS_PAGE, component: Settings, meta: devMeta\n        },\n      ],\n    }\n  }\n];\n\nexport default [...ownRoutes, ...devRoutes, ...explorerRoutes];\n",
    "pkg/dev-extension/share.ts": "/**\n * Sharing a workspace's port with someone who has no Rancher session.\n *\n * Nothing here imports api.ts, deliberately: api.ts is what calls this, and a module pair that\n * imports each other is a pair whose evaluation order depends on the bundler. What this needs\n * from a caller - the namespace, the ServiceAccount - is passed in.\n *\n * The two addresses a workspace already has are both wrong for this. The service proxy is on\n * Rancher's origin and behind Rancher's session, so sending it to a colleague means giving them\n * an account and a role binding in this cluster. A node port is the opposite: open to anyone who\n * can reach the node, with nothing in front of it at all, which is fine for a dev server you are\n * looking at yourself and not fine for a link you paste into a chat.\n *\n * So sharing puts something in front: nginx, in the workspace's own namespace, with HTTP basic\n * auth and one listener per shared port, published on a node port of its own. What is shared is\n * a URL, a username and a password, and none of the three is a Rancher credential.\n *\n * The nginx config and the password file are generated here and live in a ConfigMap and a Secret\n * beside the Deployment, so what is shared is data rather than code: adding a port rewrites the\n * config and rolls the pod, and nothing about the workspace itself changes.\n */\n\n/** One port, shared. */\nexport interface DevShare {\n  /** The workspace port being served. */\n  port: number;\n  /** The port nginx listens on for it, which is what the Service publishes. */\n  listen: number;\n  /**\n   * What the workspace speaks on that port, which is not always http.\n   *\n   * A workspace served at its own origin serves https on the shell's own development\n   * certificate, and an nginx told to proxy_pass http:// to it answers 502 with `SSL alert` in\n   * its log. nginx does not verify an upstream certificate unless it is told to, so the\n   * self-signed one needs nothing else.\n   */\n  scheme: string;\n  username: string;\n  password: string;\n}\n\n/**\n * Where nginx starts numbering its listeners.\n *\n * Not the workspace's own port numbers: two shared ports could be 80 and 8080 in the workspace\n * and nginx needs a listener for each, so the two numbering schemes have to be independent or\n * they collide the first time somebody shares a port this proxy is already using.\n */\nconst FIRST_LISTEN = 9000;\n\n/** nginx's own alpine image, which is what the closet and half of Kubernetes already pull. */\nconst IMAGE = 'nginx:alpine';\n\nconst NAME_SUFFIX = 'share';\n\nexport function shareName(namespace: string): string {\n  return `${ namespace }-${ NAME_SUFFIX }`;\n}\n\n/**\n * The password file nginx reads.\n *\n * `{PLAIN}` rather than a hash, and that is a considered choice rather than laziness: the file\n * lives in a Kubernetes Secret, so anything that can read the hash can read the Secret, and a\n * hash would only stop the person sharing the port from being able to tell somebody what the\n * password is. It is a share link's password, generated per port, not an account.\n */\nexport function htpasswd(shares: DevShare[]): string {\n  return shares.map((share) => `${ share.username }:{PLAIN}${ share.password }`).join('\\n');\n}\n\n/**\n * The nginx config for the shared ports.\n *\n * One server block per share, each on its own listener, each proxying to the workspace's own\n * Service by name. `proxy_set_header Host` carries the address the browser used, because a dev\n * server that builds absolute URLs would otherwise hand back the in-cluster name and send the\n * person somewhere they cannot reach.\n */\nexport function nginxConf(namespace: string, realm: string, shares: DevShare[]): string {\n  const servers = shares.map((share) => `\n  server {\n    listen ${ share.listen };\n\n    auth_basic           \"${ realm }\";\n    auth_basic_user_file /etc/nginx/share/htpasswd;\n\n    location / {\n      proxy_pass ${ share.scheme || 'http' }://${ namespace }.${ namespace }.svc:${ share.port };\n\n      proxy_set_header Host              $http_host;\n      proxy_set_header X-Real-IP         $remote_addr;\n      proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;\n      proxy_set_header X-Forwarded-Proto $scheme;\n\n      # A dev server's hot reload is a websocket, and a proxy that does not say so turns it into\n      # a page that loads once and never updates again.\n      proxy_http_version 1.1;\n      proxy_set_header   Upgrade    $http_upgrade;\n      proxy_set_header   Connection \"upgrade\";\n\n      # Long enough for a websocket that is idle between edits, rather than nginx's minute.\n      proxy_read_timeout 3600s;\n    }\n  }`).join('\\n');\n\n  return `# Written by the Dev extension. See pkg/dev-extension/share.ts.\nworker_processes 1;\nevents { worker_connections 1024; }\n\nhttp {\n  include       /etc/nginx/mime.types;\n  default_type  application/octet-stream;\n  sendfile      on;\n${ servers }\n}\n`;\n}\n\n/** The next free listener, so an added share does not take one an existing share is using. */\nexport function nextListen(shares: DevShare[]): number {\n  const taken = new Set(shares.map((share) => share.listen));\n  let listen = FIRST_LISTEN;\n\n  while (taken.has(listen)) {\n    listen += 1;\n  }\n\n  return listen;\n}\n\n/**\n * A password nobody chose, made where it is used.\n *\n * The alphabet leaves out the characters that a person reading one out loud gets wrong, which\n * matters for a value whose whole purpose is being passed to somebody else.\n */\nconst ALPHABET = 'abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789';\n\nexport function generatedPassword(length = 16): string {\n  const bytes = new Uint8Array(length);\n\n  window.crypto.getRandomValues(bytes);\n\n  return [...bytes].map((byte) => ALPHABET[byte % ALPHABET.length]).join('');\n}\n\n/** The pod that serves the shares. Rewritten whenever the shares change. */\nexport function sharePodSpec(namespace: string, serviceAccount: string): Record<string, unknown> {\n  const name = shareName(namespace);\n\n  return {\n    serviceAccountName: serviceAccount,\n    containers:         [{\n      name:  NAME_SUFFIX,\n      image: IMAGE,\n      // The image's own entrypoint, with the generated config in place of the shipped one.\n      volumeMounts: [\n        {\n          name: 'conf', mountPath: '/etc/nginx/nginx.conf', subPath: 'nginx.conf', readOnly: true\n        },\n        { name: 'auth', mountPath: '/etc/nginx/share', readOnly: true },\n      ],\n    }],\n    volumes: [\n      { name: 'conf', configMap: { name } },\n      // A Secret rather than the same ConfigMap: the config is a thing to read when something is\n      // wrong, and the passwords are not.\n      { name: 'auth', secret: { secretName: name } },\n    ],\n  };\n}\n",
    "pkg/dev-extension/templates.ts": "/**\n * The templates a workspace can be created from, and the sections of the sidebar.\n *\n * The harness's templates are a repo to clone and an install to run; here a template is the\n * container a workspace's pod runs, because that is the same decision expressed in Kubernetes.\n * They are a hardcoded list rather than something read out of the cluster on purpose: a\n * template is code (a command, a port, what the terminal lands in), and a ConfigMap of them\n * would only move that code somewhere it cannot be reviewed.\n *\n * There is one, and it is the one the product exists for: a rancher/dashboard dev environment,\n * which is what a RANCHER project is in the harness. The toy templates it replaced (busybox, a\n * node placeholder, an nginx page) proved the plumbing and had nothing to do with the work.\n *\n * There is no Rancher server here, and there does not need to be one. A Rancher server per\n * workspace cannot run in this cluster: rancher/rancher with a ServiceAccount token tries to\n * take over the cluster it is in, and without one its embedded k3s is killed within seconds\n * because a privileged pod here gets the node's own cgroup root rather than a namespace of its\n * own. It is also unnecessary: the workspace is already inside a Rancher, and\n * `https://rancher.cattle-system.svc` answers from any pod in this cluster, so the dev server\n * points at that.\n */\nimport {\n  VCLUSTER_VALUES, MANAGE_SCRIPT, AUTH_SCRIPT, PAUSE_SCRIPT, VCLUSTER_VERSION, SIDECAR_HOST_PATH\n} from './rancher-sidecar';\n\n/**\n * Where a workspace keeps the things that have to outlive its pod.\n *\n * The hostPath is mounted at /workspace and is the only storage a restart does not throw away, so\n * both of these are under it: a home in the container filesystem is a /login on every restart,\n * and a checkout in one is another clone and another install.\n *\n * They are here rather than in api.ts because the template's own command is what creates them,\n * and a conversation has to land in the same place the command put them. Two constants so the two\n * cannot drift. See workspaceTerminalCommand.\n */\nexport const WORKSPACE_WORKDIR = '/workspace/dashboard';\nexport const WORKSPACE_HOME = '/workspace/.home';\n\n/**\n * Where a queued conversation's prompt waits for the pane that will run it.\n *\n * Beside the home directory rather than inside it, so that clearing a claude login does not take\n * the queue with it. shell.sh derives the same path from HOME_DIR, which is what keeps the two\n * ends of this agreeing without either importing the other. See queueConversation.\n */\nexport const WORKSPACE_QUEUE = '/workspace/.queue';\n\n/**\n * One secret the product needs, declared rather than hardcoded into a form.\n *\n * Settings is generated from these, so adding a secret is a data change in the same way adding a\n * template is. The declaration carries everything the page needs to render a field for it and\n * everything a card needs to say why it cannot work without it.\n */\nexport interface DevSecret {\n  /**\n   * The key inside the one Secret. A global one is the bare key (`GH_TOKEN`); a template's own is\n   * stored under the template's own prefix, which the store adds rather than the declaration.\n   */\n  key: string;\n  label: string;\n  /** One sentence, shown under the field, saying what the value is and where to get it. */\n  help: string;\n  /** Whether the thing that declared it can work at all without it. */\n  required: boolean;\n  /**\n   * The product makes this one up rather than asking for it.\n   *\n   * An admin password for a sidecar that nobody outside this cluster will ever use is a value\n   * that has to exist and that nobody has an opinion about, so it is generated once and kept, the\n   * way the closet chart's `randAlphaNum` plus `lookup` does it. Settings shows it rather than\n   * asking for it, because a generated password you cannot read is one you cannot log in with.\n   */\n  generated?: boolean;\n}\n\n/**\n * One Rancher auth provider a sidecar can back.\n *\n * The closet says the same thing in `sidecar.yml` as `rancherAuth.modes`, and for the same reason:\n * one container can back more than one provider (keycloak is both OIDC and SAML there), so the\n * choice belongs to the card rather than to the sidecar. Rancher enables exactly one provider at a\n * time, so applying one disables the others.\n *\n * Only what the card needs is declared. How a provider is configured is the manager's, because the\n * manager is the only thing holding an admin token for the workspace's Rancher: see AUTH_SCRIPT.\n */\nexport interface DevAuthMode {\n  /** What is written into the workspace's dev-auth ConfigMap, and what the manager matches on. */\n  value: string;\n  label: string;\n}\n\n/**\n * One setting a sidecar takes, declared so the card can render a form for it.\n *\n * The closet says the same thing in `sidecar.yml` under `params`, with the same four fields, and\n * for the same reason: what a sidecar can be configured with is a property of the sidecar rather\n * than of the page, so a new setting is a line here and no change to a component.\n *\n * The value reaches the container as an environment variable, which is why `env` is not optional:\n * a parameter nothing reads is a form field that does nothing.\n */\nexport interface DevSidecarParam {\n  id: string;\n  label: string;\n  /** The variable the container reads it as. */\n  env: string;\n  /** A checkbox rather than a text field. Its value is 'true' or ''. */\n  type?: 'string' | 'boolean';\n  default?: string;\n  /** One sentence under the field, saying what the value does. */\n  description: string;\n}\n\n/**\n * An optional container a workspace can run beside itself: a Deployment, and a Service when it\n * serves something. Declared by the template so the Sidecars tab renders from data.\n */\nexport interface DevSidecar {\n  id: string;\n  /** The card's section heading, taken from the data rather than a fixed list. */\n  group: string;\n  label: string;\n  description: string;\n  image: string;\n  /** Overrides the image's entrypoint and arguments, where the image needs it. */\n  command?: string[];\n  args?: string[];\n  /** What its Service points at, when it serves a UI or an API. Omitted when it serves nothing. */\n  port?: number;\n  /** How to speak to that port, since the apiserver's service proxy takes the scheme in the path. */\n  scheme?: 'http' | 'https';\n  /**\n   * Whether its own UI survives being served under the proxy's path prefix.\n   *\n   * Rancher's does not, and neither does Keycloak's: both build absolute URLs from their own idea\n   * of where they are. The closet chart says the same thing by giving exactly those two a NodePort\n   * instead. A Launch button that opens a page which immediately redirects itself out of the\n   * prefix and 404s is worse than no button, so a card without this says where the thing is\n   * instead of offering to open it.\n   */\n  launchable?: boolean;\n  /**\n   * Environment. `{{namespace}}`, `{{workspace}}` and `{{proxyPath}}` are substituted when the\n   * Deployment is written, since all three contain the workspace's own name.\n   */\n  env?: Record<string, string>;\n  /**\n   * Files mounted read-only at `/scripts`, as a ConfigMap of this sidecar's own.\n   *\n   * A sidecar whose job is to install things is a script rather than an image, and the closet\n   * chart carries exactly these as a ConfigMap for the same reason: a script long enough to have\n   * an ordering in it does not belong on a command line.\n   */\n  scripts?: Record<string, string>;\n  /**\n   * This sidecar drives Kubernetes in the workspace's namespace, so it gets a ServiceAccount of\n   * its own with rights the ordinary workspace account does not have. See MANAGER_RULES.\n   */\n  manager?: boolean;\n  /**\n   * Considered ready only once this TCP port answers, with the chart's own budget of half an hour.\n   *\n   * Without it the card says Running the moment the container starts, which for something that\n   * installs two helm charts inside a cluster it has to create first is a lie for about ten\n   * minutes.\n   */\n  readyPort?: number;\n  /** Run before the container is stopped. What a stop has to undo beyond scaling this pod. */\n  preStop?: string[];\n  /**\n   * While this sidecar runs, the workspace's dashboard talks to it rather than to the Rancher this\n   * cluster belongs to. Starting it repoints the workspace and restarts it; stopping it puts the\n   * workspace back. See setWorkspaceApi.\n   */\n  providesApi?: boolean;\n  /**\n   * This sidecar is a browser, and the Browser tab frames it rather than framing the workspace.\n   *\n   * Which is the only way that tab can show a workspace served at an origin of its own. See\n   * ownOrigin: such a workspace is on a node port, on a development certificate nothing has\n   * accepted, and a page on Rancher's origin cannot frame that — a subframe gets no certificate\n   * interstitial to click through, so it fails silently. A browser inside the cluster has neither\n   * problem, and it is served through the proxy on Rancher's own origin, so it frames.\n   */\n  providesBrowser?: boolean;\n  /**\n   * A memory-backed /dev/shm rather than the 64MB a container gets by default.\n   *\n   * Only a browser has needed it so far, and it is declared rather than given to everything\n   * because it is the pod's own memory. See sidecarPodSpec.\n   */\n  shm?: boolean;\n  /**\n   * This sidecar is a browser, and gets the workspace's own Chromium extension mounted.\n   *\n   * Built per workspace rather than baked into an image, because what is in it is that\n   * workspace's addresses and that workspace's generated passwords. See ensureBrowserExtension.\n   */\n  extension?: boolean;\n  /**\n   * Keys from this template's own secret declarations that this sidecar needs, arriving as\n   * environment by reference under the key's own name. A sidecar whose key is not set says so on\n   * its card and cannot be started, rather than starting and answering nothing.\n   */\n  secrets?: string[];\n  /**\n   * The same values again under another environment variable's name.\n   *\n   * Images rename their variables: Keycloak 26 reads `KC_BOOTSTRAP_ADMIN_PASSWORD` where earlier\n   * versions read `KEYCLOAK_ADMIN_PASSWORD`, and the closet chart sets both so that one image\n   * works either way. This is how a declaration says that without a second copy of the value.\n   */\n  secretEnv?: Record<string, string>;\n  /**\n   * Environment read off the pod itself rather than out of the declaration.\n   *\n   * The one thing this is for is the node's address, which nothing in this code knows and which the\n   * OIDC issuer has to be: `status.hostIP` is the kubelet telling the pod where it is running.\n   */\n  fieldEnv?: Record<string, string>;\n  /**\n   * Publish this sidecar's Service on a node port as well as inside the cluster.\n   *\n   * The same trade the workspace's own origin makes, and it is offered for the same reason rather\n   * than for convenience: an OIDC provider has to be at one address that both the browser and the\n   * Rancher being configured can reach, and inside a vcluster there is no such address except the\n   * node's. The cost is that the port is open to whoever can reach the node.\n   */\n  nodePort?: boolean;\n  /** What this sidecar can be configured with, behind the card's gear. See DevSidecarParam. */\n  params?: DevSidecarParam[];\n  /** The Rancher auth providers this sidecar can back, in the order the card offers them. */\n  auth?: DevAuthMode[];\n  /**\n   * This sidecar speaks MCP at this path, so what its card offers is the line that adds it to a\n   * conversation rather than a link. The closet's card does the same thing for the same sidecar.\n   */\n  mcpPath?: string;\n}\n\nexport interface DevTemplate {\n  /** Stored on the namespace as a label, so the list can say what a workspace was made from. */\n  id: string;\n  label: string;\n  description: string;\n  image: string;\n  /** Overrides the image's entrypoint. Omitted where the image already runs a server. */\n  command?: string[];\n  /** What the Service points at. */\n  port: number;\n  /**\n   * How to speak to that port. The apiserver's service proxy takes the scheme as part of the\n   * path (`https:name:port`), and rancher/dashboard's dev server is HTTPS, so getting this\n   * wrong is a Browser tab that frames a connection error and a probe that never passes.\n   */\n  scheme?: 'http' | 'https';\n  /**\n   * The repository a workspace of this template works on.\n   *\n   * The template's own command clones it, and My Work asks GitHub about it: Dependabot alerts\n   * belong to a repository rather than to a person, so the page needs to be told which one this\n   * product is about rather than guessing from whatever is in a person's issue list.\n   */\n  repo?: string;\n  /** The section icon in the sidebar, from Rancher's own icon font. */\n  icon: string;\n  /**\n   * A brand image for that section instead of a glyph, by file name in the shell's assets.\n   *\n   * For a template whose mark is not in the icon font, which Rancher's own is not. Takes\n   * precedence over `icon` where both are set. Not called `image`: that is already this\n   * interface's word for the container a workspace runs. See DevList.\n   */\n  logo?: string;\n  /** Where the workspace keeps a checkout and its node_modules between restarts. */\n  hostPath?: string;\n  /** Extra environment for the container. */\n  env?: Record<string, string>;\n  /**\n   * This template's app has to be served at an origin of its own rather than behind the\n   * apiserver's path-prefixed service proxy.\n   *\n   * rancher/dashboard builds its API URLs absolute from the page origin, so under the prefix its\n   * `/v1` and `/v3` calls never reach its own dev server: they go to the Rancher this product is\n   * served from, carrying that session, against that cluster. Counted on a running workspace: two\n   * requests reached the workspace and a hundred and thirty-six reached the host. The workspace's\n   * own API setting cannot win that argument, because the browser never asks it.\n   *\n   * So a template that says this gets a NodePort and a dev server built with no prefix. Its Browser\n   * tab then cannot frame it directly, and frames a browser that can instead: see providesBrowser,\n   * which is the same answer the harness reaches, whose Browser tab is a browser running beside the\n   * project rather than the project itself.\n   *\n   * The cost is stated where it is offered: a node port is open to whoever can reach the node,\n   * with no Rancher session in front of it. The browser sidecar does not need it - it reaches the\n   * workspace by Service name - so what the port is left for is opening the workspace in a tab of\n   * your own.\n   */\n  ownOrigin?: boolean;\n  /** What this template's workspaces and sidecars need from the secret store. */\n  secrets?: DevSecret[];\n  /** The optional containers a workspace of this template can run beside itself. */\n  sidecars?: DevSidecar[];\n}\n\n/**\n * The secrets that belong to no template.\n *\n * One list, next to the templates' own, because Settings renders both from the same declarations\n * and the only difference between them is the prefix the store puts on the key.\n */\nexport const GLOBAL_SECRETS: DevSecret[] = [\n  {\n    key:      'GH_TOKEN',\n    label:    'GitHub token',\n    help:     'A personal access token with repo and read:user. My Work reads your issues and pull requests with it, from the browser.',\n    required: false,\n  },\n];\n\nexport const TEMPLATES: DevTemplate[] = [\n  {\n    id:            'rancher',\n    label:         'Rancher',\n    description:   'A rancher/dashboard checkout with its dependencies installed and the dev server running, pointed at the Rancher this cluster belongs to. The first boot is minutes: a clone, a yarn install and a first compile, and the workspace says which of them it is in.',\n    // Plain node rather than a built image, for the reason the dev server this extension runs\n    // in uses one: there is nothing to publish and nothing that can be older than the source.\n    image:         'node:24',\n    repo:          'rancher/dashboard',\n    // Rancher's own mark rather than a generic angle bracket: this template is a\n    // rancher/dashboard checkout, and the section heading is the one place in the column that\n    // says which product a workspace belongs to.\n    //\n    // The glyph rather than the brand image, and that is the whole reason `logo` exists and is\n    // not used here: the shell's small mark (pl/half-logo.svg) is a white shape on nothing,\n    // drawn for the dark header bar, so on the light sidebar it is an element that loads, takes\n    // its 16px and shows nothing at all. A font glyph takes currentColor and is legible in both\n    // themes.\n    icon:          'icon-rancher-desktop',\n    port:          8005,\n    // The dev server is told to serve plain http (see workspace-config.ts): Rancher's proxy\n    // terminates TLS and will not talk to the shell's self-signed dev certificate on the way\n    // through, so https here is a proxy error rather than more security.\n    scheme:        'http',\n    // See the field. What this workspace runs is rancher/dashboard, which is exactly the app that\n    // cannot be served behind a path prefix without its API calls going to the wrong Rancher.\n    ownOrigin:     true,\n    // The checkout and node_modules, kept across restarts. Without it every restart is another\n    // clone and another install, which is the difference between a workspace and a demo.\n    hostPath:      '/var/lib/rancher/dev-workspaces',\n    env:           {\n      // What the dashboard talks to: this workspace's own Rancher, from the moment the workspace\n      // exists, whether or not that Rancher has been started yet. Never the Rancher this product\n      // runs in. A workspace at its own origin publishes a node port straight to this dev server,\n      // and a dev server proxying to the host cluster's API is a way into that cluster from the\n      // node's address; pointed at its own sidecar it refuses the connection until the sidecar is\n      // there. See substituteTemplateEnv.\n      API:          '{{ownRancher}}',\n      NODE_OPTIONS: '--max_old_space_size=4096',\n      // Where this dev server is reached, which its config turns into the router base, the\n      // websocket path and the rest. `{{proxyPath}}` is substituted when the Deployment is\n      // written, because the path contains the workspace's own name.\n      DEV_PROXY_PATH: '{{proxyPath}}',\n    },\n    secrets: [\n      {\n        key:      'FIGMA_API_KEY',\n        label:    'Figma API key',\n        help:     'A personal access token from Figma. The Figma sidecar reads design files with it, and cannot be started without it.',\n        required: true,\n      },\n      // Generated rather than asked for, and generated once. The closet chart makes exactly\n      // these two the same way (randAlphaNum, kept across upgrades by a lookup), because they are\n      // values that have to exist, that nobody has an opinion about, and that a person still has\n      // to be able to read in order to log in to the sidecar they belong to.\n      {\n        key:       'KEYCLOAK_ADMIN_PASSWORD',\n        label:     'Keycloak admin password',\n        help:      'The password for Keycloak\\'s own admin user. Generated the first time Keycloak is started and kept, so a realm you configure survives a restart.',\n        required:  true,\n        generated: true,\n      },\n      {\n        key:       'RANCHER_BOOTSTRAP_PASSWORD',\n        label:     'Rancher admin password',\n        help:      'The password for admin in this workspace\\'s own Rancher. Generated the first time the Rancher sidecar is started and kept, because it is what you log in with afterwards.',\n        required:  true,\n        generated: true,\n      },\n      {\n        key:       'OPENLDAP_ADMIN_PASSWORD',\n        label:     'OpenLDAP admin password',\n        help:      'The password for cn=admin. Generated the first time OpenLDAP is started and kept, since the directory it protects is on a volume that outlives the pod.',\n        required:  true,\n        generated: true,\n      },\n      // The two values the auth switch needs and nobody has an opinion about, generated the same\n      // way as the passwords above. The client secret is shared between Keycloak's own client and\n      // Rancher's OIDC config, and the user password is what user1 logs in with in either provider,\n      // which is the closet's arrangement: the same logins work across every provider.\n      {\n        key:       'KEYCLOAK_CLIENT_SECRET',\n        label:     'Keycloak client secret',\n        help:      'The secret of the `rancher` OIDC client in Keycloak. Generated, and the same value is written into Keycloak and into this workspace\\'s Rancher.',\n        required:  true,\n        generated: true,\n      },\n      {\n        key:       'AUTH_USER_PASSWORD',\n        label:     'Auth test user password',\n        help:      'The password of user1, the user created in Keycloak and in OpenLDAP so there is somebody to sign in as. Generated, and shown here because it is what you type.',\n        required:  true,\n        generated: true,\n      },\n      // The cloud credentials the closet's rancher sidecar declares, for the same use: a cluster\n      // provisioned from the workspace's own Rancher without typing them in again. Not required,\n      // because a workspace that never provisions anything needs none of them, and the bootstrap\n      // only inserts a credential whose two halves are both set. See MANAGE_SCRIPT.\n      {\n        key:      'AWS_ACCESS_KEY',\n        label:    'AWS access key',\n        help:     'Inserted into this workspace\\'s own Rancher as a cloud credential when it starts, so an EC2 cluster can be provisioned from it.',\n        required: false,\n      },\n      {\n        key:      'AWS_SECRET_KEY',\n        label:    'AWS secret key',\n        help:     'The other half of the AWS credential. Neither is used unless both are set.',\n        required: false,\n      },\n      {\n        key:      'AWS_DEFAULT_REGION',\n        label:    'AWS region',\n        help:     'The region that credential defaults to. us-west-2 when it is left empty.',\n        required: false,\n      },\n    ],\n    // Every image here was started in this cluster and reached Ready before it was given a\n    // card. What is deliberately absent is a Rancher server: it cannot reach Running here (see\n    // the note above), so it must not appear as something a person can press Start on.\n    sidecars: [\n      {\n        id:          'rancher',\n        group:       'Dev',\n        label:       'Rancher',\n        description: 'Rancher server - the app under test.',\n        // The chart's manager image: helm and kubectl on alpine, which is all the script needs.\n        image:       'dtzar/helm-kubectl:latest',\n        command:     ['/bin/sh', '/scripts/manage.sh'],\n        port:        443,\n        scheme:      'https',\n        // Rancher's UI rewrites itself out of a path prefix, so the proxy cannot serve it. What\n        // this is for is the workspace's own dashboard, which reaches it by service name.\n        launchable:  false,\n        manager:     true,\n        readyPort:   443,\n        providesApi: true,\n        scripts:     {\n          'vcluster-values.yaml': VCLUSTER_VALUES.replace('{{dataPath}}', `${ SIDECAR_HOST_PATH }/{{namespace}}/vcluster-data`),\n          'manage.sh':            MANAGE_SCRIPT,\n          'auth.sh':              AUTH_SCRIPT,\n          'pause.sh':             PAUSE_SCRIPT,\n        },\n        preStop: ['/bin/sh', '/scripts/pause.sh'],\n        // The node's own address, which is the only address both a browser and a pod inside the\n        // vcluster can reach. See nodePort on the keycloak sidecar.\n        fieldEnv: { NODE_IP: 'status.hostIP' },\n        env:      {\n          NS:               '{{namespace}}',\n          VCLUSTER_VERSION,\n          // The name the certificate is issued for. It is not how anything reaches this Rancher\n          // (the workspace uses the service name and the relay), and the chart's is likewise a\n          // name that resolves nowhere; what it has to be is stable, so the certificate does not\n          // change under a session.\n          RANCHER_HOSTNAME: 'rancher.{{workspace}}.local',\n        },\n        // What the card's gear offers, which is the closet's own two: which Rancher to install and\n        // whether it wears the Prime branding. Both are read by the manager script when it runs\n        // the helm install, so changing either is a restart of this sidecar rather than of the\n        // workspace. See MANAGE_SCRIPT.\n        params: [\n          {\n            id:          'tag',\n            label:       'Rancher version',\n            env:         'RANCHER_TAG',\n            default:     '',\n            description: 'rancher/rancher image tag: blank for whatever the chart installs, or a released version (v2.11.3) to reproduce against what a customer runs.',\n          },\n          {\n            id:          'prime',\n            label:       'Rancher Prime branding',\n            env:         'RANCHER_PRIME',\n            type:        'boolean',\n            default:     '',\n            description: 'The SUSE Rancher Prime look (CATTLE_BASE_UI_BRAND=suse).',\n          },\n        ],\n        // Everything the auth switch needs, by reference, because the manager is where it is used:\n        // it is the only thing in the product holding an admin token for this Rancher, and the only\n        // place that can reach Keycloak's admin API and OpenLDAP's port at once. See AUTH_SCRIPT.\n        secrets: [\n          'RANCHER_BOOTSTRAP_PASSWORD', 'KEYCLOAK_ADMIN_PASSWORD', 'KEYCLOAK_CLIENT_SECRET',\n          'OPENLDAP_ADMIN_PASSWORD', 'AUTH_USER_PASSWORD',\n          // By reference like the rest, so a cloud credential is not in the pod spec either.\n          'AWS_ACCESS_KEY', 'AWS_SECRET_KEY', 'AWS_DEFAULT_REGION',\n        ],\n        // The chart's own name for it, which is also what the rancher chart's value is called.\n        secretEnv: { CATTLE_BOOTSTRAP_PASSWORD: 'RANCHER_BOOTSTRAP_PASSWORD' },\n      },\n      {\n        id:          'browser',\n        group:       'Dev',\n        label:       'Browser',\n        description: 'Chromium with CDP, for driving the UI and recording.',\n        // The image the closet's own browser sidecar runs, and the harness's Browser tab with it:\n        // Chromium plus a web UI in front of it, so the thing being framed is a page rather than a\n        // screen protocol the browser would need a plugin to speak.\n        image:       'lscr.io/linuxserver/chromium:latest',\n        // Its own UI, on the port CUSTOM_PORT tells it to serve. Plain http inside the cluster,\n        // because Rancher's proxy terminates the TLS the person's browser sees and would not talk\n        // to the image's self-signed certificate on the way through - the same trade the workspace\n        // itself makes behind the proxy.\n        port:        3000,\n        scheme:      'http',\n        // Unlike Rancher's UI and Keycloak's, this one survives a path prefix: every asset it asks\n        // for is relative and its websocket is opened against the document's own URL. Verified\n        // through the proxy before it was declared, which is what launchable is a claim about.\n        launchable:  true,\n        providesBrowser: true,\n        shm:         true,\n        extension:   true,\n        env:         {\n          // The image runs as this user and writes its profile as it. The workspace's own numbers,\n          // for the same reason the closet passes PUID/PGID: a root-owned profile in a container\n          // that then drops privileges is a browser that cannot start twice.\n          PUID:       '1000',\n          PGID:       '1000',\n          // Where its web UI listens. The image serves http here and https one port up; this is the\n          // http one, since it is the proxy rather than a person that connects to it.\n          CUSTOM_PORT: '3000',\n          // What the UI calls itself, which is what the framed page's own title bar says.\n          TITLE:       '{{workspace}}',\n          // What it opens on: this workspace's own Rancher, which is what the closet's browser\n          // sidecar opens on too (RANCHER_BROWSER_START_URL defaults to https://rancher there).\n          // The address is written in whether or not that sidecar is running, so the browser is\n          // pointed at it from the first start and shows it the moment it comes up, rather than\n          // having to be told where to go once something else has happened.\n          //\n          // The workspace's own dashboard is a tab away, at the address workspaceServiceUrl\n          // gives, and the address bar in the framed browser is how you get there.\n          //\n          // The flags are the closet's for the same image, minus its CDP ones. --ignore-certificate-errors\n          // is the one that is not cosmetic: both that Rancher and the workspace's dev server serve\n          // their own certificates, and without this the browser opens on an interstitial instead.\n          // --load-extension with --disable-extensions-except, which is the pair Chromium needs\n          // to run an unpacked extension: the first says where it is and the second says that it\n          // is the only one, which is also what stops the flag being ignored on a profile that\n          // has none. See ensureBrowserExtension for what is in that directory.\n          CHROME_CLI: '{{ownRancher}} --no-first-run --start-maximized --disable-infobars --disable-session-crashed-bubble --hide-crash-restore-bubble --ignore-certificate-errors --disable-extensions-except=/extension --load-extension=/extension',\n        },\n      },\n      {\n        id:          'keycloak',\n        group:       'Auth',\n        label:       'Keycloak',\n        description: 'OIDC/SAML identity provider.',\n        image:       'quay.io/keycloak/keycloak:26.0',\n        args:        ['start-dev'],\n        port:        8080,\n        // OIDC is the one thing here that the browser takes part in: it is sent to the issuer and\n        // sent back. So the issuer has to be an address a browser can reach, and it has to be the\n        // same address the workspace's Rancher fetches the discovery document from, from inside a\n        // vcluster. A cluster-internal name is only the second; a node port is both.\n        nodePort:    true,\n        auth:        [{ value: 'keycloak-oidc', label: 'OIDC' }],\n        env:         {\n          KEYCLOAK_ADMIN: 'admin', KC_BOOTSTRAP_ADMIN_USERNAME: 'admin', KC_HTTP_PORT: '8080'\n        },\n        secrets:   ['KEYCLOAK_ADMIN_PASSWORD'],\n        // 26 reads the KC_BOOTSTRAP_ name and warns about the other; both are set so the\n        // declaration does not have to be revised the next time the image renames it.\n        secretEnv: { KC_BOOTSTRAP_ADMIN_PASSWORD: 'KEYCLOAK_ADMIN_PASSWORD' },\n      },\n      {\n        id:          'openldap',\n        group:       'Auth',\n        label:       'OpenLDAP',\n        description: 'LDAP directory server.',\n        image:       'osixia/openldap:1.5.0',\n        port:        389,\n        // No node port and none needed: Rancher binds to LDAP itself, server to server, and the\n        // browser only ever posts a username and a password to Rancher. That is why this is the\n        // provider the product can prove end to end here and OIDC is the one with a caveat.\n        auth:        [{ value: 'openldap', label: 'LDAP' }],\n        // Nothing to open. The service proxy speaks HTTP and this port speaks LDAP, so a Launch\n        // button here would open a page that could only ever be an error.\n        launchable:  false,\n        env:         {\n          LDAP_ORGANISATION: 'dev', LDAP_DOMAIN: 'dev.local', LDAP_TLS: 'false'\n        },\n        secrets:   ['OPENLDAP_ADMIN_PASSWORD'],\n        secretEnv: { LDAP_ADMIN_PASSWORD: 'OPENLDAP_ADMIN_PASSWORD' },\n      },\n      {\n        id:          'figma',\n        group:       'Design',\n        label:       'Figma',\n        description: 'Figma MCP server, for design references.',\n        image:       'acuvity/mcp-server-figma:latest',\n        // 8000, which is what the image listens on and what the closet's compose file publishes.\n        // It was declared as 3000, so the Service pointed at a port nothing was bound to: the\n        // container's own log says `minibridge frontend configured ... listen=:8000`, and 8080 is\n        // its metrics endpoint rather than the MCP one.\n        port:        8000,\n        // Headless: it speaks MCP, not HTML, so there is nothing to open in a tab. The closet says\n        // the same thing with `launch: false` and shows the address instead.\n        launchable:  false,\n        mcpPath:     '/mcp',\n        secrets:     ['FIGMA_API_KEY'],\n      },\n    ],\n    command: [\n      '/bin/sh',\n      '-c',\n      [\n        'set -e',\n        // ---------------------------------------------------------------------------------\n        // Root section, which is the same shape the dev server pod's boot.sh has and is there\n        // for the same reason: a conversation runs claude in this tree, claude refuses\n        // --dangerously-skip-permissions as root, and the files it edits are the ones the dev\n        // server is watching. So the tree has to belong to an ordinary user and the dev server\n        // has to be that same user, or the two fight over what they each write.\n        //\n        // The container's own user stays root, deliberately. `kubectl exec` runs as it, and the\n        // terminal scripts need root once to install tmux and the claude CLI before they drop\n        // to the node user themselves.\n        // ---------------------------------------------------------------------------------\n        `mkdir -p ${ WORKSPACE_HOME }`,\n        `chown node:node /workspace ${ WORKSPACE_HOME } 2>/dev/null || true`,\n        // Once, not every boot: after the first install this is tens of thousands of files, and\n        // the hostPath keeps them between restarts. A workspace that predates this gets one\n        // slow boot and is an ordinary node-owned tree afterwards.\n        '[ -f /workspace/.owned ] || (chown -R node:node /workspace 2>/dev/null; touch /workspace/.owned)',\n        // tmux and the claude CLI, in the background, because the dev server does not depend on\n        // either and installing them here would put minutes in front of it. A conversation\n        // opened before this finishes waits for it in shell.sh, where the waiting is visible.\n        // HOME_DIR, because the script's default is the dev server pod's own and a workspace has\n        // no /app: without it the last step, which pre-answers claude's first-run questions,\n        // fails on a directory that is not there and the log ends in a node stack trace.\n        `[ -f /seed/terminal-tools.sh ] && (HOME_DIR=${ WORKSPACE_HOME } /bin/sh /seed/terminal-tools.sh >/workspace/.terminal-tools.log 2>&1 &) || true`,\n        // Everything below is the node user. setpriv rather than su, because it is what the dev\n        // server pod's boot.sh uses to do the same thing and it does not bring a login shell's\n        // environment with it.\n        'exec setpriv --reuid=1000 --regid=1000 --init-groups /bin/sh -c \\'' + [\n          'set -e',\n          `export HOME=${ WORKSPACE_HOME }`,\n          // On the hostPath, so an install is not re-downloaded on every restart, and writable\n          // by the user that runs it.\n          'export YARN_CACHE_FOLDER=/workspace/.yarn-cache',\n          // Each step is guarded by what it produces, so a restart resumes rather than repeats.\n          `[ -d ${ WORKSPACE_WORKDIR }/.git ] || git clone --depth 1 https://github.com/rancher/dashboard ${ WORKSPACE_WORKDIR }`,\n          `cd ${ WORKSPACE_WORKDIR }`,\n          '[ -f .install-done ] || (yarn install --network-timeout 600000 && touch .install-done)',\n          // The checkout is an ordinary clone, so its own config is the one that assumes a dev\n          // server on its own origin. It is kept, under the name the shipped one requires, and\n          // wrapped: see workspace-config.ts.\n          //\n          // The repo's copy is restored from git first, every boot. Guarding on the presence of\n          // the .orig instead is what breaks on the second boot: the file in the tree is by then\n          // the wrapper, and the guard saves the wrapper as the original, which then requires\n          // itself. Restoring makes this idempotent and repairs a checkout that has already been\n          // through that.\n          'git checkout -- vue.config.js || true',\n          'cp vue.config.js vue.config.orig.js',\n          'cp /dev-config/vue.config.js vue.config.js',\n          'exec yarn dev --port 8005',\n        ].join(' && ') + '\\'',\n      ].join(' && '),\n    ],\n  },\n];\n\nexport function templateById(id: string): DevTemplate | undefined {\n  return TEMPLATES.find((template) => template.id === id);\n}\n\n/**\n * The browser a template's workspaces are framed in, if it declares one.\n *\n * Asked by the page, to decide whether there is a Browser tab at all, and by the tab itself, to\n * decide what its frame points at. One function so the two cannot come to different answers.\n */\nexport function templateBrowser(template: DevTemplate | undefined): DevSidecar | undefined {\n  return (template?.sidecars || []).find((sidecar) => sidecar.providesBrowser);\n}\n",
    "pkg/dev-extension/terminals.ts": "/**\n * The global terminals, as tabs in Rancher's window manager.\n *\n * The harness puts its terminals in a resizable drawer across the bottom of the page, with a\n * tab per terminal, a close on each and a plus at the end. Rancher already has that drawer:\n * the window manager is where container shells and logs open, it is resizable, it keeps its\n * tabs across navigation, and it takes tabs from extensions. So none of it is rebuilt here.\n * This file is only the bookkeeping: which numbers are taken, and what a tab is made of.\n *\n * One tab is one tmux session in the dev server's pod, with a working directory of its own, so\n * two tabs are two conversations rather than two views of one (see pod/shell.sh). Closing a tab\n * closes this end of the socket and leaves the session running, which is what makes reopening\n * the same number a reattach rather than a fresh start.\n */\nimport {\n  DEV_POD_NAMESPACE, DEV_POD_LABELS, DEV_POD_CONTAINER, TERMINAL_SESSION_PREFIX\n} from './config/constants';\n\n/** Tab ids, so the tabs belonging to this product can be told from anyone else's. */\nconst TAB_PREFIX = 'dev-terminal-';\n\n/**\n * The window manager's layouts, as strings.\n *\n * `Layout` in @shell/types/window-manager is a `const enum`, which this build erases rather\n * than emits, so importing it would compile and then be undefined at runtime. The values are\n * these three strings.\n *\n * All three, because the drawer should be usable from anywhere in the product. The window\n * manager hides the whole panel if any tab in it lacks the current layout, so a tab that only\n * claimed `default` would take Rancher's own container shells down with it on the home page.\n */\nconst LAYOUTS = ['default', 'home', 'plain'];\n\n// eslint-disable-next-line @typescript-eslint/no-explicit-any\ntype Store = any;\n\ninterface TerminalTab {\n  id: string;\n  label: string;\n}\n\n/** The tmux session, and so the conversation, that a numbered terminal attaches to. */\nexport function terminalSession(n: number): string {\n  return `${ TERMINAL_SESSION_PREFIX }-${ n }`;\n}\n\n/** The numbers currently open in the drawer, in order. */\nexport function openTerminals(store: Store): number[] {\n  return (store.getters['wm/tabs'] || [])\n    .filter((tab: TerminalTab) => tab.id?.startsWith(TAB_PREFIX))\n    .map((tab: TerminalTab) => Number(tab.id.slice(TAB_PREFIX.length)))\n    .filter((n: number) => Number.isInteger(n))\n    .sort((a: number, b: number) => a - b);\n}\n\n/**\n * The next number to hand out: the smallest that is not taken.\n *\n * Smallest rather than one past the largest, so closing Terminal 2 and adding one gives\n * Terminal 2 back, which is also the session it left running. Numbering upwards forever would\n * make every new terminal a new conversation and quietly strand the old ones.\n *\n * Shared with a workspace's conversation list, which numbers its panes the same way, so the\n * two cannot come to disagree about what the numbers mean.\n */\nexport function nextNumber(taken: number[]): number {\n  let n = 1;\n\n  while (taken.includes(n)) {\n    n += 1;\n  }\n\n  return n;\n}\n\nexport function nextTerminalNumber(store: Store): number {\n  return nextNumber(openTerminals(store));\n}\n\n/**\n * What the sidebar's terminal icon does: show a terminal, or hide the one that is showing.\n *\n * A toggle, because the icon is the only thing in the product that opens the drawer and a\n * control that can only ever open something is one you have to close another way. With nothing\n * open it opens one, so a terminal is one click from anywhere; with one already in front of you\n * it puts the drawer away.\n *\n * Hiding is `setOpen`, not `close`. Closing a tab would end the session and throw away what is\n * on screen; this collapses the panel and leaves every tab where it was, so reopening shows the\n * same session with its scrollback, still attached to the same tmux in the pod. The window\n * manager keeps the components alive across it, which is what makes that true of the socket too.\n */\nexport function showTerminal(store: Store): number {\n  const open = openTerminals(store);\n\n  if (!open.length) {\n    return openTerminal(store);\n  }\n\n  // The one the drawer was last showing, if it is one of ours, since that is the session the\n  // person was in.\n  const active = store.state.wm?.active?.bottom;\n  const activeNumber = typeof active === 'string' && active.startsWith(TAB_PREFIX) ? Number(active.slice(TAB_PREFIX.length)) : NaN;\n  const showing = open.includes(activeNumber);\n\n  // Showing one of ours already: the icon is asking for it to go away.\n  if (showing && store.state.wm?.open?.bottom) {\n    store.commit('wm/setOpen', { position: 'bottom', open: false }, { root: true });\n\n    return activeNumber;\n  }\n\n  return openTerminal(store, showing ? activeNumber : open[0]);\n}\n\n/**\n * Open a terminal in the drawer, or bring it to the front if it is already there.\n *\n * `wm/open` does both: its addTab keeps an existing tab as it is and makes it the active one,\n * so this is also how a link to a terminal focuses it.\n */\nexport function openTerminal(store: Store, n?: number): number {\n  const number = n || nextTerminalNumber(store);\n  const session = terminalSession(number);\n\n  store.dispatch('wm/open', {\n    id:    `${ TAB_PREFIX }${ number }`,\n    label: `Terminal ${ number }`,\n    icon:  'terminal',\n    // Looked up through the extension registry rather than the shell's own window components,\n    // which is what any truthy extensionId selects. See index.ts, where the name is registered.\n    component:   'DevTerminalTab',\n    extensionId: 'dev-extension',\n    position:    'bottom',\n    layouts:     LAYOUTS,\n    // True, despite what the window manager's own docs suggest: the panel only draws its tab\n    // bar when every tab in it wants a header, so a tab asking for no header takes away the\n    // tab strip, the close buttons and the drag handle for everything else in the drawer too.\n    showHeader:  true,\n    attrs:       {\n      session,\n      number,\n      namespace: DEV_POD_NAMESPACE,\n      labels:    DEV_POD_LABELS,\n      container: DEV_POD_CONTAINER,\n    },\n  }, { root: true });\n\n  return number;\n}\n",
    "pkg/dev-extension/tsconfig.json": "{\n  \"compilerOptions\": {\n    \"allowJs\": true,\n    \"target\": \"esnext\",\n    \"module\": \"esnext\",\n    \"strict\": true,\n    \"jsx\": \"preserve\",\n    \"importHelpers\": true,\n    \"moduleResolution\": \"node\",\n    \"skipLibCheck\": true,\n    \"esModuleInterop\": true,\n    \"allowSyntheticDefaultImports\": true,\n    \"sourceMap\": true,\n    \"baseUrl\": \".\",\n    \"preserveSymlinks\": true,\n    \"typeRoots\": [\n      \"../../node_modules\",\n      \"../../node_modules/@rancher/shell/types\"\n    ],    \n    \"types\": [\n      \"node\",\n      \"webpack-env\",\n      \"@types/node\",\n      \"@types/jest\",\n      \"@types/lodash\",\n      \"rancher\",\n      \"shell\"\n    ],\n    \"lib\": [\n      \"esnext\",\n      \"dom\",\n      \"dom.iterable\",\n      \"scripthost\"\n    ],\n    \"paths\": {\n      \"@shell/*\": [\n        \"../../node_modules/@rancher/shell/*\"\n      ],\n      \"@components/*\": [\n        \"@rancher/components/*\"\n      ]\n    }\n  },\n  \"include\": [\n    \"**/*.ts\",\n    \"**/*.d.ts\",\n    \"**/*.tsx\",\n    \"**/*.vue\"\n  ],\n  \"exclude\": [\n    \"../../node_modules\"\n  ]\n}\n",
    "pkg/dev-extension/vue.config.js": "module.exports = require('./.shell/pkg/vue.config')(__dirname);\n",
    "pkg/dev-extension/workspace-api.ts": "/**\n * An API for making a workspace without a browser.\n *\n * Everything else in this product is done from the page, against Rancher, carrying the session of\n * the person looking at it. That is the right shape for a person and the wrong one for anything\n * automatic: a webhook, a cron, an agent that has just been asked to fix something cannot drive a\n * browser, so none of them could make a workspace to do it in.\n *\n * So this: a small HTTP service in dev-system, with a ServiceAccount of its own, that creates the\n * same objects the page creates.\n *\n *   POST /workspaces   { \"name\": \"issue-18536\", \"template\": \"rancher\" }\n *   GET  /workspaces   what exists\n *   GET  /templates    what can be asked for\n *\n * It is plain `node:24` from a ConfigMap, the same as the Insights server, for the same reason:\n * nothing to build and nothing that can be older than this file.\n *\n * What it does not duplicate is the templates. The extension publishes them (see ensureApi), so\n * what a workspace runs is still decided in templates.ts and this renders what it is given. The\n * one thing it renders itself is the shape - a namespace, an account, two ConfigMaps, a\n * Deployment and a Service - which is small enough to read in one screen and is checked against\n * the page's own version by the fact that both make workspaces the other one can open.\n */\nexport const WORKSPACE_API_SERVER = `// Written by the Dev extension. See pkg/dev-extension/workspace-api.ts.\nimport http from 'node:http';\nimport fs from 'node:fs';\n\nconst PORT = Number(process.env.PORT || 8080);\nconst ROOT = 'https://kubernetes.default.svc';\nconst SA = '/var/run/secrets/kubernetes.io/serviceaccount';\nconst TOKEN = fs.readFileSync(\\`\\${ SA }/token\\`, 'utf8').trim();\n\n/** Where the extension leaves the templates, so this does not carry a second copy of them. */\nconst TEMPLATES_FILE = process.env.TEMPLATES_FILE || '/templates/templates.json';\n\nfunction templates() {\n  try {\n    return JSON.parse(fs.readFileSync(TEMPLATES_FILE, 'utf8'));\n  } catch {\n    return {};\n  }\n}\n\n/**\n * One call to the apiserver.\n *\n * The ServiceAccount's CA reaches node through NODE_EXTRA_CA_CERTS on the pod, so there is\n * nothing to configure here and nothing is skipped: an api server this cannot verify is one it\n * refuses to talk to.\n */\nasync function k8s(path, init = {}) {\n  const response = await fetch(\\`\\${ ROOT }\\${ path }\\`, {\n    ...init,\n    headers: {\n      authorization:  \\`Bearer \\${ TOKEN }\\`,\n      'content-type': 'application/json',\n      ...(init.headers || {}),\n    },\n  });\n\n  const text = await response.text();\n  const body = text ? JSON.parse(text) : {};\n\n  if (!response.ok) {\n    const error = new Error(body.message || \\`\\${ response.status } from \\${ path }\\`);\n\n    error.status = response.status;\n    throw error;\n  }\n\n  return body;\n}\n\n/**\n * Create it, and treat \"it is already there\" as success.\n *\n * Every caller of this is making something that either exists or does not, and an action that\n * asks twice for the same workspace should get the same answer both times rather than a 409 it\n * has to know to ignore.\n */\nasync function create(path, body) {\n  try {\n    return await k8s(path, { method: 'POST', body: JSON.stringify(body) });\n  } catch (e) {\n    if (e.status === 409) {\n      return null;\n    }\n\n    throw e;\n  }\n}\n\n/** The same rules the page applies, because a name it refuses here is a namespace Kubernetes would. */\nfunction nameError(name) {\n  if (!name) {\n    return 'A name is required.';\n  }\n\n  if (name.length > 40) {\n    return 'A name has to be 40 characters or fewer.';\n  }\n\n  return /^[a-z0-9]([-a-z0-9]*[a-z0-9])?$/.test(name)\n    ? '' : 'A name can hold lowercase letters, numbers and dashes, and has to start and end with one of the first two.';\n}\n\n/** Substituted into a template's environment, the same three the extension substitutes. */\nfunction fill(value, name, namespace, template) {\n  const own = (template.sidecars || []).find((sidecar) => sidecar.providesApi);\n\n  return String(value)\n    .replace(/{{namespace}}/g, namespace)\n    .replace(/{{workspace}}/g, name)\n    .replace(/{{proxyPath}}/g, template.ownOrigin ? '' : \\`/k8s/clusters/local/api/v1/namespaces/\\${ namespace }/services/\\${ template.scheme || 'http' }:\\${ namespace }:\\${ template.port }/proxy/\\`)\n    .replace(/{{ownRancher}}/g, own ? \\`\\${ own.scheme || 'http' }://\\${ namespace }-\\${ own.id }.\\${ namespace }.svc\\` : '');\n}\n\nasync function makeWorkspace(name, templateId) {\n  const all = templates();\n  const template = all[templateId];\n\n  if (!template) {\n    const error = new Error(\\`No template called \\${ templateId }. There is \\${ Object.keys(all).join(', ') || 'none published yet' }.\\`);\n\n    error.status = 400;\n    throw error;\n  }\n\n  const namespace = \\`dev-\\${ name }\\`;\n  const labels = {\n    'dev.rancher.io/workspace': name,\n    'dev.rancher.io/template':  templateId,\n  };\n\n  await create('/api/v1/namespaces', {\n    apiVersion: 'v1', kind: 'Namespace', metadata: { name: namespace, labels },\n  });\n\n  await create(\\`/api/v1/namespaces/\\${ namespace }/serviceaccounts\\`, {\n    apiVersion: 'v1', kind: 'ServiceAccount', metadata: { namespace, name: 'dev-workspace' },\n  });\n\n  await create(\\`/apis/rbac.authorization.k8s.io/v1/namespaces/\\${ namespace }/rolebindings\\`, {\n    apiVersion: 'rbac.authorization.k8s.io/v1',\n    kind:       'RoleBinding',\n    metadata:   { namespace, name: 'dev-workspace' },\n    roleRef:    { apiGroup: 'rbac.authorization.k8s.io', kind: 'ClusterRole', name: 'edit' },\n    subjects:   [{ kind: 'ServiceAccount', name: 'dev-workspace', namespace }],\n  });\n\n  // The two ConfigMaps a workspace boots from: the dev server's config, and the scripts a\n  // conversation runs. Both arrive as published data rather than being built here.\n  for (const [mapName, data] of Object.entries(template.configMaps || {})) {\n    await create(\\`/api/v1/namespaces/\\${ namespace }/configmaps\\`, {\n      apiVersion: 'v1', kind: 'ConfigMap', metadata: { namespace, name: mapName }, data,\n    });\n  }\n\n  const podLabels = { app: namespace, ...labels };\n\n  await create(\\`/apis/apps/v1/namespaces/\\${ namespace }/deployments\\`, {\n    apiVersion: 'apps/v1',\n    kind:       'Deployment',\n    metadata:   { namespace, name: namespace, labels: podLabels },\n    spec:       {\n      replicas: 1,\n      selector: { matchLabels: { app: namespace } },\n      strategy: { type: 'Recreate' },\n      template: {\n        metadata: { labels: podLabels },\n        spec:     {\n          serviceAccountName: 'dev-workspace',\n          containers:         [{\n            name:    'workspace',\n            image:   template.image,\n            ...(template.command ? { command: template.command } : {}),\n            ports:   [{ name: 'http', containerPort: template.port }],\n            env:     Object.entries(template.env || {}).map(([key, value]) => ({\n              name: key, value: fill(value, name, namespace, template),\n            })),\n            envFrom:      [{ secretRef: { name: 'dev-secrets', optional: true } }],\n            volumeMounts: [\n              ...(template.hostPath ? [{ name: 'work', mountPath: '/workspace' }] : []),\n              { name: 'dev-config', mountPath: '/dev-config', readOnly: true },\n              { name: 'terminal', mountPath: '/seed', readOnly: true },\n            ],\n          }],\n          volumes: [\n            ...(template.hostPath ? [{\n              name: 'work', hostPath: { path: \\`\\${ template.hostPath }/\\${ name }\\`, type: 'DirectoryOrCreate' },\n            }] : []),\n            { name: 'dev-config', configMap: { name: 'dev-workspace-config' } },\n            {\n              name: 'terminal', configMap: { name: 'dev-terminal', defaultMode: 365, optional: true },\n            },\n          ],\n        },\n      },\n    },\n  });\n\n  await create(\\`/api/v1/namespaces/\\${ namespace }/services\\`, {\n    apiVersion: 'v1',\n    kind:       'Service',\n    metadata:   { namespace, name: namespace, labels },\n    spec:       {\n      ...(template.ownOrigin ? { type: 'NodePort' } : {}),\n      selector: { app: namespace },\n      ports:    [{\n        name: template.scheme || 'http', port: template.port, targetPort: 'http', protocol: 'TCP',\n      }],\n    },\n  });\n\n  return { name, namespace, template: templateId };\n}\n\nfunction send(res, status, body) {\n  const text = JSON.stringify(body);\n\n  res.writeHead(status, {\n    'content-type':                'application/json',\n    'content-length':              Buffer.byteLength(text),\n    'access-control-allow-origin': '*',\n  });\n  res.end(text);\n}\n\nfunction readBody(req) {\n  return new Promise((resolve, reject) => {\n    let body = '';\n\n    req.on('data', (chunk) => {\n      body += chunk;\n\n      if (body.length > 100_000) {\n        reject(new Error('That is too big to be a request.'));\n      }\n    });\n    req.on('end', () => {\n      try {\n        resolve(body ? JSON.parse(body) : {});\n      } catch {\n        reject(new Error('The body is not JSON.'));\n      }\n    });\n    req.on('error', reject);\n  });\n}\n\nhttp.createServer(async(req, res) => {\n  const url = new URL(req.url, 'http://dev-api');\n\n  try {\n    if (req.method === 'GET' && url.pathname === '/templates') {\n      return send(res, 200, {\n        templates: Object.entries(templates()).map(([id, template]) => ({\n          id, label: template.label, image: template.image,\n        })),\n      });\n    }\n\n    if (req.method === 'GET' && url.pathname === '/workspaces') {\n      const list = await k8s('/api/v1/namespaces?labelSelector=dev.rancher.io/workspace');\n\n      return send(res, 200, {\n        workspaces: (list.items || []).map((namespace) => ({\n          name:      namespace.metadata.labels['dev.rancher.io/workspace'],\n          namespace: namespace.metadata.name,\n          template:  namespace.metadata.labels['dev.rancher.io/template'] || '',\n          createdAt: namespace.metadata.creationTimestamp,\n        })),\n      });\n    }\n\n    if (req.method === 'POST' && url.pathname === '/workspaces') {\n      const body = await readBody(req);\n      const problem = nameError(body.name);\n\n      if (problem) {\n        return send(res, 400, { error: problem });\n      }\n\n      return send(res, 200, await makeWorkspace(body.name, body.template || 'rancher'));\n    }\n\n    if (req.method === 'GET' && url.pathname === '/') {\n      return send(res, 200, { api: 'ok', templates: Object.keys(templates()) });\n    }\n\n    return send(res, 404, { error: 'No such path.' });\n  } catch (e) {\n    return send(res, e.status || 500, { error: e.message });\n  }\n}).listen(PORT, () => {\n  // eslint-disable-next-line no-console\n  console.log(\\`[dev-api] listening on :\\${ PORT }\\`);\n});\n`;\n",
    "pkg/dev-extension/workspace-config.ts": "/**\n * The vue.config.js a workspace's dashboard dev server runs with.\n *\n * This is the same problem this extension's own pod already solved, one level out. A\n * rancher/dashboard dev server reached through the Kubernetes apiserver's service proxy is not\n * being reached the way its defaults assume: the Host header is the proxy's, the TLS the\n * browser sees is Rancher's, every request arrives with the proxy prefix already stripped, and\n * every URL handed back to the browser has to carry it again.\n *\n * The evidence that this is needed rather than theoretical: without it the proxy answers\n * `Invalid Host header`, which is webpack's dev server refusing the request, and the Browser\n * tab frames that instead of the dashboard.\n *\n * It is kept here as text rather than as a file because it has to end up inside a container\n * this code only ever talks to through the API. It is written into a ConfigMap in the\n * workspace's namespace and copied into the checkout on boot, beside the repo's own config,\n * which it wraps rather than replaces: a workspace is still an ordinary clone of\n * rancher/dashboard that someone can work in, and its config is still the repo's.\n *\n * The annotated original is `pkg/barn/dev-extension/pod/vue.config.js`, and the two have\n * deliberately diverged: that one serves the dev server this extension itself runs in, which is\n * only ever reached through the proxy, so it still requires a prefix. This one serves a workspace,\n * which can be reached either way. See the note on the prefix below.\n */\nexport const WORKSPACE_VUE_CONFIG = `// Written by the Dev extension. See pkg/dev-extension/workspace-config.ts.\n//\n// This dev server is reached one of two ways, and everything below is the consequence of which.\n//\n//   - behind the apiserver's service proxy, at DEV_PROXY_PATH, on Rancher's own origin. The Host\n//     header is the proxy's, the TLS the browser sees is Rancher's, the prefix is stripped on the\n//     way in and has to be put back on every URL handed out.\n//   - at an origin of its own, on a node port, with no prefix at all.\n//\n// A dev server built for one does not work at the other: the router base is baked in. Which one\n// this is comes from DEV_PROXY_PATH being set or empty, and changing it restarts the pod.\n//\n// The second mode exists because of what the first one does to a dashboard. rancher/dashboard\n// builds its API URLs absolute from the page origin, so behind the prefix its /v1 and /v3 calls\n// never reach this dev server at all: they go to the Rancher this page was served from, using\n// that session, against that cluster. Measured, on a workspace with a Rancher of its own: two\n// requests arrived here and a hundred and thirty-six went to the host. An origin of its own is\n// the only thing that fixes it, because there is no browser-side API base to set.\nconst proxyPath = (process.env.DEV_PROXY_PATH || '').replace(/\\\\/$/, '');\n\n// The prefix on every in-app link, which has to be the path the page was loaded at. Set before\n// the shell's config runs, because the shell reads it out of the environment as it does.\nprocess.env.ROUTER_BASE = proxyPath ? proxyPath + '/' : '/';\n\n// The repo's own config, kept beside this one on boot, rather than a reimplementation of it.\n// rancher/dashboard is a monorepo whose shell is ./shell rather than a node_modules package,\n// and which arguments its root config passes to that shell is the repo's business and changes\n// with the repo. Wrapping it means this file only has to know about the proxy.\nconst base = require('./vue.config.orig.js');\n\n// The proxy rewrites absolute URLs in HTML as they pass through, which is what lets a naive UI\n// work behind it at all, so an asset URL that already carried the prefix would carry it twice.\n// index.html therefore asks for '/js/...' and lets the proxy add the prefix, while webpack's\n// runtime works its own base out from the script URL it was loaded from.\nbase.publicPath = 'auto';\n\nconst previousChainWebpack = base.chainWebpack;\n\nbase.chainWebpack = (webpackConfig) => {\n  if (typeof previousChainWebpack === 'function') {\n    previousChainWebpack(webpackConfig);\n  }\n\n  webpackConfig.plugin('html-index').tap((args) => {\n    args[0].publicPath = '/';\n\n    return args;\n  });\n};\n\nbase.devServer = {\n  ...base.devServer,\n\n  // Plain http only behind the proxy, where Rancher terminates TLS and will not talk to the\n  // shell's self-signed dev certificate on the way through.\n  //\n  // At its own origin the browser talks to this server directly, and http there is not a smaller\n  // problem than a certificate warning, it is a broken login: the shipped proxy sets\n  // x-forwarded-proto: https on every request it makes, so Rancher issues its session cookie with\n  // Secure, and a browser on http throws that cookie away. What that looks like is a login that\n  // returns 200 and a page that bounces straight back to the login form, which is what it did.\n  // So https here, with the shell's own certificate, and a warning to click through once.\n  ...(proxyPath ? { server: { type: 'http' } } : {}),\n\n  // Requests arrive with whatever Host the proxy chain last set, never this server's own.\n  // Without this the proxy answers 'Invalid Host header'.\n  allowedHosts: 'all',\n\n  // The proxy cannot rewrite URLs in a compressed body: the response comes back as a stream\n  // error and the browser shows a blank page.\n  compress: false,\n\n  // The prefix is stripped before a request lands here, so everything is served from the root.\n  devMiddleware: { publicPath: '/' },\n  static:        { publicPath: '/' },\n\n  // A deep link into the dashboard has to load the app rather than 404. disableDotRule matters\n  // in Rancher, where a route routinely carries a resource name with dots in it.\n  historyApiFallback: {\n    index:             '/index.html',\n    disableDotRule:    true,\n    htmlAcceptHeaders: ['text/html', 'application/xhtml+xml']\n  },\n\n  hot:             true,\n  webSocketServer: { type: 'ws', options: { path: '/ws' } },\n  client:          {\n    // Hot reload rides the same proxy when there is one, and the page's own origin when there is\n    // not. Either way this has to be written out, because the shell's config has an address of its\n    // own in it and that address is not where this server is.\n    //\n    // Behind the proxy only the path is ours; the rest are webpack-dev-server's \"infer it from\n    // window.location\" sentinels. 'auto' is one the *server* substitutes as it serves the client.\n    //\n    // Served at its own origin the sentinels are still needed, and leaving them out was a real\n    // bug rather than a tidy default. The shell's own config sets a fixed\n    // wss://localhost:8005/ws, which is right on a laptop running the dev server and wrong\n    // everywhere else: the browser then opened a hot-reload socket to whatever was on port 8005\n    // of the machine the browser is on, and displayed that server's compile errors over this\n    // dashboard. Seen here as a webpack overlay full of a completely different project's module\n    // resolution failures, sitting on top of the workspace's login form and swallowing clicks.\n    //\n    // 0.0.0.0 and 0 are webpack-dev-server's own \"take it from window.location\" sentinels. The\n    // protocol is written out rather than left as 'auto', because 'auto' is substituted by the\n    // server as it serves the client and is handed to the WebSocket constructor unchanged when\n    // the page was loaded directly. This server is https at its own origin, so wss.\n    webSocketURL: proxyPath ? {\n      protocol: 'auto',\n      hostname: '0.0.0.0',\n      port:     0,\n      pathname: proxyPath + '/ws'\n    } : {\n      protocol: 'wss',\n      hostname: '0.0.0.0',\n      port:     0,\n      pathname: '/ws'\n    },\n    // The compile-error overlay would cover the whole framed dashboard for whoever is looking\n    // when an edit fails to compile.\n    overlay: false\n  }\n};\n\nmodule.exports = base;\n`;\n\n/** Where the ConfigMap holding it is mounted, and what the workspace copies it from. */\nexport const WORKSPACE_CONFIG_MOUNT = '/dev-config';\n"
  },
  "base": {
    "package.json": "{\n  \"name\": \"dev-extension-app\",\n  \"version\": \"0.1.0\",\n  \"private\": true,\n  \"engines\": {\n    \"node\": \">=24\"\n  },\n  \"dependencies\": {\n    \"@rancher/shell\": \"^3.0.11\"\n  },\n  \"resolutions\": {\n    \"@types/node\": \"~25.3.0\",\n    \"@types/lodash\": \"4.17.5\"\n  },\n  \"scripts\": {\n    \"dev\": \"NODE_ENV=dev ./node_modules/.bin/vue-cli-service serve\",\n    \"build\": \"./node_modules/.bin/vue-cli-service build\",\n    \"clean\": \"./node_modules/@rancher/shell/scripts/clean\"\n  }\n}\n",
    "babel.config.js": "module.exports = require('@rancher/shell/babel.config.js');\n",
    "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2018\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"Node\",\n    \"lib\": [\n      \"ESNext\",\n      \"ESNext.AsyncIterable\",\n      \"DOM\"\n    ],\n    \"esModuleInterop\": true,\n    \"allowJs\": true,\n    \"sourceMap\": false,\n    \"strict\": true,\n    \"noEmit\": true,\n    \"baseUrl\": \".\",\n    \"paths\": {\n      \"~/*\": [\n        \"./*\"\n      ],\n      \"@/*\": [\n        \"./*\"\n      ],\n      \"@shell/*\": [\n        \"./node_modules/@rancher/shell/*\"\n      ]\n    },\n    \"typeRoots\": [\n      \"./node_modules\",\n      \"./node_modules/@rancher/shell/types\"\n    ],\n    \"types\": [\n      \"@types/node\",\n      \"cypress\",\n      \"rancher\",\n      \"shell\"\n    ]\n  },\n  \"exclude\": [\n    \"node_modules\"\n  ]\n}",
    "boot.sh": "#!/bin/sh\n# Entrypoint for the dev server pod.\n#\n# A real file rather than a string built in TypeScript: it is baked into the seed ConfigMap\n# verbatim by scripts/gen-dev-extension-seed.mjs, so what is in the repo is exactly what\n# runs. The only thing substituted is __, read out of\n# pkg/barn/dev-extension.ts, so the flattening this loop undoes cannot drift from\n# the flattening that produced the ConfigMap keys.\nset -e\n\nSEP=__\nAPP_HOME=/app/.home\n\n# ---------------------------------------------------------------------------\n# Root section. The container starts as root and nothing after this does.\n#\n# A terminal tab runs claude in this tree, claude refuses\n# --dangerously-skip-permissions as root, and the files it edits are the ones\n# webpack is watching - so the tree has to belong to an ordinary user, and the\n# dev server has to be that same user or the two would fight over who owns what\n# they each write.\n# ---------------------------------------------------------------------------\nif [ \"$(id -u)\" = 0 ]; then\n  mkdir -p /app \"$APP_HOME\"\n  # Cheap, so unconditional: a directory this created as root a moment ago is\n  # one the node user cannot write, and .home in particular is where claude\n  # keeps state it has to be able to update.\n  chown node:node /app \"$APP_HOME\"\n\n  # Once, not every boot: after the first install this is tens of thousands of\n  # files, and the hostPath keeps them between restarts.\n  if [ ! -f /app/.owned ]; then\n    echo \"[boot] handing /app to the node user\"\n    chown -R node:node /app\n    touch /app/.owned\n    chown node:node /app/.owned\n  fi\n\n  # tmux and the claude CLI, in the background: the dev server does not depend\n  # on either, and installing them here would put minutes in front of it. A\n  # terminal tab that opens before this finishes waits for it in shell.sh.\n  /bin/sh /seed/terminal-tools.sh >/app/.terminal-tools.log 2>&1 &\n\n  exec setpriv --reuid=1000 --regid=1000 --init-groups /bin/sh /seed/boot.sh\nfi\n\nexport HOME=\"$APP_HOME\"\nexport YARN_CACHE_FOLDER=/app/.yarn-cache\n\ncd /app\n\n# Seed the tree from the ConfigMap.\n#\n# Only files that are not already there are written. Once the pod has booted, its copy of\n# the tree is the live source - you edit it in here, and a terminal tab points claude at it -\n# and a restart must not throw those edits away. Writing just the missing ones still lets a\n# file added to the seed reach a pod that already exists.\n#\n# vue.config.js is the exception, refreshed on every boot: it is pod plumbing (it is what\n# addresses this server through the apiserver proxy), not something anyone edits in here.\nfor f in /seed/*; do\n  name=$(basename \"$f\")\n\n  # /seed holds two kinds of file: this app tree, whose paths are flattened with $SEP, and\n  # the pod's own scripts, which are run straight out of /seed so that a terminal tab always\n  # starts the version the extension last wrote, with no pod restart in between. Only the\n  # tree belongs in /app - plus the skeleton files that sit at the root of it.\n  case \"$name\" in\n    *\"$SEP\"*|package.json|babel.config.js|tsconfig.json|vue.config.js) ;;\n    *) continue ;;\n  esac\n\n  dest=\"/app/$(echo \"$name\" | sed \"s|$SEP|/|g\")\"\n\n  if [ ! -f \"$dest\" ] || [ \"$dest\" = \"/app/vue.config.js\" ]; then\n    mkdir -p \"$(dirname \"$dest\")\"\n    cp \"$f\" \"$dest\"\n  fi\ndone\n\n# The install is guarded by a marker rather than by node_modules existing. /app is a\n# hostPath, so a pod killed part-way through an install leaves a directory that is present\n# and unusable, and \"does node_modules exist\" would then skip the install forever and fail\n# in the compile instead. The marker is only written by an install that exited 0.\nif [ ! -f /app/.install-done ]; then\n  echo \"[boot] installing dependencies (first start only, this takes a few minutes)\"\n  rm -rf /app/node_modules\n  yarn install --network-timeout 600000\n  touch /app/.install-done\nelse\n  echo \"[boot] dependencies already installed\"\nfi\n\necho \"[boot] starting the dev server\"\nexec ./node_modules/.bin/vue-cli-service serve\n",
    "claude-credentials.mjs": "// One claude login, shared by every pod, through a Kubernetes Secret.\n//\n//   node /seed/claude-credentials.mjs pull    before claude starts\n//   node /seed/claude-credentials.mjs push    after it has run\n//\n// The reason both halves exist is the same reason the harness mirrors its credential file\n// between the global session and the project containers: OAuth tokens refresh, and whoever\n// refreshed last has the only working one. Pull without push means every pod that did not do\n// the refresh is stranded on a token that has expired; push without pull means a pod that has\n// never been logged in stays that way.\n//\n// Newest wins, on `expiresAt`, which is the only ordering these two copies have in common: file\n// mtimes are per pod and a pod that merely read the file would otherwise look newer than the\n// pod that refreshed it.\n//\n// Only the `claudeAiOauth` block moves. Everything else in the local file belongs to the pod\n// it is in, and the Secret is not a backup of it.\n//\n// It never fails loudly. A pod with no kubectl, no rights, or no Secret yet is a pod that is\n// not sharing a login, which is a thing to say on the way past rather than a reason to stop a\n// terminal from opening.\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { execFileSync } from 'node:child_process';\n\nconst MODE = process.argv[2] || 'pull';\nconst NAMESPACE = 'dev-system';\nconst SECRET = 'claude-credentials';\nconst KEY = 'credentials.json';\nconst LOCAL = path.join(process.env.HOME || os.homedir(), '.claude', '.credentials.json');\n\nfunction say(message) {\n  console.log(`[credentials] ${ message }`); // eslint-disable-line no-console\n}\n\nfunction kubectl(args) {\n  return execFileSync('kubectl', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });\n}\n\nfunction readLocal() {\n  try {\n    return JSON.parse(fs.readFileSync(LOCAL, 'utf8'));\n  } catch {\n    return {};\n  }\n}\n\nfunction readRemote() {\n  try {\n    const encoded = kubectl(['-n', NAMESPACE, 'get', 'secret', SECRET, '-o', `jsonpath={.data.${ KEY.replace('.', '\\\\.') }}`]).trim();\n\n    return encoded ? JSON.parse(Buffer.from(encoded, 'base64').toString('utf8')) : {};\n  } catch {\n    return null;\n  }\n}\n\n/** When the access token in a copy runs out, or 0 for a copy that has none. */\nfunction expiresAt(blob) {\n  return Number(blob?.claudeAiOauth?.expiresAt) || 0;\n}\n\n/**\n * Replace the file in one step.\n *\n * A terminal starting while this writes would otherwise be able to read half a token, and the\n * mode is set on the temporary file rather than after the rename so the file is never briefly\n * readable by anything else on the node.\n */\nfunction writeLocal(blob) {\n  fs.mkdirSync(path.dirname(LOCAL), { recursive: true });\n\n  const tmp = path.join(path.dirname(LOCAL), `.credentials.${ process.pid }`);\n\n  fs.writeFileSync(tmp, `${ JSON.stringify(blob, null, 2) }\\n`, { mode: 0o600 });\n  fs.renameSync(tmp, LOCAL);\n}\n\nconst local = readLocal();\nconst remote = readRemote();\n\nif (remote === null) {\n  say('the shared secret is not readable from this pod, so this terminal keeps its own login');\n  process.exit(0);\n}\n\nif (MODE === 'push') {\n  if (expiresAt(local) <= expiresAt(remote)) {\n    process.exit(0);\n  }\n\n  const merged = { ...remote, claudeAiOauth: local.claudeAiOauth };\n  const encoded = Buffer.from(JSON.stringify(merged)).toString('base64');\n\n  try {\n    kubectl([\n      '-n', NAMESPACE, 'patch', 'secret', SECRET, '--type=merge',\n      '-p', JSON.stringify({ data: { [KEY]: encoded } }),\n    ]);\n    say('pushed a newer token to the shared secret');\n  } catch {\n    say('could not write the shared secret, so the refreshed token stays in this pod only');\n  }\n\n  process.exit(0);\n}\n\nif (expiresAt(remote) <= expiresAt(local)) {\n  process.exit(0);\n}\n\nwriteLocal({ ...local, claudeAiOauth: remote.claudeAiOauth });\nsay('pulled the shared login');\n",
    "claude-defaults.mjs": "// The settings a fresh claude stops and asks for, answered in advance.\n//\n// A pod is a fresh machine every time, so without this the first thing the\n// editor's terminal shows is a theme picker, then a \"do you trust this folder\"\n// dialog, then a \"Yes, I accept\" for bypass permissions - three questions whose\n// answers are the same every time and none of which the person opening the\n// editor is being asked anything real by. What they should land in is a prompt,\n// or a login.\n//\n// Only the flags are set here. The login itself is pulled from a Kubernetes\n// Secret before the pane starts (see claude-credentials.mjs); what this file\n// adds for it is the Stop hook that pushes a refreshed token back, so the pod\n// that happens to refresh does not leave every other pod on a stale one.\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { execFileSync } from 'node:child_process';\n\nconst HOME = process.env.HOME || '/app/.home';\nconst CONFIG = path.join(HOME, '.claude.json');\nconst SETTINGS = path.join(HOME, '.claude', 'settings.json');\n\n// The directories a pane may start claude in, which is not the same list in\n// every pod: the dev server's tabs land in its own tree, and a workspace's land\n// in the checkout it cloned. shell.sh passes the pane's own directory; the\n// default is the dev server pod's source and the app around it, which is what\n// boot.sh's background run has no directory to pass.\nconst TRUSTED = (process.env.TRUST_DIRS || '/app/pkg/dev-extension:/app').split(':').filter(Boolean);\n\nfunction read(file) {\n  try {\n    return JSON.parse(fs.readFileSync(file, 'utf8'));\n  } catch {\n    // Missing, or half-written by a claude that was killed. Either way the\n    // defaults below are a better starting point than failing here.\n    return {};\n  }\n}\n\n// Written back only when something actually changed. claude rewrites this file\n// as it runs, and this can be called while a session is attached, so the common\n// case (everything already set) must not touch it at all.\nfunction update(file, mutate) {\n  const before = read(file);\n  const after = JSON.parse(JSON.stringify(before));\n\n  mutate(after);\n\n  if (JSON.stringify(after) === JSON.stringify(before)) {\n    return false;\n  }\n\n  fs.mkdirSync(path.dirname(file), { recursive: true });\n  fs.writeFileSync(file, `${ JSON.stringify(after, null, 2) }\\n`, { mode: 0o600 });\n\n  return true;\n}\n\nfunction claudeVersion() {\n  try {\n    return execFileSync('claude', ['--version'], { encoding: 'utf8' }).trim().split(' ')[0];\n  } catch {\n    return undefined;\n  }\n}\n\nconst changed = [\n  update(CONFIG, (config) => {\n    // Skips the whole first-run flow, the theme picker included.\n    config.hasCompletedOnboarding = true;\n\n    // claude re-runs onboarding when its version is newer than this, so it is\n    // stamped with whatever is installed rather than hardcoded.\n    const version = claudeVersion();\n\n    if (version) {\n      config.lastOnboardingVersion = version;\n    }\n\n    config.projects = config.projects || {};\n\n    for (const dir of TRUSTED) {\n      config.projects[dir] = {\n        ...config.projects[dir],\n        // The pod's tree came from this extension's own seed, so asking whether\n        // it is trusted is asking the wrong side.\n        hasTrustDialogAccepted:       true,\n        hasCompletedProjectOnboarding: true,\n      };\n    }\n  }),\n\n  // The \"Yes, I accept\" dialog for --dangerously-skip-permissions, which the\n  // pane's claude is always started with, and the hook that shares a refreshed\n  // token with the other pods.\n  update(SETTINGS, (settings) => {\n    settings.skipDangerousModePermissionPrompt = true;\n\n    // Stop, not a session end: it runs every time claude finishes a response,\n    // which is the only moment this can be sure a refresh has already landed in\n    // the file. The script itself does nothing when the local copy is not newer,\n    // so running it that often costs a comparison.\n    //\n    // Merged rather than assigned, so a hook someone added by hand survives, and\n    // matched on the command so this cannot accumulate copies of itself.\n    const hooks = settings.hooks || (settings.hooks = {});\n    const stop = hooks.Stop || (hooks.Stop = []);\n    const command = 'node /seed/claude-credentials.mjs push';\n\n    const already = stop.some((entry) => (entry.hooks || []).some((hook) => hook.command === command));\n\n    if (!already) {\n      stop.push({ hooks: [{ type: 'command', command }] });\n    }\n  }),\n].some(Boolean);\n\nconsole.log(changed ? '[claude] defaults written' : '[claude] defaults already set');\n",
    "claude-session.sh": "#!/bin/bash\n# What runs in the tmux pane: claude, in a loop.\n#\n# The loop is the point. If claude exits - a crash, a /quit, an update - the\n# pane would die with it and take the tmux session down, so the next tab would\n# come up blank instead of where you left off. Restarting keeps the session, and\n# `--continue` means the restart resumes the conversation rather than opening a\n# new one. A run that ends in under three seconds is treated as an error and\n# backed off, so a claude that cannot start does not spin.\n#\n# bash rather than sh: `read` with no variable name is a bashism, and this is\n# the pane's interactive shell anyway.\n# The pane's own home, set by shell.sh in the tmux environment. The default is\n# only for a pane started some other way.\nexport HOME=${HOME:-/app/.home}\n\n# Ctrl-C at the prompt below leaves you in a shell rather than closing the pane.\n# While claude is running it is claude that gets the signal, not this script, so\n# this only fires where it is offered.\ntrap 'echo; exec /bin/bash' INT\n\nif ! command -v claude >/dev/null 2>&1; then\n  echo \"[claude is not installed in this pod - see /app/.terminal-tools.log]\"\n  echo \"[dropping to a shell]\"\n  exec /bin/bash\nfi\n\n# A prompt somebody queued for this conversation, used once and then gone.\n#\n# Read before the loop rather than inside it: it is what this conversation is\n# for, and a restart of claude within the same pane should carry on rather than\n# ask the same thing again. Deleted before claude runs, not after, so a claude\n# that crashes on the prompt does not ask it again on every restart.\nQUEUE=${1:-}\nPROMPT=\"\"\n\nif [ -n \"$QUEUE\" ] && [ -f \"$QUEUE\" ]; then\n  PROMPT=$(cat \"$QUEUE\")\n  rm -f \"$QUEUE\"\nfi\n\nif [ -n \"$PROMPT\" ]; then\n  claude --dangerously-skip-permissions \"$PROMPT\" || true\nfi\n\nwhile true; do\n  start=$(date +%s)\n\n  # --continue fails when the directory has no conversation yet, which is the\n  # only reason for the fallback.\n  claude --dangerously-skip-permissions --continue 2>/dev/null ||\n    claude --dangerously-skip-permissions\n\n  end=$(date +%s)\n\n  if [ $((end - start)) -lt 3 ]; then\n    echo \"\"\n    echo \"[claude exited immediately, which usually means an error. Waiting 5s.]\"\n    sleep 5\n  fi\n\n  echo \"\"\n  echo \"[claude exited - press Enter to restart, Ctrl-C for a shell]\"\n  read -r || exec /bin/bash\ndone\n",
    "session-claude.md": "# Where you are\n\nYou are claude, running in a terminal inside a Rancher extension's own dev server pod. The\nthing you are building is a **Rancher dashboard extension**, and the Rancher you are building\nit against is the one two clicks away in the next pane.\n\nThis file is copied into a session's directory the first time that session starts (see\n`/seed/shell.sh`). It is yours to edit. It describes the shape of this place, not its contents,\nbecause the contents change and a file that describes them goes stale.\n\n## The pod you are in\n\n`vue-cli-service serve` is running over `/app`, a whole Rancher dashboard with the extension\ncompiled into it. `/app/pkg/$EXTENSION_NAME-extension` (or `/app/pkg/dev-extension` if this pod\nwas made before extensions had names) is that extension's source, and it is the live one:\nsaving a file there is recompiled and pushed into the browser over the hot-reload socket within\nseconds. There is no build step and no server to restart, and **restarting the dev server is the\none thing that interrupts whoever is watching it**.\n\n`/app/node_modules/@rancher/shell` is watched too, so the login page, the nav and the rest of\nthe dashboard are editable the same way. That is deliberate and it is also a trap: an edit in\nthere changes this dashboard and nothing else, and it is not in any repo.\n\n- `node`, `npm`, `yarn`, `git`, `curl`, `tmux` and `kubectl` are here.\n- Your session is a tmux session. Closing the browser leaves it running; reopening reattaches.\n- Each terminal session has its own directory, which is what keeps its conversation its own.\n\n## What you can reach\n\nYour ServiceAccount is `barn-extension`, and it is bound to **cluster-admin**. `kubectl` is\nconfigured from it, so from this pane you can read and change every resource in the cluster this\nRancher manages. That is not an accident and it is the point: an extension is mostly a UI over\nRancher's own resources, and it cannot be written, and certainly cannot be tried, from a pane\nthat gets 403 to every question.\n\nRancher's own objects are CRDs in that same apiserver, so `kubectl` is how you look at them:\n\n```bash\nkubectl get settings.management.cattle.io                 # what Rancher is configured to do\nkubectl get users.management.cattle.io                    # who can log in\nkubectl get projects.management.cattle.io -A              # Rancher's grouping of namespaces\nkubectl get clusters.management.cattle.io                 # the clusters it manages\nkubectl get clusterrepos.catalog.cattle.io                # where its Apps come from\nkubectl get uiplugins.catalog.cattle.io -A                # extensions installed into its UI\nkubectl api-resources | grep cattle.io                    # the rest, and there is a lot of it\n```\n\nTreat that access the way you would treat a root shell on somebody's cluster: it is a live\nRancher that a person is looking at. Reading is free. Before you change or delete something that\nwas not yours to begin with, say what you are about to do.\n\n## What you are building\n\nA Rancher extension is a package under `pkg/`, and the dashboard loads it by convention rather\nthan by configuration. The parts, and where to look:\n\n| Thing | File | What it does |\n| --- | --- | --- |\n| Entry point | `index.ts` | `importTypes`, `addProduct`, `addRoutes`, `register` |\n| Product | `product.ts` | Nav entries, resource types, which store they live in |\n| Routes | `routing/index.ts` | Pages, and which parent template they render under |\n| Pages | `pages/*.vue` | The pages themselves |\n| Models | `models/<type>.js` | Behaviour on a resource: actions, computed fields, links |\n| Detail/Edit | `detail/`, `edit/` | Resolved by resource type name, not by import |\n| Strings | `l10n/en-us.yaml` | `nav.group.*`, `typeLabel.*`, and anything `t()` looks up |\n\nTwo conventions cause most of the confusion:\n\n- **Files are found by name.** A spoofed type `my.thing` looks for `models/my.thing.js`,\n  `detail/my.thing.vue`, `edit/my.thing.vue`. Renaming the type without renaming the files is a\n  page that renders blank with no error.\n- **The parent route decides the chrome.** `addRoute('default', ...)` gets the cluster side nav\n  and renders nothing until a cluster is ready; `'plain'` gets the header and the top-level\n  menu; `'blank'` gets nothing at all. A page that renders alone on a white background is\n  almost always registered under the wrong parent.\n\nThe shell's own components are the fastest documentation there is, because they are right here:\n\n```bash\nls /app/node_modules/@rancher/shell/components          # SortableTable, AppModal, Tabbed, ...\nls /app/node_modules/@rancher/shell/components/form     # LabeledInput, LabeledSelect, ...\nls /app/node_modules/@rancher/shell/pkg                 # what a packaged extension looks like\n```\n\nRead one before writing a wrapper for it. `SortableTable`, `LabeledSelect`, `AsyncButton`,\n`Banner`, `AppModal` and `Card` cover most of what a page needs, and they carry Rancher's own\nbehaviour (sorting, paging, the busy state on a button) that a hand-rolled version will not.\n\nThe published docs are at <https://extensions.rancher.io/extensions/next/home>. They are thin on\neverything above, which is why this file lists it.\n\n## The rules of this tree\n\n- **Nothing here syncs back.** The repo copy lives in the barn repo at\n  `pkg/barn/dev-extension/`, which is what a fresh pod is seeded from. A change meant to outlive\n  this pod has to be copied back there. If you are asked to make something permanent and you\n  cannot reach the repo, say so rather than assuming the edit will survive.\n- **Do not restart the dev server.** Somebody is watching the pane it serves.\n- **`yarn install` is minutes.** Adding a dependency is a real cost here and it survives only as\n  long as this pod's `/app` does.\n",
    "shell.sh": "#!/bin/sh\n# Entrypoint for a terminal tab. The extension's terminal component runs this\n# over the Kubernetes exec subresource, with the tab's session id as $1 and,\n# optionally, the directory the pane should start in as $2 and the home\n# directory claude should keep its state in as $3.\n#\n# Everything the tab runs comes out of /seed rather than the tree, so a tab\n# always starts the scripts the extension last wrote, without a pod restart.\n#\n# The session is a tmux session, which is the whole persistence story: `-A`\n# attaches to it if it is already there and creates it otherwise, so closing the\n# browser leaves claude running and reopening the editor lands back in the same\n# conversation.\nset -e\n\nSESSION=${1:-main}\n\n# Where the pane starts, and what claude is therefore pointed at. The default is\n# DevExtension's own source, the tree this pod's dev server is compiling and\n# serving, which is what the editor's pane wants.\n#\n# It is an argument because claude keys its conversation history by working\n# directory, so one directory means one conversation, and two panes sharing a\n# directory means the second one resumes the first one's conversation rather than\n# having its own. The harness gives each terminal tab a directory for exactly\n# this reason. Callers that want several independent sessions (the Dev product's\n# global terminals) pass one per session; callers that want the source tree pass\n# nothing.\nWORKDIR=${2:-/app/pkg/dev-extension}\n\n# Where claude's login and settings live, which has to be on whatever storage\n# outlives the pod or every restart is another /login. It is an argument because\n# this script runs in two kinds of pod: the dev server's, whose durable\n# directory is /app, and a workspace's, whose is /workspace.\nHOME_DIR=${3:-/app/.home}\n\n# Made here as well as by whatever booted the pod, because everything below\n# writes into it and a missing one is a login that cannot be saved. Cheap, and\n# a no-op on the second tab.\nif [ ! -d \"$HOME_DIR\" ]; then\n  mkdir -p \"$HOME_DIR\"\n\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$HOME_DIR\"\n  fi\nfi\n\n# A prompt this conversation was opened with, if something queued one. It is a file rather\n# than an argument because whoever queues it is not the thing that starts the pane: a page\n# writes it into the pod and the pane picks it up whenever it next starts. Beside the home\n# directory, so it is on the same storage and outlives a pod restart the way a login does.\nQUEUE_DIR=\"$(dirname \"$HOME_DIR\")/.queue\"\nMC_QUEUE=\"$QUEUE_DIR/$SESSION\"\n\nexport MC_QUEUE\n\nHOME_DIR=\"$HOME_DIR\" TRUST_DIRS=\"$WORKDIR\" /bin/sh /seed/terminal-tools.sh\n\n# A session directory has to exist before tmux is told to start in it, and it has\n# to belong to the node user, since everything in the pane is that user and\n# claude writes here. Only for a directory this creates: the default is the\n# source tree, which boot.sh already handed over.\nif [ ! -d \"$WORKDIR\" ]; then\n  mkdir -p \"$WORKDIR\"\n\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$WORKDIR\"\n  fi\nfi\n\n# What claude reads before it is asked anything. A session in a directory of its\n# own would otherwise start knowing nothing about the cluster it is in and\n# re-derive it, badly, every time. Copied rather than linked so a session can\n# edit its own, and only when there is none, so an edited one is never\n# overwritten. The source tree has its own CLAUDE.md, so this is a no-op there.\nif [ ! -f \"$WORKDIR/CLAUDE.md\" ] && [ -f /seed/session-claude.md ]; then\n  cp /seed/session-claude.md \"$WORKDIR/CLAUDE.md\"\n\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$WORKDIR/CLAUDE.md\"\n  fi\nfi\n\n# The shared login, before anything that would use it. Run as the node user and\n# with the pane's HOME, because it writes into that user's ~/.claude and a\n# root-owned credentials file is one claude cannot then refresh.\nif [ \"$(id -u)\" = 0 ]; then\n  setpriv --reuid=1000 --regid=1000 --init-groups \\\n    env \"HOME=$HOME_DIR\" node /seed/claude-credentials.mjs pull || true\nelse\n  env \"HOME=$HOME_DIR\" node /seed/claude-credentials.mjs pull || true\nfi\n\n# tmux does not pass this script's environment into a session it is attaching to, only into one\n# it creates, so the queue file is given on the command line of the pane's own script instead.\nset -- tmux -f /seed/tmux.conf new-session -A -s \"mc-$SESSION\" -c \"$WORKDIR\" \\\n  \"/bin/bash /seed/claude-session.sh '$MC_QUEUE'\"\n\n# The exec subresource runs as the container's user, which is root, whatever the\n# dev server dropped itself to. Everything in the pane has to be the node user\n# instead: claude refuses --dangerously-skip-permissions as root, and the files\n# it edits are the ones webpack is watching, which boot.sh made node's.\nif [ \"$(id -u)\" = 0 ]; then\n  exec setpriv --reuid=1000 --regid=1000 --init-groups \\\n    env \"HOME=$HOME_DIR\" TERM=xterm-256color \"$@\"\nfi\n\nexec env \"HOME=$HOME_DIR\" TERM=xterm-256color \"$@\"\n",
    "terminal-tools.sh": "#!/bin/sh\n# What a terminal tab needs, on top of what the dev server needs: tmux, so a\n# session outlives the browser tab that opened it, and the claude CLI, which is\n# what actually runs in the pane.\n#\n# Both land in the container filesystem, which a restart throws away, so this\n# runs on every boot. It is called twice, deliberately:\n#\n#   - from boot.sh, in the background, because the dev server does not depend on\n#     any of it and must not wait for it;\n#   - from shell.sh, in the foreground, so a tab opened before the background\n#     run finished waits here, where the waiting is visible, rather than landing\n#     in a pane with no claude in it.\n#\n# Hence the lock: the two can overlap on a pod that has just started.\nset -e\n\nLOCK=/tmp/terminal-tools.lock\n\n# Is there anything to do at all?\n#\n# Asked before the lock is touched, and that ordering is the point. Everything the lock\n# protects is an install, so a tab opening in a pod that finished installing hours ago has\n# nothing to serialise with anybody - and a pod is in that state for all but the first few\n# minutes of its life. Taking a lock to discover there is no work is how one wedged tab used to\n# block every tab after it.\nhave_tools() {\n  command -v tmux >/dev/null 2>&1 &&\n    command -v claude >/dev/null 2>&1 &&\n    command -v kubectl >/dev/null 2>&1\n}\n\n# What wedges a tab, and why the waiting had to be bounded.\n#\n# A tab is a Kubernetes exec on a pty. Close the browser tab and nothing drains that pty any\n# more, so the next write into it blocks - and stays blocked, because the reader is never\n# coming back. A shell stuck there is alive by every test available: it has a pid, kill -0\n# succeeds, and if it was holding the lock when it stopped, it holds it for the life of the pod.\n# Observed: six of them in one pod, the oldest four hours old, each stopped mid-echo of the\n# message below.\n#\n# So three things, none of which is sufficient alone. The check above means a settled pod never\n# takes the lock. The message is printed once rather than every three seconds, because it was\n# the repetition that filled the pty. And the wait gives up: if the tools turn out to be there,\n# whoever holds the lock is not installing anything this tab needs.\nif ! have_tools; then\n  waited=0\n  said=\"\"\n  took=\"\"\n\n  while true; do\n    # Taking it is the loop's exit, and `took` is how the release below knows this shell owns\n    # what it is about to delete. The other way out of here is giving up, which must not.\n    if mkdir \"$LOCK\" 2>/dev/null; then\n      took=yes\n      break\n    fi\n\n    holder=$(cat \"$LOCK/pid\" 2>/dev/null || true)\n\n    # A holder that has exited outright. Older locks carry no pid at all, which is the same\n    # conclusion by a different route once nobody has claimed it for a while.\n    if [ -n \"$holder\" ] && ! kill -0 \"$holder\" 2>/dev/null; then\n      echo \"[tools] the install holding this lock is gone; clearing it\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    if [ -z \"$holder\" ] && [ \"$waited\" -ge 10 ]; then\n      echo \"[tools] this lock has no owner; clearing it\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    # Two minutes is longer than an install of tmux and the claude CLI on a warm image and\n    # shorter than anybody will sit and watch. Past it, believe the filesystem over the lock.\n    if [ \"$waited\" -ge 40 ]; then\n      if have_tools; then\n        echo \"[tools] the lock is held but everything is installed; carrying on\"\n        break\n      fi\n\n      echo \"[tools] the lock has been held for two minutes; taking it over\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    if [ -z \"$said\" ]; then\n      echo \"[tools] another install is running, waiting for it\"\n      said=yes\n    fi\n\n    waited=$((waited + 1))\n    sleep 3\n  done\n\n  # Only what this shell actually took. Giving up on a lock somebody else holds and then\n  # deleting it on the way out would be worse than the wait it was avoiding.\n  if [ -n \"$took\" ]; then\n    echo $$ > \"$LOCK/pid\" 2>/dev/null || true\n\n    # HUP as well as the rest: an exec that is hung up should release this on the way out\n    # rather than leave it for a pod restart to clear.\n    trap 'rm -rf \"$LOCK\" 2>/dev/null || true' EXIT INT TERM HUP\n  fi\nfi\n\nif ! command -v tmux >/dev/null 2>&1; then\n  echo \"[tools] installing tmux\"\n  apt-get update -qq\n  apt-get install -y -qq tmux </dev/null\nfi\n\nif ! command -v claude >/dev/null 2>&1; then\n  echo \"[tools] installing the claude cli (this takes a moment)\"\n  npm install -g --silent @anthropic-ai/claude-code\nfi\n\n# kubectl, so the pod's own ServiceAccount is usable from a terminal. It needs\n# no configuration: in-cluster credentials are mounted and client-go finds them,\n# which is the whole reason the terminals can manage the cluster at all.\n#\n# Pinned to the cluster's version rather than \"stable\", so what a terminal gets\n# does not change under it on a day when upstream moves.\nif ! command -v kubectl >/dev/null 2>&1; then\n  echo \"[tools] installing kubectl\"\n  curl -sSLo /usr/local/bin/kubectl \"https://dl.k8s.io/release/v1.36.1/bin/linux/amd64/kubectl\"\n  chmod 0755 /usr/local/bin/kubectl\nfi\n\n# Answer claude's first-run questions before it can ask them, so a tab opens on\n# a prompt or a login rather than on a theme picker. Idempotent, and a no-op\n# once the flags are set, so it is safe to run on every boot and every tab.\n#\n# As the node user: this writes into the home claude runs with, and a root-owned\n# .claude.json is one claude cannot then update.\n# HOME_DIR is passed by shell.sh, since which directory outlives the pod depends\n# on which kind of pod this is: /app for the dev server, /workspace for a\n# workspace. The default is for the background run from boot.sh, which is the\n# dev server's.\nAPP_HOME=${HOME_DIR:-/app/.home}\n\n# TRUST_DIRS is the pane's own directory, passed by shell.sh, so the folder the\n# tab is about to open in is one claude already trusts rather than one it stops\n# and asks about.\nif [ \"$(id -u)\" = 0 ]; then\n  setpriv --reuid=1000 --regid=1000 --init-groups \\\n    env \"HOME=$APP_HOME\" \"TRUST_DIRS=${TRUST_DIRS:-}\" node /seed/claude-defaults.mjs\nelse\n  env \"HOME=$APP_HOME\" \"TRUST_DIRS=${TRUST_DIRS:-}\" node /seed/claude-defaults.mjs\nfi\n\necho \"[tools] ready\"\n",
    "tmux.conf": "# tmux config for a terminal tab. Read straight out of /seed (tmux -f), so it is\n# always the version the extension last wrote and there is no copy in the tree.\n#\n# Mouse on so the scroll wheel scrolls tmux's 50k-line scrollback (it enters\n# copy-mode automatically and exits at the bottom). A plain mouse drag selects\n# via tmux copy-mode; when the drag ends, set-clipboard emits the selection as\n# an OSC 52 sequence, which the terminal component hands to the browser\n# clipboard - so drag-select auto-copies. (Shift+drag still does a native\n# xterm.js selection.) The terminal-features line tells tmux the outer terminal\n# understands OSC 52.\nset -g mouse on\nset -g history-limit 50000\n\n# Pass focus in and out of the pane through to what is running in it. claude\n# asks for this by name on startup when it is off, and asking is the thing this\n# pod is trying not to do.\nset -g focus-events on\nset -s set-clipboard on\nset -as terminal-features ',xterm-256color:clipboard'\n\n# No status bar. The harness keeps tmux's, where it lists the windows of a\n# session you can switch between; this pane has one session and one window, so\n# it would be a row of screen spent on a constant - and a green one, which is\n# the only thing in the pane that cannot follow Rancher's theme.\nset -g status off\n",
    "vue.config.js": "// Dev server config for the pod. Seeded to /app/vue.config.js, so `__dirname` is the app.\n//\n// The browser reaches this server through the Kubernetes apiserver's service proxy, on\n// Rancher's own origin:\n//\n//   https://<rancher>/k8s/clusters/local/api/v1/namespaces/<ns>/services/http:<svc>:8005/proxy/\n//\n// That inverts the shell's dev server defaults in three ways. Every URL this build hands to\n// the browser has to carry the proxy prefix, every request that arrives has had it stripped\n// again by the proxy, and the TLS the browser sees is Rancher's, not this server's.\n//\n// DEV_PROXY_PATH is the only thing passed in. It is built by the extension out of the same\n// namespace/service/port constants it creates the Deployment and Service with, so this build\n// never learns - and never needs - the hostname Rancher is served on.\nconst proxyPath = process.env.DEV_PROXY_PATH;\n\nif (!proxyPath) {\n  throw new Error('DEV_PROXY_PATH must be set - it is the service-proxy path this dev server is reached at');\n}\n\n// The vue-router base: the prefix on every in-app link, which has to be the path the page\n// was loaded at. The shell reads it out of the environment when its exported function runs;\n// setting it above the require means that cannot matter. RESOURCE_BASE, the other half of\n// that pair, is deliberately left unset - asset URLs are handled below instead.\nprocess.env.ROUTER_BASE = `${ proxyPath }/`;\n\nconst config = require('@rancher/shell/vue.config'); // eslint-disable-line @typescript-eslint/no-var-requires\n\nconst base = config(__dirname, { excludes: [] });\n\n// Asset URLs, and why they are not simply the proxy path.\n//\n// The apiserver's service proxy rewrites absolute URLs in HTML responses, prepending its own\n// proxy path - it is what lets a naive web UI work behind it at all. So an asset URL that\n// already carried the proxy path comes back to the browser carrying it twice.\n//\n// Both halves of this use that rewriting rather than fight it:\n//\n//  - index.html asks for `/js/index.js`, and the proxy hands the browser\n//    `<proxy>/js/index.js`. Absolute, so it does not depend on which route the page was\n//    loaded at, the way a relative URL would.\n//  - webpack's runtime publicPath is `auto`, which it works out from its own script URL when\n//    it loads. So chunks, fonts and images fetched later land on the same base, and nothing\n//    has to be told what that base is.\nbase.publicPath = 'auto';\n\nconst previousChainWebpack = base.chainWebpack;\n\nbase.chainWebpack = (webpackConfig) => {\n  if (typeof previousChainWebpack === 'function') {\n    previousChainWebpack(webpackConfig);\n  }\n\n  // html-webpack-plugin has a publicPath of its own, which is what makes the two halves\n  // above able to disagree. `html-index` is the plugin's name because the shell's config\n  // declares an `index` page.\n  webpackConfig.plugin('html-index').tap((args) => {\n    args[0].publicPath = '/';\n\n    return args;\n  });\n};\n\nbase.devServer = {\n  ...base.devServer,\n\n  // Rancher's proxy terminates TLS, and it will not talk to the shell's self-signed dev\n  // certificate on the way through. Plain http here, https to the browser.\n  server: { type: 'http' },\n\n  // Requests arrive with whatever Host the proxy chain last set, never this server's own.\n  allowedHosts: 'all',\n\n  // No gzip. The proxy rewrites URLs in HTML responses as they pass through (see below),\n  // and it cannot do that to a compressed body: the request comes back as\n  // `stream error: ...; INTERNAL`, which the browser reports as an incomplete response and\n  // a blank page. webpack-dev-server compresses by default, so this has to be said.\n  compress: false,\n\n  // The proxy strips its prefix before a request lands here, so everything this server\n  // serves is served from the root: webpack's output, and the files in public/.\n  devMiddleware: { publicPath: '/' },\n  static:        { publicPath: '/' },\n\n  // Serve index.html for any path that is not a file, so a deep link into the dashboard\n  // (rather than its root) loads the app instead of 404ing. vue-cli installs a version of\n  // this derived from publicPath, which is `auto` here and therefore no use; setting it at\n  // all replaces theirs outright. disableDotRule matters more than usual in Rancher, where\n  // routes routinely carry a resource name with dots in it.\n  historyApiFallback: {\n    index:             '/index.html',\n    disableDotRule:    true,\n    htmlAcceptHeaders: ['text/html', 'application/xhtml+xml']\n  },\n\n  // Hot reload rides the same proxy: the apiserver passes the upgrade through, so webpack's\n  // own client works unmodified. The sentinels are webpack-dev-server's \"infer it from\n  // window.location\" values (protocol 'auto', hostname '0.0.0.0', port 0) - only the path is\n  // ours. The socket needs a Rancher session because the proxy does, which is the one place\n  // this shows: hot reload works on every page you are logged in for, not on the login page.\n  hot:             true,\n  webSocketServer: { type: 'ws', options: { path: '/ws' } },\n  client:          {\n    webSocketURL: {\n      protocol: 'auto',\n      hostname: '0.0.0.0',\n      port:     0,\n      pathname: `${ proxyPath }/ws`\n    },\n    // The full-screen compile-error overlay is the dev build's, so it would cover this\n    // dashboard entirely for whoever happens to be looking when an edit fails to compile.\n    overlay: false\n  }\n};\n\n// The API the shell's dev server proxies to is deliberately left at its default. The browser\n// is same-origin with Rancher here, so every /v1, /k8s and /rancherversion request it makes\n// goes straight to Rancher and never through this server - the proxy config exists for a dev\n// server on its own origin, which this one is not.\n\n// The shell ships /node_modules/ in watchOptions.ignored, which makes its own pages (login,\n// nav, anything outside pkg/) impossible to edit live. Watching @rancher/shell and ignoring\n// the rest is what makes the whole dashboard editable in the pod, not just the extension.\nconst previousConfigureWebpack = base.configureWebpack;\n\nbase.configureWebpack = (config) => {\n  const result = typeof previousConfigureWebpack === 'function'\n    ? previousConfigureWebpack(config)\n    : previousConfigureWebpack;\n\n  config.watchOptions = {\n    ...(config.watchOptions || {}),\n    ignored: /node_modules\\/(?!@rancher\\/shell)/\n  };\n\n  // Watching is not enough on its own. Webpack 5 treats node_modules as a \"managed path\" and\n  // assumes its contents never change, so it caches them and skips the watcher entirely.\n  // Clearing that is what actually makes an edit under @rancher/shell rebuild.\n  config.snapshot = {\n    ...(config.snapshot || {}),\n    managedPaths:   [],\n    immutablePaths: []\n  };\n\n  return result;\n};\n\nmodule.exports = base;\n",
    "pkg/base/CLAUDE.md": "# A Rancher extension, from inside the pod\n\nYou are claude, running in the pod that serves this extension, in the tree it serves.\n\n`/app` is a whole Rancher dashboard build with this package (`/app/pkg/base`) compiled into it,\nand `vue-cli-service serve` is watching it. Every file you save here is recompiled and pushed\ninto the browser over the hot-reload socket, usually within a few seconds. There is no build\nstep to run and no server to restart, and **restarting the dev server is the one thing that\ninterrupts whoever is watching it**.\n\nThis started as the stock extension: one product, one page, and nothing else. What it becomes\nis up to whoever asked you.\n\n## What is here\n\n| Thing | File | What it does |\n| --- | --- | --- |\n| Entry point | `index.ts` | `importTypes`, `addProduct`, `addRoutes` |\n| Product | `product.ts` | The side-menu entry and what is under it |\n| Routes | `routing/index.ts` | Pages, and which parent template they render under |\n| Pages | `pages/*.vue` | The pages themselves |\n| Strings | `l10n/en-us.yaml` | Anything `t()` looks up |\n\nTwo conventions cause most of the confusion:\n\n- **Files are found by name.** A type `my.thing` looks for `models/my.thing.js`,\n  `detail/my.thing.vue`, `edit/my.thing.vue`. Renaming the type without renaming the files is a\n  page that renders blank with no error.\n- **The parent route decides the chrome.** `addRoute('default', ...)` gets the cluster side nav\n  and renders nothing until a cluster is ready; `'plain'` gets the header and the top-level\n  menu; `'blank'` gets nothing at all. A page that renders alone on a white background is\n  almost always registered under the wrong parent.\n\nThe shell's own components are the fastest documentation there is, because they are right here:\n\n```bash\nls /app/node_modules/@rancher/shell/components          # SortableTable, AppModal, Tabbed, ...\nls /app/node_modules/@rancher/shell/components/form     # LabeledInput, LabeledSelect, ...\n```\n\nRead one before writing a wrapper for it. `SortableTable`, `LabeledSelect`, `AsyncButton`,\n`Banner`, `AppModal` and `Card` cover most of what a page needs, and they carry Rancher's own\nbehaviour that a hand-rolled version will not. The published docs are at\n<https://extensions.rancher.io/extensions/next/home>.\n\n## What you can reach\n\nThis pod runs as a ServiceAccount bound to **cluster-admin**, and `kubectl` is installed. Every\nresource in the cluster this Rancher manages is readable and writable from here, including\nRancher's own, which are CRDs in the same apiserver:\n\n```bash\nkubectl get settings.management.cattle.io      # what Rancher is configured to do\nkubectl get projects.management.cattle.io -A   # its grouping of namespaces\nkubectl get clusterrepos.catalog.cattle.io     # where its Apps come from\nkubectl api-resources | grep cattle.io         # the rest, and there is a lot of it\n```\n\nThat is deliberate: an extension is mostly a UI over those resources and cannot be tried from a\npane that gets 403 to every question about them. It is also a live Rancher somebody is looking\nat, so read freely and say what you are about to change before you change it.\n\n## The browser you can look at it in\n\nThere is one Chromium in this namespace with its DevTools protocol open, so a change can be\nlooked at rather than described. It is shared by every extension here and somebody may be\nwatching it, so leave it somewhere sensible.\n\n- **Where to point it.** `https://$NODE_IP$DEV_PROXY_PATH/`, both set on this pod.\n  `DEV_PROXY_PATH` is root-relative, which means nothing to a driver outside a page, and\n  `NODE_IP` is Rancher's address - this cluster is k3s inside the Rancher container. Never\n  write a hostname in yourself.\n- **Where the browser is.** `$BARN_BROWSER_SERVICE` on `$BARN_BROWSER_CDP_PORT`, and you have\n  to resolve the name yourself:\n  `kubectl -n barn get svc \"$BARN_BROWSER_SERVICE\" -o jsonpath='{.spec.clusterIP}'`.\n  Chromium answers a debugging-port request whose `Host` is not an IP with a 403, so the\n  ClusterIP works and `barn-browser:9222` does not.\n- **The first navigation lands on the login page**, because a fresh profile has no Rancher\n  session. That session is the `R_SESS` cookie and its value is a token from\n  `POST /v3-public/localProviders/local?action=login`; set it over CDP before navigating. The\n  admin password is the one thing this pod is not given - ask for it rather than hunting. One\n  manual login in the browser's own UI works too and needs no password here.\n- **Driving it needs no install.** Node 24 has `fetch` and `WebSocket` built in: `PUT\n  /json/new?<url>` for a tab of your own, then `Runtime.enable` and `Log.enable` on its\n  websocket, which is where a change that failed to compile shows up first. Rewrite the\n  `127.0.0.1` in the websocket URL it hands back to the address you reached it on.\n\nA save is not instant - the compile is a few seconds and the result is pushed over the\nhot-reload socket - so wait for the recompile rather than racing it.\n\n## The rules of this tree\n\n- **Nothing here syncs anywhere.** This tree lives as long as the pod's `/app` does. If you are\n  asked to make something permanent, say where it would have to go rather than assuming the edit\n  will survive.\n- **Do not restart the dev server.** Somebody is watching the pane it serves.\n- **`yarn install` is minutes**, and survives only as long as this pod does.\n",
    "pkg/base/babel.config.js": "module.exports = require('./.shell/pkg/babel.config.js');\n",
    "pkg/base/index.ts": "import { importTypes } from '@rancher/auto-import';\nimport { IPlugin } from '@shell/core/types';\nimport routes from './routing';\n\n// The entry point. The dashboard calls this once, with a plugin object to register things on.\nexport default function(plugin: IPlugin): void {\n  // Picks up models/, detail/, edit/ and list/ by filename, if you add any.\n  importTypes(plugin);\n\n  plugin.metadata = require('./package.json');\n\n  plugin.addProduct(require('./product'));\n  plugin.addRoutes(routes);\n}\n",
    "pkg/base/l10n/en-us.yaml": "product:\n  base: Base\n",
    "pkg/base/package.json": "{\n  \"name\": \"base\",\n  \"description\": \"A Rancher extension\",\n  \"version\": \"0.1.0\",\n  \"private\": false,\n  \"rancher\": {\n    \"annotations\": {\n      \"catalog.cattle.io/rancher-version\": \">= 2.10.0\",\n      \"catalog.cattle.io/ui-extensions-version\": \">= 3.0.0 < 4.0.0\"\n    }\n  },\n  \"scripts\": {},\n  \"engines\": { \"node\": \">=24\" },\n  \"devDependencies\": {\n    \"@vue/cli-plugin-babel\": \"5.0.9\",\n    \"@vue/cli-service\": \"5.0.8\",\n    \"@vue/cli-plugin-typescript\": \"5.0.9\"\n  },\n  \"browserslist\": [\"> 1%\", \"last 2 versions\", \"not dead\"]\n}\n",
    "pkg/base/pages/Home.vue": "<script>\nexport default {\n  name: 'BaseHome',\n\n  data() {\n    return { renderedAt: new Date().toLocaleTimeString() };\n  },\n};\n</script>\n\n<template>\n  <div class=\"base-home\">\n    <h1>It works</h1>\n    <p>\n      This page is served by a dev server running as a pod in this cluster. Edit\n      <code>pages/Home.vue</code> in the pane beside it and the change is here within seconds,\n      with no build step and nothing to reinstall.\n    </p>\n    <p class=\"base-home__stamp\">\n      rendered at {{ renderedAt }}\n    </p>\n  </div>\n</template>\n\n<style lang=\"scss\" scoped>\n.base-home {\n  padding: 20px;\n\n  h1 {\n    color: var(--primary);\n  }\n\n  p {\n    max-width: 70ch;\n  }\n\n  &__stamp {\n    display:       inline-block;\n    margin-top:    10px;\n    padding:       6px 10px;\n    border:        1px solid var(--border);\n    border-radius: var(--border-radius);\n    font-family:   monospace;\n  }\n}\n</style>\n",
    "pkg/base/product.ts": "import { IPlugin } from '@shell/core/types';\n\nexport const PRODUCT_NAME = 'base';\nexport const HOME_PAGE = 'home';\nexport const HOME_ROUTE = `${ PRODUCT_NAME }-c-cluster-${ HOME_PAGE }`;\n\n// A product is a top-level entry in the side menu with its own pages under it.\nexport function init($plugin: IPlugin, store: any) {\n  const { product, basicType, virtualType } = $plugin.DSL(store, PRODUCT_NAME);\n\n  product({\n    icon:                'gear',\n    inStore:             'management',\n    showClusterSwitcher: false,\n    removable:           false,\n    weight:              100,\n  });\n\n  virtualType({\n    label:      'Home',\n    name:       HOME_PAGE,\n    namespaced: false,\n    weight:     100,\n    route:      { name: HOME_ROUTE, params: { cluster: '_' } },\n  });\n\n  basicType([HOME_PAGE]);\n}\n",
    "pkg/base/routing/index.ts": "import { RouteRecordRaw } from 'vue-router';\nimport { PRODUCT_NAME, HOME_PAGE, HOME_ROUTE } from '../product';\nimport Home from '../pages/Home.vue';\n\n// A top-level product's pages need the `/{product}/c/:cluster/` shape, and `meta.product` is\n// what tells the shell whose nav to show. Without it the page renders with no side menu.\nconst routes: RouteRecordRaw[] = [\n  {\n    name:      HOME_ROUTE,\n    path:      `/${ PRODUCT_NAME }/c/:cluster/${ HOME_PAGE }`,\n    component: Home,\n    meta:      { product: PRODUCT_NAME, cluster: '_' },\n  },\n];\n\nexport default routes;\n",
    "pkg/base/tsconfig.json": "{\n  \"compilerOptions\": {\n    \"allowJs\": true,\n    \"target\": \"esnext\",\n    \"module\": \"esnext\",\n    \"strict\": true,\n    \"jsx\": \"preserve\",\n    \"importHelpers\": true,\n    \"moduleResolution\": \"node\",\n    \"skipLibCheck\": true,\n    \"esModuleInterop\": true,\n    \"allowSyntheticDefaultImports\": true,\n    \"sourceMap\": true,\n    \"baseUrl\": \".\",\n    \"preserveSymlinks\": true,\n    \"typeRoots\": [\n      \"../../node_modules\",\n      \"../../node_modules/@rancher/shell/types\"\n    ],    \n    \"types\": [\n      \"node\",\n      \"webpack-env\",\n      \"@types/node\",\n      \"@types/jest\",\n      \"@types/lodash\",\n      \"rancher\",\n      \"shell\"\n    ],\n    \"lib\": [\n      \"esnext\",\n      \"dom\",\n      \"dom.iterable\",\n      \"scripthost\"\n    ],\n    \"paths\": {\n      \"@shell/*\": [\n        \"../../node_modules/@rancher/shell/*\"\n      ],\n      \"@components/*\": [\n        \"@rancher/components/*\"\n      ]\n    }\n  },\n  \"include\": [\n    \"**/*.ts\",\n    \"**/*.d.ts\",\n    \"**/*.tsx\",\n    \"**/*.vue\"\n  ],\n  \"exclude\": [\n    \"../../node_modules\"\n  ]\n}\n",
    "pkg/base/vue.config.js": "module.exports = require('./.shell/pkg/vue.config')(__dirname);\n"
  }
};

/** What a new extension is seeded from unless something else is asked for. */
export const SEED_FILES = SEEDS.dev;
